import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Admin from './pages/Admin';
import { User, Course } from './types';
import { INITIAL_COURSE } from './constants';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [course, setCourse] = useState<Course>(INITIAL_COURSE);

  // Persistence mock
  useEffect(() => {
    const savedUser = localStorage.getItem('lms_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
    const savedCourse = localStorage.getItem('lms_course');
    if (savedCourse) {
      setCourse(JSON.parse(savedCourse));
    }
  }, []);

  const handleLogin = (u: User) => {
    setUser(u);
    localStorage.setItem('lms_user', JSON.stringify(u));
  };

  const handleLogout = () => {
    setUser(null);
    localStorage.removeItem('lms_user');
  };

  const updateCourse = (updated: Course) => {
    setCourse(updated);
    localStorage.setItem('lms_course', JSON.stringify(updated));
  };

  const toggleLessonCompletion = (lessonId: string) => {
    if (!user) return;
    const newProgress = user.progress.includes(lessonId)
      ? user.progress.filter(id => id !== lessonId)
      : [...user.progress, lessonId];

    const updatedUser = { ...user, progress: newProgress };
    setUser(updatedUser);
    localStorage.setItem('lms_user', JSON.stringify(updatedUser));
  };

  return (
    <Router>
      <Routes>
        <Route 
          path="/" 
          element={user ? <Navigate to="/dashboard" /> : <Login onLogin={handleLogin} />} 
        />
        <Route 
          path="/dashboard" 
          element={
            user ? (
              <Dashboard 
                user={user} 
                course={course} 
                onLogout={handleLogout} 
                onToggleProgress={toggleLessonCompletion}
              />
            ) : (
              <Navigate to="/" />
            )
          } 
        />
        <Route 
          path="/admin" 
          element={
            user?.role === 'admin' ? (
              <Admin 
                course={course} 
                onUpdateCourse={updateCourse} 
                onLogout={handleLogout}
              />
            ) : (
              <Navigate to="/" />
            )
          } 
        />
      </Routes>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
