export default Login;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Play, 
  CheckCircle, 
  Menu, 
  X, 
  ChevronRight, 
  FileText, 
  LogOut, 
  LayoutDashboard, 
  Settings 
} from 'lucide-react';
import { User, Course, Lesson } from '../types';
import { Link } from 'react-router-dom';

interface DashboardProps {
  user: User;
  course: Course;
  onLogout: () => void;
  onToggleProgress: (lessonId: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, course, onLogout, onToggleProgress }) => {
  const [activeLesson, setActiveLesson] = useState<Lesson>(course.modules[0].lessons[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(true);

  const completedCount = user.progress.length;
  const totalLessons = course.modules.reduce((acc, mod) => acc + mod.lessons.length, 0);
  const progressPercent = Math.round((completedCount / totalLessons) * 100);

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white flex flex-col">
      {/* NAVBAR */}
      <nav className="fixed top-0 w-full z-50 bg-black/80 backdrop-blur-xl border-b border-white/5 px-4 md:px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setSidebarOpen(!isSidebarOpen)}
            className="p-2 hover:bg-white/5 rounded-lg md:hidden"
          >
            <Menu size={24} />
          </button>
          <div className="text-2xl font-black tracking-tighter text-red-600">
            ANON<span className="text-white">ACADEMY</span>
          </div>
        </div>

        <div className="flex items-center gap-4 md:gap-8">
          <div className="hidden lg:flex items-center gap-4">
            <div className="text-right">
              <p className="text-[10px] uppercase tracking-widest text-gray-500 font-bold">Tu Progreso</p>
              <p className="text-sm font-bold">{progressPercent}% completado</p>
            </div>
            <div className="w-32 h-2 bg-white/10 rounded-full overflow-hidden">
              <motion.div 
                initial={{ width: 0 }}
                animate={{ width: `${progressPercent}%` }}
                className="h-full bg-red-600"
              />
            </div>
          </div>

          <div className="flex items-center gap-3">
            {user.role === 'admin' && (
              <Link to="/admin" className="p-2 hover:bg-white/5 rounded-full text-gray-400 hover:text-white transition-colors">
                <Settings size={20} />
              </Link>
            )}
            <button onClick={onLogout} className="p-2 hover:bg-white/5 rounded-full text-gray-400 hover:text-red-500 transition-colors">
              <LogOut size={20} />
            </button>
            <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-red-600 to-red-900 border border-white/20 flex items-center justify-center font-bold text-xs">
              {user.fullName.charAt(0)}
            </div>
          </div>
        </div>
      </nav>

      <div className="flex flex-1 pt-[73px] overflow-hidden">
        {/* SIDEBAR */}
        <AnimatePresence>
          {isSidebarOpen && (
            <motion.aside 
              initial={{ x: -300, opacity: 0 }}
              animate={{ x: 0, opacity: 1 }}
              exit={{ x: -300, opacity: 0 }}
              className="fixed md:relative z-40 w-full md:w-80 h-full bg-[#0f0f0f] border-r border-white/5 overflow-y-auto custom-scrollbar"
            >
              <div className="p-6">
                <div className="flex items-center justify-between mb-8">
                  <h2 className="text-sm font-bold flex items-center gap-2 text-gray-400 uppercase tracking-widest">
                    Contenido del Curso
                  </h2>
                  <button onClick={() => setSidebarOpen(false)} className="md:hidden text-gray-500">
                    <X size={20} />
                  </button>
                </div>

                {course.modules.map((module, idx) => (
                  <div key={module.id} className="mb-8">
                    <h3 className="text-[10px] uppercase tracking-[0.2em] text-gray-600 font-black mb-4 px-2">
                      Módulo {idx + 1}: {module.title}
                    </h3>
                    <div className="space-y-1">
