                <tbody className="divide-y divide-white/5">
                  {[
                    { name: 'Admin User', email: 'admin@academy.com', role: 'admin', progress: '100%' },
                    { name: 'John Doe', email: 'john@student.com', role: 'student', progress: '45%' },
                    { name: 'Jane Smith', email: 'jane@student.com', role: 'student', progress: '12%' },
                  ].map((u, i) => (
