// AdminPanel.tsx - GESTIÓN TOTAL DE CONTENIDO
import React, { useState, useEffect } from 'react';
import { Plus, Trash2, Edit, Save, X, Upload } from 'lucide-react';
import { supabase } from '@/lib/supabase'; // Configuración de tu DB

export default function AdminPanel() {
  const [modules, setModules] = useState([]);
  const [loading, setLoading] = useState(true);

  // 1. CARGAR DATOS
  useEffect(() => {
    fetchContent();
  }, []);

  async function fetchContent() {
    const { data } = await supabase.from('modules').select('*, lessons(*)').order('id');
    setModules(data || []);
    setLoading(false);
  }

  // 2. AGREGAR CLASE
  async function addLesson(moduleId: string) {
    const title = prompt("Título de la lección:");
    const videoUrl = prompt("URL del video (YT/Vimeo):");

    if (title && videoUrl) {
      const { error } = await supabase.from('lessons').insert([
        { module_id: moduleId, title, video_url: videoUrl }
      ]);
      if (!error) fetchContent();
    }
  }

  // 3. BORRAR CLASE O MÓDULO
  async function deleteItem(table: string, id: string) {
    if (confirm("¿Estás seguro de eliminar esto? No hay vuelta atrás.")) {
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (!error) fetchContent();
    }
  }

  return (
    <div className="p-8 bg-[#0a0a0a] min-h-screen text-white">
      <div className="max-w-4xl mx-auto">
        <header className="flex justify-between items-center mb-10">
          <h1 className="text-3xl font-black text-red-600 uppercase tracking-tighter">Panel de Control</h1>
          <button 
            onClick={() => {/* Lógica para nuevo módulo */}}
            className="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 transition-all"
          >
            <Plus size={20} /> Nuevo Módulo
          </button>
        </header>

        {loading ? (
          <p className="animate-pulse text-gray-500">Sincronizando con la red...</p>
        ) : (
          <div className="space-y-6">
            {modules.map((module) => (
              <div key={module.id} className="bg-[#111] border border-white/5 rounded-2xl p-6">
                <div className="flex justify-between items-center mb-4">
                  <h2 className="text-xl font-bold italic">{module.title}</h2>
                  <button onClick={() => deleteItem('modules', module.id)} className="text-gray-500 hover:text-red-600 transition-colors">
                    <Trash2 size={18} />
                  </button>
                </div>

                <div className="space-y-3">
                  {module.lessons?.map((lesson) => (
                    <div key={lesson.id} className="flex items-center justify-between bg-white/5 p-3 rounded-xl border border-white/5">
                      <span className="text-gray-300">{lesson.title}</span>
                      <div className="flex gap-4">
                        <button className="text-gray-500 hover:text-white"><Edit size={16} /></button>
                        <button onClick={() => deleteItem('lessons', lesson.id)} className="text-gray-500 hover:text-red-600"><Trash2 size={16} /></button>
                      </div>
                    </div>
                  ))}
                  <button 
                    onClick={() => addLesson(module.id)}
                    className="w-full py-2 border-2 border-dashed border-white/10 rounded-xl text-gray-500 hover:border-red-600/50 hover:text-red-600 transition-all text-sm font-bold"
                  >
                    + AGREGAR LECCIÓN
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

