interface DashboardProps {
  user: User;
  course: Course;
  onLogout: () => void;
  onToggleProgress: (lessonId: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, course, onLogout, onToggleProgress }) => {
  const [activeLesson, setActiveLesson] = useState<Lesson>(course.modules[0].lessons[0]);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [expandedModules, setExpandedModules] = useState<string[]>([course.modules[0].id]);

  const toggleModule = (id: string) => {
    setExpandedModules(prev => 
      prev.includes(id) ? prev.filter(m => m !== id) : [...prev, id]
    );
  };

  const completedCount = user.progress.length;
  const totalLessons = useMemo(() => course.modules.reduce((acc, mod) => acc + mod.lessons.length, 0), [course]);
  const progressPercent = Math.round((completedCount / totalLessons) * 100);

  // Markdown renderer
  const htmlDescription = useMemo(() => {
    return marked.parse(activeLesson.description || '');
  }, [activeLesson.description]);

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white flex flex-col">
