                                  if (window.innerWidth < 1024) setSidebarOpen(false);
                                }}
                                className={`w-full flex items-center gap-4 p-4 pl-6 transition-all relative group ${
                                  isActive 
                                  ? 'text-white' 
                                  : 'text-gray-500 hover:text-gray-300'
                                }`}
                              >
                                {isActive && <motion.div layoutId="activeInd" className="absolute left-0 w-1 h-6 bg-red-600 rounded-full" />}
                                <div className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center transition-all ${isActive ? 'bg-red-600' : isCompleted ? 'bg-green-600/20' : 'bg-white/5'}`}>
                                  {isCompleted ? (
                                    <CheckCircle size={14} className="text-green-500" />
                                  ) : (
                                    <Play size={14} className={isActive ? "text-white" : "text-gray-600"} fill={isActive ? "currentColor" : "none"} />
                                  )}
                                </div>
                                <div className="text-left flex-1 min-w-0">
                                  <p className="text-xs font-bold truncate leading-tight">{lesson.title}</p>
                                  <div className="flex items-center gap-2 mt-1">
                                    <Clock size={10} className="opacity-40" />
                                    <span className="text-[9px] font-black uppercase tracking-widest opacity-40">{lesson.duration}</span>
                                  </div>
                                </div>
                              </button>
                            );
                          })}
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        {/* MAIN CONTENT */}
        <main className="flex-1 overflow-y-auto bg-black custom-scrollbar relative">
          <div className="max-w-6xl mx-auto p-4 md:p-12 pb-32">
            {/* VIDEO PLAYER AREA */}
            <div className="mb-12">
              <motion.div 
                key={activeLesson.id}
                initial={{ opacity: 0, scale: 0.98 }}
                animate={{ opacity: 1, scale: 1 }}
                className="relative aspect-video w-full rounded-[2.5rem] overflow-hidden bg-[#111] border border-white/5 ring-1 ring-white/10 video-shadow"
              >
                <iframe 
                  src={activeLesson.videoUrl} 
                  className="w-full h-full"
                  frameBorder="0"
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                ></iframe>
              </motion.div>
            </div>

            {/* LESSON DETAILS */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-16">
              <div className="lg:col-span-2">
                <div className="flex items-center gap-4 mb-6">
                  <span className="px-3 py-1 bg-red-600/20 text-red-500 rounded-lg text-[10px] font-black uppercase tracking-widest border border-red-600/30">
                    Siguiente Nivel
                  </span>
                  <div className="h-1 w-1 rounded-full bg-white/20" />
                  <div className="flex items-center gap-2 text-gray-500 text-xs font-bold uppercase tracking-widest">
                    <Star size={12} className="text-yellow-500" /> Premium Content
                  </div>
                </div>

                <h1 className="text-4xl md:text-6xl font-black tracking-tighter mb-8 leading-none">
                  {activeLesson.title}
                </h1>

                {/* MARKDOWN DESCRIPTION */}
                <div 
                  className="prose prose-invert max-w-none text-gray-400"
                  dangerouslySetInnerHTML={{ __html: htmlDescription }}
                />
              </div>

              <div className="space-y-10">
                <div className="p-8 bg-[#0d0d0d] border border-white/5 rounded-[2rem] space-y-6">
                  <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-400 flex items-center gap-2">
                    <CheckCircle size={16} className="text-red-600" />
                    Tus Objetivos
                  </h3>
                  <div className="space-y-4">
                    <button 
                      onClick={() => onToggleProgress(activeLesson.id)}
                      className={`w-full py-4 rounded-2xl font-black text-sm transition-all flex items-center justify-center gap-3 ${
                        user.progress.includes(activeLesson.id)
                        ? 'bg-green-600/10 text-green-500 border border-green-600/20'
                        : 'bg-white text-black hover:bg-red-600 hover:text-white shadow-xl shadow-white/5'
                      }`}
                    >
                      {user.progress.includes(activeLesson.id) ? (
                        <><CheckCircle size={18} /> Completado</>
                      ) : (
                        'Marcar como visto'
                      )}
                    </button>
                    <p className="text-[10px] text-center text-gray-600 font-bold uppercase tracking-widest">Avanza a la siguiente lección para ganar XP</p>
                  </div>
                </div>

                <div className="space-y-6">
                  <h3 className="text-sm font-black uppercase tracking-[0.2em] text-gray-400">Recursos de Clase</h3>
                  {activeLesson.resources && activeLesson.resources.length > 0 ? (
                    <div className="space-y-3">
                      {activeLesson.resources.map((file, i) => (
