            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Plus, 
  Trash2, 
  Edit3, 
  ChevronLeft, 
  Save, 
  Settings, 
  Users, 
  BookOpen, 
  LogOut,
  ChevronRight,
  Video,
  FileText,
  X,
