import { Course, Module, Lesson } from '../types';
import { Link } from 'react-router-dom';

interface AdminProps {
  course: Course;
  onUpdateCourse: (course: Course) => void;
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ course, onUpdateCourse, onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [editingCourse, setEditingCourse] = useState<Course>(course);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);

  const handleSave = () => {
    onUpdateCourse(editingCourse);
    alert('✅ Sistema sincronizado correctamente');
  };

  const addModule = () => {
    const newModule: Module = {
      id: `m-${Math.random().toString(36).substr(2, 5)}`,
      title: "Nuevo Módulo Estratégico",
      lessons: []
    };
    setEditingCourse(prev => ({ ...prev, modules: [...prev.modules, newModule] }));
  };

  const deleteModule = (id: string) => {
    if (confirm('¿Eliminar este módulo y todas sus lecciones?')) {
      setEditingCourse(prev => ({ ...prev, modules: prev.modules.filter(m => m.id !== id) }));
    }
  };

