    const newLesson: Lesson = {
      id: `l-${Math.random().toString(36).substr(2, 5)}`,
      title: "Nueva Lección Pro",
      duration: "10:00",
      videoUrl: "https://www.youtube.com/embed/dQw4w9WgXcQ",
      description: "### Introducción\nEscribe aquí el contenido de la clase...",
      resources: []
    };
    setEditingCourse(prev => ({
      ...prev,
      modules: prev.modules.map(m => m.id === moduleId ? { ...m, lessons: [...m.lessons, newLesson] } : m)
    }));
    setEditingLessonId(newLesson.id);
  };

  const updateLesson = (lessonId: string, updates: Partial<Lesson>) => {
    setEditingCourse(prev => ({
      ...prev,
      modules: prev.modules.map(m => ({
        ...m,
        lessons: m.lessons.map(l => l.id === lessonId ? { ...l, ...updates } : l)
      }))
    }));
  };

  const deleteLesson = (moduleId: string, lessonId: string) => {
    setEditingCourse(prev => ({
      ...prev,
      modules: prev.modules.map(m => m.id === moduleId ? { ...m, lessons: m.lessons.filter(l => l.id !== lessonId) } : m)
    }));
