                    <p className="text-sm text-gray-600 max-w-xs font-medium">Desde el Architect puedes modificar videos, descripciones en Markdown y recursos descargables.</p>
                  </div>
                )}
              </AnimatePresence>
            </div>
          </div>
        ) : (
          <div className="bg-[#0d0d0d] border border-white/5 rounded-[2.5rem] p-12 overflow-hidden shadow-2xl">
            <h2 className="text-2xl font-black tracking-tighter mb-10 flex items-center gap-4">
