import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Video, FileText 
} from 'lucide-react';
import { Module, Lesson } from '../types';
import { Link } from 'react-router-dom';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [modules, setModules] = useState<Module[]>([]);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchContent();
  }, []);

  async function fetchContent() {
    const { data } = await supabase.from('modules').select('*, lessons(*)').order('order_index');
    if (data) setModules(data);
    setLoading(false);
  }

  const addModule = async () => {
    const title = prompt('Título del nuevo módulo:');
    if (title) {
      await supabase.from('modules').insert({ title, order_index: modules.length });
      fetchContent();
    }
  };

  const deleteModule = async (id: string) => {
    if (confirm('¿Borrar módulo?')) {
      await supabase.from('modules').delete().eq('id', id);
      fetchContent();
    }
  };

  const addLesson = async (moduleId: string) => {
    const title = prompt('Título de la lección:');
    if (title) {
      await supabase.from('lessons').insert({ 
        module_id: moduleId, 
        title, 
        video_url: 'https://...',
        description: 'Nueva clase...'
      });
      fetchContent();
    }
  };

  const updateLesson = async (lesson: Lesson) => {
    await supabase.from('lessons').update({
      title: lesson.title,
      video_url: lesson.video_url,
      description: lesson.description,
      resources: lesson.resources
    }).eq('id', lesson.id);
    fetchContent();
  };

  const deleteLesson = async (id: string) => {
    if (confirm('¿Borrar lección?')) {
      await supabase.from('lessons').delete().eq('id', id);
      fetchContent();
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white">
      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/80 sticky top-0 z-50 backdrop-blur-xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 font-black text-xs uppercase"><ChevronLeft size={16}/> Dashboard</Link>
          <h1 className="text-xl font-black">SYSTEM <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="text-gray-500 hover:text-red-500 transition-colors"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-10 pb-40">
        <div className="flex gap-6 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-8 py-4 rounded-2xl font-black text-xs uppercase border ${activeTab === 'content' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={16} className="inline mr-2"/> Contenido</button>
          <button onClick={() => setActiveTab('users')} className={`px-8 py-4 rounded-2xl font-black text-xs uppercase border ${activeTab === 'users' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={16} className="inline mr-2"/> Usuarios</button>
        </div>

        {activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <div className="lg:col-span-4 space-y-6">
              <div className="flex justify-between items-center px-2">
                <h2 className="text-sm font-black text-gray-500 uppercase tracking-widest">Módulos</h2>
                <button onClick={addModule} className="p-2 bg-red-600/10 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all"><Plus/></button>
              </div>
              {modules.map(mod => (
                <div key={mod.id} className="bg-[#0d0d0d] border border-white/5 rounded-2xl overflow-hidden">
                  <div className="p-4 flex justify-between bg-white/5 border-b border-white/5">
                    <span className="font-bold text-sm">{mod.title}</span>
                    <button onClick={() => deleteModule(mod.id)} className="text-gray-600 hover:text-red-500"><Trash2 size={14}/></button>
                  </div>
                  <div className="p-4 space-y-2">
                    {mod.lessons?.map(l => (
                      <button key={l.id} onClick={() => setEditingLessonId(l.id)} className={`w-full flex justify-between p-3 rounded-xl border text-xs font-bold ${editingLessonId === l.id ? 'bg-red-600/10 border-red-600/30' : 'bg-black/40 border-transparent hover:bg-white/5'}`}>
                        <span className="truncate pr-4">{l.title}</span>
                        <Edit3 size={12} className="opacity-40"/>
                      </button>
                    ))}
                    <button onClick={() => addLesson(mod.id)} className="w-full py-2 border-2 border-dashed border-white/5 rounded-xl text-[9px] font-black uppercase text-gray-700 hover:text-red-600 transition-all">+ Lección</button>
                  </div>
                </div>
              ))}
            </div>

            <div className="lg:col-span-8">
              {editingLessonId ? (
                <div className="bg-[#0d0d0d] border border-white/5 rounded-[2.5rem] p-10 space-y-10 sticky top-32">
                  {(() => {
                    const l = modules.flatMap(m => m.lessons).find(les => les.id === editingLessonId);
                    if (!l) return null;
                    return (
                      <>
                        <div className="flex justify-between">
                          <h2 className="text-2xl font-black italic underline decoration-red-600 decoration-4">Architect Mode</h2>
                          <button onClick={() => setEditingLessonId(null)} className="text-gray-500"><X/></button>
                        </div>
                        <div className="space-y-6">
                          <input type="text" value={l.title} onChange={(e) => { l.title = e.target.value; setModules([...modules]); }} className="w-full bg-black border border-white/10 rounded-xl p-4 font-bold focus:border-red-600 outline-none" placeholder="Título"/>
                          <input type="text" value={l.video_url} onChange={(e) => { l.video_url = e.target.value; setModules([...modules]); }} className="w-full bg-black border border-white/10 rounded-xl p-4 text-xs font-mono" placeholder="Embed URL"/>
                          <textarea value={l.description} onChange={(e) => { l.description = e.target.value; setModules([...modules]); }} rows={8} className="w-full bg-black border border-white/10 rounded-xl p-4 text-sm text-gray-400 font-mono resize-none" placeholder="Markdown..."/>
                          <button onClick={() => updateLesson(l)} className="w-full bg-red-600 py-4 rounded-xl font-black uppercase tracking-widest shadow-lg shadow-red-600/20 active:scale-95 transition-all">Sincronizar Lección</button>
                          <button onClick={() => deleteLesson(l.id)} className="w-full bg-transparent border border-red-600/20 text-red-500 py-4 rounded-xl font-black uppercase text-[10px] hover:bg-red-600 hover:text-white transition-all">Borrar permanentemente</button>
                        </div>
                      </>
                    );
                  })()}
                </div>
              ) : (
                <div className="h-full min-h-[400px] border-2 border-dashed border-white/5 rounded-[3rem] flex flex-col items-center justify-center text-gray-700">
                  <Video size={48} className="mb-4 opacity-20"/>
                  <p className="font-black uppercase tracking-widest text-xs">Selecciona para editar</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0d0d0d] border border-white/5 rounded-3xl p-12 text-center text-gray-600">
            <Users size={48} className="mx-auto mb-4 opacity-20"/>
            <p className="font-black text-xs uppercase tracking-widest">Gestión de alumnos en desarrollo vía Supabase Dashboard</p>
          </div>
        )}
      </div>
    </div>
  );
};

