import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Admin from './pages/Admin';
import { User } from './types';
import { supabase, ADMIN_EMAIL } from './lib/supabase';
import { ShieldAlert, Home, LogOut } from 'lucide-react';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Verificar sesión inicial
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        mapSupabaseUser(session.user);
      } else {
        setLoading(false);
      }
    });

    // Escuchar cambios de estado
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        mapSupabaseUser(session.user);
      } else {
        setUser(null);
        setLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const mapSupabaseUser = (sbUser: any) => {
    const isAdmin = sbUser.email === ADMIN_EMAIL;
    setUser({
      id: sbUser.id,
      email: sbUser.email || '',
      fullName: sbUser.user_metadata?.full_name || sbUser.email?.split('@')[0],
      role: isAdmin ? 'admin' : 'student',
      progress: [],
    });
    setLoading(false);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center gap-6">
        <div className="relative w-16 h-16">
          <div className="absolute inset-0 border-4 border-red-600/20 rounded-full" />
          <div className="absolute inset-0 border-4 border-red-600 border-t-transparent rounded-full animate-spin" />
        </div>
        <div className="text-center">
          <p className="text-white font-black uppercase tracking-[0.3em] text-xs">Anon Academy</p>
          <p className="text-gray-600 text-[10px] mt-2 animate-pulse">AUTENTICANDO SESIÓN...</p>
        </div>
      </div>
    );
  }

  // Componente de Acceso Denegado
  const AccessDenied = () => (
    <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center">
      <div className="w-20 h-20 bg-red-600/10 border border-red-600/20 rounded-full flex items-center justify-center mb-6">
        <ShieldAlert size={40} className="text-red-600" />
      </div>
      <h1 className="text-3xl font-black mb-4">ACCESO DENEGADO</h1>
      <p className="text-gray-500 max-w-md mb-8">
        No tienes privilegios de administrador para acceder a esta sección. 
        Si crees que esto es un error, contacta con el soporte técnico.
      </p>
      <div className="flex gap-4">
        <button 
          onClick={() => window.location.hash = '#/dashboard'}
          className="flex items-center gap-2 bg-white text-black px-6 py-3 rounded-xl font-bold hover:bg-gray-200 transition-all"
        >
          <Home size={18} /> Volver al Inicio
        </button>
        <button 
          onClick={handleLogout}
          className="flex items-center gap-2 bg-red-600/10 text-red-500 px-6 py-3 rounded-xl font-bold hover:bg-red-600 hover:text-white transition-all border border-red-600/20"
        >
          <LogOut size={18} /> Cerrar Sesión
        </button>
      </div>
    </div>
  );

  return (
    <Router>
      <Routes>
        <Route 
          path="/" 
          element={user ? <Navigate to="/dashboard" /> : <Login />} 
        />
        <Route 
          path="/dashboard" 
          element={user ? <Dashboard user={user} onLogout={handleLogout} /> : <Navigate to="/" />} 
        />
        <Route 
          path="/admin" 
          element={
            user ? (
              user.role === 'admin' ? <Admin onLogout={handleLogout} /> : <AccessDenied />
            ) : (
              <Navigate to="/" />
            )
          } 
        />
        {/* Redirección por defecto */}
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Mail, Lock, User as UserIcon, ShieldCheck, AlertCircle, Loader2 } from 'lucide-react';
import { supabase } from '../lib/supabase';

const Login: React.FC = () => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccessMsg(null);

    try {
      if (isRegistering) {
        // 1. Registro en Auth
        const { data, error: signUpError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: { full_name: name }
          }
        });

        if (signUpError) throw signUpError;

        // 2. Crear perfil en tabla 'profiles' (opcional según tu esquema)
        if (data.user) {
          const { error: profileError } = await supabase
            .from('profiles')
            .insert([
              { id: data.user.id, full_name: name, role: 'user' }
            ]);

          // No lanzamos error aquí para no bloquear el registro si la tabla no existe aún
          console.log("Perfil creado o ignorado", profileError);
        }

        setSuccessMsg('¡Cuenta creada! Revisa tu email para confirmar o intenta iniciar sesión.');
        setIsRegistering(false);
      } else {
        // Inicio de sesión
        const { error: signInError } = await supabase.auth.signInWithPassword({
          email,
          password,
        });

        if (signInError) {
          if (signInError.message.includes('Email not confirmed')) {
            throw new Error('Debes confirmar tu correo electrónico antes de entrar.');
          }
          if (signInError.message.includes('Invalid login credentials')) {
            throw new Error('Credenciales incorrectas. Revisa tu email y contraseña.');
          }
          throw signInError;
        }
      }
    } catch (err: any) {
      setError(err.message || 'Ocurrió un error inesperado.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-6 bg-black selection:bg-red-600 selection:text-white">
      {/* Fondo decorativo */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-red-600/10 blur-[120px] rounded-full" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-red-900/10 blur-[120px] rounded-full" />
      </div>

      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md bg-[#0d0d0d] border border-white/5 p-10 rounded-[2.5rem] shadow-2xl relative z-10"
      >
        <div className="mb-10 text-center">
          <motion.div 
            initial={{ scale: 0.8 }}
            animate={{ scale: 1 }}
            className="text-4xl font-black tracking-tighter text-red-600 mb-3"
          >
            ANON<span className="text-white">ACADEMY</span>
          </motion.div>
          <p className="text-gray-500 text-sm font-medium tracking-tight">Plataforma de Educación de Alto Rendimiento</p>
        </div>

        <AnimatePresence mode="wait">
          {error && (
            <motion.div 
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
