import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Video, FileText, Loader2
} from 'lucide-react';
import { Module, Lesson } from '../types';
import { Link } from 'react-router-dom';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [modules, setModules] = useState<Module[]>([]);
  const [editingLessonId, setEditingLessonId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    fetchContent();
  }, []);

  async function fetchContent() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('modules')
        .select('*, lessons(*)')
        .order('order_index');

      if (error) {
        console.error("Error al cargar contenido:", error);
        // Si hay un error, lo mostramos para diagnosticar (ej. tabla inexistente)
        if (error.code === '42P01') {
          alert("ERROR CRÍTICO: La tabla 'modules' no existe en tu base de datos de Supabase.");
        }
      } else {
        setModules(data || []);
      }
    } catch (err) {
      console.error("Error inesperado:", err);
    } finally {
      setLoading(false);
    }
  }

  const addModule = async () => {
    const title = window.prompt('Introduce el título para el nuevo módulo:');

    if (title && title.trim() !== "") {
      setIsProcessing(true);
      try {
        const { data, error } = await supabase
          .from('modules')
          .insert({ 
            title: title.trim(), 
            order_index: modules.length 
          })
          .select();

        if (error) {
          console.error("Error de Supabase al insertar módulo:", error);
          alert(`Error al crear módulo: ${error.message}\nCódigo: ${error.code}`);
        } else {
          console.log("Módulo creado exitosamente:", data);
          await fetchContent(); // Recargar la lista
        }
      } catch (err: any) {
        alert("Error inesperado en la aplicación: " + err.message);
      } finally {
        setIsProcessing(false);
      }
    }
  };

  const deleteModule = async (id: string) => {
    if (window.confirm('¿Estás seguro de que deseas eliminar este módulo y todas sus lecciones?')) {
      const { error } = await supabase.from('modules').delete().eq('id', id);
      if (error) {
        alert("Error al eliminar: " + error.message);
      } else {
        fetchContent();
      }
    }
  };

  const addLesson = async (moduleId: string) => {
    const title = window.prompt('Título de la nueva lección:');
    if (title && title.trim() !== "") {
      const { error } = await supabase.from('lessons').insert({ 
        module_id: moduleId, 
        title: title.trim(), 
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '### Nueva Clase\nEscribe aquí el contenido de la lección usando Markdown.',
        order_index: 0
      });

      if (error) {
        alert("Error al crear lección: " + error.message);
      } else {
        fetchContent();
      }
    }
  };

  const updateLesson = async (lesson: Lesson) => {
    setIsProcessing(true);
    const { error } = await supabase.from('lessons').update({
      title: lesson.title,
      video_url: lesson.video_url,
      description: lesson.description,
      resources: lesson.resources
    }).eq('id', lesson.id);

    if (error) {
      alert("Error al guardar cambios: " + error.message);
    } else {
      alert("✅ Cambios sincronizados con éxito");
      fetchContent();
    }
    setIsProcessing(false);
  };

  const deleteLesson = async (id: string) => {
    if (window.confirm('¿Borrar lección permanentemente?')) {
      const { error } = await supabase.from('lessons').delete().eq('id', id);
      if (error) {
        alert("Error al borrar lección: " + error.message);
      } else {
        setEditingLessonId(null);
        fetchContent();
      }
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white">
      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/80 sticky top-0 z-50 backdrop-blur-xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-xs uppercase">
            <ChevronLeft size={16}/> Dashboard
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter italic">SYSTEM <span className="text-red-600">ADMIN</span></h1>
        </div>
        <div className="flex items-center gap-4">
          {isProcessing && <Loader2 className="animate-spin text-red-600" size={20} />}
          <button onClick={onLogout} className="p-2 text-gray-500 hover:text-red-500 transition-colors">
            <LogOut size={20}/>
          </button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-10 pb-40">
        <div className="flex gap-6 mb-16">
          <button 
            onClick={() => setActiveTab('content')} 
            className={`px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest border transition-all ${activeTab === 'content' ? 'bg-white text-black border-white' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}
          >
            <BookOpen size={16} className="inline mr-2"/> Contenido Académico
          </button>
          <button 
            onClick={() => setActiveTab('users')} 
            className={`px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest border transition-all ${activeTab === 'users' ? 'bg-white text-black border-white' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}
          >
            <Users size={16} className="inline mr-2"/> Control de Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4 opacity-50">
            <Loader2 className="animate-spin text-red-600" size={40} />
            <p className="text-[10px] font-black uppercase tracking-widest">Sincronizando Base de Datos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            {/* LISTA DE MÓDULOS */}
            <div className="lg:col-span-4 space-y-6">
              <div className="flex justify-between items-center px-2">
                <h2 className="text-xs font-black text-gray-500 uppercase tracking-[0.2em]">Módulos ({modules.length})</h2>
                <button 
                  onClick={addModule} 
                  disabled={isProcessing}
                  className="p-2.5 bg-red-600/10 text-red-600 rounded-xl hover:bg-red-600 hover:text-white transition-all border border-red-600/20 active:scale-90"
                >
                  <Plus size={20}/>
                </button>
              </div>

              <div className="space-y-4">
                {modules.length === 0 && (
                  <div className="p-10 border-2 border-dashed border-white/5 rounded-3xl text-center">
                    <p className="text-[10px] font-black text-gray-700 uppercase">Sin módulos creados</p>
                  </div>
                )}

                {modules.map(mod => (
                  <div key={mod.id} className="bg-[#0d0d0d] border border-white/5 rounded-[2rem] overflow-hidden group shadow-xl">
                    <div className="p-5 flex justify-between bg-white/[0.02] border-b border-white/5 items-center">
                      <span className="font-black text-xs uppercase tracking-tight text-gray-300">{mod.title}</span>
                      <button onClick={() => deleteModule(mod.id)} className="text-gray-700 hover:text-red-500 transition-colors"><Trash2 size={16}/></button>
                    </div>
                    <div className="p-4 space-y-2 bg-black/40">
                      {mod.lessons?.map(l => (
                        <button 
                          key={l.id} 
                          onClick={() => setEditingLessonId(l.id)} 
                          className={`w-full flex justify-between p-3.5 rounded-2xl border text-[11px] font-bold transition-all ${editingLessonId === l.id ? 'bg-red-600/10 border-red-600/30 text-white shadow-lg shadow-red-600/5' : 'bg-black/40 border-transparent text-gray-500 hover:text-gray-300 hover:bg-white/5'}`}
                        >
                          <span className="truncate pr-4 uppercase tracking-tight">{l.title}</span>
                          <Edit3 size={14} className="opacity-40 flex-shrink-0"/>
                        </button>
                      ))}
                      <button 
                        onClick={() => addLesson(mod.id)} 
                        className="w-full py-3 border-2 border-dashed border-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-700 hover:text-red-600 hover:border-red-600/30 transition-all active:scale-95"
                      >
                        + Nueva Lección
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR DE LECCIONES */}
            <div className="lg:col-span-8">
              {editingLessonId ? (
                <div className="bg-[#0d0d0d] border border-white/5 rounded-[3rem] p-10 space-y-10 sticky top-32 shadow-2xl overflow-hidden">
                  {(() => {
                    const l = modules.flatMap(m => m.lessons).find(les => les.id === editingLessonId);
                    if (!l) return <div className="text-center py-20 text-gray-500">Lección no encontrada</div>;

                    return (
                      <>
                        <div className="flex justify-between items-center">
                          <div className="space-y-1">
                            <h2 className="text-3xl font-black tracking-tighter">Architect <span className="text-red-600">Mode</span></h2>
                            <p className="text-[10px] text-gray-600 font-bold uppercase tracking-widest">Editando: {l.title}</p>
                          </div>
                          <button onClick={() => setEditingLessonId(null)} className="p-3 bg-white/5 hover:bg-white/10 rounded-full text-gray-500 transition-all"><X/></button>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                          <div className="space-y-6">
                            <div className="space-y-2">
                              <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-1">Título de la clase</label>
                              <input 
                                type="text" 
                                value={l.title} 
                                onChange={(e) => { l.title = e.target.value; setModules([...modules]); }} 
                                className="w-full bg-black border border-white/10 rounded-2xl p-4 font-bold focus:border-red-600 outline-none transition-all" 
                                placeholder="Ej. Fundamentos de Backend"
                              />
                            </div>
                            <div className="space-y-2">
                              <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-1">Video Embed URL (YouTube/Vimeo)</label>
                              <div className="relative">
                                <Video size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-700" />
                                <input 
                                  type="text" 
                                  value={l.video_url} 
                                  onChange={(e) => { l.video_url = e.target.value; setModules([...modules]); }} 
                                  className="w-full bg-black border border-white/10 rounded-2xl pl-12 pr-4 py-4 text-xs font-mono text-gray-400 focus:border-red-600 outline-none transition-all" 
                                  placeholder="https://www.youtube.com/embed/..."
                                />
                              </div>
                            </div>
                            <div className="space-y-2">
                              <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-1">Duración</label>
                              <input 
                                type="text" 
                                value={l.duration || '10:00'} 
                                onChange={(e) => { l.duration = e.target.value; setModules([...modules]); }} 
                                className="w-full bg-black border border-white/10 rounded-2xl p-4 font-bold text-sm focus:border-red-600 outline-none transition-all" 
                                placeholder="00:00"
                              />
                            </div>
                          </div>

                          <div className="space-y-2">
                            <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-1">Descripción de la clase (Markdown)</label>
                            <textarea 
                              value={l.description} 
                              onChange={(e) => { l.description = e.target.value; setModules([...modules]); }} 
                              rows={10} 
                              className="w-full bg-black border border-white/10 rounded-2xl p-5 text-sm text-gray-400 font-mono resize-none focus:border-red-600 outline-none transition-all h-[260px]" 
                              placeholder="Escribe el contenido..."
                            />
                          </div>
                        </div>

                        <div className="flex flex-col sm:flex-row gap-4 pt-6 border-t border-white/5">
                          <button 
                            onClick={() => updateLesson(l)} 
                            disabled={isProcessing}
                            className="flex-1 bg-red-600 hover:bg-red-700 text-white py-4 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-red-600/20 active:scale-[0.98] transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                          >
                            <Save size={18}/> Guardar Cambios
                          </button>
                          <button 
                            onClick={() => deleteLesson(l.id)} 
                            disabled={isProcessing}
                            className="bg-transparent border border-red-600/30 text-red-600 px-8 py-4 rounded-2xl font-black uppercase text-[10px] hover:bg-red-600 hover:text-white transition-all disabled:opacity-50"
                          >
                            Eliminar
                          </button>
                        </div>
                      </>
                    );
                  })()}
                </div>
              ) : (
                <div className="h-full min-h-[500px] border-2 border-dashed border-white/5 rounded-[3.5rem] flex flex-col items-center justify-center text-gray-800 p-20 text-center">
                  <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mb-6">
                    <Video size={32} className="opacity-20"/>
                  </div>
                  <h3 className="text-lg font-black text-gray-600 uppercase tracking-tighter mb-2">Editor de Contenido</h3>
                  <p className="text-xs font-bold max-w-xs leading-relaxed opacity-40 uppercase tracking-widest">Selecciona una lección para modificar sus videos, descripciones y materiales.</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0d0d0d] border border-white/5 rounded-[3rem] p-20 text-center shadow-2xl">
            <div className="w-24 h-24 bg-red-600/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-red-600/20">
              <Users size={40} className="text-red-600" />
            </div>
            <h2 className="text-2xl font-black mb-4">Gestión de Alumnos</h2>
            <p className="text-gray-600 max-w-md mx-auto text-sm font-medium leading-relaxed mb-10">
              Actualmente, la gestión avanzada de usuarios (autorizaciones manuales) se realiza directamente desde el **Supabase Dashboard** para garantizar la seguridad de los datos.
            </p>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-3xl mx-auto">
              {[
                { label: 'Total Alumnos', val: '0' },
                { label: 'Activos Hoy', val: '0' },
                { label: 'Completados', val: '0' }
              ].map((stat, i) => (
                <div key={i} className="p-6 bg-black border border-white/5 rounded-2xl">
                  <p className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-1">{stat.label}</p>
                  <p className="text-2xl font-black text-white">{stat.val}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Mail, Lock, User as UserIcon, ShieldCheck, AlertCircle, Loader2, Youtube } from 'lucide-react';
import { supabase } from '../lib/supabase';

const Login: React.FC = () => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccessMsg(null);

    try {
      if (isRegistering) {
        const { data, error: signUpError } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: { full_name: name }
          }
        });

        if (signUpError) throw signUpError;

        if (data.user) {
          await supabase.from('profiles').insert([{ id: data.user.id, full_name: name, role: 'user' }]);
        }

        setSuccessMsg('¡Cuenta creada! Revisa tu email para confirmar o intenta iniciar sesión.');
        setIsRegistering(false);
      } else {
        const { error: signInError } = await supabase.auth.signInWithPassword({ email, password });
        if (signInError) {
          if (signInError.message.includes('Email not confirmed')) throw new Error('Debes confirmar tu correo electrónico antes de entrar.');
          if (signInError.message.includes('Invalid login credentials')) throw new Error('Credenciales incorrectas. Revisa tu email y contraseña.');
          throw signInError;
        }
      }
    } catch (err: any) {
      setError(err.message || 'Ocurrió un error inesperado.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen w-full flex bg-[#050505] overflow-hidden selection:bg-red-600 selection:text-white">

      {/* SECCIÓN IZQUIERDA: ANIMACIÓN 3D & VISUALS */}
      <div className="hidden lg:flex flex-1 relative items-center justify-center overflow-hidden border-r border-white/5">
        {/* Luces de fondo (Efectos Rojos) */}
        <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-red-600/20 blur-[160px] rounded-full animate-pulse" />
        <div className="absolute bottom-1/4 right-1/4 w-80 h-80 bg-red-900/10 blur-[120px] rounded-full" />

        {/* Contenedor 3D del Logo */}
        <motion.div 
          style={{ perspective: 1000 }}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 1.5 }}
          className="relative z-10"
        >
          <motion.div
            animate={{ 
              rotateY: [0, 15, -15, 0],
              rotateX: [0, 10, -10, 0],
              y: [-10, 10, -10]
            }}
            transition={{ 
              duration: 8, 
              repeat: Infinity, 
              ease: "easeInOut" 
            }}
            className="relative"
          >
            {/* Glow del logo */}
            <div className="absolute inset-0 bg-red-600 blur-[60px] opacity-20 scale-125" />

            {/* Icono Youtube Grande */}
            <div className="relative bg-gradient-to-br from-red-600 to-red-900 p-12 rounded-[3rem] shadow-[0_0_100px_rgba(220,38,38,0.3)] border border-white/20">
              <Youtube size={160} color="white" strokeWidth={1.5} />
            </div>

            {/* Partículas Flotantes */}
            {[...Array(6)].map((_, i) => (
              <motion.div
                key={i}
                animate={{ 
                  y: [0, -40, 0], 
                  opacity: [0, 1, 0],
                  scale: [0.5, 1, 0.5]
                }}
                transition={{ 
                  duration: 3 + i, 
                  repeat: Infinity, 
                  delay: i * 0.5 
                }}
