      .from('modules')
      .select('*, lessons(*)')
      .order('order_index');

    if (data) {
      setModules(data);
      if (data.length > 0 && data[0].lessons?.length > 0) {
        setActiveLesson(data[0].lessons[0]);
        setExpandedModules([data[0].id]);
      }
    }
    setLoading(false);
  }

  async function fetchProgress() {
    const { data } = await supabase
      .from('user_progress')
      .select('lesson_id')
      .eq('user_id', user.id);

    if (data) setProgress(data.map((p: any) => p.lesson_id));
  }

  const onToggleProgress = async (lessonId: string) => {
    const isCompleted = progress.includes(lessonId);
    if (isCompleted) {
      await supabase.from('user_progress').delete().eq('user_id', user.id).eq('lesson_id', lessonId);
      setProgress(prev => prev.filter(id => id !== lessonId));
    } else {
      await supabase.from('user_progress').insert({ user_id: user.id, lesson_id: lessonId });
      setProgress(prev => [...prev, lessonId]);
    }
  };

  const totalLessons = useMemo(() => modules.reduce((acc, mod) => acc + (mod.lessons?.length || 0), 0), [modules]);
  const progressPercent = totalLessons > 0 ? Math.round((progress.length / totalLessons) * 100) : 0;

  const htmlDescription = useMemo(() => {
    return activeLesson ? marked.parse(activeLesson.description || '') : '';
  }, [activeLesson]);

  if (loading) return (
    <div className="min-h-screen bg-black flex items-center justify-center">
      <div className="w-8 h-8 border-4 border-red-600 border-t-transparent rounded-full animate-spin" />
    </div>
  );

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white flex flex-col">
      <nav className="fixed top-0 w-full z-50 bg-black/60 backdrop-blur-2xl border-b border-white/5 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-6">
          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 hover:bg-white/10 rounded-xl">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
          <div className="text-2xl font-black tracking-tighter flex items-center gap-2">
            <span className="text-red-600">EZEH</span><span className="text-white hidden sm:inline">ACADEMY</span>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end gap-1.5">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Progreso Total</span>
              <span className="text-xs font-bold text-red-500">{progressPercent}%</span>
            </div>
            <div className="w-40 h-1.5 bg-white/10 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} className="h-full bg-red-600" />
            </div>
          </div>

          <div className="flex items-center gap-4">
            {user.role === 'admin' && (
              <Link to="/admin" className="p-2 text-gray-400 hover:text-white"><Settings size={20} /></Link>
            )}
            <button onClick={onLogout} className="text-gray-400 hover:text-red-500"><LogOut size={18} /></button>
            <div className="w-10 h-10 rounded-full bg-red-600 flex items-center justify-center font-black text-sm">{user.fullName.charAt(0)}</div>
          </div>
        </div>
      </nav>

      <div className="flex flex-1 pt-[72px] h-screen overflow-hidden">
        <AnimatePresence>
          {isSidebarOpen && (
            <motion.aside initial={{ x: -350 }} animate={{ x: 0 }} exit={{ x: -350 }} className="w-full lg:w-[350px] bg-[#0d0d0d] border-r border-white/5 overflow-y-auto custom-scrollbar">
              <div className="p-6">
                <h2 className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-6">Contenido</h2>
                {modules.map((module, mIdx) => (
                  <div key={module.id} className="mb-4">
                    <button onClick={() => setExpandedModules(prev => prev.includes(module.id) ? prev.filter(i => i !== module.id) : [...prev, module.id])} className="w-full flex justify-between p-3 rounded-xl hover:bg-white/5">
                      <div className="text-left">
                        <p className="text-[9px] font-black text-red-600">MÓDULO {mIdx + 1}</p>
                        <h3 className="text-sm font-bold">{module.title}</h3>
                      </div>
                      <ChevronDown className={`transition-transform ${expandedModules.includes(module.id) ? 'rotate-180' : ''}`} />
                    </button>
                    {expandedModules.includes(module.id) && module.lessons?.map(lesson => (
                      <button key={lesson.id} onClick={() => setActiveLesson(lesson)} className={`w-full flex items-center gap-4 p-4 pl-6 text-left ${activeLesson?.id === lesson.id ? 'text-white' : 'text-gray-500'}`}>
                        {progress.includes(lesson.id) ? <CheckCircle className="text-green-500" size={14} /> : <Play size={14} />}
                        <span className="text-xs font-bold truncate">{lesson.title}</span>
                      </button>
                    ))}
                  </div>
                ))}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        <main className="flex-1 overflow-y-auto bg-black p-4 lg:p-12">
          {activeLesson ? (
            <div className="max-w-5xl mx-auto">
              <div className="aspect-video bg-[#111] rounded-[2rem] overflow-hidden border border-white/5 mb-10">
                <iframe src={activeLesson.video_url} className="w-full h-full" allowFullScreen />
              </div>
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                <div className="lg:col-span-2">
                  <h1 className="text-4xl font-black mb-6">{activeLesson.title}</h1>
                  <div className="prose prose-invert" dangerouslySetInnerHTML={{ __html: htmlDescription }} />
                </div>
                <div className="space-y-6">
                  <button onClick={() => onToggleProgress(activeLesson.id)} className={`w-full py-4 rounded-2xl font-black ${progress.includes(activeLesson.id) ? 'bg-green-600/10 text-green-500' : 'bg-white text-black'}`}>
                    {progress.includes(activeLesson.id) ? 'Completado' : 'Marcar visto'}
                  </button>
                  <div className="p-6 bg-[#0d0d0d] border border-white/5 rounded-2xl">
                    <h3 className="text-xs font-black uppercase text-gray-500 mb-4">Materiales</h3>
                    {(activeLesson.resources as any[])?.length > 0 ? (activeLesson.resources as any[]).map((r, i) => (
                      <a key={i} href={r.url} className="flex items-center gap-3 p-3 bg-white/5 rounded-xl text-xs hover:bg-white/10 mb-2"><FileText size={14}/> {r.name}</a>
                    )) : <p className="text-[10px] text-gray-600">No hay archivos.</p>}
                  </div>
                </div>
              </div>
            </div>
          ) : <div className="text-center text-gray-500">Selecciona una clase</div>}
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

