                {modules.length === 0 ? (
                  <p className="text-[10px] text-gray-600 font-bold uppercase tracking-widest text-center py-10">Cargando módulos...</p>
                ) : modules.map((module, mIdx) => (
                  <div key={module.id} className="mb-4">
                    <button 
                      onClick={() => setExpandedModules(prev => prev.includes(module.id) ? prev.filter(i => i !== module.id) : [...prev, module.id])} 
                      className="w-full flex justify-between p-3 rounded-xl hover:bg-white/5 transition-colors group"
                    >
                      <div className="text-left">
                        <p className="text-[9px] font-black text-red-600 uppercase">MÓDULO {mIdx + 1}</p>
                        <h3 className="text-sm font-bold group-hover:text-red-500 transition-colors">{module.title}</h3>
                      </div>
                      <ChevronDown size={18} className={`transition-transform text-gray-600 ${expandedModules.includes(module.id) ? 'rotate-180 text-white' : ''}`} />
                    </button>
                    {expandedModules.includes(module.id) && module.lessons?.map(lesson => (
                      <button 
                        key={lesson.id} 
                        onClick={() => setActiveLesson(lesson)} 
                        className={`w-full flex items-center gap-4 p-4 pl-6 text-left transition-all rounded-xl mt-1 ${activeLesson?.id === lesson.id ? 'bg-red-600/10 text-white font-bold' : 'text-gray-500 hover:bg-white/5'}`}
                      >
                        {progress.includes(lesson.id) ? <CheckCircle className="text-green-500" size={14} /> : <Play size={14} className={activeLesson?.id === lesson.id ? "text-red-500" : ""} />}
                        <span className="text-xs truncate">{lesson.title}</span>
                      </button>
                    ))}
                  </div>
                ))}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        <main className="flex-1 overflow-y-auto bg-black p-4 lg:p-12 custom-scrollbar">
          {activeLesson ? (
            <div className="max-w-5xl mx-auto">
              <div className="aspect-video bg-[#111] rounded-[2rem] overflow-hidden border border-white/5 mb-10 shadow-2xl shadow-red-900/5">
                <iframe 
                  src={activeLesson.video_url} 
                  className="w-full h-full" 
                  allowFullScreen 
                  title={activeLesson.title}
                />
              </div>
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                <div className="lg:col-span-2">
                  <div className="flex items-center gap-3 mb-2">
                    <span className="px-3 py-1 bg-red-600/10 text-red-500 text-[10px] font-black uppercase tracking-widest rounded-full">Lección Actual</span>
                    <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest flex items-center gap-1"><Clock size={12}/> {activeLesson.duration || '10:00'}</span>
                  </div>
                  <h1 className="text-4xl font-black mb-6 tracking-tighter">{activeLesson.title}</h1>
                  <div 
                    className="prose prose-invert max-w-none text-gray-400" 
                    dangerouslySetInnerHTML={{ __html: htmlDescription }} 
                  />
                </div>
                <div className="space-y-6">
                  <button 
                    onClick={() => onToggleProgress(activeLesson.id)} 
                    className={`w-full py-4 rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all shadow-xl ${progress.includes(activeLesson.id) ? 'bg-green-600/10 text-green-500 border border-green-600/20' : 'bg-white text-black hover:bg-red-600 hover:text-white active:scale-95'}`}
                  >
                    {progress.includes(activeLesson.id) ? '✓ Completado' : 'Marcar como Visto'}
                  </button>
                  <div className="p-8 bg-[#0d0d0d] border border-white/5 rounded-[2.5rem] shadow-xl">
                    <h3 className="text-xs font-black uppercase text-gray-500 mb-6 tracking-widest flex items-center gap-2">
                      <FileText size={14} className="text-red-600"/> Recursos de la Clase
                    </h3>
                    {(activeLesson.resources as any[])?.length > 0 ? (activeLesson.resources as any[]).map((r, i) => (
                      <a 
                        key={i} 
                        href={r.url} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="flex items-center justify-between p-4 bg-white/5 rounded-2xl text-[11px] font-bold hover:bg-white/10 transition-all mb-3 group border border-transparent hover:border-red-600/30"
                      >
                        <span className="flex items-center gap-3"><FileText size={14} className="text-gray-500 group-hover:text-red-600"/> {r.name}</span>
                        <ExternalLink size={12} className="text-gray-700 group-hover:text-white"/>
                      </a>
                    )) : (
                      <div className="text-center py-6 opacity-30">
                        <p className="text-[9px] font-black uppercase">No hay archivos adicionales</p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-gray-800 p-20 text-center">
               <Play size={48} className="opacity-10 mb-6" />
               <h3 className="text-lg font-black uppercase tracking-widest">Selecciona una clase</h3>
               <p className="text-xs font-bold opacity-30 mt-2">Navega por los módulos para comenzar tu formación.</p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

