                                placeholder="Ej. Fundamentos de Backend"
                              />
                            </div>
                            <div className="space-y-2">
                              <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-1">URL de Video (YouTube/Vimeo)</label>
                              <div className="relative">
                                <Video size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-700" />
                                <input 
