                              value={l.description} 
                              onChange={(e) => { l.description = e.target.value; setModules([...modules]); }} 
                              rows={10} 
                              className="w-full bg-black border border-white/10 rounded-2xl p-5 text-sm text-gray-400 font-mono resize-none focus:border-red-600 outline-none transition-all h-[260px] custom-scrollbar" 
                              placeholder="Escribe el contenido detallado aquí..."
                            />
                          </div>
                        </div>

                        <div className="flex flex-col sm:flex-row gap-4 pt-6 border-t border-white/5">
                          <button 
                            onClick={() => updateLesson(l)} 
                            disabled={isProcessing}
                            className="flex-1 bg-red-600 hover:bg-red-700 text-white py-4 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-red-600/20 active:scale-[0.98] transition-all flex items-center justify-center gap-3 disabled:opacity-50"
                          >
                            <Save size={18}/> Guardar Cambios
                          </button>
                          <button 
                            onClick={() => deleteLesson(l.id)} 
                            disabled={isProcessing}
                            className="bg-transparent border border-red-600/30 text-red-600 px-8 py-4 rounded-2xl font-black uppercase text-[10px] hover:bg-red-600 hover:text-white transition-all disabled:opacity-50"
                          >
                            Eliminar Lección
                          </button>
