              ) : (
                <div className="h-full min-h-[500px] border-2 border-dashed border-white/5 rounded-[3.5rem] flex flex-col items-center justify-center text-gray-800 p-20 text-center">
                  <div className="w-20 h-20 bg-white/5 rounded-full flex items-center justify-center mb-6">
                    <Video size={32} className="opacity-20"/>
                  </div>
                  <h3 className="text-lg font-black text-gray-600 uppercase tracking-tighter mb-2">Editor de Lecciones</h3>
                  <p className="text-xs font-bold max-w-xs leading-relaxed opacity-40 uppercase tracking-widest">Selecciona cualquier lección de la lista para modificar su contenido, videos o duración.</p>
