        ) : (
          <div className="bg-[#0d0d0d] border border-white/5 rounded-[3rem] p-20 text-center shadow-2xl">
            <div className="w-24 h-24 bg-red-600/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-red-600/20">
              <Users size={40} className="text-red-600" />
