  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);

  useEffect(() => {
    fetchContent();
  }, []);

  async function fetchContent() {
    console.log('DEBUG: Iniciando fetchContent...');
    setLoading(true);
    setLastError(null);
    try {
      const { data, error } = await supabase
        .from('modules')
        .select('*, lessons(*)')
        .order('order_index');

      if (error) {
        console.error("DEBUG ERROR fetchContent:", error);
        throw error;
      }

      // Ordenar lecciones por order_index localmente para asegurar consistencia
      const sortedData = (data || []).map(mod => ({
        ...mod,
        lessons: (mod.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
      }));

      console.log('DEBUG: Contenido cargado con éxito:', sortedData);
      setModules(sortedData);
    } catch (err: any) {
      const msg = err.message || JSON.stringify(err);
      console.error("DEBUG ERROR CATCH fetchContent:", msg);
      setLastError(`Error de carga: ${msg}`);
    } finally {
      setLoading(false);
    }
  }

  const addModule = async () => {
    console.log('DEBUG: Botón "Crear Módulo" presionado.');
    const title = window.prompt('Introduce el título para el nuevo módulo:');

    if (!title || !title.trim()) {
      console.log('DEBUG: Creación de módulo cancelada por el usuario o título vacío.');
      return;
    }

    setIsProcessing(true);
    console.log('DEBUG: Iniciando inserción de módulo en Supabase...');

    try {
      const payload = { 
        title: title.trim(), 
        order_index: modules.length 
      };
      console.log('DEBUG: Payload módulo:', payload);

      const { data, error } = await supabase
        .from('modules')
        .insert(payload)
        .select();

      if (error) {
        console.error("DEBUG ERROR Supabase Insert Module:", error);
        alert(`❌ ERROR DE BASE DE DATOS:\n\nMensaje: ${error.message}\nCódigo: ${error.code}\nDetalle: ${error.details || 'Ninguno'}`);
        throw error;
      }

      console.log('DEBUG: Módulo insertado correctamente:', data);
      await fetchContent();
    } catch (err: any) {
      console.error("DEBUG CATCH addModule:", err);
    } finally {
      setIsProcessing(false);
    }
  };

  const deleteModule = async (id: string) => {
    if (!window.confirm('¿ELIMINAR MÓDULO?\n\nEsta acción borrará todas las lecciones asociadas de forma irreversible.')) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', id);
      if (error) throw error;
      fetchContent();
    } catch (err: any) {
      alert("Error al eliminar módulo: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const addLesson = async (moduleId: string) => {
    console.log('DEBUG: Botón "Nueva Lección" presionado para módulo:', moduleId);
    const title = window.prompt('Título de la lección:');

    if (!title || !title.trim()) {
      console.log('DEBUG: Creación de lección cancelada o título vacío.');
      return;
    }

    setIsProcessing(true);
    try {
      // Calcular order_index basado en lecciones actuales del módulo
      const targetModule = modules.find(m => m.id === moduleId);
      const nextIndex = targetModule?.lessons?.length || 0;

      const payload = { 
        module_id: moduleId, 
        title: title.trim(), 
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '### Nueva Clase de EZEHACADEMY\nEdita este contenido para tus alumnos.',
        duration: '10:00',
        resources: [], // Array vacío por defecto para JSONB
        order_index: nextIndex
      };

      console.log('DEBUG: Payload lección:', payload);

      const { data, error } = await supabase
        .from('lessons')
        .insert(payload)
        .select();

      if (error) {
        console.error("DEBUG ERROR Supabase Insert Lesson:", error);
        alert(`❌ ERROR AL CREAR LECCIÓN:\n\nMensaje: ${error.message}\nCódigo: ${error.code}\nDetalle: ${error.details}`);
        throw error;
      }

      console.log('DEBUG: Lección insertada con éxito:', data);
      await fetchContent();
    } catch (err: any) {
      console.error("DEBUG CATCH addLesson:", err);
    } finally {
      setIsProcessing(false);
    }
  };

