export default Admin;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Video, FileText, Loader2, Link as LinkIcon, PlusCircle, AlertTriangle, Check, Wifi, WifiOff
} from 'lucide-react';
import { Module, Lesson } from '../types';
import { Link } from 'react-router-dom';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [modules, setModules] = useState<Module[]>([]);
  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);

  // Estados para creación inline (Evitamos window.prompt)
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleTitle, setNewModuleTitle] = useState('');
  const [addingLessonToModule, setAddingLessonToModule] = useState<string | null>(null);
  const [newLessonTitle, setNewLessonTitle] = useState('');

  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchContent();
  }, []);

  useEffect(() => {
    if (isAddingModule && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isAddingModule]);

  async function fetchContent() {
    console.log('--- ADMIN: Iniciando Carga de Datos ---');
    setLoading(true);
    setLastError(null);
    try {
      const { data, error } = await supabase
        .from('modules')
        .select('*, lessons(*)')
        .order('order_index');

      if (error) throw error;

      const sortedData = (data || []).map(mod => ({
        ...mod,
        lessons: (mod.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
      }));

      console.log('--- ADMIN: Datos cargados correctamente ---', sortedData);
      setModules(sortedData);
    } catch (err: any) {
      console.error("--- ADMIN ERROR fetchContent ---", err);
      setLastError(`Error de conexión: ${err.message || 'Error desconocido'}`);
    } finally {
      setLoading(false);
    }
  }

  const handleCreateModule = async () => {
    console.log('--- EVENTO: Intentando crear módulo ---');
    if (!newModuleTitle.trim()) {
      setIsAddingModule(false);
      return;
    }

    setIsProcessing(true);
    try {
      const payload = { 
        title: newModuleTitle.trim(), 
        order_index: modules.length 
      };
      console.log('--- PAYLOAD MÓDULO ---', payload);

      const { error } = await supabase.from('modules').insert(payload);

      if (error) {
        console.error("--- ERROR SUPABASE MÓDULO ---", error);
        alert(`Error Supabase: ${error.message}`);
        throw error;
      }

      console.log('--- MÓDULO CREADO CON ÉXITO ---');
      setNewModuleTitle('');
      setIsAddingModule(false);
      await fetchContent();
    } catch (err: any) {
      console.error("--- CATCH handleCreateModule ---", err);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCreateLesson = async (moduleId: string) => {
    console.log('--- EVENTO: Intentando crear lección ---', moduleId);
    if (!newLessonTitle.trim()) {
      setAddingLessonToModule(null);
      return;
    }

    setIsProcessing(true);
    try {
      const targetModule = modules.find(m => m.id === moduleId);
      const nextIndex = targetModule?.lessons?.length || 0;

      const payload = { 
        module_id: moduleId, 
        title: newLessonTitle.trim(), 
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '### Nueva Clase\nBienvenido a esta lección.',
        duration: '10:00',
        resources: [],
        order_index: nextIndex
      };

      console.log('--- PAYLOAD LECCIÓN ---', payload);

      const { error } = await supabase.from('lessons').insert(payload);

      if (error) {
        console.error("--- ERROR SUPABASE LECCIÓN ---", error);
        alert(`Error Supabase Lección: ${error.message}`);
        throw error;
      }

      console.log('--- LECCIÓN CREADA CON ÉXITO ---');
      setNewLessonTitle('');
      setAddingLessonToModule(null);
      await fetchContent();
    } catch (err: any) {
      console.error("--- CATCH handleCreateLesson ---", err);
    } finally {
      setIsProcessing(false);
    }
  };

  const saveLessonChanges = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        duration: editingLesson.duration,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      alert("✅ Sincronización Exitosa");
      await fetchContent();
    } catch (err: any) {
      alert("Error al guardar: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const deleteModule = async (id: string) => {
    if (!window.confirm('¿Eliminar módulo permanentemente?')) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', id);
      if (error) throw error;
      fetchContent();
    } catch (err: any) {
      alert("Error: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const deleteLesson = async (id: string) => {
    if (!window.confirm('¿Eliminar lección?')) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').delete().eq('id', id);
      if (error) throw error;
      setEditingLesson(null);
      await fetchContent();
    } catch (err: any) {
      alert("Error: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const addResource = () => {
    if (!editingLesson) return;
    const name = window.prompt('Nombre del material:');
    const url = window.prompt('URL:');
    if (name && url) {
      setEditingLesson({
        ...editingLesson,
        resources: [...(editingLesson.resources || []), { name, url }]
      });
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-red-600 font-sans">
      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase">
            <ChevronLeft size={16}/> Volver
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <div className="flex items-center gap-6">
          <div className={`flex items-center gap-2 px-4 py-2 rounded-full border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-2 h-2 bg-green-500 rounded-full" />}
             <span className="text-[9px] font-black uppercase text-gray-500">{isProcessing ? 'Procesando' : 'Sistema Online'}</span>
          </div>
          <button onClick={onLogout} className="p-2 text-gray-500 hover:text-red-500"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-12">
