                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Módulos</h2>
                <button 
                  onClick={() => {
                    console.log('Click detectado en + Módulo');
                    setIsAddingModule(true);
                  }}
                  className="p-3 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/20"
                >
                  <Plus size={24}/>
