import React, { useState, useMemo, useRef } from 'react';
import ReactPlayer from 'react-player';
import { AlertCircle, RefreshCw, ExternalLink, Play, Loader2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

interface VideoPlayerProps {
  url: string;
  thumbnail?: string;
}

const VideoPlayer: React.FC<VideoPlayerProps> = ({ url, thumbnail }) => {
  const [videoError, setVideoError] = useState(false);
  const [isActivated, setIsActivated] = useState(false);
  const [isReady, setIsReady] = useState(false);
  const [videoKey, setVideoKey] = useState(0);
  const playerRef = useRef<any>(null);

  /**
   * PROTOCOLO DE INTERFAZ LIMPIA (EZEH ACADEMY):
   * Formateo de URL con parámetros agresivos de limpieza.
   */
  const formattedUrl = useMemo(() => {
    if (!url) return "";
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);

    if (match && match[2].length === 11) {
      const videoId = match[2];
      const origin = encodeURIComponent(window.location.origin);
      // controls=0: Ocultamos los controles nativos para el look nativo
      // modestbranding=1: Quita el logo de la barra
      // rel=0: No muestra sugerencias externas
      // iv_load_policy=3: Quita anotaciones
      // autohide=1: Oculta controles automáticamente
      return `https://www.youtube-nocookie.com/embed/${videoId}?enablejsapi=1&origin=${origin}&rel=0&modestbranding=1&iv_load_policy=3&showinfo=0&controls=0&autoplay=1`;
    }
    return url;
  }, [url]);

  const handleStart = () => {
    setIsActivated(true);
  };

  const handleRetry = () => {
    setVideoError(false);
    setIsActivated(false);
    setIsReady(false);
    setVideoKey(prev => prev + 1);
  };

  const handleContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();
  };

  return (
    <div 
      className="relative w-full aspect-video bg-[#050505] rounded-[2.5rem] overflow-hidden border border-white/5 shadow-[0_0_80px_rgba(0,0,0,0.5)] group"
      onContextMenu={handleContextMenu}
    >
      <AnimatePresence mode="wait">
        {!isActivated ? (
          /* 1. CUSTOM OVERLAY (VIDEO COVER) */
          <motion.div 
            key="cover"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-30 cursor-pointer group/cover"
            onClick={handleStart}
          >
            {/* Thumbnail con Blur Estético */}
            <div className="absolute inset-0 overflow-hidden">
              <img 
                src={thumbnail || "https://images.unsplash.com/photo-1611162617474-5b21e879e113?q=80&w=1000&auto=format&fit=crop"} 
                alt="Clase Preview" 
                className="w-full h-full object-cover transition-transform duration-1000 group-hover/cover:scale-110"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-black via-black/40 to-transparent" />
              <div className="absolute inset-0 bg-red-600/10 mix-blend-overlay" />
            </div>

            {/* BOTÓN DE PLAY PERSONALIZADO (Círculo Rojo Pulso) */}
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="relative">
                {/* Efecto de Pulso */}
                <motion.div 
                  animate={{ scale: [1, 1.4, 1], opacity: [0.5, 0, 0.5] }}
                  transition={{ duration: 2, repeat: Infinity }}
                  className="absolute inset-0 bg-red-600 rounded-full blur-xl"
                />
                <motion.div 
                  whileHover={{ scale: 1.1 }}
                  whileTap={{ scale: 0.9 }}
                  className="relative z-10 w-24 h-24 bg-red-600 rounded-full flex items-center justify-center shadow-[0_0_50px_rgba(239,68,68,0.4)] border border-white/20"
                >
                  <Play fill="white" size={32} className="ml-1 text-white" />
                </motion.div>
              </div>
            </div>

            {/* Texto de Acceso */}
            <div className="absolute bottom-10 left-12">
               <div className="flex items-center gap-3">
                  <div className="w-8 h-px bg-red-600" />
                  <span className="text-[10px] font-black uppercase tracking-[0.5em] text-white">Iniciar Clase Premium</span>
               </div>
            </div>
          </motion.div>
        ) : (
          /* 2. REPRODUCTOR ACTIVADO */
          <motion.div 
            key="player"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="relative w-full h-full"
          >
            {!videoError ? (
              /* MÁSCARA DE SEGURIDAD (CSS HACK) */
              <div className="relative w-full h-full scale-[1.08] origin-center"> 
                {/* El scale 1.08 empuja los bordes (título y marca de agua) fuera del viewport */}
                <ReactPlayer
                  key={videoKey}
                  ref={playerRef}
                  url={formattedUrl}
                  width="100%"
                  height="100%"
                  playing={true}
                  onReady={() => setIsReady(true)}
                  onError={() => setVideoError(true)}
                  config={{
                    youtube: {
                      playerVars: { 
                        origin: window.location.origin,
                        enablejsapi: 1,
                        modestbranding: 1,
                        rel: 0,
                        showinfo: 0,
                        iv_load_policy: 3,
                        controls: 0,
                        fs: 0
                      }
                    }
                  }}
                />

                {/* CAPA DE BLOQUEO SUPERIOR (Anticlic Título) */}
                <div className="absolute top-0 left-0 right-0 h-[80px] z-20 pointer-events-auto cursor-default" />

                {/* CAPA DE BLOQUEO INFERIOR (Anticlic Branding) */}
                <div className="absolute bottom-0 left-0 right-0 h-[60px] z-20 pointer-events-auto cursor-default" />
              </div>
            ) : (
              <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#050505] text-center p-10 z-40">
                <AlertCircle size={64} className="text-red-600 mb-6 opacity-40 animate-pulse" />
                <h2 className="text-2xl font-black uppercase tracking-tighter mb-4 italic">ERROR DE <span className="text-red-600">REPRODUCCIÓN</span></h2>
                <p className="text-gray-500 text-[10px] font-black uppercase tracking-[0.3em] max-w-sm leading-loose mb-10">
                  La red ha bloqueado el protocolo de flujo nativo.
                </p>
                <button 
                  onClick={handleRetry} 
                  className="bg-white text-black px-10 py-5 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-red-600 hover:text-white transition-all shadow-2xl"
                >
                  <RefreshCw size={18} className="inline mr-3"/> Forzar Reinicio
                </button>
              </div>
            )}

            {/* Spinner de Carga Inicial */}
            {!isReady && !videoError && (
               <div className="absolute inset-0 flex items-center justify-center bg-black z-10">
                  <div className="flex flex-col items-center gap-4">
                     <Loader2 className="animate-spin text-red-600" size={40} />
                     <span className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-700">Cargando Stream Privado...</span>
                  </div>
               </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* OVERLAY DE MARCA FINAL (ESTÉTICO) */}
      <div className="absolute inset-0 border-[1.5rem] border-black/10 pointer-events-none rounded-[2.5rem] z-50" />
    </div>
  );
};

export default VideoPlayer;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import ReactPlayer from 'react-player';
import { 
  Play, 
  Pause, 
  Volume2, 
  VolumeX, 
  Maximize, 
  Loader2, 
  RotateCcw,
  FastForward,
  Rewind
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

interface VideoPlayerProps {
  url: string;
  thumbnail?: string;
}

const VideoPlayer: React.FC<VideoPlayerProps> = ({ url, thumbnail }) => {
  // Estados del Reproductor
  const [playing, setPlaying] = useState(false);
  const [volume, setVolume] = useState(0.8);
  const [muted, setMuted] = useState(false);
  const [played, setPlayed] = useState(0);
  const [duration, setDuration] = useState(0);
  const [seeking, setSeeking] = useState(false);
  const [isReady, setIsReady] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [isActivated, setIsActivated] = useState(false);

  const playerRef = useRef<ReactPlayer>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const controlsTimeoutRef = useRef<number | null>(null);

  // Formateo de URL para modo invisible
  const formattedUrl = useMemo(() => {
    if (!url) return "";
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    if (match && match[2].length === 11) {
      const videoId = match[2];
      return `https://www.youtube-nocookie.com/embed/${videoId}?enablejsapi=1&rel=0&modestbranding=1&iv_load_policy=3&controls=0&showinfo=0&disablekb=1&fs=0`;
    }
    return url;
  }, [url]);

  // Handlers de Control
  const togglePlay = () => {
    if (!isActivated) setIsActivated(true);
    setPlaying(!playing);
  };

  const handleProgress = (state: { played: number }) => {
    if (!seeking) setPlayed(state.played);
  };

  const handleSeekChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPlayed(parseFloat(e.target.value));
  };

  const handleSeekMouseDown = () => setSeeking(true);
  const handleSeekMouseUp = (e: React.MouseEvent<HTMLInputElement>) => {
    setSeeking(false);
    playerRef.current?.seekTo(parseFloat((e.target as HTMLInputElement).value));
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      containerRef.current?.requestFullscreen();
    } else {
      document.exitFullscreen();
    }
  };

  const formatTime = (seconds: number) => {
    const date = new Date(seconds * 1000);
    const hh = date.getUTCHours();
    const mm = date.getUTCMinutes();
    const ss = date.getUTCSeconds().toString().padStart(2, '0');
    if (hh) return `${hh}:${mm.toString().padStart(2, '0')}:${ss}`;
    return `${mm}:${ss}`;
  };

  // Autohide controls logic
  useEffect(() => {
    const handleMouseMove = () => {
      setShowControls(true);
      if (controlsTimeoutRef.current) window.clearTimeout(controlsTimeoutRef.current);
      controlsTimeoutRef.current = window.setTimeout(() => {
        if (playing) setShowControls(false);
      }, 3000);
    };

    const container = containerRef.current;
    if (container) {
      container.addEventListener('mousemove', handleMouseMove);
    }
    return () => container?.removeEventListener('mousemove', handleMouseMove);
  }, [playing]);

  return (
    <div 
      ref={containerRef}
      className="relative w-full aspect-video bg-black rounded-[2.5rem] overflow-hidden border border-white/5 shadow-[0_0_100px_rgba(0,0,0,0.8)] group select-none"
      onContextMenu={(e) => e.preventDefault()}
    >
      {/* 1. MÁSCARA "ANTI-YOUTUBE" (Escalado estratégico) */}
      <div className={`absolute inset-0 transition-all duration-700 ${isActivated ? 'scale-[1.15]' : 'scale-100'}`}>
        <ReactPlayer
          ref={playerRef}
          url={formattedUrl}
          width="100%"
          height="100%"
          playing={playing}
          volume={volume}
          muted={muted}
          onProgress={handleProgress}
          onDuration={(d) => setDuration(d)}
          onReady={() => setIsReady(true)}
          config={{
            youtube: {
              playerVars: { 
                origin: window.location.origin,
                controls: 0,
                modestbranding: 1,
                rel: 0,
                showinfo: 0
              }
            }
          }}
        />
      </div>

      {/* 2. BLOQUEO DE INTERACCIÓN (Invisible Overlay) */}
      <div 
        className="absolute inset-0 z-20 cursor-pointer"
        onClick={togglePlay}
      />

      {/* 3. FONDO DE PRE-CARGA (Thumbnail Blur) */}
      <AnimatePresence>
        {!isActivated && (
          <motion.div 
            initial={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-30 flex flex-col items-center justify-center bg-black"
          >
            <img 
              src={thumbnail || "https://images.unsplash.com/photo-1611162617474-5b21e879e113?q=80&w=1000&auto=format&fit=crop"} 
              className="absolute inset-0 w-full h-full object-cover blur-2xl opacity-40 scale-110"
              alt="Pre-load"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black via-transparent to-black/80" />

            {/* Play Central Button */}
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.9 }}
              onClick={togglePlay}
              className="relative z-40 w-28 h-28 bg-red-600 rounded-full flex items-center justify-center shadow-[0_0_60px_rgba(239,68,68,0.5)] border border-white/20 group/play"
            >
              <div className="absolute inset-0 bg-red-600 rounded-full animate-ping opacity-20" />
              <Play fill="white" size={40} className="ml-2 transition-transform group-hover/play:scale-110" />
            </motion.button>

            <div className="mt-8 z-40 text-center">
              <h2 className="text-white font-black italic text-2xl tracking-tighter uppercase">EZEH <span className="text-red-600">ACADEMY</span></h2>
              <p className="text-[10px] font-black uppercase tracking-[0.4em] text-red-600/60 mt-2">Streaming de Alta Definición</p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* 4. CUSTOM CONTROLS (ESTILO NETFLIX) */}
      <AnimatePresence>
        {isActivated && (showControls || !playing) && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-40 pointer-events-none"
          >
            {/* Sombra de Controles Inferior */}
            <div className="absolute bottom-0 left-0 right-0 h-48 bg-gradient-to-t from-black via-black/60 to-transparent" />

            {/* Barra de Controles */}
            <div className="absolute bottom-0 left-0 right-0 p-8 pt-0 pointer-events-auto">

              {/* Timeline (Barra de Progreso) */}
              <div className="group/timeline relative w-full h-1.5 mb-6 bg-white/10 rounded-full cursor-pointer overflow-visible">
                <div 
                  className="absolute top-0 left-0 h-full bg-red-600 rounded-full shadow-[0_0_15px_rgba(239,68,68,0.8)] z-10"
                  style={{ width: `${played * 100}%` }}
                />
                <input
                  type="range"
                  min={0}
                  max={0.999999}
                  step="any"
                  value={played}
                  onMouseDown={handleSeekMouseDown}
                  onChange={handleSeekChange}
                  onMouseUp={handleSeekMouseUp}
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20"
                />
                {/* Knob visible en hover */}
                <div 
                  className="absolute top-1/2 -translate-y-1/2 w-4 h-4 bg-red-600 rounded-full shadow-xl opacity-0 group-hover/timeline:opacity-100 transition-opacity z-30 pointer-events-none border-2 border-white"
                  style={{ left: `calc(${played * 100}% - 8px)` }}
                />
              </div>

              {/* Botones y Acciones */}
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-8">
                  <button onClick={togglePlay} className="text-white hover:text-red-500 transition-all hover:scale-110 active:scale-95">
                    {playing ? <Pause size={28} fill="currentColor" /> : <Play size={28} fill="currentColor" />}
                  </button>

                  <div className="flex items-center gap-4 group/vol relative">
                    <button onClick={() => setMuted(!muted)} className="text-white/80 hover:text-white transition-colors">
                      {muted || volume === 0 ? <VolumeX size={24} /> : <Volume2 size={24} />}
                    </button>
                    <input 
                      type="range" 
                      min={0} 
                      max={1} 
                      step="any" 
                      value={volume} 
                      onChange={(e) => setVolume(parseFloat(e.target.value))}
                      className="w-0 group-hover/vol:w-24 transition-all duration-300 h-1 bg-white/20 accent-red-600 appearance-none rounded-full cursor-pointer"
                    />
                  </div>

                  <div className="text-[11px] font-black text-white/60 uppercase tracking-widest flex items-center gap-2">
                    <span className="text-white">{formatTime(played * duration)}</span>
                    <span className="opacity-40">/</span>
                    <span>{formatTime(duration)}</span>
                  </div>
                </div>

                <div className="flex items-center gap-6">
                  <button onClick={() => playerRef.current?.seekTo(playerRef.current?.getCurrentTime() - 10)} className="text-white/40 hover:text-white transition-all"><RotateCcw size={20}/></button>
                  <button onClick={toggleFullScreen} className="text-white/80 hover:text-white transition-all hover:scale-110">
                    <Maximize size={24} />
                  </button>
                </div>
              </div>
            </div>

            {/* Play/Pause Central (Flash on Action) */}
            {!playing && isActivated && (
              <div className="absolute inset-0 flex items-center justify-center">
                 <div className="w-24 h-24 bg-black/40 backdrop-blur-md rounded-full flex items-center justify-center border border-white/10 shadow-2xl">
                    <Play fill="white" size={32} className="ml-1 text-white" />
                 </div>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Spinner de Buffering */}
      {!isReady && isActivated && (
         <div className="absolute inset-0 flex items-center justify-center bg-black/20 backdrop-blur-sm z-50">
            <Loader2 className="animate-spin text-red-600" size={60} strokeWidth={1} />
         </div>
      )}
    </div>
  );
};

export default VideoPlayer;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Play, CheckCircle, Menu, X, ChevronDown, FileText, LogOut, Clock, ExternalLink, Bookmark
} from 'lucide-react';
import { User, Module, Lesson } from '../types.ts';
import { Link } from 'react-router-dom';
import { marked } from 'marked';
import { supabase } from '../lib/supabase.ts';
import VideoPlayer from '../components/VideoPlayer.tsx';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [modules, setModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [expandedModules, setExpandedModules] = useState<string[]>([]);
  const [progress, setProgress] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchContent();
    fetchProgress();
  }, []);

  async function fetchContent() {
    const { data } = await supabase.from('modules').select('*, lessons(*)').order('order_index');
    if (data) {
      setModules(data);
      if (data.length > 0 && data[0].lessons?.length > 0) {
        setActiveLesson(data[0].lessons[0]);
        setExpandedModules([data[0].id]);
      }
    }
    setLoading(false);
  }

  async function fetchProgress() {
    const { data } = await supabase.from('user_progress').select('lesson_id').eq('user_id', user.id);
    if (data) setProgress(data.map((p: any) => p.lesson_id));
  }

  const onToggleProgress = async (lessonId: string) => {
    if (progress.includes(lessonId)) {
      await supabase.from('user_progress').delete().eq('user_id', user.id).eq('lesson_id', lessonId);
      setProgress(prev => prev.filter(id => id !== lessonId));
    } else {
      await supabase.from('user_progress').insert({ user_id: user.id, lesson_id: lessonId });
      setProgress(prev => [...prev, lessonId]);
    }
  };

  const progressPercent = useMemo(() => {
    const total = modules.reduce((acc, mod) => acc + (mod.lessons?.length || 0), 0);
    return total > 0 ? Math.round((progress.length / total) * 100) : 0;
  }, [modules, progress]);

  const htmlDescription = useMemo(() => activeLesson ? marked.parse(activeLesson.description || '') : '', [activeLesson]);

  if (loading) return null;

  return (
    <div className="min-h-screen bg-[#050505] text-white flex flex-col selection:bg-red-600 selection:text-white">
      <nav className="fixed top-0 w-full z-50 bg-black/60 backdrop-blur-2xl border-b border-white/5 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-6">
          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 hover:bg-white/10 rounded-xl transition-all">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
          <div className="text-2xl font-black italic tracking-tighter flex items-center gap-2">
            <span className="text-red-600">EZEH</span> ACADEMY
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end gap-1.5">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Progreso de la Maestría</span>
              <span className="text-xs font-bold text-red-500">{progressPercent}%</span>
            </div>
            <div className="w-40 h-1.5 bg-white/10 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} className="h-full bg-red-600 shadow-[0_0_10px_rgba(239,68,68,0.5)]" />
            </div>
          </div>

          <div className="flex items-center gap-4">
            {user.role === 'admin' && (
              <Link to="/admin" className="p-2 text-gray-500 hover:text-white transition-colors"><Bookmark size={20} /></Link>
            )}
            <button onClick={onLogout} className="text-gray-500 hover:text-red-600 transition-colors"><LogOut size={18}/></button>
            <div className="w-10 h-10 rounded-full bg-red-600 flex items-center justify-center font-black border border-white/10 shadow-xl">{user.fullName.charAt(0)}</div>
          </div>
        </div>
      </nav>

      <div className="flex flex-1 pt-[72px] h-screen overflow-hidden">
        <AnimatePresence>
          {isSidebarOpen && (
            <motion.aside initial={{ x: -350 }} animate={{ x: 0 }} exit={{ x: -350 }} className="w-full lg:w-[350px] bg-[#080808] border-r border-white/5 overflow-y-auto custom-scrollbar">
              <div className="p-8">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em] mb-8">Currículo Digital</h2>
                {modules.map((mod, i) => (
                  <div key={mod.id} className="mb-6">
                    <div className="flex items-center gap-3 mb-3">
                       <span className="text-[9px] font-black text-red-600 uppercase bg-red-600/10 px-2 py-0.5 rounded">MOD {i + 1}</span>
                       <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 truncate">{mod.title}</h3>
                    </div>
                    <div className="space-y-1.5">
                      {mod.lessons?.map(l => (
                        <button 
                          key={l.id} 
                          onClick={() => setActiveLesson(l)} 
                          className={`w-full text-left p-4 rounded-2xl text-[11px] font-bold transition-all flex items-center justify-between group ${activeLesson?.id === l.id ? 'bg-red-600 text-white shadow-2xl shadow-red-600/20' : 'text-gray-500 hover:bg-white/5'}`}
                        >
                          <div className="flex items-center gap-3 truncate">
                            {progress.includes(l.id) ? <CheckCircle size={14} className="text-green-500"/> : <Play size={12} className={activeLesson?.id === l.id ? 'text-white' : 'text-gray-700'}/>}
                            <span className="truncate">{l.title}</span>
                          </div>
                          <span className="text-[9px] opacity-40 font-mono group-hover:opacity-100 transition-opacity">{l.duration}</span>
                        </button>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        <main className="flex-1 overflow-y-auto bg-black p-4 lg:p-12 custom-scrollbar">
          {activeLesson ? (
            <div className="max-w-5xl mx-auto">
              {/* REPRODUCTOR PREMIUM CONFIGURADO PARA LOOK NATIVO */}
              <div className="mb-12">
                <VideoPlayer 
                  url={activeLesson.video_url} 
                  thumbnail="https://images.unsplash.com/photo-1611162617474-5b21e879e113?q=80&w=1000&auto=format&fit=crop" 
                />
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-3 gap-16">
                <div className="lg:col-span-2">
                  <div className="flex items-center gap-4 mb-4">
                     <span className="bg-red-600 text-[9px] font-black uppercase px-3 py-1 rounded-full">Stream Activo</span>
                     <span className="text-gray-500 text-[10px] font-bold uppercase tracking-widest flex items-center gap-2"><Clock size={12}/> {activeLesson.duration} de contenido</span>
                  </div>
                  <h1 className="text-5xl font-black italic tracking-tighter uppercase mb-10 leading-none">
                    {activeLesson.title}
                  </h1>

                  <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-headings:text-white prose-strong:text-red-500 leading-relaxed" 
                       dangerouslySetInnerHTML={{ __html: htmlDescription }} />
                </div>

                <div className="space-y-8">
                  <button 
                    onClick={() => onToggleProgress(activeLesson.id)} 
                    className={`w-full py-6 rounded-3xl font-black text-[11px] uppercase tracking-[0.3em] transition-all shadow-2xl active:scale-95 ${progress.includes(activeLesson.id) ? 'bg-green-600/10 text-green-500 border border-green-600/20' : 'bg-white text-black hover:bg-red-600 hover:text-white'}`}
                  >
                    {progress.includes(activeLesson.id) ? 'Clase Completada ✓' : 'Marcar como Completado'}
                  </button>

                  <div className="p-10 bg-[#080808] border border-white/5 rounded-[3rem] shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/5 blur-3xl rounded-full" />
                    <h3 className="text-[10px] font-black text-gray-500 uppercase tracking-[0.4em] mb-8 flex items-center gap-3">
                       <FileText size={16} className="text-red-600" /> Archivos de Clase
                    </h3>
                    <div className="space-y-3">
                      {activeLesson.resources?.map((r, i) => (
                        <a 
                          key={i} 
                          href={r.url} 
                          target="_blank"
                          rel="noopener noreferrer"
                          className="flex items-center justify-between p-5 bg-white/5 border border-white/5 rounded-2xl text-[11px] font-bold hover:bg-red-600 hover:border-red-600 transition-all group/res"
                        >
                          <span className="truncate uppercase pr-4">{r.name}</span>
                          <ExternalLink size={14} className="text-gray-600 group-hover/res:text-white" />
                        </a>
                      ))}
                      {(!activeLesson.resources || activeLesson.resources.length === 0) && (
                        <div className="text-center py-10 border-2 border-dashed border-white/5 rounded-3xl opacity-20">
                           <p className="text-[9px] font-black uppercase tracking-widest">Sin recursos adicionales</p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-20">
               <div className="relative mb-10">
                  <div className="absolute inset-0 bg-red-600/20 blur-3xl rounded-full animate-pulse" />
                  <div className="relative w-32 h-32 bg-white/5 rounded-full flex items-center justify-center border border-white/10">
                    <Play size={48} className="opacity-10 ml-2" />
                  </div>
               </div>
               <h3 className="text-3xl font-black uppercase tracking-[0.5em] italic">EZEH <span className="text-red-600">ACADEMY</span></h3>
               <p className="text-[10px] font-bold text-gray-700 mt-6 uppercase tracking-[0.3em] max-w-sm leading-loose">
                 Selecciona una lección del currículo para comenzar tu inyección de conocimiento digital.
               </p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

