REPLAZA EL CODIGO POR ESTE PARA SOLUCIONAR ESTO DEL REPRODUCTOR: import React, { useState, useRef, useEffect } from 'react';
import ReactPlayer from 'react-player/youtube';
import { Play, Pause, Volume2, Maximize, RefreshCw } from 'lucide-react';

export default function VideoPlayer({ url, title }: { url: string; title: string }) {
  const [playing, setPlaying] = useState(false);
  const [volume, setVolume] = useState(0.8);
  const [played, setPlayed] = useState(0);
  const [duration, setDuration] = useState(0);
  const [showControls, setShowControls] = useState(true);
  const playerRef = useRef<ReactPlayer>(null);

  // Formatear tiempo (00:00)
  const formatTime = (seconds: number) => {
    const date = new Date(seconds * 1000);
    const mm = date.getUTCMinutes();
    const ss = date.getUTCSeconds().toString().padStart(2, '0');
    return `${mm}:${ss}`;
  };

  const handleSeekChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setPlayed(val);
    playerRef.current?.seekTo(val);
  };

  return (
    <div 
      className="relative group w-full aspect-video bg-black rounded-xl overflow-hidden border border-white/10 shadow-2xl"
      onMouseMove={() => setShowControls(true)}
      onMouseLeave={() => playing && setShowControls(false)}
    >
      {/* 1. EL REPRODUCTOR (BASE) */}
      <ReactPlayer
        ref={playerRef}
        url={url}
        width="100%"
        height="100%"
        playing={playing}
        volume={volume}
        onProgress={(state) => setPlayed(state.played)}
        onDuration={(d) => setDuration(d)}
        config={{
          youtube: {
            playerVars: { 
              modestbranding: 1, 
              rel: 0, 
              showinfo: 0, 
              controls: 0, 
              iv_load_policy: 3,
              disablekb: 1
            }
          }
        }}
        style={{ pointerEvents: 'none' }} // Bloquea clics directos en YT
      />

      {/* 2. MÁSCARA ANTI-RECOMENDACIONES (SOLO EN PAUSA) */}
      {!playing && (
        <div className="absolute inset-0 bg-black/80 backdrop-blur-sm z-10 flex flex-col items-center justify-center animate-in fade-in duration-500">
           <div className="text-red-600 font-black text-2xl mb-4 tracking-tighter italic">EZEH ACADEMY</div>
           <button 
             onClick={() => setPlaying(true)}
             className="w-20 h-20 bg-red-600 rounded-full flex items-center justify-center hover:scale-110 transition-transform shadow-lg shadow-red-600/40"
           >
             <Play fill="white" size={32} className="ml-1" />
           </button>
           <p className="mt-4 text-white/60 text-sm font-medium uppercase tracking-widest">Pausado: {title}</p>
        </div>
      )}

      {/* 3. PARCHES QUIRÚRGICOS (TAPAR LOGO Y TÍTULO SIN ZOOM) */}
      <div className="absolute top-0 left-0 w-full h-[60px] bg-gradient-to-b from-black to-transparent opacity-0 group-hover:opacity-100 transition-opacity z-20 pointer-events-none" />
      <div className="absolute bottom-0 right-0 w-[100px] h-[40px] bg-black z-20 pointer-events-none" />

      {/* 4. CONTROLES PERSONALIZADOS (ESTILO NETFLIX) */}
      <div className={`absolute inset-x-0 bottom-0 z-30 transition-opacity duration-500 ${showControls || !playing ? 'opacity-100' : 'opacity-0'}`}>
        <div className="bg-gradient-to-t from-black via-black/80 to-transparent p-6">

          {/* TIMELINE */}
          <div className="group/timeline relative w-full h-1.5 bg-white/20 rounded-full mb-4 cursor-pointer">
            <div 
              className="absolute top-0 left-0 h-full bg-red-600 rounded-full z-10" 
              style={{ width: `${played * 100}%` }}
            />
            <input
              type="range"
              min={0}
              max={0.999999}
              step="any"
              value={played}
              onChange={handleSeekChange}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20"
            />
          </div>

          <div className="flex items-center justify-between">
            <div className="flex items-center gap-6">
              <button onClick={() => setPlaying(!playing)} className="text-white hover:text-red-600 transition-colors">
                {playing ? <Pause size={24} fill="currentColor" /> : <Play size={24} fill="currentColor" />}
              </button>

              <div className="flex items-center gap-2">
                <Volume2 size={20} className="text-white/60" />
                <input 
                  type="range" min={0} max={1} step="any" 
                  value={volume} onChange={(e) => setVolume(parseFloat(e.target.value))}
                  className="w-20 accent-red-600"
                />
              </div>

              <div className="text-sm font-bold tabular-nums">
                <span className="text-white">{formatTime(played * duration)}</span>
                <span className="text-white/40 mx-1">/</span>
                <span className="text-white/40">{formatTime(duration)}</span>
              </div>
            </div>

            <button className="text-white/60 hover:text-white transition-colors">
              <Maximize size={20} />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

