              <div className="p-10 bg-black/40 border border-white/5 rounded-[3rem] group hover:border-white/5 transition-all">
                <div className="flex justify-center mb-4">
                  <Database size={24} className="text-gray-600" />
                </div>
                <p className="text-[10px] font-black text-gray-600 uppercase tracking-widest mb-3">Status EZEH Cloud</p>
                <p className="text-[11px] font-black text-green-500 tracking-[0.2em] mt-8 uppercase">Óptimo Online</p>
