export default Admin;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Video, FileText, Loader2, AlertTriangle, Database, ShieldCheck, Globe, Mail, Calendar, User as UserIcon, Upload, Link as LinkIcon
} from 'lucide-react';
import { Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [modules, setModules] = useState<Module[]>([]);
  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);

  // Estadísticas de Usuarios
  const [students, setStudents] = useState<User[]>([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  // Estados para creación inline
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleTitle, setNewModuleTitle] = useState('');
  const [addingLessonToModule, setAddingLessonToModule] = useState<string | null>(null);
  const [newLessonTitle, setNewLessonTitle] = useState('');

  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchContent();
    fetchUserList();

    const dbChannel = supabase
      .channel('admin-profiles-db-changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles' }, () => {
        fetchUserList();
      })
      .subscribe();

    const presenceChannel = supabase.channel('online-users');

    presenceChannel
      .on('presence', { event: 'sync' }, () => {
        const state = presenceChannel.presenceState();
        const activeIds = new Set<string>();

        Object.keys(state).forEach((key) => {
          activeIds.add(key);
        });

        setOnlineUserIds(activeIds);
      })
      .subscribe();

    return () => {
      supabase.removeChannel(dbChannel);
      supabase.removeChannel(presenceChannel);
    };
  }, []);

  useEffect(() => {
    if (isAddingModule && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isAddingModule]);

  const isUserOnline = (userId: string) => {
    return onlineUserIds.has(userId);
  };

  async function fetchUserList() {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;

      const mappedStudents = (data || []).map((p: any) => ({
        id: p.id,
        fullName: p.full_name || 'Sin nombre',
        email: p.email || 'S/E',
        role: p.role || 'student',
        last_seen: p.last_seen,
        created_at: p.created_at,
        progress: []
      })) as User[];

      setStudents(mappedStudents);
      setTotalStudents(mappedStudents.length);
    } catch (err) {
      console.error("Error fetching user stats:", err);
    }
  }

  async function fetchContent() {
    setLoading(true);
    setLastError(null);
    try {
      const { data, error } = await supabase
        .from('modules')
        .select('*, lessons(*)')
        .order('order_index');

      if (error) throw error;

      const sortedData = (data || []).map(mod => ({
        ...mod,
        lessons: (mod.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
      }));

      setModules(sortedData);
    } catch (err: any) {
      console.error("Error en fetchContent:", err);
      setLastError(`Error de conexión: ${err.message}`);
    } finally {
      setLoading(false);
    }
  }

  const handleCreateModule = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) {
      alert("❌ ERROR: No hay una sesión activa.");
      setIsAddingModule(false);
      return;
    }

    if (!newModuleTitle.trim()) {
      setIsAddingModule(false);
      return;
    }

    setIsProcessing(true);
    try {
      const { data: courses } = await supabase.from('courses').select('id').limit(1);
      const courseId = courses && courses.length > 0 ? courses[0].id : null;

      const payload: any = { 
        title: newModuleTitle.trim(), 
        order_index: modules.length
      };

      if (courseId) payload.course_id = courseId;

      const { error } = await supabase.from('modules').insert(payload);
      if (error) throw error;

      setNewModuleTitle('');
      setIsAddingModule(false);
      await fetchContent();
    } catch (err: any) {
      alert(`❌ ERROR: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCreateLesson = async (moduleId: string) => {
    if (!newLessonTitle.trim()) {
      setAddingLessonToModule(null);
      return;
    }

    setIsProcessing(true);
    try {
      const targetModule = modules.find(m => m.id === moduleId);
      const nextIndex = targetModule?.lessons?.length || 0;

      const payload = { 
        module_id: moduleId, 
        title: newLessonTitle.trim(), 
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '### Nueva Clase\nEscribe aquí el contenido educativo.',
        duration: '00:00',
        resources: [],
        order_index: nextIndex
      };

      const { error } = await supabase.from('lessons').insert(payload);
      if (error) throw error;

      setNewLessonTitle('');
      setAddingLessonToModule(null);
      await fetchContent();
    } catch (err: any) {
      alert(`❌ ERROR: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const saveLessonChanges = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      alert("✅ Sincronizado correctamente");
      await fetchContent();
    } catch (err: any) {
      alert("❌ Error al guardar: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !editingLesson) return;

    setIsProcessing(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${Math.random().toString(36).substring(2)}.${fileExt}`;
      const filePath = `resources/${editingLesson.id}/${fileName}`;

      // Intentar subir al bucket 'resources'
      const { data: uploadData, error: uploadError } = await supabase.storage
        .from('resources')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: false
        });

      if (uploadError) {
        // Manejo específico del error de bucket no encontrado
        if (uploadError.message.toLowerCase().includes('bucket not found')) {
          throw new Error("CONFIGURACIÓN REQUERIDA: El bucket 'resources' no existe en tu proyecto de Supabase. Para solucionarlo:\n\n1. Ve al panel de Supabase.\n2. Entra en 'Storage'.\n3. Crea un nuevo bucket llamado exactamente 'resources'.\n4. Asegúrate de marcarlo como 'Public' para que los alumnos puedan descargar los archivos.");
        }
        throw uploadError;
      }

      const { data: { publicUrl } } = supabase.storage
        .from('resources')
        .getPublicUrl(filePath);

      const newResource = { name: file.name, url: publicUrl };
      setEditingLesson({
        ...editingLesson,
        resources: [...(editingLesson.resources || []), newResource]
      });

      alert("✅ Archivo cargado y vinculado correctamente");
    } catch (err: any) {
      console.error("Error detallado de subida:", err);
      const errorMessage = err.message || "Error desconocido durante la carga.";

      alert(`❌ ERROR DE CARGA:\n\n${errorMessage}`);

      if (confirm("¿Deseas añadir este recurso manualmente mediante una URL externa (Google Drive, Dropbox, etc) en su lugar?")) {
        const name = prompt('Nombre del recurso:', file.name);
        const url = prompt('URL del archivo:');
        if (name && url) {
          setEditingLesson({
            ...editingLesson,
            resources: [...(editingLesson.resources || []), { name, url }]
          });
        }
      }
    } finally {
      setIsProcessing(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const deleteModule = async (id: string) => {
    if (!window.confirm('¿Eliminar módulo y todo su contenido?')) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', id);
      if (error) throw error;
      fetchContent();
    } catch (err: any) {
      alert("Error: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-red-600 font-sans">
      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-xl">
