                  <div className="flex gap-1 items-center justify-center h-8">
                    {[1, 2, 3, 4, 5].map((star) => {
                      const active = star <= (hoverRating || rating);
                      return (
                        <div key={star} className="relative w-8 h-8 flex items-center justify-center flex-shrink-0 overflow-visible">
