                          ))}
                          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                          <button onClick={() => fileInputRef.current?.click()} className="w-full py-4 border-2 border-dashed border-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-500 hover:text-white transition-all">+ Cargar Archivo</button>
                        </div>
                      </div>
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-2">Contenido (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={(e) => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm text-gray-400 font-mono resize-none focus:border-red-600 outline-none h-[560px] custom-scrollbar" />
