              ) : (
                <div className="h-full min-h-[700px] border-2 border-dashed border-white/5 rounded-[4.5rem] flex flex-col items-center justify-center text-center p-20 opacity-10">
                  <Video size={80} className="mb-8" />
                  <h3 className="text-2xl font-black uppercase tracking widest">EZEH STUDIO</h3>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] overflow-hidden">
             <div className="p-10 border-b border-white/5 flex justify-between items-center">
                <h2 className="text-2xl font-black uppercase tracking-tighter italic">Alumnos Registrados</h2>
                <button onClick={fetchUserList} className="px-6 py-3 bg-white/5 rounded-2xl text-[9px] font-black uppercase">Refrescar</button>
             </div>
             <table className="w-full text-left">
               <tbody className="divide-y divide-white/5">
                 {students.map(student => (
                   <tr key={student.id} className="hover:bg-white/[0.01]">
                     <td className="px-10 py-6">
                       <p className="font-black text-sm uppercase tracking-tighter">{student.fullName}</p>
                       <p className="text-[10px] text-gray-600">{student.email}</p>
                     </td>
                     <td className="px-10 py-6 text-right">
                       <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase ${isUserOnline(student.id) ? 'bg-green-500/10 text-green-500' : 'bg-white/5 text-gray-700'}`}>
