import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Play, CheckCircle, Menu, X, FileText, LogOut, ExternalLink, Bookmark, Star
} from 'lucide-react';
import { User, Module, Lesson } from '../types.ts';
import { Link } from 'react-router-dom';
import { marked } from 'marked';
import { supabase } from '../lib/supabase.ts';
import VideoPlayer from '../components/VideoPlayer.tsx';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [modules, setModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [progress, setProgress] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [rating, setRating] = useState(0);

  useEffect(() => {
    fetchContent();
    fetchProgress();
  }, []);

  async function fetchContent() {
    const { data } = await supabase.from('modules').select('*, lessons(*)').order('order_index');
    if (data) {
      setModules(data);
      if (data.length > 0 && data[0].lessons?.length > 0) {
        setActiveLesson(data[0].lessons[0]);
      }
    }
    setLoading(false);
  }

  async function fetchProgress() {
    const { data } = await supabase.from('user_progress').select('lesson_id').eq('user_id', user.id);
    if (data) setProgress(data.map((p: any) => p.lesson_id));
  }

  const onToggleProgress = async (lessonId: string) => {
    if (progress.includes(lessonId)) {
      await supabase.from('user_progress').delete().eq('user_id', user.id).eq('lesson_id', lessonId);
      setProgress(prev => prev.filter(id => id !== lessonId));
    } else {
      await supabase.from('user_progress').insert({ user_id: user.id, lesson_id: lessonId });
      setProgress(prev => [...prev, lessonId]);
    }
  };

  const progressPercent = useMemo(() => {
    const total = modules.reduce((acc, mod) => acc + (mod.lessons?.length || 0), 0);
    return total > 0 ? Math.round((progress.length / total) * 100) : 0;
  }, [modules, progress]);

  const htmlDescription = useMemo(() => activeLesson ? marked.parse(activeLesson.description || '') : '', [activeLesson]);

  if (loading) return null;

  return (
    <div className="min-h-screen bg-[#050505] text-white flex flex-col selection:bg-red-600 selection:text-white font-sans">
      <nav className="fixed top-0 w-full z-50 bg-black/60 backdrop-blur-2xl border-b border-white/5 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-6">
          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 hover:bg-white/10 rounded-xl transition-all">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
          <div className="text-2xl font-black italic tracking-tighter flex items-center gap-2">
            <span className="text-red-600">EZEH</span> ACADEMY
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end gap-1.5">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Progreso de la Maestría</span>
              <span className="text-xs font-bold text-red-500">{progressPercent}%</span>
            </div>
            <div className="w-40 h-1.5 bg-white/10 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} className="h-full bg-red-600 shadow-[0_0_10px_rgba(239,68,68,0.5)]" />
            </div>
          </div>

          <div className="flex items-center gap-4">
            {user.role === 'admin' && (
              <Link to="/admin" className="p-2 text-gray-500 hover:text-white transition-colors"><Bookmark size={20} /></Link>
            )}
            <button onClick={onLogout} className="text-gray-500 hover:text-red-600 transition-colors"><LogOut size={18}/></button>
            <div className="w-10 h-10 rounded-full bg-red-600 flex items-center justify-center font-black border border-white/10 shadow-xl">{user.fullName.charAt(0)}</div>
          </div>
        </div>
      </nav>

      <div className="flex flex-1 pt-[72px] h-screen overflow-hidden">
        <AnimatePresence>
          {isSidebarOpen && (
            <motion.aside initial={{ x: -350 }} animate={{ x: 0 }} exit={{ x: -350 }} className="w-full lg:w-[350px] bg-[#080808] border-r border-white/5 overflow-y-auto custom-scrollbar flex-shrink-0">
              <div className="p-8">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em] mb-8">Currículo Digital</h2>
                {modules.map((mod, i) => (
                  <div key={mod.id} className="mb-6">
                    <div className="flex items-center gap-3 mb-3">
                       <span className="text-[9px] font-black text-red-600 uppercase bg-red-600/10 px-2 py-0.5 rounded">MOD {i + 1}</span>
                       <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 break-words leading-relaxed">{mod.title}</h3>
                    </div>
                    <div className="space-y-1.5">
                      {mod.lessons?.map(l => {
                        const isCompleted = progress.includes(l.id);
                        return (
                          <div 
                            key={l.id} 
                            onClick={() => setActiveLesson(l)}
                            className={`w-full text-left p-4 rounded-2xl text-[11px] font-bold transition-all flex items-center justify-between group relative cursor-pointer ${activeLesson?.id === l.id ? 'bg-white/10 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'}`}
                          >
                            <span className="uppercase tracking-tighter pr-4 break-words flex-1 leading-normal">{l.title}</span>
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                onToggleProgress(l.id);
                              }}
                              className={`relative w-8 h-8 flex-shrink-0 rounded-lg flex items-center justify-center transition-all duration-500 overflow-hidden ${isCompleted ? 'bg-green-600 shadow-[0_0_15px_rgba(34,197,94,0.4)] border-transparent' : 'bg-white/5 border border-white/20 text-white/50 hover:text-white'}`}
                            >
                              <CheckCircle size={14} className={`relative z-10 transition-transform ${isCompleted ? 'scale-110 text-white' : 'scale-90 opacity-40'}`} />
                              {isCompleted && (
                                <motion.div 
                                  initial={{ x: '-150%' }}
                                  animate={{ x: '150%' }}
                                  transition={{ duration: 1.5, repeat: Infinity, repeatDelay: 0.5, ease: "linear" }}
                                  className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent skew-x-[-25deg] z-0"
                                />
                              )}
                            </button>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        {/* CONTENEDOR PRINCIPAL: scrollbar-gutter stable evita que la pantalla salte a la izquierda cuando aparece el scroll */}
        <main className="flex-1 overflow-y-scroll bg-black p-4 lg:p-12 custom-scrollbar" style={{ scrollbarGutter: 'stable' }}>
          {activeLesson ? (
            <div className="max-w-6xl mx-auto">
              <div className="mb-14">
                <VideoPlayer url={activeLesson.video_url} title={activeLesson.title} />
              </div>

              {/* HEADER - Títulos visibles sin truncar */}
              <div className="flex flex-col md:flex-row items-start md:items-end justify-between gap-8 mb-10 border-b border-white/5 pb-10">
                <div className="flex-1 min-w-0">
                  <h1 className="text-2xl lg:text-3xl font-black italic tracking-tighter uppercase leading-tight break-words">
                    {activeLesson.title}
                  </h1>
                </div>

                {/* SISTEMA DE ESTRELLAS - BLOQUE ESTÁTICO RÍGIDO ANTI-JITTER */}
                <div className="w-[180px] h-[52px] flex-shrink-0 flex flex-col items-start md:items-end justify-end gap-2.5 relative">
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-600 block select-none mb-0.5">Valoración de Clase</span>

                  <div className="flex gap-1 items-center justify-center h-8 w-full relative">
                    {[1, 2, 3, 4, 5].map((star) => {
                      const isActive = star <= rating;
                      const isExactlyThis = star === rating;

                      return (
                        <div key={star} className="relative w-8 h-8 flex-shrink-0 pointer-events-auto">
                          <button
                            onClick={() => setRating(star)}
                            className="absolute inset-0 flex items-center justify-center outline-none focus:outline-none transition-none"
                          >
                            <motion.div
                              key={`${star}-${rating}`} // Forzamos re-animación solo cuando cambia este valor exacto
                              animate={isExactlyThis ? { 
                                rotate: [0, 360],
                                scale: [1, 1.25, 1]
                              } : { rotate: 0, scale: 1 }}
                              transition={{ duration: 0.6, ease: "easeOut" }}
                              className="pointer-events-none"
                            >
                              <Star 
                                size={20} 
                                strokeWidth={2}
                                fill={isActive ? "#FFD700" : "none"} 
                                className={`transition-colors duration-200 ${isActive ? "text-yellow-400 drop-shadow-[0_0_8px_rgba(255,215,0,0.4)]" : "text-gray-700"}`} 
                              />
                            </motion.div>

                            {/* Brillo solo al seleccionar */}
                            <AnimatePresence>
                              {isExactlyThis && (
                                <motion.div 
                                  initial={{ scale: 0, opacity: 0 }}
                                  animate={{ scale: 2.2, opacity: [0, 0.4, 0] }}
                                  exit={{ opacity: 0 }}
                                  transition={{ duration: 0.5 }}
                                  className="absolute inset-0 bg-yellow-400 blur-2xl rounded-full pointer-events-none -z-10"
                                />
                              )}
                            </AnimatePresence>
                          </button>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>

              <div className="mb-20">
                <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-headings:text-white prose-strong:text-red-500 leading-relaxed text-lg" 
                     dangerouslySetInnerHTML={{ __html: htmlDescription }} />
              </div>

              <div className="border-t border-white/5 pt-12 pb-24">
                <div className="flex items-center gap-4 mb-8">
                   <div className="w-10 h-10 bg-red-600/10 rounded-xl flex items-center justify-center border border-red-600/20">
                      <FileText size={20} className="text-red-600" />
                   </div>
                   <div>
                      <h3 className="text-lg font-black uppercase tracking-tighter italic">Archivos y Recursos</h3>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest">Materiales de apoyo para esta lección</p>
                   </div>
                </div>

                <div className="flex flex-wrap gap-4">
                  {activeLesson.resources?.map((r, i) => (
                    <motion.a 
                      key={i} 
                      href={r.url} 
                      target="_blank"
                      rel="noopener noreferrer"
                      whileHover={{ y: -5, borderColor: '#ef4444' }}
                      className="flex items-center gap-4 p-5 bg-[#080808] border border-white/10 rounded-[1.5rem] min-w-[280px] max-w-xs transition-colors group/res"
                    >
                      <div className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center group-hover/res:bg-red-600/20 transition-colors">
                        <FileText size={18} className="text-gray-500 group-hover/res:text-red-600" />
                      </div>
                      <div className="flex-1 truncate">
                        <p className="text-[11px] font-black uppercase tracking-tighter truncate">{r.name}</p>
                        <p className="text-[9px] text-gray-600 font-bold uppercase mt-0.5">Descargar recurso</p>
                      </div>
                      <ExternalLink size={14} className="text-gray-800 group-hover/res:text-red-600 transition-colors" />
                    </motion.a>
                  ))}
                  {(!activeLesson.resources || activeLesson.resources.length === 0) && (
                    <div className="w-full text-center py-16 border-2 border-dashed border-white/5 rounded-[3rem] opacity-20">
                       <p className="text-xs font-black uppercase tracking-[0.3em]">Esta clase no contiene archivos adjuntos</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-20">
               <div className="relative mb-10">
                  <div className="absolute inset-0 bg-red-600/20 blur-3xl rounded-full animate-pulse" />
                  <div className="relative w-32 h-32 bg-white/5 rounded-full flex items-center justify-center border border-white/10">
                    <Play size={48} className="opacity-10 ml-2" />
                  </div>
               </div>
               <h3 className="text-3xl font-black uppercase tracking-[0.5em] italic">EZEH <span className="text-red-600">ACADEMY</span></h3>
               <p className="text-[10px] font-bold text-gray-700 mt-6 uppercase tracking-[0.3em] max-w-sm leading-loose">
                 Selecciona una lección del currículo para comenzar tu inyección de conocimiento digital.
               </p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Video, FileText, Loader2, AlertTriangle, Database, ShieldCheck, Globe, Mail, Calendar, User as UserIcon, Upload, Link as LinkIcon
} from 'lucide-react';
import { Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [modules, setModules] = useState<Module[]>([]);
  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleTitle, setNewModuleTitle] = useState('');
  const [addingLessonToModule, setAddingLessonToModule] = useState<string | null>(null);
  const [newLessonTitle, setNewLessonTitle] = useState('');

  const inputRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchContent();
    fetchUserList();

    const dbChannel = supabase
      .channel('admin-profiles-db-changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles' }, () => {
        fetchUserList();
      })
      .subscribe();

    const presenceChannel = supabase.channel('online-users');

    presenceChannel
      .on('presence', { event: 'sync' }, () => {
        const state = presenceChannel.presenceState();
        const activeIds = new Set<string>();

        Object.keys(state).forEach((key) => {
          activeIds.add(key);
        });

        setOnlineUserIds(activeIds);
      })
      .subscribe();

    return () => {
      supabase.removeChannel(dbChannel);
      supabase.removeChannel(presenceChannel);
    };
  }, []);

  useEffect(() => {
    if (isAddingModule && inputRef.current) {
      inputRef.current.focus();
    }
  }, [isAddingModule]);

  const isUserOnline = (userId: string) => {
    return onlineUserIds.has(userId);
  };

  async function fetchUserList() {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;

      const mappedStudents = (data || []).map((p: any) => ({
        id: p.id,
        fullName: p.full_name || 'Sin nombre',
        email: p.email || 'S/E',
        role: p.role || 'student',
        last_seen: p.last_seen,
        created_at: p.created_at,
        progress: []
      })) as User[];

      setStudents(mappedStudents);
      setTotalStudents(mappedStudents.length);
    } catch (err) {
      console.error("Error fetching user stats:", err);
    }
  }

  async function fetchContent() {
    setLoading(true);
    setLastError(null);
    try {
      const { data, error } = await supabase
        .from('modules')
        .select('*, lessons(*)')
        .order('order_index');

      if (error) throw error;

      const sortedData = (data || []).map(mod => ({
        ...mod,
        lessons: (mod.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
      }));

      setModules(sortedData);
    } catch (err: any) {
      console.error("Error en fetchContent:", err);
      setLastError(`Error de conexión: ${err.message}`);
    } finally {
      setLoading(false);
    }
  }

  const handleCreateModule = async () => {
    if (!newModuleTitle.trim()) {
      setIsAddingModule(false);
      return;
    }

    setIsProcessing(true);
    try {
      const { data: courses } = await supabase.from('courses').select('id').limit(1);
      const courseId = courses && courses.length > 0 ? courses[0].id : null;

      const payload: any = { 
        title: newModuleTitle.trim(), 
        order_index: modules.length
      };

      if (courseId) payload.course_id = courseId;

      const { error } = await supabase.from('modules').insert(payload);
      if (error) throw error;

      setNewModuleTitle('');
      setIsAddingModule(false);
      await fetchContent();
    } catch (err: any) {
      alert(`❌ ERROR: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCreateLesson = async (moduleId: string) => {
    if (!newLessonTitle.trim()) {
      setAddingLessonToModule(null);
      return;
    }

    setIsProcessing(true);
    try {
      const targetModule = modules.find(m => m.id === moduleId);
      const nextIndex = targetModule?.lessons?.length || 0;

      const payload = { 
        module_id: moduleId, 
        title: newLessonTitle.trim().substring(0, 100), 
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '### Nueva Clase\nEscribe aquí el contenido educativo.',
        duration: '00:00',
        resources: [],
        order_index: nextIndex
      };

      const { error } = await supabase.from('lessons').insert(payload);
      if (error) throw error;

      setNewLessonTitle('');
      setAddingLessonToModule(null);
      await fetchContent();
    } catch (err: any) {
      alert(`❌ ERROR: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const saveLessonChanges = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title.substring(0, 100),
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      alert("✅ Sincronizado correctamente");
      await fetchContent();
    } catch (err: any) {
      alert("❌ Error al guardar: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !editingLesson) return;

    setIsProcessing(true);
    try {
      const cleanFileName = file.name.replace(/[^\w.-]/g, '_');
      const uniqueFileName = `${Math.random().toString(36).substring(2, 9)}_${cleanFileName}`;
      const filePath = `${editingLesson.id}/${uniqueFileName}`;

      const { error: uploadError } = await supabase.storage
        .from('materials')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: false
        });

      if (uploadError) throw new Error(uploadError.message);

      const { data: { publicUrl } } = supabase.storage
        .from('materials')
        .getPublicUrl(filePath);

      const newResource = { name: file.name, url: publicUrl };
      setEditingLesson({
        ...editingLesson,
        resources: [...(editingLesson.resources || []), newResource]
      });

      alert("✅ Archivo cargado con éxito.");
    } catch (err: any) {
      alert(`❌ ERROR DE CLOUD STORAGE:\n\n${err.message}`);
    } finally {
      setIsProcessing(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const deleteModule = async (id: string) => {
    if (!window.confirm('¿Eliminar módulo y todo su contenido?')) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', id);
      if (error) throw error;
      fetchContent();
    } catch (err: any) {
      alert("Error: " + err.message);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-red-600 font-sans">
      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-widest">
            <ChevronLeft size={16}/> Volver al Master
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <div className="flex items-center gap-6">
          <div className={`flex items-center gap-2 px-4 py-2 rounded-full border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-2 h-2 bg-green-500 rounded-full" />}
             <span className="text-[9px] font-black uppercase text-gray-500">{isProcessing ? 'Sincronizando' : 'Cloud Online'}</span>
          </div>
          <button onClick={onLogout} className="p-2 text-gray-500 hover:text-red-500 transition-colors"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-12">
          <button onClick={() => setActiveTab('content')} className={`px-10 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] border transition-all ${activeTab === 'content' ? 'bg-white text-black border-white shadow-2xl shadow-white/5' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <BookOpen size={16} className="inline mr-3"/> Gestión de Contenido
          </button>
          <button onClick={() => { setActiveTab('users'); fetchUserList(); }} className={`px-10 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] border transition-all ${activeTab === 'users' ? 'bg-white text-black border-white shadow-2xl shadow-white/5' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <Users size={16} className="inline mr-3"/> Alumnos y Acceso
          </button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-40 gap-6">
            <Loader2 className="animate-spin text-red-600" size={40} />
            <p className="text-[10px] font-black uppercase tracking-[0.4em] text-red-600 animate-pulse">Conectando con EZEH Cloud...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            <div className="lg:col-span-4 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.3em]">Jerarquía del Curso</h2>
                <button onClick={() => setIsAddingModule(true)} className="p-3 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/20"><Plus size={24}/></button>
              </div>

              <div className="space-y-4">
                {modules.map((mod, mIdx) => (
                  <div key={mod.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl">
                    <div className="p-5 flex justify-between bg-white/[0.01] border-b border-white/5 items-center">
                      <div className="flex flex-col flex-1 min-w-0">
                        <span className="text-[8px] font-black text-red-600 uppercase tracking-widest mb-0.5">MOD {mIdx + 1}</span>
                        <span className="font-black text-[11px] uppercase tracking-tighter text-gray-300 break-words leading-tight">{mod.title}</span>
                      </div>
                      <button onClick={() => deleteModule(mod.id)} className="text-gray-800 hover:text-red-500 transition-colors p-2 flex-shrink-0"><Trash2 size={16}/></button>
                    </div>
                    <div className="p-4 space-y-2">
                      {mod.lessons?.map(l => (
                        <button key={l.id} onClick={() => setEditingLesson(l)} className={`w-full flex justify-between items-center p-4 rounded-2xl border text-[11px] font-bold transition-all ${editingLesson?.id === l.id ? 'bg-red-600 text-white border-red-600 shadow-xl' : 'bg-black/40 border-white/5 text-gray-500 hover:text-gray-300 hover:bg-white/5'}`}>
                          <span className="pr-4 uppercase tracking-tighter break-words text-left flex-1 leading-normal">{l.title}</span>
                          <Edit3 size={14} className="flex-shrink-0 ml-2" />
                        </button>
                      ))}

                      {addingLessonToModule === mod.id ? (
                        <div className="p-2 space-y-2">
                          <input 
                            maxLength={100}
                            autoFocus
                            type="text" 
                            placeholder="Nombre lección (Max 100)..."
                            className="w-full bg-black border border-white/10 rounded-xl p-3 text-[10px] font-bold outline-none focus:border-red-600"
                            value={newLessonTitle}
                            onChange={(e) => setNewLessonTitle(e.target.value)}
                          />
                          <div className="flex gap-2">
                            <button onClick={() => handleCreateLesson(mod.id)} className="flex-1 bg-red-600 text-[9px] font-black uppercase py-2 rounded-lg">Crear</button>
                            <button onClick={() => setAddingLessonToModule(null)} className="px-3 bg-white/5 text-[9px] font-black uppercase rounded-lg">X</button>
                          </div>
                        </div>
                      ) : (
                        <button onClick={() => setAddingLessonToModule(mod.id)} className="w-full py-4 border-2 border-dashed border-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-700 hover:text-red-600 transition-all">+ Nueva Clase</button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="lg:col-span-8">
              {editingLesson ? (
                <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-8 lg:p-12 space-y-12 shadow-2xl relative">
                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-1 block">Editor de Clase</span>
                      <h2 className="text-4xl font-black tracking-tighter uppercase italic">EZEH<span className="text-red-600">STUDIO</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 hover:bg-red-600 hover:text-white rounded-full transition-all text-gray-600"><X size={20}/></button>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-8">
                      <div className="space-y-3">
                        <div className="flex justify-between ml-2">
                          <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Título (Max 100)</label>
                          <span className="text-[8px] font-bold text-gray-700">{editingLesson.title.length}/100</span>
                        </div>
                        <input maxLength={100} type="text" value={editingLesson.title} onChange={(e) => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-5 font-bold focus:border-red-600 outline-none text-sm text-gray-200" />
                      </div>
                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-2">URL Video</label>
                        <input type="text" value={editingLesson.video_url} onChange={(e) => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-5 text-xs font-mono text-gray-500 focus:border-red-600 outline-none" />
                      </div>
                      <div className="space-y-3">
                        <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-2">Materiales</label>
                        <div className="bg-black/80 border border-white/5 rounded-[2rem] p-6 space-y-3">
                          {editingLesson.resources?.map((res, idx) => (
                            <div key={idx} className="flex items-center justify-between bg-white/[0.03] p-4 rounded-2xl border border-white/5">
                              <span className="text-[10px] font-black truncate uppercase text-white">{res.name}</span>
                              <button onClick={() => {
                                const nr = [...editingLesson.resources];
                                nr.splice(idx, 1);
                                setEditingLesson({...editingLesson, resources: nr});
                              }} className="text-gray-700 hover:text-red-500"><Trash2 size={16}/></button>
                            </div>
                          ))}
                          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                          <button onClick={() => fileInputRef.current?.click()} className="w-full py-4 border-2 border-dashed border-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-500 hover:text-white transition-all">+ Cargar Archivo</button>
                        </div>
                      </div>
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black text-gray-600 uppercase tracking-widest ml-2">Contenido (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={(e) => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm text-gray-400 font-mono resize-none focus:border-red-600 outline-none h-[560px] custom-scrollbar" />
                    </div>
                  </div>

                  <div className="flex gap-6 pt-10 border-t border-white/5">
                    <button onClick={saveLessonChanges} disabled={isProcessing} className="flex-[2] bg-red-600 hover:bg-red-700 text-white py-6 rounded-[1.8rem] font-black uppercase text-[11px] tracking-[0.3em] flex items-center justify-center gap-4">
                      {isProcessing ? <Loader2 className="animate-spin" size={18}/> : <Save size={20}/>} Guardar
                    </button>
                    <button onClick={() => { if(confirm('¿Borrar?')) supabase.from('lessons').delete().eq('id', editingLesson.id).then(() => { setEditingLesson(null); fetchContent(); }) }} className="flex-1 border border-red-600/30 text-red-600 px-8 py-6 rounded-[1.8rem] font-black uppercase text-[10px]">Eliminar</button>
                  </div>
                </div>
              ) : (
                <div className="h-full min-h-[700px] border-2 border-dashed border-white/5 rounded-[4.5rem] flex flex-col items-center justify-center text-center p-20 opacity-10">
                  <Video size={80} className="mb-8" />
                  <h3 className="text-2xl font-black uppercase tracking-widest">EZEH STUDIO</h3>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] overflow-hidden">
             <div className="p-10 border-b border-white/5 flex justify-between items-center">
                <h2 className="text-2xl font-black uppercase tracking-tighter italic">Alumnos Registrados</h2>
                <button onClick={fetchUserList} className="px-6 py-3 bg-white/5 rounded-2xl text-[9px] font-black uppercase">Refrescar</button>
             </div>
             <table className="w-full text-left">
               <tbody className="divide-y divide-white/5">
                 {students.map(student => (
                   <tr key={student.id} className="hover:bg-white/[0.01]">
                     <td className="px-10 py-6">
                       <p className="font-black text-sm uppercase tracking-tighter">{student.fullName}</p>
                       <p className="text-[10px] text-gray-600">{student.email}</p>
                     </td>
                     <td className="px-10 py-6 text-right">
                       <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase ${isUserOnline(student.id) ? 'bg-green-500/10 text-green-500' : 'bg-white/5 text-gray-700'}`}>
                         {isUserOnline(student.id) ? 'Online' : 'Offline'}
                       </span>
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Video, FileText, Loader2, AlertTriangle, ChevronDown, Layers, Layout, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [editingModule, setEditingModule] = useState<Module | null>(null);

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchAllData();
    fetchUserList();
    // Subscripción a presencia para usuarios online
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  async function fetchAllData() {
    setLoading(true);
    try {
      const { data: coursesData, error: coursesError } = await supabase
        .from('courses')
        .select(`
          *,
          modules:modules (
            *,
            lessons:lessons (*)
          )
        `)
        .order('order_index');

      if (coursesError) throw coursesError;

      // Ordenar módulos y lecciones internamente
      const sortedCourses = (coursesData || []).map(course => ({
        ...course,
        modules: (course.modules || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0)).map((mod: any) => ({
          ...mod,
          lessons: (mod.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
        }))
      }));

      setCourses(sortedCourses);
    } catch (err: any) {
      console.error("Error fetching data:", err);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    const { data } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
    if (data) {
      setStudents(data.map((p: any) => ({
        id: p.id,
        fullName: p.full_name || 'Sin nombre',
        email: p.email || 'S/E',
        role: p.role || 'student',
        last_seen: p.last_seen,
        created_at: p.created_at,
        progress: []
      })));
    }
  }

  const toggleCourse = (id: string) => {
    const next = new Set(expandedCourses);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedCourses(next);
  };

  const toggleModule = (id: string) => {
    const next = new Set(expandedModules);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedModules(next);
  };

  // --- OPERACIONES CRUD ---

  const handleCreateCourse = async () => {
    const title = prompt("Título del nuevo curso (Máx 100 caracteres):");
    if (!title) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('courses').insert({
        title: title.substring(0, 100),
        order_index: courses.length,
        description: 'Nueva descripción del curso'
      });
      if (error) throw error;
      await fetchAllData();
    } catch (err: any) { alert(err.message); }
    finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (courseId: string) => {
    const title = prompt("Título del módulo:");
    if (!title) return;
    setIsProcessing(true);
    try {
      const course = courses.find(c => c.id === courseId);
      const { error } = await supabase.from('modules').insert({
        course_id: courseId,
        title: title.substring(0, 100),
        order_index: course?.modules?.length || 0
      });
      if (error) throw error;
      await fetchAllData();
      const next = new Set(expandedCourses);
      next.add(courseId);
      setExpandedCourses(next);
    } catch (err: any) { alert(err.message); }
    finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (moduleId: string) => {
    const title = prompt("Título de la clase:");
    if (!title) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert({
        module_id: moduleId,
        title: title.substring(0, 100),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: 'Contenido de la clase...',
        order_index: 0 // Simplificado para creación rápida
      });
      if (error) throw error;
      await fetchAllData();
      const next = new Set(expandedModules);
      next.add(moduleId);
      setExpandedModules(next);
    } catch (err: any) { alert(err.message); }
    finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title.substring(0, 100),
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources,
        order_index: editingLesson.order_index
      }).eq('id', editingLesson.id);
      if (error) throw error;
      alert("✅ Clase guardada");
      await fetchAllData();
    } catch (err: any) { alert(err.message); }
    finally { setIsProcessing(false); }
  };

  const saveCourse = async () => {
    if (!editingCourse) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('courses').update({
        title: editingCourse.title.substring(0, 100),
        description: editingCourse.description,
        order_index: editingCourse.order_index
      }).eq('id', editingCourse.id);
      if (error) throw error;
      alert("✅ Curso guardado");
      setEditingCourse(null);
      await fetchAllData();
    } catch (err: any) { alert(err.message); }
    finally { setIsProcessing(false); }
  };

  const saveModule = async () => {
    if (!editingModule) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').update({
        title: editingModule.title.substring(0, 100),
        order_index: editingModule.order_index
      }).eq('id', editingModule.id);
      if (error) throw error;
      alert("✅ Módulo guardado");
      setEditingModule(null);
      await fetchAllData();
    } catch (err: any) { alert(err.message); }
    finally { setIsProcessing(false); }
  };

  const handleDelete = async (type: 'course' | 'module' | 'lesson', id: string) => {
    const msg = type === 'course' 
      ? '¡ATENCIÓN! Eliminar un curso borrará permanentemente TODOS sus módulos y clases asociadas. ¿Estás seguro?'
      : '¿Seguro que deseas eliminar este elemento?';

    if (!window.confirm(msg)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      if (editingLesson?.id === id) setEditingLesson(null);
      await fetchAllData();
    } catch (err: any) { alert(err.message); }
    finally { setIsProcessing(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !editingLesson) return;
    setIsProcessing(true);
    try {
      const filePath = `${editingLesson.id}/${Date.now()}_${file.name}`;
      const { error: uploadError } = await supabase.storage.from('materials').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data: { publicUrl } } = supabase.storage.from('materials').getPublicUrl(filePath);
      const newResource = { name: file.name, url: publicUrl };
      setEditingLesson({...editingLesson, resources: [...(editingLesson.resources || []), newResource]});
    } catch (err: any) { alert(err.message); }
    finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-red-600 font-sans">
      {/* NAVBAR */}
      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-widest">
            <ChevronLeft size={16}/> Dashboard Alumno
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex items-center gap-6">
          <div className={`flex items-center gap-2 px-4 py-2 rounded-full border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-2 h-2 bg-green-500 rounded-full" />}
             <span className="text-[9px] font-black uppercase text-gray-500">{isProcessing ? 'Procesando' : 'Ezeh Cloud'}</span>
          </div>
          <button onClick={onLogout} className="p-2 text-gray-500 hover:text-red-500 transition-colors"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-12">
          <button onClick={() => setActiveTab('content')} className={`px-10 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] border transition-all ${activeTab === 'content' ? 'bg-white text-black border-white' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <BookOpen size={16} className="inline mr-3"/> Jerarquía de Cursos
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-10 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] border transition-all ${activeTab === 'users' ? 'bg-white text-black border-white' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <Users size={16} className="inline mr-3"/> Gestión de Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-40 gap-6">
            <Loader2 className="animate-spin text-red-600" size={40} />
            <p className="text-[10px] font-black uppercase tracking-[0.4em] text-red-600">Sincronizando Base de Datos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* PANEL IZQUIERDO: ÁRBOL DE CONTENIDO */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.3em]">Cursos Activos</h2>
                <button onClick={handleCreateCourse} className="p-3 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/20 flex items-center gap-2">
                  <Plus size={20}/> <span className="text-[10px] font-black uppercase">Nuevo Curso</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl">
                    {/* ACORDEÓN CURSO */}
                    <div className="p-6 flex items-center justify-between cursor-pointer hover:bg-white/[0.02] transition-colors" onClick={() => toggleCourse(course.id)}>
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-red-600/10 rounded-xl flex items-center justify-center border border-red-600/20">
                          <Layout size={18} className="text-red-600" />
                        </div>
                        <div>
                          <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                          <p className="text-[9px] text-gray-600 font-bold uppercase tracking-widest">{course.modules?.length || 0} Módulos</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button onClick={(e) => { e.stopPropagation(); setEditingCourse(course); }} className="p-2 text-gray-700 hover:text-white transition-colors"><Edit3 size={14}/></button>
                        <button onClick={(e) => { e.stopPropagation(); handleDelete('course', course.id); }} className="p-2 text-gray-700 hover:text-red-600 transition-colors"><Trash2 size={14}/></button>
                        <ChevronDown size={18} className={`text-gray-700 transition-transform ${expandedCourses.has(course.id) ? 'rotate-180' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} className="overflow-hidden bg-black/40 border-t border-white/5">
                          <div className="p-6 space-y-4">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 rounded-[2rem] overflow-hidden">
                                {/* ACORDEÓN MÓDULO */}
                                <div className="p-4 flex items-center justify-between bg-white/[0.01] cursor-pointer" onClick={() => toggleModule(mod.id)}>
                                  <div className="flex items-center gap-3">
                                    <Layers size={14} className="text-gray-500" />
                                    <span className="font-bold text-[11px] uppercase tracking-tighter text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button onClick={(e) => { e.stopPropagation(); setEditingModule(mod); }} className="p-1.5 text-gray-800 hover:text-white"><Edit3 size={12}/></button>
                                    <button onClick={(e) => { e.stopPropagation(); handleDelete('module', mod.id); }} className="p-1.5 text-gray-800 hover:text-red-500"><Trash2 size={12}/></button>
                                    <ChevronDown size={14} className={`text-gray-800 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/20 space-y-2">
                                    {mod.lessons?.map((lesson) => (
                                      <button key={lesson.id} onClick={() => setEditingLesson(lesson)} className={`w-full flex justify-between items-center p-4 rounded-2xl border text-[10px] font-black uppercase transition-all ${editingLesson?.id === lesson.id ? 'bg-red-600 text-white border-red-600' : 'bg-black/40 border-white/5 text-gray-600 hover:text-gray-300'}`}>
                                        <span className="truncate">{lesson.title}</span>
                                        <Edit3 size={12} />
                                      </button>
                                    ))}
                                    <button onClick={() => handleCreateLesson(mod.id)} className="w-full py-3 border-2 border-dashed border-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-800 hover:text-red-600 transition-all">+ Nueva Clase</button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button onClick={() => handleCreateModule(course.id)} className="w-full py-4 bg-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-500 hover:text-white transition-all">+ Agregar Módulo al Curso</button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* PANEL DERECHO: EDITOR DE ELEMENTOS */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-8 lg:p-12 space-y-10 shadow-2xl sticky top-32">
                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-1 block">Editor de Clase</span>
                      <h2 className="text-3xl font-black tracking-tighter uppercase italic">{editingLesson.title}</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 hover:bg-red-600 hover:text-white rounded-full transition-all text-gray-600"><X size={20}/></button>
                  </div>

                  <div className="space-y-6">
                    <div className="grid grid-cols-2 gap-6">
                      <div className="space-y-2">
                        <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Título de Clase</label>
                        <input maxLength={100} type="text" value={editingLesson.title} onChange={(e) => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-4 font-bold text-sm text-gray-200 outline-none focus:border-red-600" />
                      </div>
                      <div className="space-y-2">
                        <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Orden (Índice)</label>
                        <input type="number" value={editingLesson.order_index} onChange={(e) => setEditingLesson({...editingLesson, order_index: parseInt(e.target.value)})} className="w-full bg-black border border-white/5 rounded-2xl p-4 font-bold text-sm text-gray-200 outline-none focus:border-red-600" />
                      </div>
