                                  </div>
                                )}
                              </div>
                            ))}
                            <button onClick={() => handleCreateModule(course.id)} className="w-full py-4 bg-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-500 hover:text-white transition-all">+ Agregar Módulo</button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* PANEL DERECHO */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-8 lg:p-12 space-y-10 shadow-2xl sticky top-32">
                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-1 block">Editor de Clase</span>
                      <h2 className="text-3xl font-black tracking-tighter uppercase italic">{editingLesson.title}</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 hover:bg-red-600 hover:text-white rounded-full transition-all text-gray-600"><X size={20}/></button>
