                      </div>
                      <div className="space-y-2">
                        <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Orden (Índice)</label>
                        <input type="number" value={editingLesson.order_index} onChange={(e) => setEditingLesson({...editingLesson, order_index: parseInt(e.target.value)})} className="w-full bg-black border border-white/5 rounded-2xl p-4 font-bold text-sm text-gray-200 outline-none focus:border-red-600" />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Video URL (Embed)</label>
                      <input type="text" value={editingLesson.video_url} onChange={(e) => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-4 text-xs font-mono text-gray-500 outline-none focus:border-red-600" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Materiales</label>
                      <div className="bg-black/50 border border-white/5 rounded-2xl p-4 space-y-2">
                        {editingLesson.resources?.map((res, idx) => (
                          <div key={idx} className="flex items-center justify-between bg-white/[0.02] p-3 rounded-xl border border-white/5">
                            <span className="text-[9px] font-black uppercase text-gray-400 truncate">{res.name}</span>
                            <button onClick={() => {
                              const nr = [...editingLesson.resources]; nr.splice(idx, 1);
                              setEditingLesson({...editingLesson, resources: nr});
                            }} className="text-gray-700 hover:text-red-500"><Trash2 size={12}/></button>
                          </div>
                        ))}
                        <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
                        <button onClick={() => fileInputRef.current?.click()} className="w-full py-3 border border-dashed border-white/10 rounded-xl text-[9px] font-black uppercase text-gray-600 hover:text-white transition-all">+ Subir Archivo</button>
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Contenido (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={(e) => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-6 text-sm text-gray-500 font-mono h-40 outline-none focus:border-red-600" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 hover:bg-red-700 text-white py-6 rounded-3xl font-black uppercase text-[11px] tracking-[0.3em] flex items-center justify-center gap-4">
                    <Save size={18}/> {isProcessing ? 'Guardando...' : 'Actualizar Clase'}
                  </button>
                </div>
              ) : editingCourse ? (
                <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-8 lg:p-12 space-y-8 shadow-2xl sticky top-32">
                  <div className="flex justify-between items-center">
                    <h2 className="text-2xl font-black uppercase tracking-tighter italic">Editar Curso</h2>
                    <button onClick={() => setEditingCourse(null)} className="p-3 bg-white/5 rounded-full"><X size={18}/></button>
                  </div>
                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Título</label>
                      <input maxLength={100} type="text" value={editingCourse.title} onChange={(e) => setEditingCourse({...editingCourse, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-4 font-bold text-gray-200 outline-none focus:border-red-600" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Descripción</label>
                      <textarea value={editingCourse.description} onChange={(e) => setEditingCourse({...editingCourse, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-4 text-gray-400 h-24 outline-none focus:border-red-600" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Orden</label>
                      <input type="number" value={editingCourse.order_index} onChange={(e) => setEditingCourse({...editingCourse, order_index: parseInt(e.target.value)})} className="w-full bg-black border border-white/5 rounded-2xl p-4 outline-none focus:border-red-600" />
                    </div>
                  </div>
                  <button onClick={saveCourse} className="w-full bg-white text-black py-6 rounded-3xl font-black uppercase text-[11px] tracking-[0.3em] flex items-center justify-center gap-4">
                    <Save size={18}/> Guardar Curso
                  </button>
                </div>
              ) : editingModule ? (
                <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-8 lg:p-12 space-y-8 shadow-2xl sticky top-32">
                  <div className="flex justify-between items-center">
                    <h2 className="text-2xl font-black uppercase tracking-tighter italic">Editar Módulo</h2>
                    <button onClick={() => setEditingModule(null)} className="p-3 bg-white/5 rounded-full"><X size={18}/></button>
                  </div>
                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Título</label>
                      <input maxLength={100} type="text" value={editingModule.title} onChange={(e) => setEditingModule({...editingModule, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-4 font-bold text-gray-200 outline-none focus:border-red-600" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Orden</label>
                      <input type="number" value={editingModule.order_index} onChange={(e) => setEditingModule({...editingModule, order_index: parseInt(e.target.value)})} className="w-full bg-black border border-white/5 rounded-2xl p-4 outline-none focus:border-red-600" />
                    </div>
                  </div>
                  <button onClick={saveModule} className="w-full bg-red-600 text-white py-6 rounded-3xl font-black uppercase text-[11px] tracking-[0.3em] flex items-center justify-center gap-4">
                    <Save size={18}/> Guardar Módulo
                  </button>
                </div>
              ) : (
                <div className="h-full min-h-[500px] border-2 border-dashed border-white/5 rounded-[4rem] flex flex-col items-center justify-center text-center p-20 opacity-20">
                  <MoveVertical size={32} className="mb-6" />
                  <h3 className="text-xl font-black uppercase tracking-widest">Editor Central</h3>
                  <p className="text-[10px] font-bold text-gray-600 mt-4 uppercase tracking-[0.2em]">Selecciona un elemento para editarlo</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          /* GESTIÓN DE USUARIOS */
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] overflow-hidden shadow-2xl">
             <div className="p-10 border-b border-white/5 flex justify-between items-center">
                <h2 className="text-2xl font-black uppercase tracking-tighter italic">Alumnos</h2>
                <div className="px-6 py-2 bg-red-600/10 border border-red-600/20 rounded-full">
                  <span className="text-[10px] font-black uppercase text-red-500">{students.length} Miembros</span>
                </div>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                 <thead className="border-b border-white/5 bg-black/50">
                   <tr>
                     <th className="px-10 py-5 text-[9px] font-black uppercase tracking-[0.3em] text-gray-500">Nombre</th>
                     <th className="px-10 py-5 text-[9px] font-black uppercase tracking-[0.3em] text-gray-500">Estado</th>
                     <th className="px-10 py-5 text-[9px] font-black uppercase tracking-[0.3em] text-gray-500">Email</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-white/5">
                   {students.map(student => (
                     <tr key={student.id} className="hover:bg-white/[0.01] transition-colors group">
                       <td className="px-10 py-6 font-black text-sm uppercase tracking-tighter">{student.fullName}</td>
                       <td className="px-10 py-6">
                         <div className={`flex items-center gap-2 text-[8px] font-black uppercase ${onlineUserIds.has(student.id) ? 'text-green-500' : 'text-gray-700'}`}>
                           <div className={`w-1.5 h-1.5 rounded-full ${onlineUserIds.has(student.id) ? 'bg-green-500 animate-pulse' : 'bg-gray-800'}`} />
                           {onlineUserIds.has(student.id) ? 'Online' : 'Offline'}
                         </div>
                       </td>
                       <td className="px-10 py-6 text-[10px] font-mono text-gray-500">{student.email}</td>
                     </tr>
                   ))}
                 </tbody>
               </table>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Video, FileText, Loader2, AlertTriangle, ChevronDown, Layers, Layout, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [editingModule, setEditingModule] = useState<Module | null>(null);

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchAllData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  async function fetchAllData() {
    setLoading(true);
    try {
      console.log("Sincronizando jerarquía completa...");
      const { data: coursesData, error: coursesError } = await supabase
        .from('courses')
        .select(`
          *,
          modules (*, lessons (*))
        `)
        .order('order_index');

      if (coursesError) throw coursesError;

      const sortedCourses = (coursesData || []).map(course => ({
        ...course,
        modules: (course.modules || [])
          .sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          .map((mod: any) => ({
            ...mod,
            lessons: (mod.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          }))
      }));

      setCourses(sortedCourses);
    } catch (err: any) {
      console.error("Error fetching admin data:", err.message || err);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'S/E',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("Error fetching user list:", err.message || err);
    }
  }

  const toggleCourse = (id: string) => {
    const next = new Set(expandedCourses);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedCourses(next);
  };

  const toggleModule = (id: string) => {
    const next = new Set(expandedModules);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedModules(next);
  };

  // --- REPARACIÓN: NUEVO CURSO ---
  const handleCreateCourse = async () => {
    console.log("Botón 'NUEVO CURSO' presionado");
    const title = window.prompt("Título del nuevo curso (Máx 100 caracteres):");
    if (!title || title.trim() === "") {
      console.log("Operación cancelada o título vacío");
      return;
    }

    setIsProcessing(true);
    try {
      console.log("Intentando insertar curso en Supabase...");
      const { data, error } = await supabase.from('courses').insert([
        { 
          title: title.trim().substring(0, 100),
          description: 'Nueva descripción del curso creada desde el panel.',
          order_index: courses.length 
        }
      ]).select();

      if (error) {
        console.error("Error de Supabase:", error);
        throw error;
      }

      console.log("Curso creado exitosamente:", data);
      await fetchAllData();
      alert("✅ Curso creado correctamente.");
    } catch (err: any) {
      console.error("Error al crear curso:", err);
      alert(`❌ ERROR DE SUPABASE: ${err.message || "No se pudo crear el curso"}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCreateModule = async (courseId: string) => {
    const title = prompt("Título del módulo:");
    if (!title) return;
    setIsProcessing(true);
    try {
      const course = courses.find(c => c.id === courseId);
      const { error } = await supabase.from('modules').insert([
        {
          course_id: courseId,
          title: title.substring(0, 100),
          order_index: course?.modules?.length || 0
        }
      ]);
      if (error) throw error;
      await fetchAllData();
      const next = new Set(expandedCourses);
      next.add(courseId);
      setExpandedCourses(next);
    } catch (err: any) { alert(`❌ Error: ${err.message}`); }
    finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (moduleId: string) => {
    const title = prompt("Título de la clase:");
    if (!title) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([
        {
          module_id: moduleId,
          title: title.substring(0, 100),
          video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
          description: 'Contenido inicial de la clase...',
          order_index: 0 
        }
      ]);
      if (error) throw error;
      await fetchAllData();
      const next = new Set(expandedModules);
      next.add(moduleId);
      setExpandedModules(next);
    } catch (err: any) { alert(`❌ Error: ${err.message}`); }
    finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title.substring(0, 100),
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources,
        order_index: editingLesson.order_index
      }).eq('id', editingLesson.id);
      if (error) throw error;
      alert("✅ Sincronizado");
      await fetchAllData();
    } catch (err: any) { alert(`❌ Error al guardar: ${err.message}`); }
    finally { setIsProcessing(false); }
  };

  const saveCourse = async () => {
    if (!editingCourse) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('courses').update({
        title: editingCourse.title.substring(0, 100),
        description: editingCourse.description,
        order_index: editingCourse.order_index
      }).eq('id', editingCourse.id);
      if (error) throw error;
      alert("✅ Curso actualizado");
      setEditingCourse(null);
      await fetchAllData();
    } catch (err: any) { alert(`❌ Error: ${err.message}`); }
    finally { setIsProcessing(false); }
  };

  const saveModule = async () => {
    if (!editingModule) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').update({
        title: editingModule.title.substring(0, 100),
        order_index: editingModule.order_index
      }).eq('id', editingModule.id);
      if (error) throw error;
      alert("✅ Módulo actualizado");
      setEditingModule(null);
      await fetchAllData();
    } catch (err: any) { alert(`❌ Error: ${err.message}`); }
    finally { setIsProcessing(false); }
  };

  const handleDelete = async (type: 'course' | 'module' | 'lesson', id: string) => {
    const msg = type === 'course' 
      ? '¡BORRADO CRÍTICO! Eliminar este curso destruirá todos sus módulos y clases. ¿Continuar?'
      : '¿Eliminar este elemento?';

    if (!window.confirm(msg)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      if (editingLesson?.id === id) setEditingLesson(null);
      await fetchAllData();
    } catch (err: any) { alert(`❌ Error al eliminar: ${err.message}`); }
    finally { setIsProcessing(false); }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !editingLesson) return;
    setIsProcessing(true);
    try {
      const filePath = `${editingLesson.id}/${Date.now()}_${file.name}`;
      const { error: uploadError } = await supabase.storage.from('materials').upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data: { publicUrl } } = supabase.storage.from('materials').getPublicUrl(filePath);
      const newResource = { name: file.name, url: publicUrl };
      setEditingLesson({...editingLesson, resources: [...(editingLesson.resources || []), newResource]});
    } catch (err: any) { alert(`❌ Error de carga: ${err.message}`); }
    finally { setIsProcessing(false); }
  };

  return (
