import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Play, CheckCircle, Menu, X, FileText, LogOut, ExternalLink, Bookmark, Star
} from 'lucide-react';
import { User, Module, Lesson, Course } from '../types.ts';
import { Link } from 'react-router-dom';
import { marked } from 'marked';
import { supabase } from '../lib/supabase.ts';
import VideoPlayer from '../components/VideoPlayer.tsx';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [course, setCourse] = useState<Course | null>(null);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [progress, setProgress] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [rating, setRating] = useState(0);

  useEffect(() => {
    fetchInitialData();
  }, []);

  async function fetchInitialData() {
    setLoading(true);
    try {
      console.log("Cargando experiencia educativa...");
      const { data: coursesData, error: coursesError } = await supabase
        .from('courses')
        .select(`
          *,
          modules (*, lessons (*))
        `)
        .order('order_index')
        .limit(1)
        .maybeSingle();

      if (coursesError) throw coursesError;

      if (coursesData) {
        const sortedModules = (coursesData.modules || [])
          .sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          .map((m: any) => ({
            ...m,
            lessons: (m.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          }));

        const finalCourse = { ...coursesData, modules: sortedModules };
        setCourse(finalCourse);

        if (sortedModules.length > 0 && sortedModules[0].lessons?.length > 0) {
          setActiveLesson(sortedModules[0].lessons[0]);
        }
      }

      const { data: progressData, error: progressError } = await supabase
        .from('user_progress')
        .select('lesson_id')
        .eq('user_id', user.id);

      if (progressError) throw progressError;
      if (progressData) setProgress(progressData.map((p: any) => p.lesson_id));

    } catch (err: any) {
      console.error("Error crítico en Dashboard:", err.message || err);
    } finally {
      setLoading(false);
    }
  }

  const onToggleProgress = async (lessonId: string) => {
    try {
      if (progress.includes(lessonId)) {
        const { error } = await supabase.from('user_progress').delete().eq('user_id', user.id).eq('lesson_id', lessonId);
        if (error) throw error;
        setProgress(prev => prev.filter(id => id !== lessonId));
      } else {
        const { error } = await supabase.from('user_progress').insert({ user_id: user.id, lesson_id: lessonId });
        if (error) throw error;
        setProgress(prev => [...prev, lessonId]);
      }
    } catch (e: any) {
      console.error("Error al actualizar progreso:", e.message);
    }
  };

  const progressPercent = useMemo(() => {
    if (!course || !course.modules) return 0;
    const total = course.modules.reduce((acc, mod) => acc + (mod.lessons?.length || 0), 0);
    return total > 0 ? Math.round((progress.length / total) * 100) : 0;
  }, [course, progress]);

  const htmlDescription = useMemo(() => activeLesson ? marked.parse(activeLesson.description || '') : '', [activeLesson]);

  if (loading) {
    return (
      <div className="min-h-screen bg-[#050505] flex flex-col items-center justify-center gap-6">
        <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin shadow-[0_0_20px_rgba(239,68,68,0.4)]" />
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-red-600 animate-pulse">Sincronizando con Ezeh Cloud...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#050505] text-white flex flex-col selection:bg-red-600 selection:text-white font-sans">
      <nav className="fixed top-0 w-full z-50 bg-black/60 backdrop-blur-2xl border-b border-white/5 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-6">
          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 hover:bg-white/10 rounded-xl transition-all">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
          <div className="text-2xl font-black italic tracking-tighter flex items-center gap-2">
            <span className="text-red-600">EZEH</span> ACADEMY
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end gap-1.5">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Tu Progreso</span>
              <span className="text-xs font-bold text-red-500">{progressPercent}%</span>
            </div>
            <div className="w-40 h-1.5 bg-white/10 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} className="h-full bg-red-600 shadow-[0_0_10px_rgba(239,68,68,0.5)]" />
            </div>
          </div>

          <div className="flex items-center gap-4">
            {user.role === 'admin' && (
              <Link to="/admin" className="p-2 text-gray-500 hover:text-white transition-colors"><Bookmark size={20} /></Link>
            )}
            <button onClick={onLogout} className="text-gray-500 hover:text-red-600 transition-colors"><LogOut size={18}/></button>
            <div className="w-10 h-10 rounded-full bg-red-600 flex items-center justify-center font-black border border-white/10 shadow-xl">{user.fullName.charAt(0)}</div>
          </div>
        </div>
      </nav>

      <div className="flex flex-1 pt-[72px] h-screen overflow-hidden">
        <AnimatePresence>
          {isSidebarOpen && (
            <motion.aside initial={{ x: -350 }} animate={{ x: 0 }} exit={{ x: -350 }} className="w-full lg:w-[350px] bg-[#080808] border-r border-white/5 overflow-y-auto custom-scrollbar flex-shrink-0">
              <div className="p-8">
                {course ? (
                  <>
                    <div className="mb-10">
                      <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em] mb-4">Maestría Actual</h2>
                      <h1 className="text-sm font-black uppercase italic tracking-tighter text-white">{course.title}</h1>
                    </div>

                    <h2 className="text-[10px] font-black text-gray-700 uppercase tracking-[0.4em] mb-6">Módulos del Programa</h2>
                    {course.modules?.map((mod, i) => (
                      <div key={mod.id} className="mb-6">
                        <div className="flex items-center gap-3 mb-3">
                           <span className="text-[9px] font-black text-red-600 uppercase bg-red-600/10 px-2 py-0.5 rounded">MOD {i + 1}</span>
                           <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 break-words leading-relaxed">{mod.title}</h3>
                        </div>
                        <div className="space-y-1.5">
                          {mod.lessons?.map(l => {
                            const isCompleted = progress.includes(l.id);
                            return (
                              <div 
                                key={l.id} 
                                onClick={() => setActiveLesson(l)}
                                className={`w-full text-left p-4 rounded-2xl text-[11px] font-bold transition-all flex items-center justify-between group relative cursor-pointer ${activeLesson?.id === l.id ? 'bg-white/10 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'}`}
                              >
                                <span className="uppercase tracking-tighter pr-4 break-words flex-1 leading-normal">{l.title}</span>
                                <button
                                  onClick={(e) => { e.stopPropagation(); onToggleProgress(l.id); }}
                                  className={`relative w-8 h-8 flex-shrink-0 rounded-lg flex items-center justify-center transition-all duration-500 overflow-hidden ${isCompleted ? 'bg-green-600 shadow-[0_0_15px_rgba(34,197,94,0.4)]' : 'bg-white/5 border border-white/20 text-white/50 hover:text-white'}`}
                                >
                                  <CheckCircle size={14} className={`relative z-10 ${isCompleted ? 'scale-110 text-white' : 'scale-90 opacity-40'}`} />
                                </button>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    ))}
                  </>
                ) : (
                  <div className="py-20 text-center opacity-20">
                    <p className="text-[10px] font-black uppercase tracking-[0.3em]">No hay contenido disponible</p>
                  </div>
                )}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        <main className="flex-1 overflow-y-scroll bg-black p-4 lg:p-12 custom-scrollbar" style={{ scrollbarGutter: 'stable' }}>
          {activeLesson ? (
            <div className="max-w-6xl mx-auto">
              <div className="mb-14">
                <VideoPlayer url={activeLesson.video_url} title={activeLesson.title} />
              </div>

              <div className="flex flex-col md:flex-row items-start md:items-end justify-between gap-8 mb-10 border-b border-white/5 pb-10">
                <div className="flex-1 min-w-0">
                  <h1 className="text-2xl lg:text-3xl font-black italic tracking-tighter uppercase leading-tight break-words">
                    {activeLesson.title}
                  </h1>
                </div>

                <div className="w-[180px] h-[52px] flex-shrink-0 flex flex-col items-start md:items-end justify-end gap-2.5 relative">
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-600 block select-none mb-0.5">Valoración</span>
                  <div className="flex gap-1 items-center justify-center h-8 w-full relative">
                    {[1, 2, 3, 4, 5].map((star) => {
                      const isActive = star <= rating;
                      const isExactlyThis = star === rating;
                      return (
                        <div key={star} className="relative w-8 h-8 flex-shrink-0 pointer-events-auto">
                          <button onClick={() => setRating(star)} className="absolute inset-0 flex items-center justify-center outline-none focus:outline-none transition-none">
                            <motion.div animate={isExactlyThis ? { rotate: [0, 360], scale: [1, 1.25, 1] } : { rotate: 0, scale: 1 }} transition={{ duration: 0.6, ease: "easeOut" }}>
                              <Star size={20} strokeWidth={2} fill={isActive ? "#FFD700" : "none"} className={`transition-colors duration-200 ${isActive ? "text-yellow-400 drop-shadow-[0_0_8px_rgba(255,215,0,0.4)]" : "text-gray-700"}`} />
                            </motion.div>
                            <AnimatePresence>
                              {isExactlyThis && (
                                <motion.div initial={{ scale: 0, opacity: 0 }} animate={{ scale: 2.2, opacity: [0, 0.4, 0] }} exit={{ opacity: 0 }} transition={{ duration: 0.5 }} className="absolute inset-0 bg-yellow-400 blur-2xl rounded-full pointer-events-none -z-10" />
                              )}
                            </AnimatePresence>
                          </button>
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>

              <div className="mb-20">
                <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-headings:text-white prose-strong:text-red-500 leading-relaxed text-lg" 
                     dangerouslySetInnerHTML={{ __html: htmlDescription }} />
              </div>

              <div className="border-t border-white/5 pt-12 pb-24">
                <div className="flex items-center gap-4 mb-8">
                   <div className="w-10 h-10 bg-red-600/10 rounded-xl flex items-center justify-center border border-red-600/20">
                      <FileText size={20} className="text-red-600" />
                   </div>
                   <div>
                      <h3 className="text-lg font-black uppercase tracking-tighter italic">Recursos</h3>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest">Materiales descargables</p>
                   </div>
                </div>

                <div className="flex flex-wrap gap-4">
                  {activeLesson.resources?.map((r, i) => (
                    <motion.a key={i} href={r.url} target="_blank" rel="noopener noreferrer" whileHover={{ y: -5, borderColor: '#ef4444' }} className="flex items-center gap-4 p-5 bg-[#080808] border border-white/10 rounded-[1.5rem] min-w-[280px] max-w-xs transition-colors group/res">
                      <div className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center group-hover/res:bg-red-600/20 transition-colors">
                        <FileText size={18} className="text-gray-500 group-hover/res:text-red-600" />
                      </div>
                      <div className="flex-1 truncate">
                        <p className="text-[11px] font-black uppercase tracking-tighter truncate">{r.name}</p>
                        <p className="text-[9px] text-gray-600 font-bold uppercase mt-0.5">Descargar</p>
                      </div>
                      <ExternalLink size={14} className="text-gray-800 group-hover/res:text-red-600 transition-colors" />
                    </motion.a>
                  ))}
                  {(!activeLesson.resources || activeLesson.resources.length === 0) && (
                    <div className="w-full text-center py-16 border-2 border-dashed border-white/5 rounded-[3rem] opacity-20">
                       <p className="text-xs font-black uppercase tracking-[0.3em]">No hay archivos adjuntos</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-20">
               <div className="relative mb-10">
                  <div className="absolute inset-0 bg-red-600/20 blur-3xl rounded-full animate-pulse" />
                  <div className="relative w-32 h-32 bg-white/5 rounded-full flex items-center justify-center border border-white/10">
                    <Play size={48} className="opacity-10 ml-2" />
                  </div>
               </div>
               <h3 className="text-3xl font-black uppercase tracking-[0.5em] italic">EZEH <span className="text-red-600">ACADEMY</span></h3>
               <p className="text-[10px] font-bold text-gray-700 mt-6 uppercase tracking-[0.3em] max-w-sm leading-loose">
                 Selecciona una lección para comenzar tu formación.
               </p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

// Defined Lesson with optional module_id for static initial data
export interface Lesson {
  id: string;
  module_id: string;
  title: string;
  video_url: string;
  description: string;
  resources: { name: string; url: string }[];
  order_index: number;
  created_at?: string;
}

export interface Module {
  id: string;
  course_id: string;
  title: string;
  lessons: Lesson[];
  order_index: number;
  created_at?: string;
}

export interface Course {
  id: string;
  title: string;
  description: string;
  order_index: number;
  modules: Module[];
  created_at?: string;
}

export interface User {
  id: string;
  email: string;
  role: 'admin' | 'student';
  fullName: string;
  progress: string[];
  last_seen?: string;
  created_at?: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [editingCourse, setEditingCourse] = useState<Course | null>(null);
  const [editingModule, setEditingModule] = useState<Module | null>(null);

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    fetchAllData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  async function fetchAllData() {
    setLoading(true);
    try {
      console.log("Admin: Sincronizando datos...");
      const { data, error } = await supabase
        .from('courses')
        .select('*, modules (*, lessons (*))')
        .order('order_index');

      if (error) throw error;

      const sortedData = (data || []).map((course: any) => ({
        ...course,
        modules: (course.modules || [])
          .sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          .map((mod: any) => ({
            ...mod,
            lessons: (mod.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          }))
      }));

      setCourses(sortedData);
    } catch (err: any) {
      console.error("Error en Admin fetchAllData:", err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'S/E',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("Error en Admin fetchUserList:", err.message);
    }
  }

  const handleCreateCourse = async () => {
    const title = window.prompt("Título del nuevo curso:");
    if (!title || title.trim() === "") return;

    setIsProcessing(true);
    try {
      const { data, error } = await supabase.from('courses').insert([
        { 
          title: title.trim(),
          description: 'Sin descripción.',
          order_index: courses.length 
        }
      ]).select();

      if (error) throw error;
      console.log("Curso creado:", data);
      await fetchAllData();
      alert("✅ Curso creado.");
    } catch (err: any) {
      alert(`❌ Error al crear curso: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCreateModule = async (courseId: string) => {
    const title = window.prompt("Título del módulo:");
    if (!title || title.trim() === "") return;

    setIsProcessing(true);
    try {
      const { data, error } = await supabase.from('modules').insert([
        {
          course_id: courseId,
          title: title.trim(),
          order_index: 0
        }
      ]).select();

      if (error) throw error;
      await fetchAllData();
      const next = new Set(expandedCourses);
      next.add(courseId);
      setExpandedCourses(next);
    } catch (err: any) {
      alert(`❌ Error al crear módulo: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCreateLesson = async (moduleId: string) => {
    const title = window.prompt("Título de la clase:");
    if (!title || title.trim() === "") return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([
        {
          module_id: moduleId,
          title: title.trim(),
          video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
          description: 'Contenido...',
          order_index: 0,
          resources: []
        }
      ]).select();

      if (error) throw error;
      await fetchAllData();
      const next = new Set(expandedModules);
      next.add(moduleId);
      setExpandedModules(next);
    } catch (err: any) {
      alert(`❌ Error al crear clase: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources,
        order_index: editingLesson.order_index
      }).eq('id', editingLesson.id);

      if (error) throw error;
      alert("✅ Cambios guardados.");
      await fetchAllData();
    } catch (err: any) {
      alert(`❌ Error al guardar clase: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDelete = async (type: 'course' | 'module' | 'lesson', id: string) => {
    const confirm = window.confirm(`¿Estás seguro de eliminar este ${type}?`);
    if (!confirm) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      if (editingLesson?.id === id) setEditingLesson(null);
      await fetchAllData();
    } catch (err: any) {
      alert(`❌ Error al eliminar: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600">
      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-widest">
            <ChevronLeft size={16}/> Volver al Master
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex items-center gap-6">
          <div className={`flex items-center gap-2 px-4 py-2 rounded-full border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-2 h-2 bg-green-500 rounded-full" />}
             <span className="text-[9px] font-black uppercase text-gray-500">{isProcessing ? 'Procesando' : 'Online'}</span>
          </div>
          <button onClick={onLogout} className="p-2 text-gray-500 hover:text-red-500 transition-colors"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-12">
          <button onClick={() => setActiveTab('content')} className={`px-10 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] border transition-all ${activeTab === 'content' ? 'bg-white text-black border-white shadow-2xl shadow-white/5' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <BookOpen size={16} className="inline mr-3"/> Jerarquía
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-10 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] border transition-all ${activeTab === 'users' ? 'bg-white text-black border-white shadow-2xl shadow-white/5' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <Users size={16} className="inline mr-3"/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-40 gap-6">
            <Loader2 className="animate-spin text-red-600" size={40} />
            <p className="text-[10px] font-black uppercase tracking-[0.4em] text-red-600">Conectando...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.3em]">Cursos</h2>
                <button onClick={handleCreateCourse} disabled={isProcessing} className="p-3 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/20 flex items-center gap-2 disabled:opacity-50">
                  {isProcessing ? <Loader2 className="animate-spin" size={20} /> : <Plus size={20}/>}
                  <span className="text-[10px] font-black uppercase">Nuevo Curso</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.length === 0 && (
                  <div className="p-10 border-2 border-dashed border-white/5 rounded-[3rem] text-center opacity-20">
                    <p className="text-[10px] font-black uppercase tracking-widest">Aún no hay cursos.</p>
                  </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl">
                    <div className="p-6 flex items-center justify-between cursor-pointer hover:bg-white/[0.02]" onClick={() => {
                      const next = new Set(expandedCourses);
                      if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                      setExpandedCourses(next);
                    }}>
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-red-600/10 rounded-xl flex items-center justify-center border border-red-600/20">
                          <Layout size={18} className="text-red-600" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200 truncate">{course.title}</h3>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <button onClick={(e) => { e.stopPropagation(); handleDelete('course', course.id); }} className="p-2 text-gray-700 hover:text-red-600"><Trash2 size={14}/></button>
                        <ChevronDown size={18} className={`text-gray-700 transition-transform ${expandedCourses.has(course.id) ? 'rotate-180' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} className="overflow-hidden bg-black/40 border-t border-white/5">
                          <div className="p-6 space-y-4">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 rounded-[2rem] overflow-hidden">
                                <div className="p-4 flex items-center justify-between bg-white/[0.01] cursor-pointer" onClick={() => {
                                  const next = new Set(expandedModules);
                                  if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                  setExpandedModules(next);
                                }}>
                                  <div className="flex items-center gap-3">
                                    <Layers size={14} className="text-gray-500" />
                                    <span className="font-bold text-[11px] uppercase tracking-tighter text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button onClick={(e) => { e.stopPropagation(); handleDelete('module', mod.id); }} className="p-1.5 text-gray-800 hover:text-red-500"><Trash2 size={12}/></button>
                                  </div>
                                </div>
                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/20 space-y-2">
                                    {mod.lessons?.map((lesson) => (
                                      <button key={lesson.id} onClick={() => setEditingLesson(lesson)} className={`w-full flex justify-between items-center p-4 rounded-2xl border text-[10px] font-black uppercase ${editingLesson?.id === lesson.id ? 'bg-red-600 text-white border-red-600' : 'bg-black/40 border-white/5 text-gray-600'}`}>
                                        <span className="truncate">{lesson.title}</span>
                                        <Edit3 size={12} />
                                      </button>
                                    ))}
                                    <button onClick={() => handleCreateLesson(mod.id)} className="w-full py-3 border border-dashed border-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-800 hover:text-red-600">+ Nueva Clase</button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button onClick={() => handleCreateModule(course.id)} className="w-full py-4 bg-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-500 hover:text-white">+ Agregar Módulo</button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            <div className="lg:col-span-7">
              {editingLesson ? (
                <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-8 lg:p-12 space-y-10 shadow-2xl sticky top-32">
                  <div className="flex justify-between items-start">
                    <div>
                      <span className="text-[10px] font-black text-red-600 uppercase tracking-widest block mb-2">Editor de Clase</span>
                      <h2 className="text-2xl font-black tracking-tighter uppercase italic">{editingLesson.title}</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-3 bg-white/5 hover:bg-red-600 rounded-full transition-all"><X size={20}/></button>
                  </div>

                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Título de Clase</label>
                      <input type="text" value={editingLesson.title} onChange={(e) => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-4 font-bold text-gray-200 focus:border-red-600 outline-none" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Video URL</label>
                      <input type="text" value={editingLesson.video_url} onChange={(e) => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-4 text-xs font-mono text-gray-500 focus:border-red-600 outline-none" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-2">Descripción (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={(e) => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-6 text-sm text-gray-500 font-mono h-40 focus:border-red-600 outline-none custom-scrollbar" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 hover:bg-red-700 text-white py-6 rounded-3xl font-black uppercase text-[11px] tracking-[0.3em] flex items-center justify-center gap-4">
                    {isProcessing ? <Loader2 className="animate-spin" size={20} /> : <Save size={18}/>} 
                    Sincronizar Clase
                  </button>
                </div>
              ) : (
                <div className="h-full min-h-[500px] border-2 border-dashed border-white/5 rounded-[4rem] flex flex-col items-center justify-center text-center p-20 opacity-20">
                  <MoveVertical size={32} className="mb-6" />
                  <h3 className="text-xl font-black uppercase tracking-widest">EZEH EDITOR</h3>
                  <p className="text-[10px] font-bold text-gray-600 mt-4 uppercase tracking-[0.2em]">Selecciona un elemento para editarlo.</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] overflow-hidden shadow-2xl">
             <div className="p-10 border-b border-white/5 flex justify-between items-center">
                <h2 className="text-2xl font-black uppercase tracking-tighter italic">Alumnos</h2>
                <span className="text-[10px] font-black uppercase text-red-500 bg-red-600/10 px-4 py-2 rounded-full border border-red-600/20">{students.length} Miembros</span>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                 <thead className="border-b border-white/5 bg-black/50">
                   <tr>
                     <th className="px-10 py-5 text-[9px] font-black uppercase tracking-[0.3em] text-gray-500">Nombre</th>
                     <th className="px-10 py-5 text-[9px] font-black uppercase tracking-[0.3em] text-gray-500">Estado</th>
                     <th className="px-10 py-5 text-[9px] font-black uppercase tracking-[0.3em] text-gray-500">Email</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-white/5">
                   {students.map(student => (
                     <tr key={student.id} className="hover:bg-white/[0.01]">
                       <td className="px-10 py-6 font-black text-sm uppercase tracking-tighter">{student.fullName}</td>
                       <td className="px-10 py-6">
                         <div className={`flex items-center gap-2 text-[8px] font-black uppercase ${onlineUserIds.has(student.id) ? 'text-green-500' : 'text-gray-700'}`}>
                           <div className={`w-1.5 h-1.5 rounded-full ${onlineUserIds.has(student.id) ? 'bg-green-500 animate-pulse' : 'bg-gray-800'}`} />
                           {onlineUserIds.has(student.id) ? 'Online' : 'Desconectado'}
                         </div>
                       </td>
                       <td className="px-10 py-6 text-[10px] font-mono text-gray-500">{student.email}</td>
