import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Play, CheckCircle, Menu, X, FileText, LogOut, ExternalLink, Bookmark, Star
} from 'lucide-react';
import { User, Module, Lesson, Course } from '../types.ts';
import { Link } from 'react-router-dom';
import { marked } from 'marked';
import { supabase } from '../lib/supabase.ts';
import VideoPlayer from '../components/VideoPlayer.tsx';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [course, setCourse] = useState<Course | null>(null);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [progress, setProgress] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [rating, setRating] = useState(0);

  useEffect(() => {
    fetchInitialData();
  }, []);

  async function fetchInitialData() {
    setLoading(true);
    try {
      console.log("Dashboard: Cargando contenido...");
      const { data, error } = await supabase
        .from('courses')
        .select('*, modules (*, lessons (*))')
        .order('order_index')
        .limit(1)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        const sortedModules = (data.modules || [])
          .sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          .map((m: any) => ({
            ...m,
            lessons: (m.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          }));

        setCourse({ ...data, modules: sortedModules });

        if (sortedModules.length > 0 && sortedModules[0].lessons?.length > 0) {
          setActiveLesson(sortedModules[0].lessons[0]);
        }
      }

      const { data: progressData } = await supabase.from('user_progress').select('lesson_id').eq('user_id', user.id);
      if (progressData) setProgress(progressData.map((p: any) => p.lesson_id));

    } catch (err: any) {
      console.error("Dashboard Error:", err.message);
    } finally {
      setLoading(false);
    }
  }

  const onToggleProgress = async (lessonId: string) => {
    try {
      if (progress.includes(lessonId)) {
        await supabase.from('user_progress').delete().eq('user_id', user.id).eq('lesson_id', lessonId);
        setProgress(prev => prev.filter(id => id !== lessonId));
      } else {
        await supabase.from('user_progress').insert({ user_id: user.id, lesson_id: lessonId });
        setProgress(prev => [...prev, lessonId]);
      }
    } catch (e: any) {
      console.error("Progress Toggle Error:", e.message);
    }
  };

  const progressPercent = useMemo(() => {
    if (!course || !course.modules) return 0;
    const total = course.modules.reduce((acc, mod) => acc + (mod.lessons?.length || 0), 0);
    return total > 0 ? Math.round((progress.length / total) * 100) : 0;
  }, [course, progress]);

  const htmlDescription = useMemo(() => activeLesson ? marked.parse(activeLesson.description || '') : '', [activeLesson]);

  if (loading) {
    return (
      <div className="min-h-screen bg-[#050505] flex flex-col items-center justify-center gap-6">
        <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin shadow-[0_0_20px_rgba(239,68,68,0.4)]" />
        <p className="text-[10px] font-black uppercase tracking-[0.5em] text-red-600 animate-pulse">Sincronizando...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#050505] text-white flex flex-col selection:bg-red-600 font-sans">
      <nav className="fixed top-0 w-full z-50 bg-black/60 backdrop-blur-2xl border-b border-white/5 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-6">
          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 hover:bg-white/10 rounded-xl transition-all">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
          <div className="text-2xl font-black italic tracking-tighter flex items-center gap-2 uppercase">
            <span className="text-red-600">EZEH</span> ACADEMY
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end gap-1.5">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-500">Progreso</span>
              <span className="text-xs font-bold text-red-500">{progressPercent}%</span>
            </div>
            <div className="w-40 h-1.5 bg-white/10 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} className="h-full bg-red-600 shadow-[0_0_10px_rgba(239,68,68,0.5)]" />
            </div>
          </div>

          <div className="flex items-center gap-4">
            {user.role === 'admin' && (
              <Link to="/admin" className="p-2 text-gray-500 hover:text-white transition-colors"><Bookmark size={20} /></Link>
            )}
            <button onClick={onLogout} className="text-gray-500 hover:text-red-600 transition-colors"><LogOut size={18}/></button>
            <div className="w-10 h-10 rounded-full bg-red-600 flex items-center justify-center font-black border border-white/10 shadow-xl">{user.fullName.charAt(0)}</div>
          </div>
        </div>
      </nav>

      <div className="flex flex-1 pt-[72px] h-screen overflow-hidden">
        <AnimatePresence>
          {isSidebarOpen && (
            <motion.aside initial={{ x: -350 }} animate={{ x: 0 }} exit={{ x: -350 }} className="w-full lg:w-[350px] bg-[#080808] border-r border-white/5 overflow-y-auto custom-scrollbar flex-shrink-0">
              <div className="p-8">
                {course ? (
                  <>
                    <div className="mb-10">
                      <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em] mb-4">Maestría Actual</h2>
                      <h1 className="text-sm font-black uppercase italic tracking-tighter text-white">{course.title}</h1>
                    </div>

                    <h2 className="text-[10px] font-black text-gray-700 uppercase tracking-[0.4em] mb-6">Módulos</h2>
                    {course.modules?.map((mod, i) => (
                      <div key={mod.id} className="mb-6">
                        <div className="flex items-center gap-3 mb-3">
                           <span className="text-[9px] font-black text-red-600 uppercase bg-red-600/10 px-2 py-0.5 rounded">MOD {i + 1}</span>
                           <h3 className="text-xs font-black uppercase tracking-widest text-gray-400 leading-relaxed">{mod.title}</h3>
                        </div>
                        <div className="space-y-1.5">
                          {mod.lessons?.map(l => (
                            <div key={l.id} onClick={() => setActiveLesson(l)} className={`w-full text-left p-4 rounded-2xl text-[11px] font-bold transition-all flex items-center justify-between group cursor-pointer ${activeLesson?.id === l.id ? 'bg-white/10 text-white shadow-xl' : 'text-gray-500 hover:bg-white/5'}`}>
                              <span className="uppercase tracking-tighter pr-4 break-words flex-1 leading-normal">{l.title}</span>
                              <button onClick={(e) => { e.stopPropagation(); onToggleProgress(l.id); }} className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${progress.includes(l.id) ? 'bg-green-600 text-white' : 'bg-white/5 text-white/50 border border-white/20'}`}>
                                <CheckCircle size={14} />
                              </button>
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </>
                ) : (
                  <div className="py-20 text-center opacity-20">
                    <p className="text-[10px] font-black uppercase tracking-[0.3em]">No hay cursos disponibles.</p>
                  </div>
                )}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        <main className="flex-1 overflow-y-scroll bg-black p-4 lg:p-12 custom-scrollbar">
          {activeLesson ? (
            <div className="max-w-6xl mx-auto">
              <div className="mb-14">
                <VideoPlayer url={activeLesson.video_url} title={activeLesson.title} />
              </div>

              <div className="flex flex-col md:flex-row items-start md:items-end justify-between gap-8 mb-10 border-b border-white/5 pb-10">
                <h1 className="text-2xl lg:text-3xl font-black italic tracking-tighter uppercase break-words flex-1">
                  {activeLesson.title}
                </h1>

                <div className="w-[180px] flex flex-col items-start md:items-end">
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-600 mb-2">Valoración</span>
                  <div className="flex gap-1 h-8">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <button key={star} onClick={() => setRating(star)} className="outline-none">
                        <Star size={20} fill={star <= rating ? "#FFD700" : "none"} className={`transition-colors ${star <= rating ? "text-yellow-400" : "text-gray-700"}`} />
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <div className="mb-20">
                <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-headings:text-white leading-relaxed text-lg" 
                     dangerouslySetInnerHTML={{ __html: htmlDescription }} />
              </div>

              <div className="border-t border-white/5 pt-12 pb-24">
                <div className="flex items-center gap-4 mb-8">
                   <div className="w-10 h-10 bg-red-600/10 rounded-xl flex items-center justify-center border border-red-600/20">
                      <FileText size={20} className="text-red-600" />
                   </div>
                   <h3 className="text-lg font-black uppercase tracking-tighter italic">Materiales</h3>
                </div>

                <div className="flex flex-wrap gap-4">
                  {activeLesson.resources?.map((r, i) => (
                    <motion.a key={i} href={r.url} target="_blank" rel="noopener noreferrer" whileHover={{ y: -5, borderColor: '#ef4444' }} className="flex items-center gap-4 p-5 bg-[#080808] border border-white/10 rounded-[1.5rem] min-w-[280px] max-w-xs transition-colors group">
                      <div className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center group-hover:bg-red-600/20">
                        <FileText size={18} className="text-gray-500 group-hover:text-red-600" />
                      </div>
                      <div className="flex-1 truncate">
                        <p className="text-[11px] font-black uppercase tracking-tighter truncate">{r.name}</p>
                        <p className="text-[9px] text-gray-600 font-bold uppercase mt-0.5">Descargar</p>
                      </div>
                      <ExternalLink size={14} className="text-gray-800 group-hover:text-red-600" />
                    </motion.a>
                  ))}
                  {(!activeLesson.resources || activeLesson.resources.length === 0) && (
                    <div className="w-full text-center py-16 border-2 border-dashed border-white/5 rounded-[3rem] opacity-20">
                       <p className="text-xs font-black uppercase tracking-[0.3em]">Sin archivos adjuntos</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-20">
               <div className="relative mb-10">
                  <div className="absolute inset-0 bg-red-600/20 blur-3xl rounded-full animate-pulse" />
                  <div className="relative w-32 h-32 bg-white/5 rounded-full flex items-center justify-center border border-white/10">
                    <Play size={48} className="opacity-10 ml-2" />
                  </div>
               </div>
               <h3 className="text-3xl font-black uppercase tracking-[0.5em] italic">EZEH <span className="text-red-600">ACADEMY</span></h3>
               <p className="text-[10px] font-bold text-gray-700 mt-6 uppercase tracking-[0.3em] max-w-sm leading-loose">
                 Selecciona una lección del currículo para empezar.
               </p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

