          .sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          .map((m: any) => ({
            ...m,
            lessons: (m.lessons || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
          }));

        setCourse({ ...data, modules: sortedModules });

        if (sortedModules.length > 0 && sortedModules[0].lessons?.length > 0) {
          setActiveLesson(sortedModules[0].lessons[0]);
        }
      }

      const { data: progressData, error: progressError } = await supabase.from('user_progress').select('lesson_id').eq('user_id', user.id);
