import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Play, CheckCircle, Menu, X, FileText, LogOut, ExternalLink, Bookmark, Star, RefreshCw, AlertCircle, Database, Check
} from 'lucide-react';
import { User, Module, Lesson, Course } from '../types.ts';
import { Link } from 'react-router-dom';
import { marked } from 'marked';
import { supabase } from '../lib/supabase.ts';
import VideoPlayer from '../components/VideoPlayer.tsx';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [course, setCourse] = useState<Course | null>(null);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [progress, setProgress] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [rating, setRating] = useState(0);
  const [dbError, setDbError] = useState<string | null>(null);

  useEffect(() => {
    fetchInitialData();
  }, []);

  async function fetchInitialData() {
    setLoading(true);
    setDbError(null);
    try {
      console.log("Dashboard: Sincronizando jerarquía completa con order_index...");

      // 1. Obtener la estructura del curso ordenada
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true })
        .limit(1)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setCourse(data as Course);
        // Autoseleccionar la primera lección si no hay ninguna activa
        const firstLesson = data.modules?.[0]?.lessons?.[0];
        if (firstLesson) {
          setActiveLesson(firstLesson);
        }
      }

      // 2. Obtener el progreso del usuario
      const { data: progressData, error: progressError } = await supabase
        .from('user_progress')
        .select('lesson_id')
        .eq('user_id', user.id);

      if (progressError) {
        // Manejo silencioso: Si la tabla falla, simplemente no cargamos progreso
        console.warn("Error cargando progreso (posible tabla faltante):", progressError.message);
        if (progressError.message.includes("schema cache") || progressError.message.includes("not found")) {
          setDbError("La tabla user_progress no está lista.");
        }
      } else if (progressData) {
        setProgress(progressData.map((p: any) => p.lesson_id));
      }

    } catch (err: any) {
      console.error("DASHBOARD_FATAL_ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  const onToggleProgress = async (lessonId: string) => {
    try {
      if (progress.includes(lessonId)) {
        // Marcar como NO completada
        const { error } = await supabase
          .from('user_progress')
          .delete()
          .eq('user_id', user.id)
          .eq('lesson_id', lessonId);

        if (error) throw error;
        setProgress(prev => prev.filter(id => id !== lessonId));
      } else {
        // Marcar como completada
        const { error } = await supabase
          .from('user_progress')
          .insert({ user_id: user.id, lesson_id: lessonId });

        if (error) throw error;
        setProgress(prev => [...prev, lessonId]);
      }
    } catch (e: any) {
      console.error("PROGRESS_UPDATE_ERROR:", e.message);
      alert("Error al sincronizar progreso. Asegúrate de que la tabla 'user_progress' exista.");
    }
  };

  const progressPercent = useMemo(() => {
    if (!course || !course.modules) return 0;
    const allLessons = course.modules.flatMap(m => m.lessons || []);
    if (allLessons.length === 0) return 0;
    return Math.round((progress.length / allLessons.length) * 100);
  }, [course, progress]);

  const htmlDescription = useMemo(() => activeLesson ? marked.parse(activeLesson.description || '') : '', [activeLesson]);

  if (loading) {
    return (
      <div className="min-h-screen bg-[#050505] flex flex-col items-center justify-center gap-6">
        <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin shadow-[0_0_30px_rgba(239,68,68,0.3)]" />
        <div className="text-center">
          <p className="text-[10px] font-black uppercase tracking-[0.5em] text-red-600 animate-pulse italic">Cargando Academia</p>
          <p className="text-gray-600 text-[8px] mt-2 font-bold uppercase tracking-widest">Estableciendo conexión estratégica...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#050505] text-white flex flex-col selection:bg-red-600 font-sans">
      {/* HEADER DE ALTO IMPACTO */}
      <nav className="fixed top-0 w-full z-50 bg-black/60 backdrop-blur-2xl border-b border-white/5 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-6">
          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 hover:bg-white/10 rounded-xl transition-all border border-transparent hover:border-white/5">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
          <div className="text-2xl font-black italic tracking-tighter flex items-center gap-2 uppercase select-none">
            <span className="text-red-600">EZEH</span> ACADEMY
          </div>
        </div>

        <div className="flex items-center gap-8">
          {/* BARRA DE PROGRESO GLOBAL */}
          <div className="hidden md:flex flex-col items-end gap-1.5">
            <div className="flex items-center gap-3">
              <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-500">Avance del Master</span>
              <span className="text-xs font-bold text-red-500">{progressPercent}%</span>
            </div>
            <div className="w-48 h-1.5 bg-white/5 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} className="h-full bg-red-600 shadow-[0_0_15px_#ef4444]" />
            </div>
          </div>

          <div className="flex items-center gap-4">
            {user.role === 'admin' && (
              <Link to="/admin" className="p-2.5 text-gray-500 hover:text-white transition-all bg-white/5 rounded-xl border border-white/5 hover:border-red-600/30">
                <Bookmark size={20} />
              </Link>
            )}
            <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 transition-colors bg-white/5 rounded-xl border border-white/5 hover:border-red-600/30">
              <LogOut size={18}/>
            </button>
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-red-600 to-red-900 flex items-center justify-center font-black border border-white/20 shadow-2xl shadow-red-600/20">
              {user.fullName?.charAt(0)}
            </div>
          </div>
        </div>
      </nav>

      <div className="flex flex-1 pt-[72px] h-screen overflow-hidden">
        {/* SIDEBAR DE CURRÍCULO MODULAR */}
        <AnimatePresence>
          {isSidebarOpen && (
            <motion.aside initial={{ x: -350, opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: -350, opacity: 0 }} className="w-full lg:w-[360px] bg-[#080808] border-r border-white/5 overflow-y-auto custom-scrollbar flex-shrink-0">
              <div className="p-8 pb-32">
                {course ? (
                  <>
                    <div className="mb-12">
                      <h2 className="text-[9px] font-black text-gray-600 uppercase tracking-[0.4em] mb-4">Currículo del Master</h2>
                      <h1 className="text-sm font-black uppercase italic tracking-tighter text-white leading-tight">{course.title}</h1>
                    </div>

                    {course.modules && course.modules.length > 0 ? (
                      course.modules.map((mod, i) => (
                        <div key={mod.id} className="mb-10">
                          <div className="flex items-center gap-3 mb-4">
                             <span className="text-[8px] font-black text-red-600 uppercase bg-red-600/10 px-2 py-0.5 rounded border border-red-600/20">MOD {i + 1}</span>
                             <h3 className="text-xs font-black uppercase tracking-[0.1em] text-gray-400 truncate">{mod.title}</h3>
                          </div>
                          <div className="space-y-2 ml-1 border-l border-white/5 pl-5 py-1">
                            {mod.lessons && mod.lessons.map(l => (
                              <button 
                                key={l.id} 
                                onClick={() => setActiveLesson(l)} 
                                className={`w-full text-left p-4 rounded-2xl text-[11px] font-bold transition-all flex items-center justify-between group border ${activeLesson?.id === l.id ? 'bg-white/10 text-white border-white/10 shadow-2xl' : 'text-gray-500 hover:bg-white/5 border-transparent'}`}
                              >
                                <span className="uppercase tracking-tighter pr-4 break-words flex-1 leading-normal group-hover:text-white transition-colors">
                                  {l.title}
                                </span>
                                <div 
                                  onClick={(e) => { e.stopPropagation(); onToggleProgress(l.id); }} 
                                  className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${progress.includes(l.id) ? 'bg-green-600 text-white shadow-lg shadow-green-600/20 scale-110' : 'bg-white/5 text-white/20 border border-white/10 group-hover:border-white/30'}`}
                                >
                                  {progress.includes(l.id) ? <Check size={14} strokeWidth={3} /> : <CheckCircle size={14} />}
                                </div>
                              </button>
                            ))}
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="py-20 text-center px-4">
                        <AlertCircle size={32} className="mx-auto text-gray-800 mb-4" />
                        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-700">Contenido en preparación.</p>
                      </div>
                    )}
                  </>
                ) : (
                  <div className="py-24 text-center">
                    <RefreshCw className="animate-spin mx-auto text-red-600 mb-6" size={32} />
                    <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-30">Cargando formación...</p>
                  </div>
                )}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        {/* REPRODUCTOR Y CONTENIDO */}
        <main className="flex-1 overflow-y-scroll bg-black p-4 lg:p-12 custom-scrollbar relative">
          {activeLesson ? (
            <div className="max-w-6xl mx-auto pb-40">
              {/* VIDEO PLAYER */}
              <div className="mb-14 group/player relative">
                <div className="absolute -inset-1 bg-gradient-to-r from-red-600 to-red-900 rounded-[1.8rem] blur opacity-10 group-hover/player:opacity-20 transition duration-1000"></div>
                <div className="relative">
                   <VideoPlayer url={activeLesson.video_url} title={activeLesson.title} />
                </div>
              </div>

              {/* TÍTULO Y RATING */}
              <div className="flex flex-col md:flex-row items-start md:items-end justify-between gap-10 mb-12 border-b border-white/5 pb-12">
                <div className="flex-1">
                  <span className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-3 block">Sesión Activa</span>
                  <h1 className="text-3xl lg:text-4xl font-black italic tracking-tighter uppercase break-words leading-[0.9]">
                    {activeLesson.title}
                  </h1>
                </div>

                <div className="flex flex-col items-start md:items-end gap-3 bg-white/5 p-6 rounded-3xl border border-white/5">
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-500">Valoración de Clase</span>
                  <div className="flex gap-1.5">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <button key={star} onClick={() => setRating(star)} className="outline-none transform active:scale-90 transition-transform">
                        <Star size={22} fill={star <= rating ? "#FFD700" : "none"} className={`transition-colors ${star <= rating ? "text-yellow-400 drop-shadow-[0_0_10px_rgba(255,215,0,0.5)]" : "text-gray-800"}`} />
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {/* DESCRIPCIÓN Y RECURSOS */}
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-20">
                <div className="lg:col-span-8">
                  <h3 className="text-xl font-black uppercase tracking-tighter italic mb-8 flex items-center gap-4">
                    <span className="w-8 h-px bg-red-600"></span> Resumen Estratégico
                  </h3>
                  <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-p:text-lg prose-headings:text-white leading-relaxed" 
                       dangerouslySetInnerHTML={{ __html: htmlDescription }} />
                </div>

                <div className="lg:col-span-4">
                  <div className="bg-[#080808] border border-white/5 rounded-[2.5rem] p-8 lg:p-10 sticky top-8">
                    <h3 className="text-lg font-black uppercase tracking-tighter italic mb-8 flex items-center gap-3">
                      <FileText size={20} className="text-red-600" /> Materiales
                    </h3>

                    <div className="space-y-4">
                      {activeLesson.resources && activeLesson.resources.length > 0 ? (
                        activeLesson.resources.map((r, i) => (
                          <motion.a key={i} href={r.url} target="_blank" rel="noopener noreferrer" whileHover={{ x: 5 }} className="flex items-center gap-4 p-5 bg-white/5 border border-white/10 rounded-2xl transition-all group hover:border-red-600/50">
                            <div className="w-10 h-10 bg-black rounded-xl flex items-center justify-center group-hover:bg-red-600/10 transition-colors">
                              <FileText size={18} className="text-gray-500 group-hover:text-red-600 transition-colors" />
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="text-[11px] font-black uppercase tracking-tighter truncate text-gray-200">{r.name}</p>
                              <p className="text-[9px] text-gray-600 font-bold uppercase mt-1">Descargar</p>
                            </div>
                            <ExternalLink size={14} className="text-gray-800 group-hover:text-red-600 transition-colors" />
                          </motion.a>
                        ))
                      ) : (
                        <div className="text-center py-12 border border-dashed border-white/5 rounded-3xl opacity-20">
                           <p className="text-[9px] font-black uppercase tracking-[0.2em]">Sin archivos adjuntos</p>
                        </div>
                      )}
                    </div>

                    <button 
                      onClick={() => onToggleProgress(activeLesson.id)} 
                      className={`w-full mt-10 py-5 rounded-2xl font-black uppercase text-[10px] tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${progress.includes(activeLesson.id) ? 'bg-green-600/10 text-green-500 border border-green-600/20' : 'bg-red-600 hover:bg-red-700 text-white shadow-2xl shadow-red-600/20'}`}
                    >
                      {progress.includes(activeLesson.id) ? (
                        <><Check size={16} strokeWidth={3}/> Clase Completada</>
                      ) : (
                        'Marcar Finalizada'
                      )}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-20 select-none">
               <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="relative mb-14">
                  <div className="absolute inset-0 bg-red-600/20 blur-[120px] rounded-full animate-pulse" />
                  <div className="relative w-40 h-40 bg-white/5 rounded-[3rem] flex items-center justify-center border border-white/10 rotate-12">
                    <Play size={64} className="text-white/5 ml-3 -rotate-12" />
                  </div>
               </motion.div>
               <h3 className="text-4xl font-black uppercase tracking-[0.4em] italic leading-tight text-white/50">
                 CENTRAL DE <span className="text-red-600">FORMACIÓN</span>
               </h3>
               <p className="text-[11px] font-bold text-gray-700 mt-8 uppercase tracking-[0.5em] max-w-sm leading-relaxed">
                 Selecciona un módulo del currículo lateral para comenzar tu transformación digital.
               </p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, Database, CheckCircle2
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchAllData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  async function fetchAllData() {
    setLoading(true);
    try {
      console.log("Admin: Sincronizando jerarquía estratégica...");
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  const handleCreateCourse = async () => {
    console.log("Iniciando creación de curso...");
    if (!newCourseData.title.trim()) return;

    setIsProcessing(true);
    try {
      // 1. Insertar el curso
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([
          { 
            title: newCourseData.title.trim(),
            description: newCourseData.description.trim() || 'Nueva formación estratégica.',
            order_index: courses.length
          }
        ])
        .select()
        .single();

      if (courseError) throw courseError;
      console.log("Curso creado exitosamente:", courseData.id);

      // 2. Crear módulo de bienvenida automático
      const { error: moduleError } = await supabase
        .from('modules')
        .insert([
          {
            course_id: courseData.id,
            title: 'Módulo 1: Bienvenida e Introducción',
            order_index: 0
          }
        ]);

      if (moduleError) throw moduleError;
      console.log("Módulo inicial creado.");

      // 3. Reset y actualizar
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchAllData();

      // Expandir el nuevo curso automáticamente
      setExpandedCourses(prev => new Set([...prev, courseData.id]));

      console.log("Proceso de creación finalizado correctamente.");
    } catch (err: any) {
      console.error("CREATE_COURSE_ERROR:", err.message);
      alert(`Error crítico al crear curso: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCreateModule = async (courseId: string) => {
    const title = window.prompt("Título del módulo educativo:");
    if (!title || title.trim() === "") return;

    const currentCourse = courses.find(c => c.id === courseId);
    const orderIndex = currentCourse?.modules?.length || 0;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([
        {
          course_id: courseId,
          title: title.trim(),
          order_index: orderIndex
        }
      ]);

      if (error) throw error;
      await fetchAllData();
      setExpandedCourses(prev => new Set([...prev, courseId]));
    } catch (err: any) {
      alert(`ERROR: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCreateLesson = async (moduleId: string) => {
    const title = window.prompt("Título de la lección:");
    if (!title || title.trim() === "") return;

    let orderIndex = 0;
    courses.forEach(c => {
      const m = c.modules?.find(mod => mod.id === moduleId);
      if (m) orderIndex = m.lessons?.length || 0;
    });

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([
        {
          module_id: moduleId,
          title: title.trim(),
          video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
          description: '# Nueva Clase\nBienvenido al contenido premium.',
          resources: [],
          order_index: orderIndex
        }
      ]);

      if (error) throw error;
      await fetchAllData();
      setExpandedModules(prev => new Set([...prev, moduleId]));
    } catch (err: any) {
      alert(`ERROR: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources,
        order_index: editingLesson.order_index
      }).eq('id', editingLesson.id);

      if (error) throw error;
      await fetchAllData();
      alert("Sincronización completada.");
    } catch (err: any) {
      alert(`ERROR AL GUARDAR: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDelete = async (type: 'course' | 'module' | 'lesson', id: string) => {
    const confirm = window.confirm(`¿Seguro que deseas eliminar este ${type}? Esta acción es irreversible.`);
    if (!confirm) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      if (editingLesson?.id === id) setEditingLesson(null);
      await fetchAllData();
    } catch (err: any) {
      alert(`ERROR AL ELIMINAR: ${err.message}`);
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600">
      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver al Master
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex items-center gap-6">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Procesando' : 'Activo'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 transition-all bg-white/5 rounded-xl border border-white/5"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-14">
          <button onClick={() => setActiveTab('content')} className={`flex-1 lg:flex-none px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center justify-center gap-4 ${activeTab === 'content' ? 'bg-white text-black border-white shadow-[0_20px_40px_rgba(255,255,255,0.1)]' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <BookOpen size={18}/> Contenido
          </button>
          <button onClick={() => setActiveTab('users')} className={`flex-1 lg:flex-none px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center justify-center gap-4 ${activeTab === 'users' ? 'bg-white text-black border-white shadow-[0_20px_40px_rgba(255,255,255,0.1)]' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44 gap-8">
            <Loader2 className="animate-spin text-red-600" size={48} />
            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-red-600 animate-pulse">Sincronizando base de datos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Estructura de Cursos</h2>
                <button 
                  onClick={() => {
                    console.log("Clic en CREAR CURSO");
                    setShowCreateModal(true);
                  }} 
                  disabled={isProcessing} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 disabled:opacity-50 active:scale-95"
                >
                  <Plus size={20}/>
                  <span className="text-[10px] font-black uppercase tracking-widest">Crear Curso</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.length === 0 && (
                  <div className="p-16 border-2 border-dashed border-white/5 rounded-[3.5rem] text-center opacity-30 flex flex-col items-center gap-4">
                    <AlertTriangle size={32} />
                    <p className="text-[10px] font-black uppercase tracking-widest">Sin cursos vinculados en el sistema.</p>
                  </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl transition-all hover:border-white/10">
                    <div className="p-8 flex items-center justify-between cursor-pointer group" onClick={() => {
                      const next = new Set(expandedCourses);
                      if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                      setExpandedCourses(next);
                    }}>
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600/20 transition-all">
                          <Layout size={20} className="text-red-600" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200 truncate">{course.title}</h3>
                          <p className="text-[9px] text-gray-600 font-bold uppercase mt-1 tracking-widest">{course.modules?.length || 0} Módulos</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        <button onClick={(e) => { e.stopPropagation(); handleDelete('course', course.id); }} className="p-2.5 text-gray-800 hover:text-red-600 transition-colors bg-white/5 rounded-xl"><Trash2 size={14}/></button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden bg-white/[0.01] border-t border-white/5">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.02] transition-colors" onClick={() => {
                                  const next = new Set(expandedModules);
                                  if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                  setExpandedModules(next);
                                }}>
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-[0.1em] text-gray-400">{mod.title}</span>
                                  </div>
                                  <button onClick={(e) => { e.stopPropagation(); handleDelete('module', mod.id); }} className="p-2 text-gray-800 hover:text-red-500 transition-colors"><Trash2 size={12}/></button>
                                </div>
                                {expandedModules.has(mod.id) && (
                                  <div className="p-5 bg-black/40 border-t border-white/5 space-y-3">
                                    {mod.lessons?.map((lesson) => (
                                      <button key={lesson.id} onClick={() => setEditingLesson(lesson)} className={`w-full flex justify-between items-center p-5 rounded-2xl border text-[10px] font-black uppercase transition-all active:scale-[0.98] ${editingLesson?.id === lesson.id ? 'bg-red-600 text-white border-red-600 shadow-xl' : 'bg-black/60 border-white/5 text-gray-600 hover:border-white/20'}`}>
                                        <span className="truncate pr-4 leading-relaxed">{lesson.title}</span>
                                        <Edit3 size={12} className={editingLesson?.id === lesson.id ? 'text-white' : 'text-gray-800'} />
                                      </button>
                                    ))}
                                    <button onClick={() => handleCreateLesson(mod.id)} className="w-full py-4 border border-dashed border-white/10 rounded-2xl text-[9px] font-black uppercase text-gray-700 hover:text-red-600 hover:border-red-600/50 transition-all">+ Nueva Clase</button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button onClick={() => handleCreateModule(course.id)} className="w-full py-5 bg-white/5 rounded-3xl text-[9px] font-black uppercase text-gray-500 hover:text-white hover:bg-white/10 transition-all tracking-[0.2em]">+ Agregar Módulo</button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-8 lg:p-14 space-y-12 shadow-2xl sticky top-32">
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <span className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] block mb-3">Editor Maestro</span>
                      <h2 className="text-3xl font-black tracking-tighter uppercase italic leading-[0.8]">{editingLesson.title}</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 hover:bg-red-600 rounded-2xl transition-all border border-white/5"><X size={20}/></button>
                  </div>

                  <div className="space-y-8">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-3">
                        <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-3">Título de la Lección</label>
                        <input type="text" value={editingLesson.title} onChange={(e) => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-5 font-bold text-gray-200 focus:border-red-600 outline-none transition-all" />
                      </div>
                      <div className="space-y-3">
                        <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-3">Orden (order_index)</label>
                        <input type="number" value={editingLesson.order_index || 0} onChange={(e) => setEditingLesson({...editingLesson, order_index: parseInt(e.target.value)})} className="w-full bg-black border border-white/5 rounded-3xl p-5 font-bold text-gray-200 focus:border-red-600 outline-none transition-all" />
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-3">Video Embed URL</label>
                      <input type="text" value={editingLesson.video_url} onChange={(e) => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-5 text-xs font-mono text-gray-500 focus:border-red-600 outline-none transition-all" />
                    </div>

                    <div className="space-y-3">
                      <label className="text-[9px] font-black text-gray-600 uppercase tracking-widest ml-3">Síntesis (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={(e) => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm text-gray-500 font-mono h-56 focus:border-red-600 outline-none custom-scrollbar transition-all leading-relaxed" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 hover:bg-red-700 text-white py-8 rounded-[2.5rem] font-black uppercase text-[12px] tracking-[0.4em] flex items-center justify-center gap-5 transition-all shadow-[0_30px_60px_rgba(239,68,68,0.2)] active:scale-[0.98] disabled:opacity-50">
                    {isProcessing ? <Loader2 className="animate-spin" size={24} /> : <Save size={22}/>} 
                    Sincronizar Lección
                  </button>
                </motion.div>
              ) : (
                <div className="h-full min-h-[600px] border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none">
                  <div className="w-32 h-32 bg-white/5 rounded-full flex items-center justify-center mb-10 border border-white/10">
                    <MoveVertical size={40} className="text-gray-400" />
                  </div>
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">CENTRAL DE <span className="text-red-600">MANDO</span></h3>
                  <p className="text-[11px] font-bold text-gray-600 mt-6 uppercase tracking-[0.3em] max-w-xs leading-loose">
                    Selecciona una clase para editar su núcleo de conocimiento.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }} className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] overflow-hidden shadow-2xl">
             <div className="p-12 border-b border-white/5 flex justify-between items-center bg-white/[0.01]">
                <h2 className="text-2xl font-black uppercase tracking-tighter italic">Base de Datos de Alumnos</h2>
                <span className="text-[10px] font-black uppercase text-red-500 bg-red-600/10 px-6 py-3 rounded-full border border-red-600/20">{students.length} Miembros Registrados</span>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                 <thead className="border-b border-white/5 bg-black/50">
                   <tr>
                     <th className="px-12 py-7 text-[9px] font-black uppercase tracking-[0.4em] text-gray-600">Identidad</th>
                     <th className="px-12 py-7 text-[9px] font-black uppercase tracking-[0.4em] text-gray-600">Estado Online</th>
                     <th className="px-12 py-7 text-[9px] font-black uppercase tracking-[0.4em] text-gray-600">Credenciales</th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-white/5">
                   {students.map(student => (
                     <tr key={student.id} className="hover:bg-white/[0.01] transition-colors group">
                       <td className="px-12 py-8 font-black text-sm uppercase tracking-tighter flex items-center gap-5">
                          <div className="w-10 h-10 bg-white/5 rounded-xl flex items-center justify-center text-xs text-gray-600 group-hover:text-white transition-colors">
                            {student.fullName.charAt(0)}
                          </div>
                          {student.fullName}
                       </td>
                       <td className="px-12 py-8">
                         <div className={`flex items-center gap-3 text-[9px] font-black uppercase tracking-widest ${onlineUserIds.has(student.id) ? 'text-green-500' : 'text-gray-700'}`}>
                           <div className={`w-2 h-2 rounded-full ${onlineUserIds.has(student.id) ? 'bg-green-500 shadow-[0_0_10px_#22c55e] animate-pulse' : 'bg-gray-900'}`} />
                           {onlineUserIds.has(student.id) ? 'En Línea' : 'Offline'}
                         </div>
                       </td>
                       <td className="px-12 py-8 text-[11px] font-mono text-gray-600 group-hover:text-gray-400 transition-colors tracking-tighter">{student.email}</td>
                     </tr>
                   ))}
                 </tbody>
               </table>
             </div>
          </motion.div>
        )}
      </div>

      {/* MODAL DE CREACIÓN PREMIUM */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
            <motion.div 
              initial={{ opacity: 0 }} 
              animate={{ opacity: 1 }} 
              exit={{ opacity: 0 }} 
              onClick={() => !isProcessing && setShowCreateModal(false)}
              className="absolute inset-0 bg-black/80 backdrop-blur-md" 
            />
            <motion.div 
              initial={{ scale: 0.9, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.9, opacity: 0, y: 20 }}
              className="relative w-full max-w-xl bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-10 lg:p-14 shadow-[0_0_100px_rgba(239,68,68,0.1)]"
            >
              <div className="flex justify-between items-center mb-10">
                <h3 className="text-2xl font-black italic uppercase tracking-tighter"><span className="text-red-600">Nuevo</span> Curso</h3>
                <button onClick={() => setShowCreateModal(false)} className="text-gray-500 hover:text-white"><X size={24}/></button>
              </div>

              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-600 ml-3">Título Maestro</label>
                  <input 
                    type="text" 
                    value={newCourseData.title}
                    onChange={(e) => setNewCourseData({...newCourseData, title: e.target.value})}
                    placeholder="Ej: Master en E-Commerce"
                    className="w-full bg-black border border-white/5 rounded-3xl p-6 font-bold text-lg focus:border-red-600 outline-none transition-all"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-600 ml-3">Descripción Breve</label>
                  <textarea 
                    value={newCourseData.description}
                    onChange={(e) => setNewCourseData({...newCourseData, description: e.target.value})}
                    placeholder="Explica qué aprenderán en esta formación..."
                    className="w-full bg-black border border-white/5 rounded-3xl p-6 text-sm font-medium h-32 focus:border-red-600 outline-none transition-all"
                  />
                </div>
              </div>

              <button 
                onClick={handleCreateCourse} 
                disabled={isProcessing || !newCourseData.title.trim()}
                className="w-full mt-10 bg-red-600 hover:bg-red-700 text-white py-6 rounded-3xl font-black uppercase text-xs tracking-[0.3em] flex items-center justify-center gap-4 transition-all disabled:opacity-50"
              >
                {isProcessing ? <Loader2 className="animate-spin" size={20}/> : <CheckCircle2 size={20}/>}
                Lanzar Formación
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchAllData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  // Auto-hide notifications
  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 5000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchAllData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  const handleCreateCourse = async () => {
    console.log("🚀 Ejecutando handleCreateCourse...");
    if (!newCourseData.title.trim()) {
      setNotification({ type: 'error', msg: 'El título es obligatorio.' });
      return;
    }

    setIsProcessing(true);
    try {
      // 1. Inserción del Curso (Dejamos que Supabase genere el ID)
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([
          { 
            title: newCourseData.title.trim(),
            description: newCourseData.description.trim() || 'Nueva formación estratégica de alto nivel.',
            order_index: courses.length // Al final de la lista
          }
        ])
        .select()
        .single();

      if (courseError) {
        console.error("❌ Error al insertar curso:", courseError);
        throw courseError;
      }

      console.log("✅ Curso creado ID:", courseData.id);

      // 2. Inserción automática de Módulo de Bienvenida
      const { error: moduleError } = await supabase
        .from('modules')
        .insert([
          {
            course_id: courseData.id,
            title: 'Módulo 0: Bienvenida e Instrucciones',
            order_index: 0
          }
        ]);

      if (moduleError) {
        console.warn("⚠️ Curso creado pero falló el módulo inicial:", moduleError);
      }

      // 3. Éxito y Limpieza
      setNotification({ type: 'success', msg: '¡Curso y estructura inicial creados con éxito!' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });

      // Actualización dinámica del estado local
      await fetchAllData();

      // Auto-expandir el nuevo curso
      setExpandedCourses(prev => new Set([...prev, courseData.id]));

    } catch (err: any) {
      console.error("🔴 Error en el proceso de creación:", err.message);
      setNotification({ 
        type: 'error', 
        msg: err.message.includes('RLS') 
          ? 'Error de permisos (RLS). Revisa las políticas en Supabase.' 
          : `Error: ${err.message}` 
      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDelete = async (type: 'course' | 'module' | 'lesson', id: string) => {
    if (!window.confirm(`¿Seguro que deseas eliminar este ${type}? Se borrarán todos sus contenidos dependientes.`)) return;
    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      setNotification({ type: 'success', msg: `${type.toUpperCase()} eliminado correctamente.` });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: `Error al eliminar: ${err.message}` });
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative">
      {/* TOAST SYSTEM */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -100, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -100, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[200] px-8 py-5 rounded-[2rem] border shadow-2xl flex items-center gap-4 min-w-[320px] backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/10 border-green-500/30 text-green-400' : 'bg-red-600/10 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-xs font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver al Master
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex items-center gap-6">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Sincronizando' : 'Sist. Operativo'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 transition-all bg-white/5 rounded-xl border border-white/5"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-14">
          <button onClick={() => setActiveTab('content')} className={`flex-1 lg:flex-none px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center justify-center gap-4 ${activeTab === 'content' ? 'bg-white text-black border-white shadow-[0_20px_40px_rgba(255,255,255,0.1)]' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <BookOpen size={18}/> Contenido
          </button>
          <button onClick={() => setActiveTab('users')} className={`flex-1 lg:flex-none px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center justify-center gap-4 ${activeTab === 'users' ? 'bg-white text-black border-white shadow-[0_20px_40px_rgba(255,255,255,0.1)]' : 'bg-white/5 text-gray-500 border-white/5 hover:bg-white/10'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44 gap-8">
            <Loader2 className="animate-spin text-red-600" size={48} />
            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-red-600 animate-pulse">Estableciendo conexión estratégica...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Estructura de Cursos</h2>
                <button 
                  onClick={() => {
                    console.log("🟢 Abriendo modal de creación...");
                    setShowCreateModal(true);
                  }} 
                  disabled={isProcessing}
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 disabled:opacity-50 active:scale-95"
                >
                  <Plus size={20}/>
                  <span className="text-[10px] font-black uppercase tracking-widest">Crear Curso</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.length === 0 && (
                  <div className="p-16 border-2 border-dashed border-white/5 rounded-[3.5rem] text-center opacity-30 flex flex-col items-center gap-4">
                    <AlertTriangle size={32} />
                    <p className="text-[10px] font-black uppercase tracking-widest">Base de datos de cursos vacía.</p>
                  </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl transition-all hover:border-white/10">
                    <div className="p-8 flex items-center justify-between cursor-pointer group" onClick={() => {
                      const next = new Set(expandedCourses);
                      if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                      setExpandedCourses(next);
                    }}>
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600/20 transition-all">
                          <Layout size={20} className="text-red-600" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200 truncate">{course.title}</h3>
                          <p className="text-[9px] text-gray-600 font-bold uppercase mt-1 tracking-widest">{course.modules?.length || 0} Módulos</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        <button onClick={(e) => { e.stopPropagation(); handleDelete('course', course.id); }} className="p-2.5 text-gray-800 hover:text-red-600 transition-colors bg-white/5 rounded-xl"><Trash2 size={14}/></button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden bg-white/[0.01] border-t border-white/5">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.02] transition-colors" onClick={() => {
                                  const next = new Set(expandedModules);
                                  if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                  setExpandedModules(next);
                                }}>
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-[0.1em] text-gray-400">{mod.title}</span>
                                  </div>
                                  <button onClick={(e) => { e.stopPropagation(); handleDelete('module', mod.id); }} className="p-2 text-gray-800 hover:text-red-500 transition-colors"><Trash2 size={12}/></button>
                                </div>
                              </div>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            <div className="lg:col-span-7">
              {editingLesson ? (
                <div className="p-10 bg-white/5 rounded-[4rem] border border-white/5">
                  {/* Aquí iría el editor de lecciones ya implementado */}
                </div>
              ) : (
                <div className="h-full min-h-[600px] border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none">
                  <div className="w-32 h-32 bg-white/5 rounded-full flex items-center justify-center mb-10 border border-white/10">
                    <MoveVertical size={40} className="text-gray-400" />
                  </div>
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">CENTRAL DE <span className="text-red-600">MANDO</span></h3>
                  <p className="text-[11px] font-bold text-gray-600 mt-6 uppercase tracking-[0.3em] max-w-xs leading-loose">
                    Gestiona la arquitectura de conocimiento desde el panel izquierdo.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] overflow-hidden shadow-2xl p-12">
            <h2 className="text-2xl font-black uppercase tracking-tighter italic mb-10">Gestión de Alumnos</h2>
            {/* Lista de alumnos simplificada */}
            <div className="space-y-4">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-white/5 rounded-2xl border border-white/5 hover:border-white/10 transition-all">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-red-600/20 rounded-xl flex items-center justify-center text-red-600 font-black">{s.fullName.charAt(0)}</div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tighter">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest ${onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border border-green-500/20' : 'bg-white/5 text-gray-600 border border-white/5'}`}>
                    {onlineUserIds.has(s.id) ? 'En Línea' : 'Offline'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL DE CREACIÓN PREMIUM */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
            <motion.div 
              initial={{ opacity: 0 }} 
              animate={{ opacity: 1 }} 
              exit={{ opacity: 0 }} 
              onClick={() => !isProcessing && setShowCreateModal(false)}
              className="absolute inset-0 bg-black/80 backdrop-blur-md" 
            />
            <motion.div 
              initial={{ scale: 0.9, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.9, opacity: 0, y: 20 }}
