            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      setNotification({ type: 'error', msg: 'El título es obligatorio.' });
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title.trim(), description: newCourseData.description.trim(), order_index: courses.length }])
        .select().single();
      if (courseError) throw courseError;
      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Bienvenida', order_index: 0 }]);
      setNotification({ type: 'success', msg: 'Curso desplegado correctamente.' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchAllData();
      setExpandedCourses(new Set([courseData.id]));
    } catch (err: any) {
      setNotification({ type: 'error', msg: `Error: ${err.message}` });
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (courseId: string) => {
    const title = window.prompt("Título del nuevo módulo:");
    if (!title) return;
    setIsProcessing(true);
    try {
      const course = courses.find(c => c.id === courseId);
      const { error } = await supabase.from('modules').insert([{ course_id: courseId, title, order_index: course?.modules?.length || 0 }]);
      if (error) throw error;
      await fetchAllData();
      setNotification({ type: 'success', msg: 'Módulo agregado.' });
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (moduleId: string) => {
    const title = window.prompt("Nombre de la lección:");
    if (!title) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: 'Nueva lección estratégica.',
        order_index: 0
      }]);
      if (error) throw error;
      await fetchAllData();
      setNotification({ type: 'success', msg: 'Lección creada.' });
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        order_index: editingLesson.order_index
      }).eq('id', editingLesson.id);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'Cambios sincronizados.' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleDelete = async (type: 'course' | 'module' | 'lesson', id: string) => {
    if (!window.confirm(`¿Seguro que deseas eliminar este ${type}?`)) return;
    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'Eliminado con éxito.' });
      if (editingLesson?.id === id) setEditingLesson(null);
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: `Error: ${err.message}` });
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      <AnimatePresence>
        {notification && (
          <motion.div initial={{ opacity: 0, y: -50, x: '-50%' }} animate={{ opacity: 1, y: 0, x: '-50%' }} exit={{ opacity: 0, y: -50, x: '-50%' }} className={`fixed top-12 left-1/2 z-[300] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-5 min-w-[400px] backdrop-blur-2xl ${notification.type === 'success' ? 'bg-green-600/10 border-green-500/30 text-green-400' : 'bg-red-600/10 border-red-500/30 text-red-400'}`}>
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-xs font-bold">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-3xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver al Master
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Procesando' : 'Online'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-14">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Estructura</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Alumnos</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44 gap-8"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Mis Formaciones</h2>
                <button onClick={() => setShowCreateModal(true)} className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl flex items-center gap-3 active:scale-95"><Plus size={20}/><span className="text-[10px] font-black uppercase">Crear Curso</span></button>
              </div>

              <div className="space-y-6">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden">
                    <div className="p-8 flex items-center justify-between cursor-pointer group" onClick={() => {
                      const next = new Set(expandedCourses);
                      if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                      setExpandedCourses(next);
                    }}>
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20"><Layout size={20} className="text-red-600" /></div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button onClick={(e) => { e.stopPropagation(); handleDelete('course', course.id); }} className="p-2.5 text-gray-800 hover:text-red-600 bg-white/5 rounded-xl"><Trash2 size={14}/></button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} className="overflow-hidden border-t border-white/5">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div className="p-5 flex items-center justify-between cursor-pointer" onClick={() => {
                                  const next = new Set(expandedModules);
                                  if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                  setExpandedModules(next);
                                }}>
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button onClick={(e) => { e.stopPropagation(); handleDelete('module', mod.id); }} className="p-2 text-gray-800 hover:text-red-500"><Trash2 size={12}/></button>
                                    <ChevronDown size={14} className={`text-gray-700 ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>
                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600' : 'bg-black border-white/5'}`}>
                                        <button onClick={() => setEditingLesson(l)} className="text-[10px] font-black uppercase text-left truncate flex-1">{l.title}</button>
                                        <button onClick={() => handleDelete('lesson', l.id)} className="p-2 text-gray-800 hover:text-white"><Trash2 size={12}/></button>
                                      </div>
                                    ))}
                                    <button onClick={() => handleCreateLesson(mod.id)} className="w-full py-3 border border-dashed border-white/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600">+ Clase</button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button onClick={() => handleCreateModule(course.id)} className="w-full py-5 bg-white/5 rounded-3xl text-[9px] font-black uppercase text-gray-500 hover:text-white transition-all">+ Agregar Módulo</button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 space-y-10 sticky top-32">
                  <div className="flex justify-between items-center">
                    <h2 className="text-2xl font-black italic uppercase">Editor de <span className="text-red-600">Clase</span></h2>
                    <button onClick={() => setEditingLesson(null)} className="p-3 bg-white/5 rounded-2xl"><X size={20}/></button>
                  </div>
                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-4">Título</label>
                      <input type="text" value={editingLesson.title} onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-6 font-bold" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-4">Video URL</label>
                      <input type="text" value={editingLesson.video_url} onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-6 text-gray-500 font-mono text-sm" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-4">Descripción (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed" />
                    </div>
                  </div>
                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 py-7 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/20">
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={20}/>} Guardar Cambios
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none">
                  <MoveVertical size={48} className="mb-8 text-gray-600" />
                  <h3 className="text-xl font-black uppercase tracking-widest italic">Panel de <span className="text-red-600">Mando</span></h3>
                  <p className="text-[11px] font-bold mt-4 uppercase tracking-widest">Selecciona una lección para editar su estructura.</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12">
            <h2 className="text-2xl font-black uppercase italic mb-10">Alumnos Registrados</h2>
            <div className="space-y-4">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-white/5 rounded-2xl border border-white/5">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-red-600/20 rounded-xl flex items-center justify-center text-red-600 font-black">{s.fullName.charAt(0)}</div>
                    <div>
                      <p className="text-sm font-black uppercase">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase ${onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500' : 'bg-white/5 text-gray-600'}`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Offline'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/90 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[3.5rem] p-12 lg:p-16 shadow-2xl">
              <div className="flex justify-between items-center mb-12">
                <h3 className="text-3xl font-black italic uppercase">NUEVO <span className="text-red-600">CURSO</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-3 text-gray-500 hover:text-white bg-white/5 rounded-2xl"><X size={20}/></button>
              </div>
              <div className="space-y-8">
                <div className="space-y-3">
                  <label className="text-[10px] font-black uppercase text-gray-600 ml-4">Nombre</label>
                  <input type="text" value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título..." className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-xl outline-none" />
                </div>
                <div className="space-y-3">
                  <label className="text-[10px] font-black uppercase text-gray-600 ml-4">Descripción</label>
                  <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Resumen..." className="w-full bg-black border border-white/5 rounded-3xl p-7 text-sm h-40 resize-none outline-none" />
                </div>
              </div>
              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-12 bg-red-600 text-white py-7 rounded-[2rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-5 transition-all shadow-xl disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={20}/>} Lanzar Formación
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchAllData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 5000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchAllData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES DE CREACIÓN ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      setNotification({ type: 'error', msg: 'El título es obligatorio.' });
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      // Crear módulo por defecto
      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Bienvenida', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'Curso desplegado con éxito.' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchAllData();
      setExpandedCourses(new Set([courseData.id]));
    } catch (err: any) {
      setNotification({ type: 'error', msg: `Error: ${err.message}` });
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (courseId: string) => {
    const title = window.prompt("Nombre del nuevo módulo:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const course = courses.find(c => c.id === courseId);
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title, 
        order_index: course?.modules?.length || 0 
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'Módulo agregado a la estructura.' });
      await fetchAllData();
      setExpandedModules(prev => new Set([...prev])); 
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (moduleId: string) => {
    const title = window.prompt("Título de la nueva lección:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: 'Escribe aquí el contenido de la clase...',
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'Lección vinculada correctamente.' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  // --- ACCIONES DE EDICIÓN Y BORRADO ---

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'Cambios guardados en el servidor.' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleDelete = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation(); // CRÍTICO: Evita que el acordeón se cierre/abra

    const confirmMsg = `¿Deseas eliminar este ${type} definitivamente? Esta acción no se puede deshacer.`;
    if (!window.confirm(confirmMsg)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} eliminado correctamente.` });
      if (editingLesson?.id === id) setEditingLesson(null);
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: `Fallo al borrar: ${err.message}` });
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      {/* SISTEMA DE NOTIFICACIONES */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -100, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -100, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[300] px-8 py-4 rounded-[2rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-2xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={20}/> : <AlertCircle size={20}/>}
            <span className="text-[11px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-5 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-3xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver al Master
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Sincronizando' : 'Activo'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-14">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Estructura de Cursos</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Gestión Alumnos</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44 gap-8"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* LISTADO DE CURSOS (COLUMNA IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Arquitectura de Formación</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 active:scale-95 group"
                >
                  <PlusCircle size={20} className="group-hover:rotate-90 transition-transform" />
                  <span className="text-[10px] font-black uppercase">Crear Nuevo Curso</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.length === 0 && (
                  <div className="p-16 border-2 border-dashed border-white/5 rounded-[3rem] text-center opacity-30 flex flex-col items-center gap-4">
                    <AlertTriangle size={32} />
                    <p className="text-[10px] font-black uppercase tracking-widest">No hay cursos en la base de datos.</p>
                  </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600/20 transition-all">
                          <Layout size={20} className="text-red-600" />
                        </div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDelete(e, 'course', course.id)} 
                          className="p-3 text-gray-600 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 hover:border-red-600/30 transition-all"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03] transition-colors" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button onClick={(e) => handleDelete(e, 'module', mod.id)} className="p-2 text-gray-700 hover:text-red-500 transition-colors"><Trash2 size={14}/></button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600' : 'bg-black border-white/5 hover:border-white/10'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1 hover:pl-2 transition-all"
                                        >
                                          {l.title}
                                        </button>
                                        <button onClick={(e) => handleDelete(e, 'lesson', l.id)} className="p-2 text-gray-800 hover:text-white transition-colors"><Trash2 size={12}/></button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={() => handleCreateLesson(mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-white/5 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/50 transition-all bg-white/[0.02]"
                                    >
                                      + Añadir Nueva Clase
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            {/* BOTÓN AGREGAR MÓDULO VISIBLE */}
                            <button 
                              onClick={() => handleCreateModule(course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-white/5 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-white hover:border-white/20 transition-all flex items-center justify-center gap-3"
                            >
                              <Plus size={16} /> AGREGAR NUEVO MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR DE CLASE (COLUMNA DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-[0_0_80px_rgba(239,68,68,0.1)]">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Editor de Contenido</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter">Modificando <span className="text-white">Clase</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Título de la Lección</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">URL del Video (Embed)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Descripción Estratégica</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-64 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    disabled={isProcessing} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR CAMBIOS ESTRATÉGICOS
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <div className="w-24 h-24 bg-white/5 rounded-full flex items-center justify-center mb-10 border border-white/5">
                    <MoveVertical size={40} className="text-gray-500" />
                  </div>
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">CENTRAL DE <span className="text-red-600">GESTIÓN</span></h3>
                  <p className="text-[11px] font-bold text-gray-600 mt-6 uppercase tracking-[0.3em] max-w-xs leading-loose">
                    Selecciona una lección del esquema para abrir el terminal de edición avanzado.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          /* GESTIÓN DE ALUMNOS (SIMPLIFICADA) */
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Comunidad <span className="text-red-600">Premium</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                    onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'
                  }`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Desconectado'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL CREAR CURSO */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 lg:p-20 shadow-[0_0_150px_rgba(239,68,68,0.2)]">
              <div className="flex justify-between items-center mb-16">
                <div>
                  <span className="text-[10px] font-black text-red-600 uppercase tracking-[0.6em] mb-3 block">Nuevo Registro</span>
                  <h3 className="text-4xl font-black italic uppercase tracking-tighter">Lanzar <span className="text-white">Curso</span></h3>
                </div>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>

              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Programa</label>
                  <input 
                    type="text" 
                    autoFocus
                    value={newCourseData.title} 
                    onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} 
                    placeholder="Escribe el nombre aquí..." 
                    className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" 
                  />
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Descripción Global</label>
                  <textarea 
                    value={newCourseData.description} 
                    onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} 
                    placeholder="Define el impacto de esta formación..." 
                    className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-48 resize-none outline-none focus:border-red-600 transition-all placeholder:text-gray-800" 
                  />
                </div>
              </div>

              <button 
                onClick={handleCreateCourse} 
                disabled={isProcessing || !newCourseData.title.trim()} 
                className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all hover:bg-red-700 shadow-[0_20px_60px_rgba(239,68,68,0.4)] disabled:opacity-50 active:scale-95"
              >
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} DESPLEGAR FORMACIÓN
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchAllData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchAllData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES DE CREACIÓN ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      setNotification({ type: 'error', msg: 'Título obligatorio' });
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      // Inyección automática de módulo de inicio
      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Fase Inicial', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'Curso Lanzado Exitosamente' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchAllData();
      setExpandedCourses(prev => new Set([...prev, courseData.id]));
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation(); // Evita abrir/cerrar curso
    const title = window.prompt("Nombre del nuevo Módulo:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: title.trim(), 
        order_index: 99 // Se ajustará por DB
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'Módulo Agregado' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation(); // Evita cerrar módulo
    const title = window.prompt("Título de la nueva Clase:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nContenido estratégico.',
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'Clase Creada' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  // --- ACCIONES DE EDICIÓN Y BORRADO ---

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'Sincronizado' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation(); // CRÍTICO: Detiene la propagación del click al contenedor padre

    const confirmMsg = `¿Deseas eliminar este ${type}? Esta acción es definitiva.`;
    if (!window.confirm(confirmMsg)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);

      // Actualización inmediata del estado local para fluidez total
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: `Error: ${err.message}` });
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      {/* TOAST SYSTEM */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Enviando' : 'Sistema OK'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Arquitectura</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Alumnos</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* ESTRUCTURA (IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Cursos Activos</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 active:scale-95 group"
                >
                  <PlusCircle size={20} className="group-hover:rotate-90 transition-transform" />
                  <span className="text-[10px] font-black uppercase">Nuevo Curso</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600/20 transition-all">
                          <Layout size={20} className="text-red-600" />
                        </div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 hover:border-red-600/40 transition-all"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03] transition-colors" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button onClick={(e) => handleDeleteItem(e, 'module', mod.id)} className="p-2 text-gray-700 hover:text-red-500 transition-colors"><Trash2 size={14}/></button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600' : 'bg-black border-white/5 hover:border-white/10'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1"
                                        >
                                          {l.title}
                                        </button>
                                        <button onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} className="p-2 text-gray-800 hover:text-white transition-colors"><Trash2 size={12}/></button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={(e) => handleCreateLesson(e, mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-white/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/50 transition-all"
                                    >
                                      + Añadir Clase
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button 
                              onClick={(e) => handleCreateModule(e, course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/40 transition-all flex items-center justify-center gap-3"
                            >
                              <Plus size={16} /> AGREGAR MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR (DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Editor</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de <span className="text-white">Lección</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Título</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Video URL</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Contenido (Markdown)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-64 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    disabled={isProcessing} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR ESTRUCTURA
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8 text-gray-600" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-600 mt-6 uppercase tracking-[0.3em] max-w-xs leading-loose">
                    Selecciona una lección para activar la terminal de edición avanzada.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos <span className="text-red-600">Registrados</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                    onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'
                  }`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Offline'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">LANZAR <span className="text-red-600">CURSO</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>

              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Programa</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Breve Resumen</label>
                  <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Impacto..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-48 resize-none outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                </div>
              </div>

              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-2xl disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} DESPLEGAR
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle, Link as LinkIcon, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchAllData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchAllData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES DE CREACIÓN ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      setNotification({ type: 'error', msg: 'Título obligatorio' });
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      // Inyección automática de módulo de inicio
      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Bienvenida al Master', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'CURSO LANZADO CON ÉXITO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchAllData();
      setExpandedCourses(prev => new Set([...prev, courseData.id]));
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation();
    const title = window.prompt("Título del nuevo Módulo (Ej: 'Fase de Escalamiento'):");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: title.trim(), 
        order_index: 99
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO AGREGADO' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation();
    const title = window.prompt("Nombre de la Lección:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nEdita este contenido para tus alumnos.',
        resources: [],
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'LECCIÓN CREADA' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  // --- ACCIONES DE EDICIÓN Y BORRADO ---

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'DATOS SINCRONIZADOS' });
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation();

    const confirmMsg = `¿Deseas eliminar este ${type} definitivamente?`;
    if (!window.confirm(confirmMsg)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);
      await fetchAllData();
    } catch (err: any) {
      setNotification({ type: 'error', msg: `ERROR: ${err.message}` });
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre del recurso (Ej: Guía PDF):");
    const url = window.prompt("URL del archivo (Pega el link del bucket materials):");
    if (name && url) {
      const updatedResources = [...(editingLesson.resources || []), { name, url }];
      setEditingLesson({ ...editingLesson, resources: updatedResources });
    }
  };

  const handleRemoveResource = (index: number) => {
    if (!editingLesson) return;
    const updatedResources = [...editingLesson.resources];
    updatedResources.splice(index, 1);
    setEditingLesson({ ...editingLesson, resources: updatedResources });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      {/* TOAST SYSTEM */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Panel de Control
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">ADMIN <span className="text-red-600">TERMINAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Sincronizando' : 'Conectado'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Formaciones</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Comunidad</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* ESTRUCTURA (IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Programas Disponibles</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 active:scale-95 group"
                >
                  <PlusCircle size={20} className="group-hover:rotate-90 transition-transform" />
                  <span className="text-[10px] font-black uppercase">Crear Curso</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.length === 0 && (
                  <div className="py-20 border-2 border-dashed border-white/5 rounded-[3rem] text-center opacity-30">
                    <AlertTriangle size={32} className="mx-auto mb-4" />
                    <p className="text-[10px] font-black uppercase tracking-widest">Base de datos vacía</p>
                  </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20">
                          <Layout size={20} className="text-red-600" />
                        </div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 hover:border-red-600/40 transition-all"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03] transition-colors" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button onClick={(e) => handleDeleteItem(e, 'module', mod.id)} className="p-2 text-gray-700 hover:text-red-500 transition-colors"><Trash2 size={14}/></button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600' : 'bg-black border-white/5 hover:border-white/10'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1"
                                        >
                                          {l.title}
                                        </button>
                                        <button onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} className="p-2 text-gray-800 hover:text-white transition-colors"><Trash2 size={12}/></button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={(e) => handleCreateLesson(e, mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-red-600/20 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/50 transition-all"
                                    >
                                      + AGREGAR LECCIÓN
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button 
                              onClick={(e) => handleCreateModule(e, course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/40 transition-all flex items-center justify-center gap-3"
                            >
                              <Plus size={16} /> AGREGAR NUEVO MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR (DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Terminal de Edición</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de <span className="text-white">Contenido</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 overflow-y-auto max-h-[60vh] pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Título de la Sesión</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Video URL (YouTube/Vimeo)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all" 
                      />
                    </div>

                    {/* GESTIÓN DE RECURSOS */}
                    <div className="space-y-4">
                      <div className="flex justify-between items-center ml-5">
                        <label className="text-[10px] font-black uppercase text-gray-600 tracking-widest">Materiales de la Clase</label>
                        <button onClick={handleAddResource} className="text-[9px] font-black uppercase text-red-600 flex items-center gap-2 hover:underline">
                          <Plus size={12}/> Añadir Material
                        </button>
                      </div>
                      <div className="space-y-2">
                        {editingLesson.resources?.map((r, i) => (
                          <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
                            <div className="flex items-center gap-3">
                              <FileText size={14} className="text-red-600" />
                              <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                            </div>
                            <button onClick={() => handleRemoveResource(i)} className="p-2 text-gray-700 hover:text-red-600">
                              <Trash2 size={12} />
                            </button>
                          </div>
                        ))}
                        {(!editingLesson.resources || editingLesson.resources.length === 0) && (
                          <div className="p-6 border border-dashed border-white/5 rounded-2xl text-center opacity-20">
                            <p className="text-[8px] font-black uppercase tracking-widest">Sin recursos vinculados</p>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Descripción (Markdown)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    disabled={isProcessing} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR CONFIGURACIÓN
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8 text-gray-600" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">ADMIN</span></h3>
                  <p className="text-[11px] font-bold text-gray-600 mt-6 uppercase tracking-[0.3em] max-w-xs leading-loose">
                    Selecciona una lección del currículo para activar los comandos de edición avanzada.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos <span className="text-red-600">Activos</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                    onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'
                  }`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Off'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL CREAR CURSO */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">PROGRAMA</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>

              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Master</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Ej: Master en Ventas High Ticket..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Objetivo del Curso</label>
                  <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Describe qué aprenderán los alumnos..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-48 resize-none outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                </div>
              </div>

              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-2xl disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR FORMACIÓN
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle, Link as LinkIcon, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchCourses();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchCourses() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
      alert("Error al cargar datos: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES DE CREACIÓN ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      alert("El título del curso es obligatorio.");
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      // Módulo inicial por defecto
      const { error: modError } = await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Introducción', order_index: 0 }]);
      if (modError) throw modError;

      setNotification({ type: 'success', msg: 'CURSO CREADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchCourses();
      setExpandedCourses(prev => new Set([...prev, courseData.id]));
    } catch (err: any) {
      alert("Error al crear curso: " + err.message);
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation(); // Evita colapso del acordeón
    const nombre = window.prompt("Introduce el título del nuevo Módulo:");
    if (!nombre || !nombre.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: nombre.trim(), 
        order_index: 99
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO AGREGADO' });
      await fetchCourses();
    } catch (err: any) {
      alert("Error al agregar módulo: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation(); // Evita colapso del módulo
    const title = window.prompt("Nombre de la nueva Lección:");
    if (!title || !title.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nContenido dinámico para tus alumnos.',
        resources: [],
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'LECCIÓN CREADA' });
      await fetchCourses();
    } catch (err: any) {
      alert("Error al crear lección: " + err.message);
    } finally { setIsProcessing(false); }
  };

  // --- ACCIONES DE EDICIÓN Y BORRADO ---

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS GUARDADOS' });
      await fetchCourses();
    } catch (err: any) {
      alert("Error al guardar cambios: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation(); // CRÍTICO: Evita la propagación del click al contenedor padre (Acordeón)

    const confirmMsg = `¿Deseas eliminar este ${type} de forma permanente?`;
    if (!window.confirm(confirmMsg)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);

      // Actualizar estado local inmediatamente
      await fetchCourses();
    } catch (err: any) {
      alert(`Error al eliminar ${type}: ` + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre del material (Ej: PDF de Estrategia):");
    const url = window.prompt("URL pública del archivo (debe ser accesible):");
    if (name && url) {
      const updatedResources = [...(editingLesson.resources || []), { name, url }];
      setEditingLesson({ ...editingLesson, resources: updatedResources });
    }
  };

  const handleRemoveResource = (index: number) => {
    if (!editingLesson) return;
    const updatedResources = [...editingLesson.resources];
    updatedResources.splice(index, 1);
    setEditingLesson({ ...editingLesson, resources: updatedResources });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      {/* TOAST SYSTEM */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver al Dashboard
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Procesando' : 'Sistema Listo'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Arquitectura</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Comunidad</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* ESTRUCTURA (IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Esquema de Formación</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 active:scale-95 group"
                >
                  <PlusCircle size={20} className="group-hover:rotate-90 transition-transform" />
                  <span className="text-[10px] font-black uppercase">Nuevo Curso</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.length === 0 && (
                  <div className="py-20 border-2 border-dashed border-white/5 rounded-[3rem] text-center opacity-30">
                    <AlertTriangle size={32} className="mx-auto mb-4" />
                    <p className="text-[10px] font-black uppercase tracking-widest">No hay cursos creados</p>
                  </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all">
                          <Layout size={20} className="text-red-600 group-hover:text-white" />
                        </div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 hover:border-red-600/40 transition-all active:scale-90"
                          title="Eliminar Curso"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03] transition-colors" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button 
                                      onClick={(e) => handleDeleteItem(e, 'module', mod.id)} 
                                      className="p-2 text-gray-700 hover:text-red-500 transition-colors active:scale-90"
                                      title="Eliminar Módulo"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600' : 'bg-black border-white/5 hover:border-white/10'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1 pr-4"
                                        >
                                          {l.title}
                                        </button>
                                        <button 
                                          onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} 
                                          className="p-2 text-gray-800 hover:text-white transition-colors active:scale-90"
                                        >
                                          <Trash2 size={12}/>
                                        </button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={(e) => handleCreateLesson(e, mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-red-600/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/50 transition-all bg-white/[0.01]"
                                    >
                                      + AGREGAR LECCIÓN
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button 
                              onClick={(e) => handleCreateModule(e, course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/40 transition-all flex items-center justify-center gap-3 active:scale-95"
                            >
                              <Plus size={16} /> AGREGAR NUEVO MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR (DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Editor Estratégico</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de <span className="text-white">Sesión</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 overflow-y-auto max-h-[60vh] pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Título del Video</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Embed URL (YouTube/Vimeo)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all" 
                      />
                    </div>

                    {/* GESTIÓN DE RECURSOS */}
                    <div className="space-y-4">
                      <div className="flex justify-between items-center ml-5">
                        <label className="text-[10px] font-black uppercase text-gray-600 tracking-widest">Recursos Descargables</label>
                        <button onClick={handleAddResource} className="text-[9px] font-black uppercase text-red-600 flex items-center gap-2 hover:underline">
                          <Plus size={12}/> Vincular Material
                        </button>
                      </div>
                      <div className="space-y-2">
                        {editingLesson.resources?.map((r, i) => (
                          <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
                            <div className="flex items-center gap-3">
                              <FileText size={14} className="text-red-600" />
                              <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                            </div>
                            <button onClick={() => handleRemoveResource(i)} className="p-2 text-gray-700 hover:text-red-600">
                              <Trash2 size={12} />
                            </button>
                          </div>
                        ))}
                        {(!editingLesson.resources || editingLesson.resources.length === 0) && (
                          <div className="p-6 border border-dashed border-white/5 rounded-2xl text-center opacity-20">
                            <p className="text-[8px] font-black uppercase tracking-widest">Sin materiales adjuntos</p>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Contenido Formativo (Markdown)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    disabled={isProcessing} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR EN LA NUBE
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8 text-gray-600" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-600 mt-6 uppercase tracking-[0.3em] max-w-xs leading-loose">
                    Selecciona una unidad didáctica para activar los protocolos de edición avanzada.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Comunidad <span className="text-red-600">Academia</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                    onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'
                  }`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Inactivo'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL CREAR CURSO */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">REGISTRO</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>

              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Programa</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Descripción Global</label>
                  <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Impacto..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-48 resize-none outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                </div>
              </div>

              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-2xl disabled:opacity-50 active:scale-95">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR FORMACIÓN
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle, Link as LinkIcon, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchCourses();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchCourses() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
      alert("Error crítico al obtener cursos: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES DE CREACIÓN ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      alert("El título del programa es obligatorio.");
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      // Módulo por defecto para evitar cursos vacíos
      await supabase.from('modules').insert([{ 
        course_id: courseData.id, 
        title: 'Módulo 1: Inicio', 
        order_index: 0 
      }]);

      setNotification({ type: 'success', msg: 'ESTRUCTURA LANZADA' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchCourses();
      setExpandedCourses(prev => new Set([...prev, courseData.id]));
    } catch (err: any) {
      alert("Error de Supabase (Curso): " + err.message);
      setNotification({ type: 'error', msg: err.message });
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation(); // CRÍTICO: Evita colapsar el curso
    e.preventDefault();

    const nombre = window.prompt("Nombre del nuevo Módulo:");
    if (!nombre || !nombre.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: nombre.trim(), 
        order_index: 99
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO SINCRONIZADO' });
      await fetchCourses();
    } catch (err: any) {
      alert("Error de Supabase (Módulo): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation(); // CRÍTICO: Evita colapsar el módulo
    e.preventDefault();

    const title = window.prompt("Título de la Lección:");
    if (!title || !title.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Unidad\nIntroduce aquí el contenido estratégico para tus alumnos.',
        resources: [],
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'LECCIÓN VINCULADA' });
      await fetchCourses();
    } catch (err: any) {
      alert("Error de Supabase (Lección): " + err.message);
    } finally { setIsProcessing(false); }
  };

  // --- ACCIONES DE EDICIÓN Y BORRADO ---

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'ACTUALIZACIÓN EXITOSA' });
      await fetchCourses();
    } catch (err: any) {
      alert("Error de Supabase (Edición): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation(); // CRÍTICO: Previene el bubbling al acordeón
    e.preventDefault();

    const confirmMsg = `ADVERTENCIA: ¿Estás seguro de eliminar este ${type}? Se perderán todos los datos vinculados.`;
    if (!window.confirm(confirmMsg)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);

      // Actualización reactiva instantánea
      await fetchCourses();
    } catch (err: any) {
      alert(`Error de Supabase (Borrado ${type}): ` + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre descriptivo (Ej: Guía Estratégica):");
    const url = window.prompt("URL del Recurso (Ej: https://...):");
    if (name && url) {
      const updatedResources = [...(editingLesson.resources || []), { name, url }];
      setEditingLesson({ ...editingLesson, resources: updatedResources });
    }
  };

  const handleRemoveResource = (index: number) => {
    if (!editingLesson) return;
    const updatedResources = [...editingLesson.resources];
    updatedResources.splice(index, 1);
    setEditingLesson({ ...editingLesson, resources: updatedResources });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      {/* SISTEMA DE NOTIFICACIONES */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver al Master
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Sincronizando' : 'Mando Listo'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-90"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Arquitectura</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Comunidad</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44 gap-8"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* ESTRUCTURA (IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Control de Formación</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 active:scale-95 group"
                >
                  <PlusCircle size={20} className="group-hover:rotate-90 transition-transform" />
                  <span className="text-[10px] font-black uppercase">Crear Master</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.length === 0 && (
                  <div className="p-20 border-2 border-dashed border-white/5 rounded-[3rem] text-center opacity-30 flex flex-col items-center gap-4">
                    <AlertTriangle size={32} />
                    <p className="text-[10px] font-black uppercase tracking-widest">Base de datos vacía.</p>
                  </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all shadow-lg">
                          <Layout size={20} className="text-red-600 group-hover:text-white" />
                        </div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 hover:border-red-600/40 transition-all active:scale-90"
                          title="Eliminar Programa"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03] transition-colors" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button 
                                      onClick={(e) => handleDeleteItem(e, 'module', mod.id)} 
                                      className="p-2 text-gray-700 hover:text-red-500 transition-colors active:scale-90"
                                      title="Eliminar Módulo"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600' : 'bg-black border-white/5 hover:border-white/10'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1 pr-4"
                                        >
                                          {l.title}
                                        </button>
                                        <button 
                                          onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} 
                                          className="p-2 text-gray-800 hover:text-white transition-colors active:scale-90"
                                          title="Eliminar Clase"
                                        >
                                          <Trash2 size={12}/>
                                        </button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={(e) => handleCreateLesson(e, mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-red-600/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/50 transition-all bg-white/[0.01]"
                                    >
                                      + AGREGAR LECCIÓN
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button 
                              onClick={(e) => handleCreateModule(e, course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/40 transition-all flex items-center justify-center gap-3 active:scale-95"
                            >
                              <Plus size={16} /> AGREGAR NUEVO MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR ESTRATÉGICO (DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Protocolo de Edición</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de <span className="text-white">Contenido</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 overflow-y-auto max-h-[60vh] pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Título de la Sesión</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all shadow-inner" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Embed URL (YouTube/Vimeo)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all shadow-inner" 
                      />
                    </div>

                    {/* GESTIÓN DE RECURSOS */}
                    <div className="space-y-4">
                      <div className="flex justify-between items-center ml-5">
                        <label className="text-[10px] font-black uppercase text-gray-600 tracking-widest">Materiales de la Clase</label>
                        <button onClick={handleAddResource} className="text-[9px] font-black uppercase text-red-600 flex items-center gap-2 hover:underline">
                          <Plus size={12}/> Vincular Recurso
                        </button>
                      </div>
                      <div className="space-y-2">
                        {editingLesson.resources?.map((r, i) => (
                          <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-white/10 transition-all group">
                            <div className="flex items-center gap-3">
                              <FileText size={14} className="text-red-600" />
                              <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                            </div>
                            <button onClick={() => handleRemoveResource(i)} className="p-2 text-gray-700 hover:text-red-600 transition-colors">
                              <Trash2 size={12} />
                            </button>
                          </div>
                        ))}
                        {(!editingLesson.resources || editingLesson.resources.length === 0) && (
                          <div className="p-6 border border-dashed border-white/5 rounded-2xl text-center opacity-20">
                            <p className="text-[8px] font-black uppercase tracking-widest">Sin archivos adjuntos</p>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Cuerpo de la Clase (Markdown)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar shadow-inner" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    disabled={isProcessing} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR CONFIGURACIÓN ESTRATÉGICA
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8 text-gray-600" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">COMANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-6 uppercase tracking-[0.5em] max-w-xs leading-loose">
                    Selecciona una sesión de la jerarquía lateral para activar los protocolos de edición avanzada.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos <span className="text-red-600">Verificados</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group shadow-sm">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all shadow-inner">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                    onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'
                  }`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Inactivo'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL CREAR CURSO */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">PROGRAMA</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>

              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Master</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Ej: Master en Ecom 2024..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Descripción Global</label>
                  <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Define el impacto del curso..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-48 resize-none outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                </div>
              </div>

              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_rgba(239,68,68,0.3)] disabled:opacity-50 active:scale-95">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle, Link as LinkIcon, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
      alert("Error al cargar datos: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES DE CREACIÓN ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      alert("El título del programa es obligatorio.");
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      // Inyección automática del primer módulo para estructura base
      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Introducción al Master', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'MASTER DESPLEGADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
      setExpandedCourses(prev => new Set([...prev, courseData.id]));
    } catch (err: any) {
      alert("Error de Supabase (Curso): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation(); 
    e.preventDefault();

    const nombre = window.prompt("Título del nuevo Módulo:");
    if (!nombre || !nombre.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: nombre.trim(), 
        order_index: 99
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
      await fetchData();
    } catch (err: any) {
      alert("Error de Supabase (Módulo): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Nombre de la nueva Lección:");
    if (!title || !title.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nDefine aquí los objetivos y el contenido estratégico de la sesión.',
        resources: [],
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'LECCIÓN AGREGADA' });
      await fetchData();
    } catch (err: any) {
      alert("Error de Supabase (Lección): " + err.message);
    } finally { setIsProcessing(false); }
  };

  // --- ACCIONES DE EDICIÓN Y BORRADO ---

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS SINCRONIZADOS' });
      await fetchData();
    } catch (err: any) {
      alert("Error de Supabase (Guardar): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation(); // CRÍTICO: Evita colapsar el acordeón al borrar
    e.preventDefault();

    const confirmMsg = `¿Confirmas la eliminación definitiva de este ${type}? No hay vuelta atrás.`;
    if (!window.confirm(confirmMsg)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);

      // Actualización inmediata del estado local para fluidez
      await fetchData();
    } catch (err: any) {
      alert(`Error de Supabase (Borrar ${type}): ` + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre del material (Ej: PDF de Estrategia):");
    const url = window.prompt("URL del archivo:");
    if (name && url) {
      const updatedResources = [...(editingLesson.resources || []), { name, url }];
      setEditingLesson({ ...editingLesson, resources: updatedResources });
    }
  };

  const handleRemoveResource = (index: number) => {
    if (!editingLesson) return;
    const updatedResources = [...editingLesson.resources];
    updatedResources.splice(index, 1);
    setEditingLesson({ ...editingLesson, resources: updatedResources });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      {/* TOAST SYSTEM */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver al Dashboard
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">MANDO <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Enviando' : 'Sistema OK'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-90"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Formaciones</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Alumnos</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* ESTRUCTURA (IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Esquema de Cursos</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 active:scale-95 group"
                >
                  <PlusCircle size={20} className="group-hover:rotate-90 transition-transform" />
                  <span className="text-[10px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.length === 0 && (
                  <div className="py-20 border-2 border-dashed border-white/5 rounded-[3rem] text-center opacity-30 flex flex-col items-center gap-4">
                    <AlertTriangle size={32} />
                    <p className="text-[10px] font-black uppercase tracking-widest">Base de datos vacía</p>
                  </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all shadow-lg">
                          <Layout size={20} className="text-red-600 group-hover:text-white" />
                        </div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 hover:border-red-600/40 transition-all active:scale-90"
                          title="Eliminar Master"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03] transition-colors" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button 
                                      onClick={(e) => handleDeleteItem(e, 'module', mod.id)} 
                                      className="p-2 text-gray-700 hover:text-red-500 transition-colors active:scale-90"
                                      title="Eliminar Módulo"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600 shadow-[0_0_15px_rgba(239,68,68,0.2)]' : 'bg-black border-white/5 hover:border-white/10'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1 pr-4"
                                        >
                                          {l.title}
                                        </button>
                                        <button 
                                          onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} 
                                          className="p-2 text-gray-800 hover:text-white transition-colors active:scale-90"
                                          title="Eliminar Clase"
                                        >
                                          <Trash2 size={12}/>
                                        </button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={(e) => handleCreateLesson(e, mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-red-600/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/50 transition-all bg-white/[0.01]"
                                    >
                                      + AGREGAR LECCIÓN
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button 
                              onClick={(e) => handleCreateModule(e, course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/40 transition-all flex items-center justify-center gap-3 active:scale-95"
                            >
                              <Plus size={16} /> AGREGAR NUEVO MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR ESTRATÉGICO (DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Protocolo de Ajuste</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Editor de <span className="text-white">Contenido</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all active:scale-90"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 overflow-y-auto max-h-[60vh] pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Título del Video</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Embed URL (YouTube/Vimeo)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all" 
                      />
                    </div>

                    {/* GESTIÓN DE MATERIALES */}
                    <div className="space-y-4">
                      <div className="flex justify-between items-center ml-5">
                        <label className="text-[10px] font-black uppercase text-gray-600 tracking-widest">Materiales Adjuntos</label>
                        <button onClick={handleAddResource} className="text-[9px] font-black uppercase text-red-600 flex items-center gap-2 hover:underline active:scale-95">
                          <Plus size={12}/> Vincular Recurso
                        </button>
                      </div>
                      <div className="space-y-2">
                        {editingLesson.resources?.map((r, i) => (
                          <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-white/10 transition-all">
                            <div className="flex items-center gap-3">
                              <FileText size={14} className="text-red-600" />
                              <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                            </div>
                            <button onClick={() => handleRemoveResource(i)} className="p-2 text-gray-700 hover:text-red-600 active:scale-90">
                              <Trash2 size={12} />
                            </button>
                          </div>
                        ))}
                        {(!editingLesson.resources || editingLesson.resources.length === 0) && (
                          <div className="p-6 border border-dashed border-white/5 rounded-2xl text-center opacity-20">
                            <p className="text-[8px] font-black uppercase tracking-widest">Sin archivos vinculados</p>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Cuerpo de la Clase (Markdown)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    disabled={isProcessing} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR CONFIGURACIÓN
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8 text-gray-600" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">ADMIN</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-6 uppercase tracking-[0.5em] max-w-xs leading-loose">
                    Selecciona una unidad de la jerarquía lateral para activar los protocolos de edición avanzada.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Comunidad <span className="text-red-600">Academia</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                    onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'
                  }`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Inactivo'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL CREAR CURSO */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">PROGRAMA</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>

              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Master</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Ej: Master en Ecom 2025..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Descripción Global</label>
                  <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Describe el impacto de la formación..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-48 resize-none outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                </div>
              </div>

              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_rgba(239,68,68,0.3)] disabled:opacity-50 active:scale-95">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle, Link as LinkIcon, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("FETCH_ERROR:", err.message);
      alert("ERROR DE CARGA: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- CRUD OPERATIVO ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      alert("Título obligatorio");
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      // Auto-módulo inicial
      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Fase Inicial', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'PROGRAMA ACTIVADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR REAL (CREATE COURSE): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation();
    e.preventDefault();

    const nombre = window.prompt("Nombre del nuevo Módulo:");
    if (!nombre || !nombre.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: nombre.trim(), 
        order_index: 99
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO SINCRONIZADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR REAL (CREATE MODULE): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Título de la Lección:");
    if (!title || !title.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nContenido listo para editar.',
        resources: [],
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'LECCIÓN VINCULADA' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR REAL (CREATE LESSON): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation();
    e.preventDefault();

    if (!window.confirm(`¿Estás seguro de eliminar este ${type}? Esta acción es irreversible.`)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);

      // Actualización local inmediata
      if (type === 'course') {
        setCourses(prev => prev.filter(c => c.id !== id));
      } else {
        await fetchData();
      }
    } catch (err: any) {
      alert(`ERROR REAL (DELETE ${type.toUpperCase()}): ` + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS GUARDADOS' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR REAL (SAVE LESSON): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre del material:");
    const url = window.prompt("Enlace del archivo:");
    if (name && url) {
      const updatedResources = [...(editingLesson.resources || []), { name, url }];
      setEditingLesson({ ...editingLesson, resources: updatedResources });
    }
  };

  const handleRemoveResource = (index: number) => {
    if (!editingLesson) return;
    const updatedResources = [...editingLesson.resources];
    updatedResources.splice(index, 1);
    setEditingLesson({ ...editingLesson, resources: updatedResources });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative">
      {/* NOTIFICACIONES */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">MANDO <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Procesando' : 'Sistema OK'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-90"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Arquitectura</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Usuarios</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* ESTRUCTURA (IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Estructura del Currículo</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 active:scale-95 group"
                >
                  <PlusCircle size={20} className="group-hover:rotate-90 transition-transform" />
                  <span className="text-[10px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02] transition-colors" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600 transition-all">
                          <Layout size={20} className="text-red-600 group-hover:text-white" />
                        </div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-90 z-20"
                          title="Eliminar Curso"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03] transition-colors" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button 
                                      onClick={(e) => handleDeleteItem(e, 'module', mod.id)} 
                                      className="p-2 text-gray-700 hover:text-red-500 transition-colors active:scale-90 z-20"
                                      title="Eliminar Módulo"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600' : 'bg-black border-white/5 hover:border-white/10'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1 pr-4"
                                        >
                                          {l.title}
                                        </button>
                                        <button 
                                          onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} 
                                          className="p-2 text-gray-800 hover:text-white transition-colors active:scale-90 z-20"
                                        >
                                          <Trash2 size={12}/>
                                        </button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={(e) => handleCreateLesson(e, mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-red-600/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/50 transition-all bg-white/[0.01]"
                                    >
                                      + AGREGAR LECCIÓN
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button 
                              onClick={(e) => handleCreateModule(e, course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/40 transition-all flex items-center justify-center gap-3 active:scale-95"
                            >
                              <Plus size={16} /> AGREGAR NUEVO MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR (DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Editor Estratégico</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de <span className="text-white">Sesión</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 overflow-y-auto max-h-[60vh] pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Título de la Sesión</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Video URL (YouTube/Vimeo)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all" 
                      />
                    </div>

                    <div className="space-y-4">
                      <div className="flex justify-between items-center ml-5">
                        <label className="text-[10px] font-black uppercase text-gray-600 tracking-widest">Recursos Adjuntos</label>
                        <button onClick={handleAddResource} className="text-[9px] font-black uppercase text-red-600 flex items-center gap-2 hover:underline">
                          <Plus size={12}/> Vincular Material
                        </button>
                      </div>
                      <div className="space-y-2">
                        {editingLesson.resources?.map((r, i) => (
                          <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
                            <div className="flex items-center gap-3">
                              <FileText size={14} className="text-red-600" />
                              <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                            </div>
                            <button onClick={() => handleRemoveResource(i)} className="p-2 text-gray-700 hover:text-red-600">
                              <Trash2 size={12} />
                            </button>
                          </div>
                        ))}
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Contenido (Markdown)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    disabled={isProcessing} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR CONFIGURACIÓN
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8 text-gray-600" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">COMANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-600 mt-6 uppercase tracking-[0.3em] max-w-xs leading-loose">
                    Selecciona una lección para activar los protocolos de edición.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Usuarios <span className="text-red-600">Verificados</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                    onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'
                  }`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Inactivo'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL CREAR CURSO */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">MAESTRO</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>

              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Programa</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                </div>
              </div>

              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-2xl disabled:opacity-50 active:scale-95">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
      alert("Error al cargar datos: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACTIONS ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      alert("El título del programa es obligatorio.");
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Introducción al Master', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'MASTER DESPLEGADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("Error de Supabase (Curso): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation(); 
    e.preventDefault();

    const nombre = window.prompt("Título del nuevo Módulo:");
    if (!nombre || !nombre.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: nombre.trim(), 
        order_index: 99
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
      await fetchData();
    } catch (err: any) {
      alert("Error de Supabase (Módulo): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Nombre de la nueva Lección:");
    if (!title || !title.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nContenido listo.',
        resources: [],
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'LECCIÓN AGREGADA' });
      await fetchData();
    } catch (err: any) {
      alert("Error de Supabase (Lección): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation(); 
    e.preventDefault();

    if (!window.confirm(`¿Confirmas la eliminación de este ${type}?`)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);
      await fetchData();
    } catch (err: any) {
      alert(`Error de Supabase (Borrar ${type}): ` + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS SINCRONIZADOS' });
      await fetchData();
    } catch (err: any) {
      alert("Error de Supabase (Guardar): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre del material:");
    const url = window.prompt("URL del archivo:");
    if (name && url) {
      const updatedResources = [...(editingLesson.resources || []), { name, url }];
      setEditingLesson({ ...editingLesson, resources: updatedResources });
    }
  };

  const handleRemoveResource = (index: number) => {
    if (!editingLesson) return;
    const updatedResources = [...editingLesson.resources];
    updatedResources.splice(index, 1);
    setEditingLesson({ ...editingLesson, resources: updatedResources });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Dashboard
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">MANDO <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Arquitectura</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Alumnos</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Cursos</h2>
                <button onClick={() => setShowCreateModal(true)} className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all flex items-center gap-3">
                  <PlusCircle size={20} />
                  <span className="text-[10px] font-black uppercase">Nuevo Curso</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl">
                    <div className="p-8 flex items-center justify-between cursor-pointer group" onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                    }}>
                      <div className="flex items-center gap-5">
                        <Layout size={20} className="text-red-600" />
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button onClick={(e) => handleDeleteItem(e, 'course', course.id)} className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all"><Trash2 size={16}/></button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform ${expandedCourses.has(course.id) ? 'rotate-180' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div className="p-5 flex items-center justify-between cursor-pointer" onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                }}>
                                  <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  <div className="flex items-center gap-2">
                                    <button onClick={(e) => handleDeleteItem(e, 'module', mod.id)} className="p-2 text-gray-700 hover:text-red-500 transition-colors"><Trash2 size={14}/></button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600' : 'bg-black border-white/5'}`}>
                                        <button onClick={() => setEditingLesson(l)} className="text-[10px] font-black uppercase text-left truncate flex-1">{l.title}</button>
                                        <button onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} className="p-2 text-gray-800 hover:text-white transition-colors"><Trash2 size={12}/></button>
                                      </div>
                                    ))}
                                    <button onClick={(e) => handleCreateLesson(e, mod.id)} className="w-full py-4 mt-2 border-2 border-dashed border-red-600/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 transition-all">+ AGREGAR LECCIÓN</button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button onClick={(e) => handleCreateModule(e, course.id)} className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all">+ AGREGAR MÓDULO</button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <h2 className="text-3xl font-black uppercase tracking-tighter">Editor</h2>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 overflow-y-auto max-h-[60vh] pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Título</label>
                      <input type="text" value={editingLesson.title} onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">URL Video</label>
                      <input type="text" value={editingLesson.video_url} onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all" />
                    </div>

                    <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Materiales</label>
                        <button onClick={handleAddResource} className="text-[9px] font-black uppercase text-red-600 ml-4 hover:underline">+ Vincular Material</button>
                        <div className="space-y-2">
                            {editingLesson.resources?.map((r, i) => (
                                <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
                                    <div className="flex items-center gap-3">
                                        <FileText size={14} className="text-red-600" />
                                        <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                                    </div>
                                    <button onClick={() => handleRemoveResource(i)} className="p-2 text-gray-700 hover:text-red-600 transition-colors"><Trash2 size={12} /></button>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Descripción (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 active:scale-[0.98] disabled:opacity-50">
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR CAMBIOS
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic">MANDO <span className="text-red-600">CENTRAL</span></h3>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic mb-12">Alumnos</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl">{s.fullName.charAt(0)}</div>
                    <div>
                      <p className="text-sm font-black uppercase">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black border ${onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'}`}>{onlineUserIds.has(s.id) ? 'Online' : 'Inactivo'}</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter">NUEVO <span className="text-red-600">MASTER</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 transition-all"><X size={24}/></button>
              </div>
              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Ej: Master High Ticket..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                </div>
              </div>
              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-2xl active:scale-95 disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR MASTER
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

