Aquí tienes la estructura completa y corregida para que la pegues en tu archivo pages/Admin.tsx y todo funcione, incluyendo los botones de eliminar y agregar.

🛠️ Código Completo para pages/Admin.tsx
TypeScript

import React, { useState, useEffect } from 'react';
import { supabase } from '@/lib/supabase'; // Verifica que tu carpeta de supabase sea esta

const AdminPage = () => {
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);

  // 1. CARGAR DATOS (Jerarquía completa)
  const fetchData = async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from('courses')
      .select('*, modules(*, lessons(*))')
      .order('created_at', { ascending: false });

    if (error) alert("Error cargando datos: " + error.message);
    else setCourses(data || []);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, []);

  // 2. ELIMINAR CURSO (Con stopPropagation para el acordeón)
  const handleDeleteCourse = async (id, e) => {
    e.stopPropagation(); 
    e.preventDefault();
    if (!confirm("¿Seguro que quieres eliminar este curso?")) return;

    const { error } = await supabase.from('courses').delete().eq('id', id);
    if (error) alert("ERROR: " + error.message);
    else setCourses(prev => prev.filter(c => c.id !== id));
  };

  // 3. AGREGAR MÓDULO
  const handleAddModule = async (courseId, e) => {
    e.stopPropagation();
    const title = window.prompt("Nombre del nuevo módulo:");
    if (!title) return;

    const { error } = await supabase
      .from('modules')
      .insert([{ title, course_id: courseId }]);

    if (error) alert("Error: " + error.message);
    else fetchData();
  };

  // 4. ELIMINAR MÓDULO
  const handleDeleteModule = async (moduleId, e) => {
    e.stopPropagation();
    if (!confirm("¿Eliminar este módulo?")) return;

    const { error } = await supabase.from('modules').delete().eq('id', moduleId);
    if (error) alert("Error: " + error.message);
    else fetchData();
  };

  if (loading) return <div className="p-10 text-white">Cargando Ezeh Admin...</div>;

  return (
    <div className="min-h-screen bg-black text-white p-8">
      <h1 className="text-3xl font-bold mb-8 text-red-600">EZEH ADMIN - GESTIÓN</h1>

      {/* Botón para crear curso nuevo */}
      <button 
        onClick={() => {
          const title = window.prompt("Título del curso:");
          if(title) supabase.from('courses').insert([{title}]).then(() => fetchData());
        }}
        className="bg-red-600 px-4 py-2 rounded mb-6 font-bold"
      >
        + NUEVO CURSO
      </button>

      <div className="space-y-4">
        {courses.map(course => (
          <div key={course.id} className="border border-zinc-800 rounded-lg p-4 bg-zinc-900">
            <div className="flex justify-between items-center">
              <h2 className="text-xl font-bold">{course.title}</h2>
              <div className="flex gap-2">
                <button 
                  onClick={(e) => handleAddModule(course.id, e)}
                  className="text-xs bg-zinc-700 px-2 py-1 rounded"
                >
                  + MÓDULO
                </button>
                <button 
                  onClick={(e) => handleDeleteCourse(course.id, e)}
                  className="text-red-500 p-2"
                >
                  🗑️
                </button>
              </div>
            </div>

            {/* Render de Módulos */}
            <div className="mt-4 ml-6 space-y-2">
              {course.modules?.map(mod => (
                <div key={mod.id} className="flex justify-between bg-zinc-800 p-2 rounded">
                  <span>{mod.title}</span>
                  <button onClick={(e) => handleDeleteModule(mod.id, e)} className="text-red-400 text-sm">Eliminar</button>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// ESTA ES LA LÍNEA QUE TE FALTA
export default AdminPage;

