import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("FETCH_ERROR:", err.message);
      alert("ERROR DE CARGA: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- CRUD LÓGICA BLINDADA ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      alert("El título es obligatorio");
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      // Módulo inicial por defecto
      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Bienvenida al Programa', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'MASTER LANZADO CON ÉXITO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR SUPABASE (Curso): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation();
    e.preventDefault();

    const nombre = window.prompt("Nombre del nuevo Módulo:");
    if (!nombre || !nombre.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: nombre.trim(), 
        order_index: 99
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO SINCRONIZADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR SUPABASE (Módulo): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Título de la nueva Lección:");
    if (!title || !title.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Unidad\nIntroduce aquí el contenido estratégico.',
        resources: [],
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'UNIDAD VINCULADA' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR SUPABASE (Lección): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    // CRÍTICO: BLOQUEO DE PROPAGACIÓN PARA EVITAR CONFLICTO CON ACORDEONES
    e.stopPropagation();
    e.preventDefault();

    if (!window.confirm(`¿ADVERTENCIA: Deseas eliminar este ${type} permanentemente?`)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);

      // Actualización local para UI instantánea
      await fetchData();
    } catch (err: any) {
      alert(`ERROR SUPABASE (Borrar ${type}): ` + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS GUARDADOS' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR SUPABASE (Guardar): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre del material:");
    const url = window.prompt("URL del archivo:");
    if (name && url) {
      const updatedResources = [...(editingLesson.resources || []), { name, url }];
      setEditingLesson({ ...editingLesson, resources: updatedResources });
    }
  };

  const handleRemoveResource = (index: number) => {
    if (!editingLesson) return;
    const updatedResources = [...editingLesson.resources];
    updatedResources.splice(index, 1);
    setEditingLesson({ ...editingLesson, resources: updatedResources });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      {/* SISTEMA DE NOTIFICACIONES PREMIUM */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Volver al Dashboard
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">MANDO <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <div className={`flex items-center gap-2 px-5 py-2.5 rounded-2xl border ${isProcessing ? 'border-red-600/50 bg-red-600/5' : 'border-white/5 bg-white/5'}`}>
             {isProcessing ? <Loader2 className="animate-spin text-red-600" size={14} /> : <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse" />}
             <span className="text-[9px] font-black uppercase text-gray-500 tracking-widest">{isProcessing ? 'Sincronizando' : 'Operativo'}</span>
          </div>
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-90"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-40">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Currículo</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Alumnos</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* ESTRUCTURA JERÁRQUICA */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Organización Educativa</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl shadow-red-600/30 flex items-center gap-3 active:scale-95 group"
                >
                  <PlusCircle size={20} className="group-hover:rotate-90 transition-transform" />
                  <span className="text-[10px] font-black uppercase">Nuevo Programa</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <div className="w-12 h-12 bg-red-600/10 rounded-2xl flex items-center justify-center border border-red-600/20 group-hover:bg-red-600 transition-all">
                          <Layout size={20} className="text-red-600 group-hover:text-white" />
                        </div>
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-90"
                          title="Eliminar Master"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03] transition-colors" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <div className="flex items-center gap-4">
                                    <Layers size={16} className="text-red-600/50" />
                                    <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  </div>
                                  <div className="flex items-center gap-2">
                                    <button 
                                      onClick={(e) => handleDeleteItem(e, 'module', mod.id)} 
                                      className="p-2 text-gray-700 hover:text-red-500 transition-colors active:scale-90"
                                      title="Eliminar Módulo"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600 shadow-[0_0_15px_#ef444433]' : 'bg-black border-white/5 hover:border-white/10'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1 pr-4"
                                        >
                                          {l.title}
                                        </button>
                                        <button 
                                          onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} 
                                          className="p-2 text-gray-800 hover:text-white transition-colors active:scale-90"
                                          title="Eliminar Lección"
                                        >
                                          <Trash2 size={12}/>
                                        </button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={(e) => handleCreateLesson(e, mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-red-600/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 hover:border-red-600/50 transition-all bg-white/[0.01]"
                                    >
                                      + AGREGAR LECCIÓN
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button 
                              onClick={(e) => handleCreateModule(e, course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all flex items-center justify-center gap-3 active:scale-95"
                            >
                              <Plus size={16} /> AGREGAR NUEVO MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR DE CONTENIDO ESTRATÉGICO */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Editor de Sesión</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de <span className="text-white">Contenido</span></h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 overflow-y-auto max-h-[60vh] pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Título de la Lección</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all shadow-inner" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Video URL (YouTube/Vimeo)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all shadow-inner" 
                      />
                    </div>

                    {/* GESTIÓN DE RECURSOS ADJUNTOS */}
                    <div className="space-y-4">
                      <div className="flex justify-between items-center ml-5">
                        <label className="text-[10px] font-black uppercase text-gray-600 tracking-widest">Materiales de la Clase</label>
                        <button onClick={handleAddResource} className="text-[9px] font-black uppercase text-red-600 flex items-center gap-2 hover:underline active:scale-95">
                          <Plus size={12}/> Vincular Recurso
                        </button>
                      </div>
                      <div className="space-y-2">
                        {editingLesson.resources?.map((r, i) => (
                          <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5 hover:border-white/10 transition-all">
                            <div className="flex items-center gap-3">
                              <FileText size={14} className="text-red-600" />
                              <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                            </div>
                            <button onClick={() => handleRemoveResource(i)} className="p-2 text-gray-700 hover:text-red-600 transition-colors">
                              <Trash2 size={12} />
                            </button>
                          </div>
                        ))}
                        {(!editingLesson.resources || editingLesson.resources.length === 0) && (
                          <div className="p-6 border border-dashed border-white/5 rounded-2xl text-center opacity-20">
                            <p className="text-[8px] font-black uppercase tracking-widest">Sin archivos vinculados</p>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5 tracking-[0.2em]">Cuerpo de la Clase (Markdown)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar shadow-inner" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    disabled={isProcessing} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR CONFIGURACIÓN ESTRATÉGICA
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8 text-gray-600" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-6 uppercase tracking-[0.5em] max-w-xs leading-loose">
                    Selecciona una unidad de la jerarquía lateral para activar los protocolos de edición avanzada.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos <span className="text-red-600">Verificados</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group shadow-sm">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 transition-all shadow-inner">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase tracking-widest border ${
                    onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'
                  }`}>
                    {onlineUserIds.has(s.id) ? 'Online' : 'Inactivo'}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL LANZAMIENTO DE CURSO */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVA <span className="text-red-600">FORMACIÓN</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>

              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Programa</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Ej: Master High Ticket 2025..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                </div>
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Descripción Global</label>
                  <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Define el impacto de esta formación..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-48 resize-none outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                </div>
              </div>

              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_#ef44444d] disabled:opacity-50 active:scale-95">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, AlertTriangle, CheckCircle2, AlertCircle, PlusCircle, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchData();
    fetchUserList();
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();
    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_DATA_FETCH_ERROR:", err.message);
      alert("ERROR REAL EN CARGA: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- CRUD LÓGICA CON BLOQUEO DE PROPAGACIÓN ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) {
      alert("El título del programa es obligatorio.");
      return;
    }
    setIsProcessing(true);
    try {
      const { data: courseData, error: courseError } = await supabase
        .from('courses')
        .insert([{ 
          title: newCourseData.title.trim(), 
          description: newCourseData.description.trim(), 
          order_index: courses.length 
        }])
        .select().single();

      if (courseError) throw courseError;

      await supabase.from('modules').insert([{ course_id: courseData.id, title: 'Bienvenida', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'MASTER DESPLEGADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR REAL (CREATE COURSE): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation(); // BLOQUEO CRÍTICO
    e.preventDefault();

    const nombre = window.prompt("Nombre del nuevo Módulo:");
    if (!nombre || !nombre.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ 
        course_id: courseId, 
        title: nombre.trim(), 
        order_index: courses.find(c => c.id === courseId)?.modules?.length || 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR REAL (CREATE MODULE): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation(); // BLOQUEO CRÍTICO
    e.preventDefault();

    const title = window.prompt("Título de la Lección:");
    if (!title || !title.trim()) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title: title.trim(),
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Sesión\nEdita este contenido para tus alumnos.',
        resources: [],
        order_index: 0
      }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'LECCIÓN AGREGADA' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR REAL (CREATE LESSON): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation(); // BLOQUEO CRÍTICO - Evita que el acordeón se cierre/abra
    e.preventDefault();

    if (!window.confirm(`¿Seguro que quieres eliminar este ${type} permanentemente?`)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);

      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);

      // Actualización local inmediata
      if (type === 'course') {
        setCourses(prev => prev.filter(c => c.id !== id));
      } else {
        await fetchData();
      }
    } catch (err: any) {
      alert(`ERROR REAL (DELETE ${type.toUpperCase()}): ` + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS SINCRONIZADOS' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR REAL (SAVE LESSON): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre del material:");
    const url = window.prompt("URL del archivo:");
    if (name && url) {
      const updatedResources = [...(editingLesson.resources || []), { name, url }];
      setEditingLesson({ ...editingLesson, resources: updatedResources });
    }
  };

  const handleRemoveResource = (index: number) => {
    if (!editingLesson) return;
    const updatedResources = [...editingLesson.resources];
    updatedResources.splice(index, 1);
    setEditingLesson({ ...editingLesson, resources: updatedResources });
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-10 py-5 rounded-[2.5rem] border shadow-2xl flex items-center gap-4 min-w-[350px] backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={24}/> : <AlertCircle size={24}/>}
            <span className="text-[11px] font-black uppercase tracking-[0.2em]">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> Dash
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">MANDO <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <div className="flex gap-4">
          <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all"><LogOut size={20}/></button>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}><BookOpen size={18}/> Arquitectura</button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}><Users size={18}/> Alumnos</button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* ESTRUCTURA (IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-8">
              <div className="flex justify-between items-center px-6">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em]">Programas</h2>
                <button onClick={() => setShowCreateModal(true)} className="p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all flex items-center gap-3 active:scale-95">
                  <PlusCircle size={20} />
                  <span className="text-[10px] font-black uppercase">Nuevo Curso</span>
                </button>
              </div>

              <div className="space-y-6">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] overflow-hidden shadow-2xl">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <Layout size={20} className="text-red-600" />
                        <h3 className="font-black text-sm uppercase tracking-tighter text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-3 text-gray-700 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all z-20"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform ${expandedCourses.has(course.id) ? 'rotate-180' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2.5rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03]" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <span className="font-bold text-[11px] uppercase tracking-wider text-gray-400">{mod.title}</span>
                                  <div className="flex items-center gap-2">
                                    <button 
                                      onClick={(e) => handleDeleteItem(e, 'module', mod.id)} 
                                      className="p-2 text-gray-700 hover:text-red-500 transition-colors z-20"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600' : 'bg-black border-white/5'}`}>
                                        <button 
                                          onClick={() => setEditingLesson(l)} 
                                          className="text-[10px] font-black uppercase text-left truncate flex-1 pr-4"
                                        >
                                          {l.title}
                                        </button>
                                        <button 
                                          onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} 
                                          className="p-2 text-gray-800 hover:text-white transition-colors z-20"
                                        >
                                          <Trash2 size={12}/>
                                        </button>
                                      </div>
                                    ))}
                                    <button 
                                      onClick={(e) => handleCreateLesson(e, mod.id)} 
                                      className="w-full py-4 mt-2 border-2 border-dashed border-red-600/10 rounded-xl text-[9px] font-black uppercase text-gray-500 hover:text-red-600 transition-all"
                                    >
                                      + AGREGAR LECCIÓN
                                    </button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button 
                              onClick={(e) => handleCreateModule(e, course.id)} 
                              className="w-full py-6 bg-white/[0.03] border-2 border-dashed border-red-600/10 rounded-[2rem] text-[10px] font-black uppercase text-gray-500 hover:text-red-600 transition-all flex items-center justify-center gap-3"
                            >
                              <Plus size={16} /> AGREGAR MÓDULO
                            </button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR (DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Protocolo de Edición</p>
                      <h2 className="text-3xl font-black uppercase tracking-tighter leading-none">Ajuste de Sesión</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 overflow-y-auto max-h-[60vh] pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Título de la Sesión</label>
                      <input type="text" value={editingLesson.title} onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all shadow-inner" />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Embed URL (YouTube/Vimeo)</label>
                      <input type="text" value={editingLesson.video_url} onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 text-gray-500 font-mono text-xs focus:border-red-600 outline-none transition-all shadow-inner" />
                    </div>

                    <div className="space-y-4">
                        <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Materiales Adjuntos</label>
                        <button onClick={handleAddResource} className="text-[9px] font-black uppercase text-red-600 ml-4 hover:underline active:scale-95">+ Vincular Material</button>
                        <div className="space-y-2">
                            {editingLesson.resources?.map((r, i) => (
                                <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-2xl border border-white/5">
                                    <div className="flex items-center gap-3">
                                        <FileText size={14} className="text-red-600" />
                                        <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                                    </div>
                                    <button onClick={() => handleRemoveResource(i)} className="p-2 text-gray-700 hover:text-red-600 transition-colors active:scale-90"><Trash2 size={12} /></button>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[10px] font-black uppercase text-gray-600 ml-5">Contenido (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none custom-scrollbar shadow-inner" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-xs tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl active:scale-[0.98] disabled:opacity-50">
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR CAMBIOS
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-8 text-gray-600" />
                  <h3 className="text-2xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-6 uppercase tracking-[0.5em] max-w-xs leading-loose">
                    Selecciona una sesión de la jerarquía para activar los protocolos de edición avanzada.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[4rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos <span className="text-red-600">Verificados</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group">
                  <div className="flex items-center gap-5">
                    <div className="w-14 h-14 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-xl border border-red-600/20 group-hover:bg-red-600 transition-all">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[10px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-full text-[9px] font-black uppercase border ${onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'}`}>{onlineUserIds.has(s.id) ? 'Online' : 'Inactivo'}</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[400] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-14 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">MASTER</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 transition-all"><X size={24}/></button>
              </div>
              <div className="space-y-10">
                <div className="space-y-4">
                  <label className="text-[11px] font-black uppercase text-gray-600 ml-6 tracking-widest">Nombre del Programa</label>
                  <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Ej: Master High Ticket 2025..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                </div>
              </div>
              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-2xl active:scale-95 disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR MASTER
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layers, Layout, MoveVertical, CheckCircle2, AlertCircle, PlusCircle, FileText
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);
  const [onlineUserIds, setOnlineUserIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchData();
    fetchUserList();

    // Tracking de presencia para admin
    const channel = supabase.channel('online-users').on('presence', { event: 'sync' }, () => {
      const state = channel.presenceState();
      setOnlineUserIds(new Set(Object.keys(state)));
    }).subscribe();

    return () => { supabase.removeChannel(channel); };
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      // Cargamos jerarquía completa
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('order_index', { ascending: true })
        .order('order_index', { foreignTable: 'modules', ascending: true })
        .order('order_index', { foreignTable: 'modules.lessons', ascending: true });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_FETCH_ERROR:", err.message);
      setNotification({ type: 'error', msg: 'FALLO AL CARGAR CURRÍCULO' });
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          last_seen: p.last_seen,
          created_at: p.created_at,
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("ADMIN_USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES CRUD BLINDADAS (CON STOP PROPAGATION) ---

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return alert("El título es obligatorio");
    setIsProcessing(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title, description: newCourseData.description, order_index: courses.length }])
        .select().single();

      if (error) throw error;

      // Módulo inicial automático
      await supabase.from('modules').insert([{ course_id: data.id, title: 'Introducción', order_index: 0 }]);

      setNotification({ type: 'success', msg: 'MASTER LANZADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      fetchData(); // Recarga completa para asegurar jerarquía
    } catch (err: any) {
      alert("ERROR REAL (CREATE): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateModule = async (e: React.MouseEvent, courseId: string) => {
    e.stopPropagation(); e.preventDefault();
    const title = window.prompt("Nombre del nuevo módulo:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId, order_index: 99 }]);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO SINCRONIZADO' });
      fetchData();
    } catch (err: any) {
      alert("ERROR REAL (MOD): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateLesson = async (e: React.MouseEvent, moduleId: string) => {
    e.stopPropagation(); e.preventDefault();
    const title = window.prompt("Título de la lección:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nContenido listo para editar.',
        resources: [],
        order_index: 0
      }]);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'LECCIÓN VINCULADA' });
      fetchData();
    } catch (err: any) {
      alert("ERROR REAL (LESSON): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteItem = async (e: React.MouseEvent, type: 'course' | 'module' | 'lesson', id: string) => {
    e.stopPropagation(); e.preventDefault();
    if (!window.confirm(`¿Seguro que quieres eliminar este ${type} permanentemente?`)) return;

    setIsProcessing(true);
    try {
      const table = type === 'course' ? 'courses' : type === 'module' ? 'modules' : 'lessons';
      const { error } = await supabase.from(table).delete().eq('id', id);
      if (error) throw error;

      setNotification({ type: 'success', msg: `${type.toUpperCase()} ELIMINADO` });
      if (editingLesson?.id === id) setEditingLesson(null);

      // Actualización de UI inmediata (Master Strategy)
      if (type === 'course') {
        setCourses(prev => prev.filter(c => c.id !== id));
      } else {
        fetchData();
      }
    } catch (err: any) {
      alert(`ERROR REAL (DELETE ${type}): ` + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS GUARDADOS' });
      fetchData();
    } catch (err: any) {
      alert("ERROR REAL (SAVE): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddResource = () => {
    if (!editingLesson) return;
    const name = window.prompt("Nombre del material:");
    const url = window.prompt("Enlace:");
    if (name && url) {
      setEditingLesson({ ...editingLesson, resources: [...(editingLesson.resources || []), { name, url }] });
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600 relative overflow-x-hidden">
      {/* NOTIFICACIONES FLOTANTES */}
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-12 left-1/2 z-[500] px-8 py-4 rounded-[2rem] border shadow-2xl flex items-center gap-4 backdrop-blur-3xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={20}/> : <AlertCircle size={20}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> DASHBOARD
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="p-3 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-90">
          <LogOut size={20}/>
        </button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-10 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <BookOpen size={18}/> Currículo
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-10 py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex flex-col items-center justify-center py-44"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

            {/* LISTADO DE CURSOS (COLUMNA IZQUIERDA) */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-[0.3em]">Jerarquía</h2>
                <button onClick={() => setShowCreateModal(true)} className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2 active:scale-95">
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-xl transition-all hover:border-white/10">
                    <div 
                      className="p-6 flex items-center justify-between cursor-pointer group" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-4">
                        <Layout size={18} className="text-red-600" />
                        <h3 className="font-bold text-sm uppercase tracking-tight text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          onClick={(e) => handleDeleteItem(e, 'course', course.id)} 
                          className="p-2.5 text-gray-700 hover:text-red-600 bg-white/5 rounded-lg border border-white/5 transition-all z-20"
                        >
                          <Trash2 size={16}/>
                        </button>
                        <ChevronDown size={20} className={`text-gray-700 transition-transform ${expandedCourses.has(course.id) ? 'rotate-180' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-6 space-y-4">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-2xl overflow-hidden">
                                <div 
                                  className="p-4 flex items-center justify-between cursor-pointer hover:bg-white/[0.03]" 
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <span className="font-bold text-[10px] uppercase tracking-wider text-gray-500">{mod.title}</span>
                                  <div className="flex items-center gap-2">
                                    <button 
                                      onClick={(e) => handleDeleteItem(e, 'module', mod.id)} 
                                      className="p-2 text-gray-700 hover:text-red-500 transition-colors z-20"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                    <ChevronDown size={14} className={`text-gray-700 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`} />
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-3 bg-black/60 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex items-center justify-between p-3 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600/20 border-red-600' : 'bg-black border-white/5'}`}>
                                        <button onClick={() => setEditingLesson(l)} className="text-[9px] font-black uppercase text-left truncate flex-1">{l.title}</button>
                                        <button onClick={(e) => handleDeleteItem(e, 'lesson', l.id)} className="p-1.5 text-gray-800 hover:text-white transition-colors z-20"><Trash2 size={12}/></button>
                                      </div>
                                    ))}
                                    <button onClick={(e) => handleCreateLesson(e, mod.id)} className="w-full py-3 mt-1 border-2 border-dashed border-red-600/10 rounded-xl text-[8px] font-black uppercase text-gray-600 hover:text-red-600 transition-all">+ LECCIÓN</button>
                                  </div>
                                )}
                              </div>
                            ))}
                            <button onClick={(e) => handleCreateModule(e, course.id)} className="w-full py-4 bg-white/[0.02] border-2 border-dashed border-white/5 rounded-2xl text-[9px] font-black uppercase text-gray-600 hover:text-red-600 hover:border-red-600/30 transition-all">+ MÓDULO</button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR (DERECHA) */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[3rem] p-10 space-y-8 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-6">
                    <h2 className="text-2xl font-black italic uppercase tracking-tighter">Editor de Sesión</h2>
                    <button onClick={() => setEditingLesson(null)} className="p-3 bg-white/5 rounded-xl border border-white/5 hover:bg-white/10 transition-all"><X size={20}/></button>
                  </div>

                  <div className="space-y-6 max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">Título</label>
                      <input type="text" value={editingLesson.title} onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-5 font-bold outline-none focus:border-red-600 transition-all" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">URL Video (YouTube/Vimeo)</label>
                      <input type="text" value={editingLesson.video_url} onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-5 font-mono text-xs outline-none focus:border-red-600 transition-all text-gray-500" />
                    </div>

                    <div className="space-y-3">
                      <div className="flex justify-between items-center px-4">
                        <label className="text-[9px] font-black uppercase text-gray-600 tracking-widest">Materiales</label>
                        <button onClick={handleAddResource} className="text-[8px] font-black uppercase text-red-600 hover:underline">+ Agregar</button>
                      </div>
                      <div className="space-y-2">
                        {editingLesson.resources?.map((r, i) => (
                          <div key={i} className="flex items-center justify-between p-4 bg-white/5 rounded-xl border border-white/5">
                            <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                            <button onClick={() => setEditingLesson({...editingLesson, resources: editingLesson.resources.filter((_, idx) => idx !== i)})} className="p-1.5 text-gray-700 hover:text-red-600"><Trash2 size={12} /></button>
                          </div>
                        ))}
                      </div>
                    </div>

                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">Descripción (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-6 h-40 text-sm outline-none focus:border-red-600 transition-all resize-none" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 py-6 rounded-[2rem] font-black uppercase text-[11px] tracking-[0.3em] flex items-center justify-center gap-3 transition-all hover:bg-red-700 shadow-xl disabled:opacity-50 active:scale-95">
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={20}/>} GUARDAR CONFIGURACIÓN
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[4rem] flex flex-col items-center justify-center text-center p-20 opacity-20 bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-6" />
                  <h3 className="text-xl font-black uppercase tracking-[0.3em] italic">MANDO CENTRAL</h3>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] p-10 shadow-2xl">
            <h2 className="text-2xl font-black uppercase italic tracking-tighter mb-10">Alumnos Verificados</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-white/[0.02] rounded-2xl border border-white/5">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-red-600/20 rounded-xl flex items-center justify-center text-red-600 font-black text-lg">{s.fullName.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-black uppercase">{s.fullName}</p>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase border ${onlineUserIds.has(s.id) ? 'bg-green-600/10 text-green-500 border-green-500/20' : 'bg-white/5 text-gray-600 border-white/5'}`}>{onlineUserIds.has(s.id) ? 'Online' : 'Inactivo'}</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL CREACIÓN */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-lg bg-[#0d0d0d] border border-white/10 rounded-[3rem] p-12 shadow-2xl">
              <div className="flex justify-between items-center mb-10">
                <h3 className="text-3xl font-black italic uppercase tracking-tighter">NUEVO <span className="text-red-600">PROGRAMA</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-3 bg-white/5 rounded-xl border border-white/5 transition-all"><X size={20}/></button>
              </div>
              <div className="space-y-6">
                <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título del Master..." className="w-full bg-black border border-white/5 rounded-2xl p-6 font-black text-xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Descripción breve..." className="w-full bg-black border border-white/5 rounded-2xl p-6 h-32 outline-none focus:border-red-600 transition-all" />
              </div>
              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-10 bg-red-600 text-white py-6 rounded-3xl font-black uppercase text-[11px] tracking-[0.4em] flex items-center justify-center gap-4 transition-all shadow-xl active:scale-95 disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layout, PlusCircle, CheckCircle2, AlertCircle, FileText, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);

  useEffect(() => {
    fetchData();
    fetchUserList();
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .select(`
          *,
          modules (
            *,
            lessons (*)
          )
        `)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_FETCH_ERROR:", err.message);
      setNotification({ type: 'error', msg: 'ERROR AL SINCRONIZAR DATOS' });
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          progress: []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- LOGICA DE EVENTOS BLINDADA ---

  const handleDeleteCourse = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation(); e.preventDefault();
    if (!window.confirm("¿Confirmas la eliminación total de este Master?")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('courses').delete().eq('id', id);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MASTER ELIMINADO' });
      setCourses(prev => prev.filter(c => c.id !== id));
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddModule = async (courseId: string, e: React.MouseEvent) => {
    e.stopPropagation(); e.preventDefault();
    const title = window.prompt("Nombre del nuevo módulo:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteModule = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation(); e.preventDefault();
    if (!window.confirm("¿Eliminar este módulo?")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO BORRADO' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return;
    setIsProcessing(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title, description: newCourseData.description }])
        .select().single();

      if (error) throw error;
      setNotification({ type: 'success', msg: 'NUEVO MASTER LANZADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS SINCRONIZADOS' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans relative overflow-x-hidden selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[500] px-8 py-4 rounded-3xl border shadow-2xl flex items-center gap-3 backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em]">
            <ChevronLeft size={16}/> Volver al Dash
          </Link>
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-10 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] border transition-all flex items-center gap-3 ${activeTab === 'content' ? 'bg-white text-black shadow-xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <BookOpen size={18}/> Arquitectura
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-10 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] border transition-all flex items-center gap-3 ${activeTab === 'users' ? 'bg-white text-black shadow-xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-40"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* PANEL IZQUIERDO */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Master Programs</h2>
                <button onClick={() => setShowCreateModal(true)} className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2">
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Curso</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-xl">
                    <div 
                      className="p-6 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-4">
                        <Layout size={18} className="text-red-600" />
                        <h3 className="font-bold text-sm uppercase tracking-tight text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button onClick={(e) => handleAddModule(course.id, e)} className="text-[8px] bg-white/5 px-3 py-1.5 rounded-lg border border-white/10 hover:border-red-600/50 transition-all font-black uppercase">+ Módulo</button>
                        <button onClick={(e) => handleDeleteCourse(course.id, e)} className="p-2 text-gray-700 hover:text-red-600 transition-all"><Trash2 size={16}/></button>
                        <ChevronDown size={20} className={`text-gray-700 transition-transform ${expandedCourses.has(course.id) ? 'rotate-180' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-6 space-y-4">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-2xl overflow-hidden">
                                <div className="p-4 flex items-center justify-between">
                                  <span className="font-bold text-[10px] uppercase text-gray-500">📦 {mod.title}</span>
                                  <button onClick={(e) => handleDeleteModule(mod.id, e)} className="text-[8px] text-gray-700 hover:text-red-500 font-black uppercase">Eliminar</button>
                                </div>
                                <div className="p-4 bg-black/40 border-t border-white/5 space-y-2">
                                  {mod.lessons?.map(l => (
                                    <div key={l.id} className="flex justify-between items-center p-3 rounded-xl border border-white/5 bg-black hover:border-red-600/30 transition-all">
                                      <button onClick={() => setEditingLesson(l)} className="text-[9px] font-black uppercase truncate flex-1 text-left">{l.title}</button>
                                      <Trash2 size={12} className="text-gray-800 hover:text-red-600 cursor-pointer" />
                                    </div>
                                  ))}
                                  <button className="w-full py-3 mt-2 border border-dashed border-white/10 rounded-xl text-[8px] font-black uppercase text-gray-600 hover:text-red-600">+ Clase</button>
                                </div>
                              </div>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR DERECHO */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[3rem] p-10 space-y-8 sticky top-32">
                  <div className="flex justify-between items-center border-b border-white/5 pb-6">
                    <h2 className="text-2xl font-black italic uppercase tracking-tighter">Editor de Clase</h2>
                    <button onClick={() => setEditingLesson(null)} className="p-3 bg-white/5 rounded-xl hover:bg-white/10 transition-all"><X size={20}/></button>
                  </div>

                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">Título</label>
                      <input type="text" value={editingLesson.title} onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-5 font-bold outline-none focus:border-red-600 transition-all" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">URL Video</label>
                      <input type="text" value={editingLesson.video_url} onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-5 font-mono text-xs outline-none focus:border-red-600 transition-all text-gray-500" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">Contenido (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-2xl p-6 h-40 text-sm outline-none focus:border-red-600 transition-all resize-none" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 py-6 rounded-2xl font-black uppercase text-[11px] tracking-[0.3em] flex items-center justify-center gap-3 hover:bg-red-700 transition-all shadow-xl shadow-red-600/20 active:scale-95 disabled:opacity-50">
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={20}/>} GUARDAR CONFIGURACIÓN
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[4rem] flex flex-col items-center justify-center text-center p-20 opacity-20 bg-white/[0.01]">
                  <MoveVertical size={40} className="mb-6" />
                  <h3 className="text-xl font-black uppercase tracking-[0.3em] italic">MANDO CENTRAL</h3>
                  <p className="text-[10px] mt-4 font-bold uppercase tracking-widest">Selecciona una lección para editar</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[3rem] p-10 shadow-2xl">
            <h2 className="text-2xl font-black uppercase italic tracking-tighter mb-10">Alumnos Verificados</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-6 bg-white/[0.02] rounded-2xl border border-white/5">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-red-600/20 rounded-xl flex items-center justify-center text-red-600 font-black text-lg">{s.fullName.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest">{s.email}</p>
                    </div>
                  </div>
                  <div className="px-4 py-1.5 rounded-full text-[8px] font-black uppercase border bg-white/5 text-gray-600 border-white/5">Activo</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-lg bg-[#0d0d0d] border border-white/10 rounded-[3rem] p-12 shadow-2xl">
              <div className="flex justify-between items-center mb-10">
                <h3 className="text-3xl font-black italic uppercase tracking-tighter">NUEVO <span className="text-red-600">MASTER</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-3 bg-white/5 rounded-xl border border-white/5 transition-all"><X size={20}/></button>
              </div>
              <div className="space-y-6">
                <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título del Programa..." className="w-full bg-black border border-white/5 rounded-2xl p-6 font-black text-xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Descripción estratégica..." className="w-full bg-black border border-white/5 rounded-2xl p-6 h-32 outline-none focus:border-red-600 transition-all" />
              </div>
              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-10 bg-red-600 text-white py-6 rounded-3xl font-black uppercase text-[11px] tracking-[0.4em] flex items-center justify-center gap-4 transition-all shadow-xl active:scale-95 disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layout, PlusCircle, CheckCircle2, AlertCircle, FileText, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);

  useEffect(() => {
    fetchData();
    fetchUserList();
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      // Cargamos jerarquía completa según estructura real
      const { data, error } = await supabase
        .from('courses')
        .select(`
          id, title, description, created_at,
          modules (
            id, title, course_id,
            lessons (
              id, title, module_id, video_url, description, resources
            )
          )
        `)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_FETCH_ERROR:", err.message);
      setNotification({ type: 'error', msg: 'ERROR DE SINCRONIZACIÓN' });
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data, error } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (error) throw error;

      // Consultamos progresos usando la columna correcta: 'user_id'
      const { data: progressData } = await supabase.from('user_progress').select('user_id');

      if (data) {
        setStudents(data.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          progress: progressData?.filter(pr => pr.user_id === p.id).map(pr => pr.user_id) || []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- LOGICA DE EVENTOS BLINDADA (STOP PROPAGATION) ---

  const handleDeleteCourse = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation(); e.preventDefault();
    if (!window.confirm("¿Confirmas la eliminación definitiva? Módulos y clases se borrarán por CASCADE.")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('courses').delete().eq('id', id);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MASTER ELIMINADO' });
      // Actualización de estado local instantánea
      setCourses(prev => prev.filter(c => c.id !== id));
      if (editingLesson && courses.find(c => c.id === id)?.modules.some(m => m.lessons.some(l => l.id === editingLesson.id))) {
        setEditingLesson(null);
      }
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddModule = async (courseId: string, e: React.MouseEvent) => {
    e.stopPropagation(); e.preventDefault();
    const title = window.prompt("Nombre del nuevo módulo:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteModule = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation(); e.preventDefault();
    if (!window.confirm("¿Eliminar este módulo? Se borrarán sus clases.")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'MÓDULO BORRADO' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddLesson = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation(); e.preventDefault();
    const title = window.prompt("Título de la nueva clase:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nContenido listo para producción.',
        resources: []
      }]);
      if (error) throw error;
      setNotification({ type: 'success', msg: 'CLASE AGREGADA' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return;
    setIsProcessing(true);
    try {
      const { data, error } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title, description: newCourseData.description }])
        .select().single();

      if (error) throw error;
      setNotification({ type: 'success', msg: 'ESTRUCTURA LANZADA' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'SISTEMA ACTUALIZADO' });
      await fetchData();
    } catch (err: any) {
      alert("Error Supabase: " + err.message);
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans relative overflow-x-hidden selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[500] px-8 py-4 rounded-3xl border shadow-2xl flex items-center gap-3 backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> DASHBOARD
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">MANDO <span className="text-red-600">CENTRAL</span></h1>
        </div>
        <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl scale-105' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <BookOpen size={18}/> Currículo
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl scale-105' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-40"><Loader2 className="animate-spin text-red-600" size={48} /></div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* PANEL IZQUIERDO: ESTRUCTURA */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Master Hierarchy</h2>
                <button onClick={() => setShowCreateModal(true)} className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2 shadow-lg shadow-red-600/20">
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <Layout size={20} className="text-red-600" />
                        <h3 className="font-bold text-sm uppercase tracking-tight text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button onClick={(e) => handleAddModule(course.id, e)} className="text-[9px] bg-white/5 px-4 py-2 rounded-xl border border-white/10 hover:border-red-600/50 transition-all font-black uppercase">+ MÓDULO</button>
                        <button onClick={(e) => handleDeleteCourse(course.id, e)} className="p-2.5 text-gray-700 hover:text-red-600 transition-all"><Trash2 size={18}/></button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2rem] overflow-hidden shadow-inner">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03]"
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <span className="font-bold text-[10px] uppercase text-gray-500 tracking-wider">📦 {mod.title}</span>
                                  <div className="flex items-center gap-3">
                                    <button onClick={(e) => handleAddLesson(mod.id, e)} className="text-[8px] bg-white/5 px-3 py-1 rounded-lg border border-white/10 hover:border-red-600/50 font-black uppercase">+ CLASE</button>
                                    <button onClick={(e) => handleDeleteModule(mod.id, e)} className="p-1.5 text-gray-700 hover:text-red-500 transition-colors"><Trash2 size={14}/></button>
                                  </div>
                                </div>
                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/40 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex justify-between items-center p-4 rounded-xl border transition-all ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600 shadow-[0_0_15px_rgba(239,68,68,0.2)]' : 'bg-black border-white/5 hover:border-red-600/30'}`}>
                                        <button onClick={() => setEditingLesson(l)} className="text-[10px] font-black uppercase truncate flex-1 text-left text-gray-200">{l.title}</button>
                                        <div className="flex items-center gap-2">
                                          <button onClick={(e) => { e.stopPropagation(); setEditingLesson(l); }} className="p-2 text-gray-700 hover:text-white"><Edit3 size={12}/></button>
                                          <button onClick={(e) => { e.stopPropagation(); alert("Usa CASCADE borrando el módulo o implementa delete directo si es necesario"); }} className="p-2 text-gray-800 hover:text-red-500"><Trash2 size={12}/></button>
                                        </div>
                                      </div>
                                    ))}
                                    {(!mod.lessons || mod.lessons.length === 0) && (
                                      <p className="text-[8px] uppercase font-black text-gray-700 text-center py-4">Módulo vacío</p>
                                    )}
                                  </div>
                                )}
                              </div>
                            ))}
                            {(!course.modules || course.modules.length === 0) && (
                              <p className="text-[9px] uppercase font-black text-gray-700 text-center py-6">Sin módulos creados</p>
                            )}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR DERECHO: CONTENIDO */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Protocolo de Edición</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de Clase</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all active:scale-90"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 max-h-[55vh] overflow-y-auto pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Título de la Sesión</label>
                      <input type="text" value={editingLesson.title} onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all shadow-inner" />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Video Embed Link (YT/Vimeo)</label>
                      <input type="text" value={editingLesson.video_url} onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 font-mono text-xs outline-none focus:border-red-600 transition-all text-gray-500 shadow-inner" />
                    </div>

                    <div className="space-y-4">
                      <div className="flex justify-between items-center ml-5">
                         <label className="text-[9px] font-black uppercase text-gray-600 tracking-widest">Recursos Adjuntos</label>
                         <button onClick={() => {
                           const name = window.prompt("Nombre del archivo:");
                           const url = window.prompt("URL del archivo:");
                           if (name && url) setEditingLesson({...editingLesson, resources: [...(editingLesson.resources || []), {name, url}]});
                         }} className="text-[8px] font-black uppercase text-red-600 hover:underline">+ Agregar</button>
                      </div>
                      <div className="space-y-2">
                         {editingLesson.resources?.map((r, i) => (
                           <div key={i} className="flex items-center justify-between p-4 bg-white/5 border border-white/5 rounded-2xl">
                              <div className="flex items-center gap-3">
                                 <FileText size={14} className="text-red-600" />
                                 <span className="text-[10px] font-bold uppercase truncate max-w-[200px]">{r.name}</span>
                              </div>
                              <button onClick={() => setEditingLesson({...editingLesson, resources: editingLesson.resources.filter((_, idx) => idx !== i)})} className="p-2 text-gray-700 hover:text-red-500 transition-all"><Trash2 size={14} /></button>
                           </div>
                         ))}
                      </div>
                    </div>

                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Descripción Estratégica (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-8 h-56 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none shadow-inner" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-[11px] tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50">
