                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>
              <div className="space-y-10">
                <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Nombre del Máster..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Visión estratégica..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-40 outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner resize-none" />
              </div>
              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3.5rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_rgba(220,38,38,0.3)] active:scale-95 disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminPage;

