Para que el sistema funcione al 100% y los botones dejen de estar bloqueados, necesitamos una **sincronización total** entre tu base de datos Supabase y el Frontend. 

Aquí tienes la guía definitiva y el código corregido.

### 1. CONFIGURACIÓN CRÍTICA EN SUPABASE (SQL)
Copia y pega este script en el **SQL Editor** de tu proyecto de Supabase. Esto soluciona los errores de "Cascade" (que impiden borrar cursos si tienen módulos) y las políticas de seguridad (RLS).

```sql
-- 1. Habilitar extensiones necesarias
create extension if not exists "uuid-ossp";

-- 2. Tabla de Perfiles (profiles)
create table if not exists profiles (
  id uuid references auth.users on delete cascade primary key,
  full_name text,
  role text default 'student',
  last_seen timestamp with time zone default now(),
  created_at timestamp with time zone default now()
);

-- 3. Tabla de Cursos (courses)
create table if not exists courses (
  id uuid default uuid_generate_v4() primary key,
  title text not null,
  description text,
  order_index serial,
  created_at timestamp with time zone default now()
);

-- 4. Tabla de Módulos (modules) con BORRADO EN CASCADA
create table if not exists modules (
  id uuid default uuid_generate_v4() primary key,
  course_id uuid references courses(id) on delete cascade not null,
  title text not null,
  order_index serial,
  created_at timestamp with time zone default now()
);

-- 5. Tabla de Lecciones (lessons) con BORRADO EN CASCADA
create table if not exists lessons (
  id uuid default uuid_generate_v4() primary key,
  module_id uuid references modules(id) on delete cascade not null,
  title text not null,
  video_url text,
  description text,
  resources jsonb default '[]'::jsonb,
  order_index serial,
  created_at timestamp with time zone default now()
);

-- 6. Tabla de Progreso (user_progress)
create table if not exists user_progress (
  user_id uuid references profiles(id) on delete cascade not null,
  lesson_id uuid references lessons(id) on delete cascade not null,
  created_at timestamp with time zone default now(),
  primary key (user_id, lesson_id)
);

-- 7. POLÍTICAS DE SEGURIDAD (RLS) - Permitir todo para pruebas (Luego puedes restringir)
alter table profiles enable row level security;
alter table courses enable row level security;
alter table modules enable row level security;
alter table lessons enable row level security;
alter table user_progress enable row level security;

create policy "Acceso total" on profiles for all using (true) with check (true);
create policy "Acceso total" on courses for all using (true) with check (true);
create policy "Acceso total" on modules for all using (true) with check (true);
create policy "Acceso total" on lessons for all using (true) with check (true);
create policy "Acceso total" on user_progress for all using (true) with check (true);
```

