import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layout, PlusCircle, CheckCircle2, AlertCircle, FileText, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);

  useEffect(() => {
    fetchData();
    fetchUserList();
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      // Carga jerárquica completa
      const { data, error } = await supabase
        .from('courses')
        .select(`
          id, title, description, created_at,
          modules (
            id, title, course_id,
            lessons (
              id, title, module_id, video_url, description, resources
            )
          )
        `)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setCourses(data || []);
    } catch (err: any) {
      console.error("ADMIN_FETCH_ERROR:", err.message);
      alert("Error al sincronizar con Supabase: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data: profiles, error: pError } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (pError) throw pError;

      const { data: progressData } = await supabase.from('user_progress').select('user_id');

      if (profiles) {
        setStudents(profiles.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          progress: progressData?.filter(pr => pr.user_id === p.id).map(pr => pr.user_id) || []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES CRUD BLINDADAS (USAR e.stopPropagation() ES VITAL) ---

  const handleDeleteCourse = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    if (!window.confirm("¿ESTÁS SEGURO? Se borrarán todos los módulos y clases de este máster inmediatamente.")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('courses').delete().eq('id', id);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'PROGRAMA ELIMINADO' });
      setCourses(prev => prev.filter(c => c.id !== id));
      if (editingLesson) setEditingLesson(null);
    } catch (err: any) {
      alert("ERROR DE SUPABASE: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddModule = async (courseId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Nombre del nuevo módulo:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR AL CREAR MÓDULO: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteModule = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    if (!window.confirm("¿Eliminar este módulo y sus clases?")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MÓDULO ELIMINADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR AL ELIMINAR MÓDULO: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddLesson = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Título de la clase:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nEdita este contenido.',
        resources: []
      }]);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'CLASE AÑADIDA' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR AL CREAR CLASE: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title, description: newCourseData.description }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MASTER LANZADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR AL LANZAR MASTER: " + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'CAMBIOS GUARDADOS' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR AL GUARDAR: " + err.message);
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[1000] px-8 py-4 rounded-3xl border shadow-2xl flex items-center gap-3 backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> VOLVER
          </Link>
          <h1 className="text-xl font-black tracking-tighter uppercase italic">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-10 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] border transition-all flex items-center gap-3 ${activeTab === 'content' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <BookOpen size={18}/> Contenido
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-10 py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] border transition-all flex items-center gap-3 ${activeTab === 'users' ? 'bg-white text-black' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-40 flex-col gap-4">
            <Loader2 className="animate-spin text-red-600" size={48} />
            <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-20">Sincronizando Base de Datos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* LISTA DE CURSOS */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Master Tree</h2>
                <button onClick={() => setShowCreateModal(true)} className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2 shadow-xl shadow-red-600/20 active:scale-95">
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-2xl">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <Layout size={20} className="text-red-600" />
                        <h3 className="font-bold text-sm uppercase tracking-tight text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        {/* BOTÓN AGREGAR MÓDULO (BLINDADO) */}
                        <button 
                          onClick={(e) => handleAddModule(course.id, e)} 
                          className="text-[8px] bg-white/5 px-4 py-2 rounded-xl border border-white/10 hover:border-red-600/50 transition-all font-black uppercase"
                        >
                          + MÓDULO
                        </button>
                        {/* BOTÓN ELIMINAR CURSO (BLINDADO) */}
                        <button 
                          onClick={(e) => handleDeleteCourse(course.id, e)} 
                          className="p-2.5 text-gray-700 hover:text-red-600 transition-all active:scale-90"
                        >
                          <Trash2 size={18}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2rem] overflow-hidden">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03]"
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <span className="font-bold text-[10px] uppercase text-gray-500 tracking-wider">📦 {mod.title}</span>
                                  <div className="flex items-center gap-3">
                                    <button onClick={(e) => handleAddLesson(mod.id, e)} className="text-[8px] bg-white/5 px-3 py-1 rounded-lg border border-white/10 hover:border-red-600/50 font-black uppercase">+ CLASE</button>
                                    <button onClick={(e) => handleDeleteModule(mod.id, e)} className="p-1.5 text-gray-700 hover:text-red-500 transition-colors"><Trash2 size={14}/></button>
                                  </div>
                                </div>
                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/40 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div key={l.id} className={`flex justify-between items-center p-4 rounded-xl border transition-all cursor-pointer ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600 shadow-xl shadow-red-600/20' : 'bg-black border-white/5 hover:border-red-600/30'}`} onClick={() => setEditingLesson(l)}>
                                        <div className="text-[10px] font-black uppercase truncate flex-1 text-left text-gray-200">{l.title}</div>
                                        <div className="flex items-center gap-2">
                                          <button onClick={(e) => { e.stopPropagation(); setEditingLesson(l); }} className="p-2 text-gray-700 hover:text-white"><Edit3 size={12}/></button>
                                        </div>
                                      </div>
                                    ))}
                                  </div>
                                )}
                              </div>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* EDITOR DE CONTENIDO */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <h2 className="text-3xl font-black italic uppercase tracking-tighter">Editor de Clase</h2>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 max-h-[50vh] overflow-y-auto pr-4 custom-scrollbar">
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">Título</label>
                      <input type="text" value={editingLesson.title} onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold outline-none focus:border-red-600 transition-all" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">Video URL (YT/Vimeo)</label>
                      <input type="text" value={editingLesson.video_url} onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 font-mono text-xs outline-none focus:border-red-600 transition-all text-gray-500" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-4 tracking-widest">Descripción (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-8 h-48 text-sm outline-none focus:border-red-600 transition-all resize-none" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-[11px] tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 disabled:opacity-50">
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} GUARDAR SESIÓN
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 bg-white/[0.01]">
                  <MoveVertical size={48} className="mb-10 text-gray-600" />
                  <h3 className="text-3xl font-black uppercase tracking-[0.4em] italic leading-tight text-white/50">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-8 uppercase tracking-[0.5em] max-w-xs leading-loose">Selecciona una lección para iniciar los protocolos de edición.</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos Registrados</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5">
                  <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-2xl border border-red-600/20">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest mt-1">{s.email}</p>
                    </div>
                  </div>
                  <div className="px-5 py-2 rounded-full text-[8px] font-black uppercase border border-white/5 bg-white/5 text-gray-600">ACTIVO</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-16 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">MASTER</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>
              <div className="space-y-10">
                <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título del Máster..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800" />
                <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Visión estratégica..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-40 outline-none focus:border-red-600 transition-all placeholder:text-gray-800 resize-none" />
              </div>
              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3.5rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_rgba(220,38,38,0.3)] active:scale-95 disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layout, PlusCircle, CheckCircle2, AlertCircle, FileText, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);

  useEffect(() => {
    fetchData();
    fetchUserList();
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      console.log("Admin: Sincronizando estructura...");
      const { data, error } = await supabase
        .from('courses')
        .select(`
          id, title, description, created_at,
          modules (
            id, title, course_id,
            lessons (
              id, title, module_id, video_url, description, resources
            )
          )
        `)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setCourses(data || []);
      console.log("Admin: Cursos cargados ->", data?.length);
    } catch (err: any) {
      console.error("ADMIN_FETCH_ERROR:", err.message);
      alert("FALLO CRÍTICO DE CONEXIÓN: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data: profiles, error: pError } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (pError) throw pError;

      const { data: progressData } = await supabase.from('user_progress').select('user_id');

      if (profiles) {
        setStudents(profiles.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          progress: progressData?.filter(pr => pr.user_id === p.id).map(pr => pr.user_id) || []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES CRUD CON BLINDAJE DE EVENTOS ---

  const handleDeleteCourse = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    console.log("Admin: Intentando borrar curso", id);

    if (!window.confirm("⚠️ ATENCIÓN: ¿Borrar este máster y TODO su contenido? Esta acción no se puede deshacer.")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('courses').delete().eq('id', id);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'CURSO ELIMINADO' });
      setCourses(prev => prev.filter(c => c.id !== id));
      if (editingLesson) setEditingLesson(null);
    } catch (err: any) {
      alert("ERROR DE SUPABASE (CURSO): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddModule = async (courseId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    console.log("Admin: Agregando módulo a", courseId);

    const title = window.prompt("Nombre del nuevo módulo:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR DE SUPABASE (MÓDULO): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteModule = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    console.log("Admin: Borrando módulo", moduleId);

    if (!window.confirm("¿Confirmas eliminar este módulo y todas sus clases?")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MÓDULO BORRADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR DE SUPABASE (BORRAR MÓDULO): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddLesson = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    console.log("Admin: Agregando clase a módulo", moduleId);

    const title = window.prompt("Título de la nueva sesión:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Contenido Estratégico\nEdita esta descripción.',
        resources: []
      }]);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'SESIÓN AGREGADA' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR DE SUPABASE (CLASE): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title, description: newCourseData.description }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MASTER INICIADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR DE SUPABASE (CREAR MASTER): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'SISTEMA ACTUALIZADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR AL GUARDAR CAMBIOS: " + err.message);
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[1000] px-8 py-4 rounded-3xl border shadow-2xl flex items-center gap-3 backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> VOLVER
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5 hover:border-white/10'}`}>
            <BookOpen size={18}/> Currículo
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5 hover:border-white/10'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-40 flex-col gap-6">
            <Loader2 className="animate-spin text-red-600" size={48} />
            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-700">Sincronizando Archivos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* PANEL IZQUIERDO: ESTRUCTURA */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Master Hierarchy</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2 shadow-lg shadow-red-600/20 active:scale-95"
                >
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    {/* CURSO HEADER (ACORDEÓN) */}
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <Layout size={20} className="text-red-600" />
                        <h3 className="font-bold text-sm uppercase tracking-tight text-gray-200">{course.title}</h3>
                      </div>
                      <div className="flex items-center gap-3">
                        <button 
                          type="button"
                          onClick={(e) => handleAddModule(course.id, e)} 
                          className="text-[8px] bg-white/5 px-4 py-2 rounded-xl border border-white/10 hover:border-red-600/50 transition-all font-black uppercase z-20"
                        >
                          + MÓDULO
                        </button>
                        <button 
                          type="button"
                          onClick={(e) => handleDeleteCourse(course.id, e)} 
                          className="p-2.5 text-gray-700 hover:text-red-600 transition-all active:scale-90 z-20"
                        >
                          <Trash2 size={18}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2rem] overflow-hidden shadow-inner">
                                {/* MÓDULO HEADER */}
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03]"
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <span className="font-bold text-[10px] uppercase text-gray-500 tracking-wider">📦 {mod.title}</span>
                                  <div className="flex items-center gap-3">
                                    <button 
                                      type="button"
                                      onClick={(e) => handleAddLesson(mod.id, e)} 
                                      className="text-[8px] bg-white/5 px-3 py-1 rounded-lg border border-white/10 hover:border-red-600/50 font-black uppercase z-20"
                                    >
                                      + CLASE
                                    </button>
                                    <button 
                                      type="button"
                                      onClick={(e) => handleDeleteModule(mod.id, e)} 
                                      className="p-1.5 text-gray-700 hover:text-red-500 transition-colors active:scale-90 z-20"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                  </div>
                                </div>
                                {/* LISTA DE CLASES */}
                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/40 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div 
                                        key={l.id} 
                                        className={`flex justify-between items-center p-4 rounded-xl border transition-all cursor-pointer ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600 shadow-[0_0_15px_rgba(239,68,68,0.2)]' : 'bg-black border-white/5 hover:border-red-600/30'}`}
                                        onClick={() => setEditingLesson(l)}
                                      >
                                        <div className="text-[10px] font-black uppercase truncate flex-1 text-left text-gray-200">{l.title}</div>
                                        <div className="flex items-center gap-2">
                                          <button 
                                            type="button"
                                            onClick={(e) => { e.stopPropagation(); setEditingLesson(l); }} 
                                            className="p-2 text-gray-700 hover:text-white"
                                          >
                                            <Edit3 size={12}/>
                                          </button>
                                          <button 
                                            type="button"
                                            onClick={(e) => { 
                                              e.stopPropagation(); 
                                              if(window.confirm("¿Borrar esta sesión definitivamente?")) {
                                                supabase.from('lessons').delete().eq('id', l.id).then(() => {
                                                  setNotification({type: 'success', msg: 'SESIÓN ELIMINADA'});
                                                  fetchData();
                                                });
                                              }
                                            }} 
                                            className="p-2 text-gray-800 hover:text-red-500"
                                          >
                                            <Trash2 size={12}/>
                                          </button>
                                        </div>
                                      </div>
                                    ))}
                                    {(!mod.lessons || mod.lessons.length === 0) && (
                                      <p className="text-[8px] uppercase font-black text-gray-700 text-center py-4">Módulo vacío</p>
                                    )}
                                  </div>
                                )}
                              </div>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* PANEL DERECHO: EDITOR */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Editor Estratégico</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de Sesión</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 max-h-[55vh] overflow-y-auto pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Título de la Sesión</label>
                      <input type="text" value={editingLesson.title} onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all shadow-inner" />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">URL Video (YT/Vimeo)</label>
                      <input type="text" value={editingLesson.video_url} onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-7 font-mono text-xs outline-none focus:border-red-600 transition-all text-gray-500 shadow-inner" />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Descripción (Markdown)</label>
                      <textarea value={editingLesson.description} onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} className="w-full bg-black border border-white/5 rounded-3xl p-8 h-56 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none shadow-inner" />
                    </div>
                  </div>

                  <button onClick={saveLesson} disabled={isProcessing} className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-[11px] tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50">
                    {isProcessing ? <Loader2 className="animate-spin"/> : <Save size={22}/>} SINCRONIZAR CAMBIOS
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={48} className="mb-10 text-gray-600" />
                  <h3 className="text-3xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-8 uppercase tracking-[0.5em] max-w-xs leading-loose">
                    Selecciona una sesión de la jerarquía lateral para activar los protocolos de edición.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos <span className="text-red-600">Verificados</span></h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 hover:border-white/10 transition-all group">
                  <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-2xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all shadow-inner">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest mt-1">{s.email}</p>
                      <div className="flex items-center gap-2 mt-2">
                        <CheckCircle2 size={10} className="text-red-600" />
                        <span className="text-[8px] font-black uppercase text-gray-700 tracking-[0.2em]">{s.progress.length} Sesiones</span>
                      </div>
                    </div>
                  </div>
                  <div className="px-5 py-2 rounded-full text-[8px] font-black uppercase border border-white/5 bg-white/5 text-gray-600 tracking-widest group-hover:border-red-600/20 transition-all">ACTIVO</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => !isProcessing && setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-16 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">MASTER</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>
              <div className="space-y-10">
                <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título del Máster..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Descripción estratégica..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-40 outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner resize-none" />
              </div>
              <button onClick={handleCreateCourse} disabled={isProcessing || !newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3.5rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_rgba(220,38,38,0.3)] active:scale-95 disabled:opacity-50">
                {isProcessing ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layout, PlusCircle, CheckCircle2, AlertCircle, FileText, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [students, setStudents] = useState<User[]>([]);

  useEffect(() => {
    fetchData();
    fetchUserList();
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      console.log("Admin: Sincronizando estructura...");
      const { data, error } = await supabase
        .from('courses')
        .select(`
          id, title, description, created_at,
          modules (
            id, title, course_id,
            lessons (
              id, title, module_id, video_url, description, resources
            )
          )
        `)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setCourses(data || []);
      console.log("Admin: Cursos cargados ->", data?.length);
    } catch (err: any) {
      console.error("ADMIN_FETCH_ERROR:", err.message);
      alert("FALLO CRÍTICO DE CONEXIÓN: " + err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data: profiles, error: pError } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (pError) throw pError;

      const { data: progressData } = await supabase.from('user_progress').select('user_id');

      if (profiles) {
        setStudents(profiles.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          progress: progressData?.filter(pr => pr.user_id === p.id).map(pr => pr.user_id) || []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES CRUD CON BLINDAJE DE EVENTOS ---

  const handleDeleteCourse = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    console.log("Admin: Intentando borrar curso", id);

    if (!window.confirm("⚠️ ATENCIÓN: ¿Borrar este máster y TODO su contenido? Esta acción no se puede deshacer.")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('courses').delete().eq('id', id);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'CURSO ELIMINADO' });
      setCourses(prev => prev.filter(c => c.id !== id));
      if (editingLesson) setEditingLesson(null);
    } catch (err: any) {
      alert("ERROR DE SUPABASE (CURSO): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddModule = async (courseId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    console.log("Admin: Agregando módulo a", courseId);

    const title = window.prompt("Nombre del nuevo módulo:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR DE SUPABASE (MÓDULO): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleDeleteModule = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    console.log("Admin: Borrando módulo", moduleId);

    if (!window.confirm("¿Confirmas eliminar este módulo y todas sus clases?")) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MÓDULO BORRADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR DE SUPABASE (BORRAR MÓDULO): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleAddLesson = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    console.log("Admin: Agregando clase a módulo", moduleId);

    const title = window.prompt("Título de la nueva sesión:");
    if (!title) return;

    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Contenido Estratégico\nEdita esta descripción.',
        resources: []
      }]);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'SESIÓN AGREGADA' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR DE SUPABASE (CLASE): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title, description: newCourseData.description }]);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'MASTER INICIADO' });
      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR DE SUPABASE (CREAR MASTER): " + err.message);
    } finally { setIsProcessing(false); }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    setIsProcessing(true);
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;
      setNotification({ type: 'success', msg: 'SISTEMA ACTUALIZADO' });
      await fetchData();
    } catch (err: any) {
      alert("ERROR AL GUARDAR CAMBIOS: " + err.message);
    } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[1000] px-8 py-4 rounded-3xl border shadow-2xl flex items-center gap-3 backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> VOLVER
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5 hover:border-white/10'}`}>
            <BookOpen size={18}/> Currículo
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5 hover:border-white/10'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-40 flex-col gap-6">
            <Loader2 className="animate-spin text-red-600" size={48} />
            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-700">Sincronizando Archivos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* PANEL IZQUIERDO: ESTRUCTURA */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Master Hierarchy</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2 shadow-lg shadow-red-600/20 active:scale-95"
                >
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-2xl hover:border-white/10 transition-all">
                    {/* CURSO HEADER (ACORDEÓN) */}
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
