                  <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-2xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all shadow-inner">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest mt-1">{s.email}</p>
                      <div className="flex items-center gap-2 mt-2">
                        <CheckCircle2 size={10} className="text-red-600" />
