                      </div>
                    </div>
                  </div>
                  <div className="px-5 py-2 rounded-full text-[8px] font-black uppercase border border-white/5 bg-white/5 text-gray-600 tracking-widest group-hover:border-red-600/20 transition-all">ACTIVO</div>
                </div>
