import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layout, PlusCircle, CheckCircle2, AlertCircle, FileText, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);
  const [students, setStudents] = useState<User[]>([]);

  useEffect(() => {
    console.log("📦 ESTADO ACTUAL DE CURSOS:", courses);
  }, [courses]);

  useEffect(() => {
    fetchData();
    fetchUserList();
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE: Fetch de estructura completa...");
      const { data, error } = await supabase
        .from('courses')
        .select(`
          id, title, description, created_at,
          modules (
            id, title, course_id,
            lessons (
              id, title, module_id, video_url, description, resources
            )
          )
        `)
        .order('created_at', { ascending: false });

      if (error) {
        console.error("❌ ERROR DE SUPABASE AL CARGAR:", error);
        alert("FALLO CARGA: " + error.message);
        throw error;
      }

      setCourses(data || []);
      console.log("✅ ACCIÓN EXITOSA: Cursos sincronizados.");
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data: profiles, error: pError } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (pError) throw pError;

      const { data: progressData } = await supabase.from('user_progress').select('user_id');

      if (profiles) {
        setStudents(profiles.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          progress: progressData?.filter(pr => pr.user_id === p.id).map(pr => pr.user_id) || []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES CRUD: FUERZA BRUTA PARA DIAGNÓSTICO ---

  const handleDeleteCourse = async (id: string, e: React.MouseEvent) => {
    console.log("🔍 CLICK DETECTADO EN: Eliminar Curso ID:", id);
    e.stopPropagation();
    e.preventDefault();

    if (!window.confirm("⚠️ ¿BORRAR MASTER? Esta acción eliminará permanentemente el curso, sus módulos y sus clases.")) return;

    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA ELIMINAR:", id);
      const { error } = await supabase.from('courses').delete().eq('id', id);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR DE TABLA/POLÍTICA: " + error.message + " (Código: " + error.code + ")");
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setNotification({ type: 'success', msg: 'MASTER ELIMINADO' });
        // Refresh forzado optimista
        setCourses(current => current.filter(c => c.id !== id));
        if (editingLesson?.module_id === id) setEditingLesson(null);
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("EL CÓDIGO FALLÓ ANTES DE LLEGAR A SUPABASE: " + err.message);
    }
  };

  const handleAddModule = async (courseId: string, e: React.MouseEvent) => {
    console.log("🔍 CLICK DETECTADO EN: Agregar Módulo al curso:", courseId);
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Nombre del módulo:");
    if (!title) return;

    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA CREAR MÓDULO");
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR DE TABLA/POLÍTICA: " + error.message + " (Código: " + error.code + ")");
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("EL CÓDIGO FALLÓ ANTES DE LLEGAR A SUPABASE: " + err.message);
    }
  };

  const handleDeleteModule = async (moduleId: string, e: React.MouseEvent) => {
    console.log("🔍 CLICK DETECTADO EN: Eliminar Módulo ID:", moduleId);
    e.stopPropagation();
    e.preventDefault();

    if (!window.confirm("¿Borrar módulo y sus clases?")) return;

    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA ELIMINAR MÓDULO");
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR: " + error.message);
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setNotification({ type: 'success', msg: 'MÓDULO BORRADO' });
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("ERROR: " + err.message);
    }
  };

  const handleAddLesson = async (moduleId: string, e: React.MouseEvent) => {
    console.log("🔍 CLICK DETECTADO EN: Agregar Clase a módulo:", moduleId);
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Título de la clase:");
    if (!title) return;

    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA CREAR CLASE");
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nEdita este contenido.',
        resources: []
      }]);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR AL CREAR CLASE: " + error.message);
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("ERROR AL CREAR CLASE: " + err.message);
    }
  };

  const handleCreateCourse = async () => {
    console.log("🔍 ACCIÓN: Iniciando creación de nuevo Master");
    if (!newCourseData.title.trim()) return;
    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA CREAR MASTER");
      const { error } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title, description: newCourseData.description }]);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("FALLO AL LANZAR MASTER: " + error.message);
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setShowCreateModal(false);
        setNewCourseData({ title: '', description: '' });
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("FALLO AL LANZAR MASTER: " + err.message);
    }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA ACTUALIZAR LECCIÓN ID:", editingLesson.id);
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR AL GUARDAR: " + error.message);
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setNotification({ type: 'success', msg: 'SESIÓN GUARDADA' });
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("ERROR AL GUARDAR: " + err.message);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[1000] px-8 py-4 rounded-3xl border shadow-2xl flex items-center gap-3 backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> VOLVER
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-95"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <BookOpen size={18}/> Currículo
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-40 flex-col gap-6">
            <Loader2 className="animate-spin text-red-600" size={48} />
            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-700">Sincronizando Base de Datos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* PANEL IZQUIERDO: ESTRUCTURA */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Master Hierarchy</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2 shadow-lg shadow-red-600/20 active:scale-95"
                >
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.length === 0 && (
                   <div className="text-center py-20 bg-white/[0.02] rounded-[2rem] border border-dashed border-white/10 opacity-30">
                     <p className="text-[10px] font-black uppercase tracking-widest">Sin cursos activos</p>
                   </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-2xl relative">
                    {/* CABECERA ACORDEÓN */}
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <Layout size={20} className="text-red-600" />
                        <h3 className="font-bold text-sm uppercase tracking-tight text-gray-200">{course.title}</h3>
                      </div>

                      {/* BOTONES DE ACCIÓN (BLINDADOS) */}
                      <div className="flex items-center gap-3">
                        <button 
                          type="button"
                          onClick={(e) => handleAddModule(course.id, e)} 
                          className="text-[8px] bg-white text-black px-4 py-2 rounded-lg font-black uppercase hover:bg-red-600 hover:text-white transition-all shadow-xl z-20"
                        >
                          + MÓDULO
                        </button>
                        <button 
                          type="button"
                          onClick={(e) => handleDeleteCourse(course.id, e)} 
                          className="p-2.5 text-gray-600 hover:text-red-600 bg-white/5 rounded-lg border border-white/5 hover:border-red-600 transition-all z-20"
                        >
                          <Trash2 size={18}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2rem] overflow-hidden shadow-inner relative">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03]"
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <span className="font-bold text-[10px] uppercase text-gray-500 tracking-wider">📦 {mod.title}</span>
                                  <div className="flex items-center gap-3 relative z-30">
                                    <button 
                                      type="button"
                                      onClick={(e) => handleAddLesson(mod.id, e)} 
                                      className="text-[8px] bg-white/5 px-3 py-1 rounded-lg border border-white/10 hover:border-red-600 font-black uppercase"
                                    >
                                      + CLASE
                                    </button>
                                    <button 
                                      type="button"
                                      onClick={(e) => handleDeleteModule(mod.id, e)} 
                                      className="p-1.5 text-gray-700 hover:text-red-500 transition-colors"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/40 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div 
                                        key={l.id} 
                                        className={`flex justify-between items-center p-4 rounded-xl border transition-all cursor-pointer ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600 shadow-[0_0_15px_rgba(239,68,68,0.2)]' : 'bg-black border-white/5 hover:border-red-600/30'}`}
                                        onClick={() => {
                                          console.log("🔍 SELECCIÓN: Editando lección", l.id);
                                          setEditingLesson(l);
                                        }}
                                      >
                                        <div className="text-[10px] font-black uppercase truncate flex-1 text-left text-gray-200">{l.title}</div>
                                        <div className="flex items-center gap-2">
                                          <button 
                                            type="button"
                                            onClick={(e) => { e.stopPropagation(); setEditingLesson(l); }} 
                                            className="p-2 text-gray-700 hover:text-white"
                                          >
                                            <Edit3 size={12}/>
                                          </button>
                                        </div>
                                      </div>
                                    ))}
                                    {(!mod.lessons || mod.lessons.length === 0) && (
                                      <p className="text-[8px] uppercase font-black text-gray-700 text-center py-2 opacity-50">Módulo sin sesiones</p>
                                    )}
                                  </div>
                                )}
                              </div>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* PANEL DERECHO: EDITOR */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Protocolo de Edición</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de Sesión</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 max-h-[55vh] overflow-y-auto pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Título</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">URL Video (Embed)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-mono text-xs outline-none focus:border-red-600 transition-all text-gray-500" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Descripción (MD)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-56 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-[11px] tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98]"
                  >
                    <Save size={22}/> SINCRONIZAR CAMBIOS
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={48} className="mb-10 text-gray-600" />
                  <h3 className="text-3xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-8 uppercase tracking-[0.5em] max-w-xs leading-loose text-center">
                    Selecciona una sesión de la jerarquía lateral para activar los protocolos de edición estratégica.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos Registrados</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 group transition-all hover:border-red-600/20">
                  <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-2xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all shadow-inner">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest mt-1">{s.email}</p>
                    </div>
                  </div>
                  <div className="px-5 py-2 rounded-full text-[8px] font-black uppercase border border-white/5 bg-white/5 text-gray-600 tracking-widest">ACTIVO</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-16 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">MASTER</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>
              <div className="space-y-10">
                <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título del Máster..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Descripción estratégica..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-40 outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner resize-none" />
              </div>
              <button onClick={handleCreateCourse} disabled={!newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3.5rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_rgba(220,38,38,0.3)] active:scale-95 disabled:opacity-50">
                <CheckCircle2 size={24}/> LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layout, PlusCircle, CheckCircle2, AlertCircle, FileText, MoveVertical
} from 'lucide-react';
import { Course, Module, Lesson, User } from '../types';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);
  const [students, setStudents] = useState<User[]>([]);

  useEffect(() => {
    fetchData();
    fetchUserList();
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  async function fetchData() {
    setLoading(true);
    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE: Fetch de estructura completa...");
      const { data, error } = await supabase
        .from('courses')
        .select(`
          id, title, description, created_at,
          modules (
            id, title, course_id,
            lessons (
              id, title, module_id, video_url, description, resources
            )
          )
        `)
        .order('created_at', { ascending: false });

      if (error) {
        console.error("❌ ERROR DE SUPABASE AL CARGAR:", error);
        throw error;
      }

      setCourses(data || []);
      console.log("✅ ACCIÓN EXITOSA: Cursos sincronizados.");
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data: profiles, error: pError } = await supabase.from('profiles').select('*').order('created_at', { ascending: false });
      if (pError) throw pError;

      const { data: progressData } = await supabase.from('user_progress').select('user_id');

      if (profiles) {
        setStudents(profiles.map((p: any) => ({
          id: p.id,
          fullName: p.full_name || 'Sin nombre',
          email: p.email || 'N/A',
          role: p.role || 'student',
          progress: progressData?.filter(pr => pr.user_id === p.id).map(pr => pr.user_id) || []
        })));
      }
    } catch (err: any) {
      console.error("USER_FETCH_ERROR:", err.message);
    }
  }

  // --- ACCIONES CRUD: FUERZA BRUTA PARA DIAGNÓSTICO ---

  const handleDeleteCourse = async (id: string, e: React.MouseEvent) => {
    console.log("🔍 CLICK DETECTADO EN: Eliminar Curso ID:", id);
    e.stopPropagation();
    e.preventDefault();

    if (!window.confirm("⚠️ ¿BORRAR MASTER? Esta acción eliminará permanentemente el curso, sus módulos y sus clases.")) return;

    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA ELIMINAR:", id);
      const { error } = await supabase.from('courses').delete().eq('id', id);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR DE TABLA/POLÍTICA: " + error.message + " (Código: " + error.code + ")");
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setNotification({ type: 'success', msg: 'MASTER ELIMINADO' });
        // Refresh forzado optimista
        setCourses(current => current.filter(c => c.id !== id));
        if (editingLesson?.module_id === id) setEditingLesson(null);
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("EL CÓDIGO FALLÓ ANTES DE LLEGAR A SUPABASE: " + err.message);
    }
  };

  const handleAddModule = async (courseId: string, e: React.MouseEvent) => {
    console.log("🔍 CLICK DETECTADO EN: Agregar Módulo al curso:", courseId);
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Nombre del módulo:");
    if (!title) return;

    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA CREAR MÓDULO");
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR DE TABLA/POLÍTICA: " + error.message + " (Código: " + error.code + ")");
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setNotification({ type: 'success', msg: 'MÓDULO CREADO' });
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("EL CÓDIGO FALLÓ ANTES DE LLEGAR A SUPABASE: " + err.message);
    }
  };

  const handleDeleteModule = async (moduleId: string, e: React.MouseEvent) => {
    console.log("🔍 CLICK DETECTADO EN: Eliminar Módulo ID:", moduleId);
    e.stopPropagation();
    e.preventDefault();

    if (!window.confirm("¿Borrar módulo y sus clases?")) return;

    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA ELIMINAR MÓDULO");
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR: " + error.message);
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setNotification({ type: 'success', msg: 'MÓDULO BORRADO' });
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("ERROR: " + err.message);
    }
  };

  const handleAddLesson = async (moduleId: string, e: React.MouseEvent) => {
    console.log("🔍 CLICK DETECTADO EN: Agregar Clase a módulo:", moduleId);
    e.stopPropagation();
    e.preventDefault();

    const title = window.prompt("Título de la clase:");
    if (!title) return;

    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA CREAR CLASE");
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ',
        description: '# Nueva Clase\nEdita este contenido.',
        resources: []
      }]);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR AL CREAR CLASE: " + error.message);
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("ERROR AL CREAR CLASE: " + err.message);
    }
  };

  const handleCreateCourse = async () => {
    console.log("🔍 ACCIÓN: Iniciando creación de nuevo Master");
    if (!newCourseData.title.trim()) return;
    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA CREAR MASTER");
      const { error } = await supabase
        .from('courses')
        .insert([{ title: newCourseData.title, description: newCourseData.description }]);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("FALLO AL LANZAR MASTER: " + error.message);
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setShowCreateModal(false);
        setNewCourseData({ title: '', description: '' });
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("FALLO AL LANZAR MASTER: " + err.message);
    }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    try {
      console.log("📡 ENVIANDO ORDEN A SUPABASE PARA ACTUALIZAR LECCIÓN ID:", editingLesson.id);
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) {
        console.error("❌ ERROR DE SUPABASE:", error);
        alert("ERROR AL GUARDAR: " + error.message);
      } else {
        console.log("✅ ACCIÓN EXITOSA EN BACKEND");
        setNotification({ type: 'success', msg: 'SESIÓN GUARDADA' });
        await fetchData();
      }
    } catch (err: any) {
      console.error("🚨 ERROR DE EJECUCIÓN FRONTEND:", err);
      alert("ERROR AL GUARDAR: " + err.message);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[1000] px-8 py-4 rounded-3xl border shadow-2xl flex items-center gap-3 backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> VOLVER
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-95"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <BookOpen size={18}/> Currículo
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-40 flex-col gap-6">
            <Loader2 className="animate-spin text-red-600" size={48} />
            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-700">Sincronizando Base de Datos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* PANEL IZQUIERDO: ESTRUCTURA */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Master Hierarchy</h2>
                <button 
                  onClick={() => setShowCreateModal(true)} 
                  className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2 shadow-lg shadow-red-600/20 active:scale-95"
                >
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.length === 0 && (
                   <div className="text-center py-20 bg-white/[0.02] rounded-[2rem] border border-dashed border-white/10 opacity-30">
                     <p className="text-[10px] font-black uppercase tracking-widest">Sin cursos activos</p>
                   </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-2xl relative">
                    {/* CABECERA ACORDEÓN */}
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <Layout size={20} className="text-red-600" />
                        <h3 className="font-bold text-sm uppercase tracking-tight text-gray-200">{course.title}</h3>
                      </div>

                      {/* BOTONES DE ACCIÓN (BLINDADOS) */}
                      <div className="flex items-center gap-3">
                        <button 
                          type="button"
                          onClick={(e) => handleAddModule(course.id, e)} 
                          className="text-[8px] bg-white text-black px-4 py-2 rounded-lg font-black uppercase hover:bg-red-600 hover:text-white transition-all shadow-xl z-20"
                        >
                          + MÓDULO
                        </button>
                        <button 
                          type="button"
                          onClick={(e) => handleDeleteCourse(course.id, e)} 
                          className="p-2.5 text-gray-600 hover:text-red-600 bg-white/5 rounded-lg border border-white/5 hover:border-red-600 transition-all z-20"
                        >
                          <Trash2 size={18}/>
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2rem] overflow-hidden shadow-inner relative">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03]"
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <span className="font-bold text-[10px] uppercase text-gray-500 tracking-wider">📦 {mod.title}</span>
                                  <div className="flex items-center gap-3 relative z-30">
                                    <button 
                                      type="button"
                                      onClick={(e) => handleAddLesson(mod.id, e)} 
                                      className="text-[8px] bg-white/5 px-3 py-1 rounded-lg border border-white/10 hover:border-red-600 font-black uppercase"
                                    >
                                      + CLASE
                                    </button>
                                    <button 
                                      type="button"
                                      onClick={(e) => handleDeleteModule(mod.id, e)} 
                                      className="p-1.5 text-gray-700 hover:text-red-500 transition-colors"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/40 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div 
                                        key={l.id} 
                                        className={`flex justify-between items-center p-4 rounded-xl border transition-all cursor-pointer ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600 shadow-[0_0_15px_rgba(239,68,68,0.2)]' : 'bg-black border-white/5 hover:border-red-600/30'}`}
                                        onClick={() => {
                                          console.log("🔍 SELECCIÓN: Editando lección", l.id);
                                          setEditingLesson(l);
                                        }}
                                      >
                                        <div className="text-[10px] font-black uppercase truncate flex-1 text-left text-gray-200">{l.title}</div>
                                        <div className="flex items-center gap-2">
                                          <button 
                                            type="button"
                                            onClick={(e) => { e.stopPropagation(); setEditingLesson(l); }} 
                                            className="p-2 text-gray-700 hover:text-white"
                                          >
                                            <Edit3 size={12}/>
                                          </button>
                                        </div>
                                      </div>
                                    ))}
                                    {(!mod.lessons || mod.lessons.length === 0) && (
                                      <p className="text-[8px] uppercase font-black text-gray-700 text-center py-2 opacity-50">Módulo sin sesiones</p>
                                    )}
                                  </div>
                                )}
                              </div>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* PANEL DERECHO: EDITOR */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Protocolo de Edición</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de Sesión</h2>
                    </div>
                    <button onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 max-h-[55vh] overflow-y-auto pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Título</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">URL Video (Embed)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-mono text-xs outline-none focus:border-red-600 transition-all text-gray-500" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Descripción (MD)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-56 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none" 
                      />
                    </div>
                  </div>

                  <button 
                    onClick={saveLesson} 
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-[11px] tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98]"
                  >
                    <Save size={22}/> SINCRONIZAR CAMBIOS
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={48} className="mb-10 text-gray-600" />
                  <h3 className="text-3xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-8 uppercase tracking-[0.5em] max-w-xs leading-loose text-center">
                    Selecciona una sesión de la jerarquía lateral para activar los protocolos de edición estratégica.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos Registrados</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 group transition-all hover:border-red-600/20">
                  <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-2xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all shadow-inner">
                      {s.fullName.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.fullName}</p>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest mt-1">{s.email}</p>
                    </div>
                  </div>
                  <div className="px-5 py-2 rounded-full text-[8px] font-black uppercase border border-white/5 bg-white/5 text-gray-600 tracking-widest">ACTIVO</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-16 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">MASTER</span></h3>
                <button onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>
              <div className="space-y-10">
                <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título del Máster..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Descripción estratégica..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-40 outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner resize-none" />
              </div>
              <button onClick={handleCreateCourse} disabled={!newCourseData.title.trim()} className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3.5rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_rgba(220,38,38,0.3)] active:scale-95 disabled:opacity-50">
                <CheckCircle2 size={24}/> LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default AdminPage;

export interface Lesson {
  id: string;
  module_id: string; // Obligatorio para integridad referencial
  title: string;
  video_url: string;
  duration?: string;
  description: string;
  resources: { name: string; url: string }[];
  order_index?: number;
  created_at?: string;
}

export interface Module {
  id: string;
  course_id: string; // Obligatorio
  title: string;
  lessons: Lesson[];
  order_index?: number;
  created_at?: string;
}

export interface Course {
  id: string;
  title: string;
  description: string;
  thumbnail?: string;
  order_index?: number;
  modules: Module[];
  created_at?: string;
}

export interface User {
  id: string;
  email: string;
  role: 'admin' | 'student';
  fullName: string;
  progress: string[];
  last_seen?: string;
  created_at?: string;
}

import React, { useState, useEffect } from 'react';
import { 
  Plus, Trash2, Edit3, ChevronLeft, Save, Users, BookOpen, LogOut, X, Loader2, ChevronDown, Layout, PlusCircle, CheckCircle2, AlertCircle, FileText, MoveVertical
} from 'lucide-react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';
import { Course, Module, Lesson, User } from '../types';

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState<'content' | 'users'>('content');
  const [courses, setCourses] = useState<Course[]>([]);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const [editingLesson, setEditingLesson] = useState<Lesson | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '', description: '' });

  const [loading, setLoading] = useState(true);
  const [processingId, setProcessingId] = useState<string | null>(null); // Para mostrar loading en botones específicos
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);
  const [students, setStudents] = useState<any[]>([]);

  useEffect(() => {
    fetchData();
    fetchUserList();
  }, []);

  useEffect(() => {
    if (notification) {
      const timer = setTimeout(() => setNotification(null), 4000);
      return () => clearTimeout(timer);
    }
  }, [notification]);

  // --- LECTURA DE DATOS ---

  async function fetchData() {
    setLoading(true);
    try {
      console.log("🔄 ADMIN: Sincronizando estructura...");
      const { data, error } = await supabase
        .from('courses')
        .select(`
          id, title, description, created_at,
          modules (
            id, title, course_id,
            lessons (
              id, title, module_id, video_url, description, resources
            )
          )
        `)
        .order('created_at', { ascending: false });

      if (error) {
        console.error("❌ ERROR FETCH:", error);
        throw error;
      }

      // Ordenamiento manual para asegurar jerarquía visual correcta
      const sortedData = data?.map((c: any) => ({
        ...c,
        modules: c.modules?.sort((a: any, b: any) => a.title.localeCompare(b.title))
      })) || [];

      setCourses(sortedData as Course[]);
    } catch (err: any) {
      console.error("ADMIN LOAD ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  async function fetchUserList() {
    try {
      const { data } = await supabase.from('profiles').select('*');
      if (data) setStudents(data);
    } catch (err) { console.error(err); }
  }

  // --- ESCRITURA BLINDADA (CRUD) ---

  const verifySession = async () => {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) {
      alert("⚠️ SESIÓN EXPIRADA. Por favor recarga la página.");
      return false;
    }
    return true;
  };

  const handleDeleteCourse = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation(); // DETIENE EL EVENTO AQUÍ
    if (!await verifySession()) return;
    if (!window.confirm("🔴 ¿BORRAR MASTER COMPLETO?\nEsta acción es irreversible.")) return;

    setProcessingId(id);
    console.log(`🔥 BORRANDO CURSO ${id}...`);

    try {
      const { error } = await supabase.from('courses').delete().eq('id', id);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MASTER ELIMINADO' });
      setCourses(prev => prev.filter(c => c.id !== id));
    } catch (err: any) {
      alert(`ERROR: ${err.message}`);
    } finally {
      setProcessingId(null);
    }
  };

  const handleAddModule = async (courseId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!await verifySession()) return;

    const title = window.prompt("Nombre del NUEVO MÓDULO:");
    if (!title) return;

    setProcessingId(`add-mod-${courseId}`);
    try {
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MÓDULO AGREGADO' });
      await fetchData();
    } catch (err: any) {
      alert(`ERROR: ${err.message}`);
    } finally {
      setProcessingId(null);
    }
  };

  const handleDeleteModule = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!await verifySession()) return;
    if (!window.confirm("¿Eliminar módulo y su contenido?")) return;

    try {
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'MÓDULO BORRADO' });
      await fetchData();
    } catch (err: any) {
      alert(`ERROR: ${err.message}`);
    }
  };

  const handleAddLesson = async (moduleId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!await verifySession()) return;

    const title = window.prompt("Título de la NUEVA CLASE:");
    if (!title) return;

    setProcessingId(`add-lesson-${moduleId}`);
    try {
      const { error } = await supabase.from('lessons').insert([{
        module_id: moduleId,
        title,
        video_url: 'https://www.youtube.com/embed/dQw4w9WgXcQ', // Placeholder
        description: '# Nueva Clase\nAgrega tu descripción aquí.',
        resources: []
      }]);
      if (error) throw error;

      setNotification({ type: 'success', msg: 'CLASE CREADA' });
      await fetchData();
    } catch (err: any) {
      alert(`ERROR: ${err.message}`);
    } finally {
      setProcessingId(null);
    }
  };

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return;
    if (!await verifySession()) return;

    setProcessingId('create-course');
    try {
      const { error } = await supabase.from('courses').insert([{
        title: newCourseData.title,
        description: newCourseData.description
      }]);
      if (error) throw error;

      setShowCreateModal(false);
      setNewCourseData({ title: '', description: '' });
      setNotification({ type: 'success', msg: 'MASTER CREADO EXITOSAMENTE' });
      await fetchData();
    } catch (err: any) {
      alert(`ERROR: ${err.message}`);
    } finally {
      setProcessingId(null);
    }
  };

  const saveLesson = async () => {
    if (!editingLesson) return;
    if (!await verifySession()) return;

    setProcessingId('save-lesson');
    try {
      const { error } = await supabase.from('lessons').update({
        title: editingLesson.title,
        video_url: editingLesson.video_url,
        description: editingLesson.description,
        resources: editingLesson.resources
      }).eq('id', editingLesson.id);

      if (error) throw error;

      setNotification({ type: 'success', msg: 'CAMBIOS GUARDADOS' });
      await fetchData();
    } catch (err: any) {
      alert(`ERROR GUARDANDO: ${err.message}`);
    } finally {
      setProcessingId(null);
    }
  };

  // --- RENDER ---

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div 
            initial={{ opacity: 0, y: -50, x: '-50%' }}
            animate={{ opacity: 1, y: 0, x: '-50%' }}
            exit={{ opacity: 0, y: -50, x: '-50%' }}
            className={`fixed top-10 left-1/2 z-[1000] px-8 py-4 rounded-3xl border shadow-2xl flex items-center gap-3 backdrop-blur-xl ${
              notification.type === 'success' ? 'bg-green-600/20 border-green-500/30 text-green-400' : 'bg-red-600/20 border-red-500/30 text-red-400'
            }`}
          >
            {notification.type === 'success' ? <CheckCircle2 size={18}/> : <AlertCircle size={18}/>}
            <span className="text-[10px] font-black uppercase tracking-widest">{notification.msg}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <nav className="border-b border-white/5 px-8 py-6 flex justify-between items-center bg-black/90 sticky top-0 z-50 backdrop-blur-2xl">
        <div className="flex items-center gap-8">
          <Link to="/dashboard" className="flex items-center gap-2 text-gray-500 hover:text-white transition-all font-black text-[10px] uppercase tracking-[0.3em] group">
            <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform"/> VOLVER
          </Link>
          <div className="h-6 w-px bg-white/10" />
          <h1 className="text-xl font-black tracking-tighter uppercase italic select-none">EZEH <span className="text-red-600">ADMIN</span></h1>
        </div>
        <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 bg-white/5 rounded-xl border border-white/5 transition-all active:scale-95"><LogOut size={20}/></button>
      </nav>

      <div className="max-w-7xl mx-auto p-6 lg:p-12 pb-32">
        <div className="flex gap-4 mb-16">
          <button onClick={() => setActiveTab('content')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'content' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <BookOpen size={18}/> Currículo
          </button>
          <button onClick={() => setActiveTab('users')} className={`px-12 py-6 rounded-2xl font-black text-[10px] uppercase tracking-[0.3em] border transition-all flex items-center gap-4 ${activeTab === 'users' ? 'bg-white text-black shadow-2xl' : 'bg-white/5 text-gray-500 border-white/5'}`}>
            <Users size={18}/> Alumnos
          </button>
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-40 flex-col gap-6">
            <Loader2 className="animate-spin text-red-600" size={48} />
            <p className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-700">Sincronizando Base de Datos...</p>
          </div>
        ) : activeTab === 'content' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

            {/* --- LISTA DE CURSOS (HIERARCHY) --- */}
            <div className="lg:col-span-5 space-y-6">
              <div className="flex justify-between items-center px-4">
                <h2 className="text-[10px] font-black text-gray-600 uppercase tracking-widest">Master Hierarchy</h2>
                <button 
                  type="button"
                  onClick={() => setShowCreateModal(true)} 
                  className="p-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-all flex items-center gap-2 shadow-lg shadow-red-600/20 active:scale-95"
                >
                  <PlusCircle size={18} /> <span className="text-[9px] font-black uppercase">Nuevo Master</span>
                </button>
              </div>

              <div className="space-y-4">
                {courses.length === 0 && (
                   <div className="text-center py-20 bg-white/[0.02] rounded-[2rem] border border-dashed border-white/10 opacity-30">
                     <p className="text-[10px] font-black uppercase tracking-widest">Sin cursos activos</p>
                   </div>
                )}
                {courses.map((course) => (
                  <div key={course.id} className="bg-[#0a0a0a] border border-white/5 rounded-[2rem] overflow-hidden shadow-2xl relative">
                    <div 
                      className="p-8 flex items-center justify-between cursor-pointer group hover:bg-white/[0.02]" 
                      onClick={() => {
                        const next = new Set(expandedCourses);
                        if (next.has(course.id)) next.delete(course.id); else next.add(course.id);
                        setExpandedCourses(next);
                      }}
                    >
                      <div className="flex items-center gap-5">
                        <Layout size={20} className="text-red-600" />
                        <h3 className="font-bold text-sm uppercase tracking-tight text-gray-200">{course.title}</h3>
                      </div>

                      <div className="flex items-center gap-3">
                        <button 
                          type="button" 
                          onClick={(e) => handleAddModule(course.id, e)} 
                          className="text-[8px] bg-white text-black px-4 py-2 rounded-lg font-black uppercase hover:bg-red-600 hover:text-white transition-all shadow-xl z-20"
                        >
                          {processingId === `add-mod-${course.id}` ? <Loader2 size={12} className="animate-spin"/> : '+ MÓDULO'}
                        </button>
                        <button 
                          type="button"
                          onClick={(e) => handleDeleteCourse(course.id, e)} 
                          className="p-2.5 text-gray-600 hover:text-red-600 bg-white/5 rounded-lg border border-white/5 hover:border-red-600 transition-all z-20"
                        >
                          {processingId === course.id ? <Loader2 size={14} className="animate-spin text-red-600"/> : <Trash2 size={18}/>}
                        </button>
                        <ChevronDown size={22} className={`text-gray-700 transition-transform duration-300 ${expandedCourses.has(course.id) ? 'rotate-180 text-white' : ''}`} />
                      </div>
                    </div>

                    <AnimatePresence>
                      {expandedCourses.has(course.id) && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-white/[0.01]">
                          <div className="p-8 space-y-6">
                            {course.modules?.map((mod) => (
                              <div key={mod.id} className="border border-white/5 bg-black/40 rounded-[2rem] overflow-hidden shadow-inner relative">
                                <div 
                                  className="p-5 flex items-center justify-between cursor-pointer hover:bg-white/[0.03]"
                                  onClick={() => {
                                    const next = new Set(expandedModules);
                                    if (next.has(mod.id)) next.delete(mod.id); else next.add(mod.id);
                                    setExpandedModules(next);
                                  }}
                                >
                                  <span className="font-bold text-[10px] uppercase text-gray-500 tracking-wider">📦 {mod.title}</span>
                                  <div className="flex items-center gap-3 relative z-30">
                                    <button 
                                      type="button"
                                      onClick={(e) => handleAddLesson(mod.id, e)} 
                                      className="text-[8px] bg-white/5 px-3 py-1 rounded-lg border border-white/10 hover:border-red-600 font-black uppercase flex items-center gap-2"
                                    >
                                      {processingId === `add-lesson-${mod.id}` ? <Loader2 size={10} className="animate-spin"/> : '+ CLASE'}
                                    </button>
                                    <button 
                                      type="button"
                                      onClick={(e) => handleDeleteModule(mod.id, e)} 
                                      className="p-1.5 text-gray-700 hover:text-red-500 transition-colors"
                                    >
                                      <Trash2 size={14}/>
                                    </button>
                                  </div>
                                </div>

                                {expandedModules.has(mod.id) && (
                                  <div className="p-4 bg-black/40 border-t border-white/5 space-y-2">
                                    {mod.lessons?.map(l => (
                                      <div 
                                        key={l.id} 
                                        className={`flex justify-between items-center p-4 rounded-xl border transition-all cursor-pointer ${editingLesson?.id === l.id ? 'bg-red-600 border-red-600 shadow-[0_0_15px_rgba(239,68,68,0.2)]' : 'bg-black border-white/5 hover:border-red-600/30'}`}
                                        onClick={() => setEditingLesson(l)}
                                      >
                                        <div className="text-[10px] font-black uppercase truncate flex-1 text-left text-gray-200">{l.title}</div>
                                        <div className="flex items-center gap-2">
                                          <button 
                                            type="button"
                                            onClick={(e) => { e.stopPropagation(); setEditingLesson(l); }} 
                                            className="p-2 text-gray-700 hover:text-white"
                                          >
                                            <Edit3 size={12}/>
                                          </button>
                                        </div>
                                      </div>
                                    ))}
                                    {(!mod.lessons || mod.lessons.length === 0) && (
                                      <p className="text-[8px] uppercase font-black text-gray-700 text-center py-2 opacity-50">Módulo sin sesiones</p>
                                    )}
                                  </div>
                                )}
                              </div>
                            ))}
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </div>
                ))}
              </div>
            </div>

            {/* --- EDITOR (PANEL DERECHO) --- */}
            <div className="lg:col-span-7">
              {editingLesson ? (
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-[#0a0a0a] border border-white/10 rounded-[4rem] p-12 space-y-10 sticky top-32 shadow-2xl">
                  <div className="flex justify-between items-center border-b border-white/5 pb-8">
                    <div>
                      <p className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-2">Protocolo de Edición</p>
                      <h2 className="text-3xl font-black italic uppercase tracking-tighter leading-none">Ajuste de Sesión</h2>
                    </div>
                    <button type="button" onClick={() => setEditingLesson(null)} className="p-4 bg-white/5 rounded-2xl hover:bg-white/10 border border-white/5 transition-all"><X size={24}/></button>
                  </div>

                  <div className="space-y-8 max-h-[55vh] overflow-y-auto pr-4 custom-scrollbar">
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Título</label>
                      <input 
                        type="text" 
                        value={editingLesson.title} 
                        onChange={e => setEditingLesson({...editingLesson, title: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-bold text-lg focus:border-red-600 outline-none transition-all" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">URL Video (Embed)</label>
                      <input 
                        type="text" 
                        value={editingLesson.video_url} 
                        onChange={e => setEditingLesson({...editingLesson, video_url: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-7 font-mono text-xs outline-none focus:border-red-600 transition-all text-gray-500" 
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[9px] font-black uppercase text-gray-600 ml-5 tracking-widest">Descripción (Markdown)</label>
                      <textarea 
                        value={editingLesson.description} 
                        onChange={e => setEditingLesson({...editingLesson, description: e.target.value})} 
                        className="w-full bg-black border border-white/5 rounded-3xl p-8 h-56 text-sm leading-relaxed focus:border-red-600 outline-none transition-all resize-none" 
                      />
                    </div>
                  </div>

                  <button 
                    type="button"
                    onClick={saveLesson} 
                    disabled={processingId === 'save-lesson'}
                    className="w-full bg-red-600 py-8 rounded-[2.5rem] font-black uppercase text-[11px] tracking-[0.4em] flex items-center justify-center gap-4 transition-all hover:bg-red-700 shadow-2xl shadow-red-600/30 active:scale-[0.98] disabled:opacity-50"
                  >
                    {processingId === 'save-lesson' ? <Loader2 className="animate-spin"/> : <Save size={22}/>} SINCRONIZAR CAMBIOS
                  </button>
                </motion.div>
              ) : (
                <div className="h-full border-2 border-dashed border-white/5 rounded-[5rem] flex flex-col items-center justify-center text-center p-20 opacity-20 select-none bg-white/[0.01]">
                  <MoveVertical size={48} className="mb-10 text-gray-600" />
                  <h3 className="text-3xl font-black uppercase tracking-[0.4em] italic leading-tight">MANDO <span className="text-red-600">CENTRAL</span></h3>
                  <p className="text-[11px] font-bold text-gray-700 mt-8 uppercase tracking-[0.5em] max-w-xs leading-loose text-center">
                    Selecciona una sesión de la jerarquía lateral para activar los protocolos de edición estratégica.
                  </p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-[#0a0a0a] border border-white/5 rounded-[3.5rem] p-12 shadow-2xl">
            <h2 className="text-3xl font-black uppercase italic tracking-tighter mb-12">Alumnos Registrados</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {students.map(s => (
                <div key={s.id} className="flex items-center justify-between p-8 bg-white/[0.02] rounded-[2.5rem] border border-white/5 group transition-all hover:border-red-600/20">
                  <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-red-600/20 rounded-2xl flex items-center justify-center text-red-600 font-black text-2xl border border-red-600/20 group-hover:bg-red-600 group-hover:text-white transition-all shadow-inner">
                      {s.full_name?.charAt(0) || 'U'}
                    </div>
                    <div>
                      <p className="text-sm font-black uppercase tracking-tight">{s.full_name || 'Usuario'}</p>
                      <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest mt-1">{s.email || 'Sin email'}</p>
                    </div>
                  </div>
                  <div className="px-5 py-2 rounded-full text-[8px] font-black uppercase border border-white/5 bg-white/5 text-gray-600 tracking-widest">ACTIVO</div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* MODAL DE CREACIÓN */}
      <AnimatePresence>
        {showCreateModal && (
          <div className="fixed inset-0 z-[600] flex items-center justify-center p-6">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowCreateModal(false)} className="absolute inset-0 bg-black/95 backdrop-blur-xl" />
            <motion.div initial={{ scale: 0.9, opacity: 0, y: 30 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.9, opacity: 0, y: 30 }} className="relative w-full max-w-xl bg-[#0d0d0d] border border-white/10 rounded-[4rem] p-16 shadow-2xl">
              <div className="flex justify-between items-center mb-16">
                <h3 className="text-4xl font-black italic uppercase tracking-tighter leading-none">NUEVO <span className="text-red-600">MASTER</span></h3>
                <button type="button" onClick={() => setShowCreateModal(false)} className="p-4 bg-white/5 rounded-2xl border border-white/5 hover:text-red-600 transition-all"><X size={24}/></button>
              </div>
              <div className="space-y-10">
                <input type="text" autoFocus value={newCourseData.title} onChange={e => setNewCourseData({...newCourseData, title: e.target.value})} placeholder="Título del Máster..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 font-black text-2xl outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner" />
                <textarea value={newCourseData.description} onChange={e => setNewCourseData({...newCourseData, description: e.target.value})} placeholder="Descripción estratégica..." className="w-full bg-black border border-white/5 rounded-[2.5rem] p-8 text-sm h-40 outline-none focus:border-red-600 transition-all placeholder:text-gray-800 shadow-inner resize-none" />
              </div>
              <button 
                type="button"
                onClick={handleCreateCourse} 
                disabled={!newCourseData.title.trim() || processingId === 'create-course'} 
                className="w-full mt-16 bg-red-600 text-white py-8 rounded-[3.5rem] font-black uppercase text-xs tracking-[0.5em] flex items-center justify-center gap-6 transition-all shadow-[0_20px_50px_rgba(220,38,38,0.3)] active:scale-95 disabled:opacity-50"
              >
                {processingId === 'create-course' ? <Loader2 className="animate-spin" /> : <CheckCircle2 size={24}/>} LANZAR ESTRUCTURA
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

