import React, { useState, useEffect } from 'react';
import { 
  Trash2, LogOut, ChevronDown, Layout, PlusCircle, Box, Video, X, MousePointerClick
} from 'lucide-react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

const AdminPage = ({ onLogout }: { onLogout: () => void }) => {
  const [courses, setCourses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '' });
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => { fetchData(); }, []);

  async function fetchData() {
    setLoading(true);
    const { data, error } = await supabase
      .from('courses')
      .select('*, modules(*, lessons(*))') 
      .order('created_at', { ascending: false });

    if (error) console.error("❌ ERROR:", error);
    else {
      // Ordenamiento seguro para evitar errores si no hay fechas
      const sortedData = data?.map(course => ({
        ...course,
        modules: course.modules?.sort((a: any, b: any) => (a.created_at || '').localeCompare(b.created_at || ''))
      }));
      setCourses(sortedData || []);
    }
    setLoading(false);
  }

  // --- ACCIONES CRUD (SIN INTERFERENCIAS) ---

  const handleDeleteCourse = async (id: string) => {
    // Nota: Ya no pasamos 'e' porque el botón está aislado
    if (!window.confirm("⚠️ ¿ELIMINAR MASTER?")) return;

    const { error } = await supabase.from('courses').delete().eq('id', id);
    if (error) alert(error.message);
    else {
      setCourses(prev => prev.filter(c => c.id !== id));
      showNotify('success', 'MASTER ELIMINADO');
    }
  };

  const handleAddModule = async (courseId: string) => {
    const title = window.prompt("Nombre del Nuevo Módulo:");
    if (!title) return;

    const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);
    if (error) alert(error.message);
    else {
      showNotify('success', 'MÓDULO CREADO');
      fetchData();
    }
  };

  const handleDeleteModule = async (moduleId: string) => {
    if (!window.confirm("¿Eliminar este módulo?")) return;

    const { error } = await supabase.from('modules').delete().eq('id', moduleId);
    if (error) alert(error.message);
    else {
      showNotify('success', 'MÓDULO BORRADO');
      fetchData();
    }
  };

  const handleAddLesson = async (moduleId: string) => {
    const title = window.prompt("Título de la Clase:");
    if (!title) return;

    const { error } = await supabase.from('lessons').insert([{ 
      title, 
      module_id: moduleId,
      description: 'Pendiente...'
    }]);

    if (error) alert(error.message);
    else {
      showNotify('success', 'CLASE AÑADIDA');
      fetchData();
    }
  };

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return;
    const { error } = await supabase.from('courses').insert([{ title: newCourseData.title }]);
    if (error) alert(error.message);
    else {
      setShowCreateModal(false);
      setNewCourseData({ title: '' });
      fetchData();
      showNotify('success', 'MASTER CREADO');
    }
  };

  const showNotify = (type: 'success'|'error', msg: string) => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  const toggleCourse = (id: string) => {
    const next = new Set(expandedCourses);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedCourses(next);
  };

  if (loading) return <div className="min-h-screen bg-black flex items-center justify-center text-red-600 font-bold uppercase tracking-[0.5em]">Sincronizando...</div>;

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans p-8 selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div initial={{ y: -100 }} animate={{ y: 0 }} exit={{ y: -100 }} className="fixed top-6 left-1/2 -translate-x-1/2 z-[9999] bg-zinc-800 border border-red-600/50 px-8 py-4 rounded-2xl font-black shadow-[0_0_30px_rgba(220,38,38,0.3)]">
             <span className="text-red-500">●</span> {notification.msg}
          </motion.div>
        )}
      </AnimatePresence>

      <div className="max-w-6xl mx-auto pb-40">
        <nav className="flex justify-between items-center mb-16 border-b border-white/5 pb-8">
            <h1 className="text-4xl font-black italic tracking-tighter">EZEH <span className="text-red-600">ADMIN</span></h1>
            <button onClick={onLogout} className="text-zinc-600 hover:text-white transition-colors"><LogOut size={24}/></button>
        </nav>

        <div className="flex justify-between items-end mb-10">
            <div>
                <h2 className="text-xs font-bold text-zinc-500 uppercase tracking-[0.3em] mb-2">Panel de Control</h2>
                <p className="text-2xl font-bold text-white">Estructura Académica</p>
            </div>
            <button onClick={() => setShowCreateModal(true)} className="px-8 py-4 bg-red-600 hover:bg-red-700 rounded-[1.5rem] font-black uppercase tracking-widest transition-all shadow-lg shadow-red-900/20 active:scale-95 flex items-center gap-3">
                <PlusCircle size={20}/> Nuevo Master
            </button>
        </div>

        <div className="space-y-12">
          {courses.map((course) => (
            <div key={course.id} className="bg-[#0a0a0a] border border-white/10 rounded-[3rem] overflow-hidden shadow-2xl relative">

              {/* --- ZONA SUPERIOR: CONTENEDOR FLEXIBLE --- */}
              <div className="p-10 flex items-center justify-between">

                {/* ZONA 1: CLIC PARA ABRIR (SOLO TÍTULO E ICONO) */}
                <div 
                  className="flex items-center gap-8 cursor-pointer group"
                  onClick={() => toggleCourse(course.id)}
                >
                    <div className="w-16 h-16 bg-red-600/10 rounded-2xl flex items-center justify-center text-red-600 border border-red-600/10 group-hover:bg-red-600 group-hover:text-white transition-all">
                        {expandedCourses.has(course.id) ? <ChevronDown size={32}/> : <Layout size={32}/>}
                    </div>
                    <div>
                        <h3 className="font-black text-2xl uppercase italic tracking-tight group-hover:text-red-500 transition-colors">{course.title}</h3>
                        <div className="flex items-center gap-2 mt-2">
                           <MousePointerClick size={12} className="text-zinc-600"/>
                           <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.2em]">Clic para ver contenido</p>
                        </div>
                    </div>
                </div>

                {/* ZONA 2: BOTONES DE ACCIÓN (TOTALMENTE SEPARADOS DEL CLICK DE APERTURA) */}
                <div className="flex items-center gap-4">
                  <button 
                    onClick={() => handleAddModule(course.id)}
                    className="bg-white text-black px-6 py-3 rounded-xl font-black text-[10px] uppercase hover:bg-zinc-200 transition-all shadow-lg tracking-widest active:scale-95"
                  >
                    + Módulo
                  </button>
                  <button 
                    onClick={() => handleDeleteCourse(course.id)}
                    className="p-3 text-zinc-700 hover:text-red-500 bg-black rounded-xl border border-white/5 transition-all hover:border-red-600/30 active:scale-95"
                  >
                    <Trash2 size={20}/>
                  </button>
                </div>
              </div>

              {/* LISTA DE MÓDULOS */}
              <AnimatePresence>
                {expandedCourses.has(course.id) && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-zinc-900/30">
                    <div className="p-10 space-y-6">
                      {course.modules?.map((mod: any) => (
                         <div key={mod.id} className="bg-black border border-white/5 rounded-[2rem] overflow-hidden">
                            {/* CABECERA MÓDULO */}
                            <div className="p-6 flex justify-between items-center border-b border-white/5 bg-white/[0.02]">
                                <div className="flex items-center gap-4">
                                    <Box size={18} className="text-zinc-500"/>
                                    <span className="font-black text-sm text-zinc-200 uppercase tracking-wide">{mod.title}</span>
                                </div>
                                <div className="flex items-center gap-3">
                                    <button 
                                        onClick={() => handleAddLesson(mod.id)}
                                        className="text-[9px] bg-red-600/10 text-red-500 border border-red-600/20 px-4 py-2 rounded-lg font-black uppercase hover:bg-red-600 hover:text-white transition-all"
                                    >
                                        + Clase
                                    </button>
                                    <button 
                                        onClick={() => handleDeleteModule(mod.id)}
                                        className="text-zinc-600 hover:text-red-500 p-2"
                                    >
                                        <Trash2 size={16}/>
                                    </button>
                                </div>
                            </div>

                            {/* LECCIONES */}
                            <div className="p-4 space-y-2">
                                {mod.lessons?.map((lesson: any) => (
                                    <div key={lesson.id} className="flex items-center gap-4 p-4 rounded-xl hover:bg-white/5 transition-colors group cursor-pointer border border-transparent hover:border-white/5">
                                        <div className="p-2 bg-zinc-900 rounded-lg text-zinc-600 group-hover:text-red-500 transition-colors">
                                            <Video size={16}/>
                                        </div>
                                        <span className="text-xs font-bold text-zinc-400 group-hover:text-white transition-colors uppercase">{lesson.title}</span>
                                    </div>
                                ))}
                                {(!mod.lessons || mod.lessons.length === 0) && (
                                    <div className="py-2 text-center text-[9px] text-zinc-700 font-bold uppercase tracking-widest opacity-50">Vacío</div>
                                )}
                            </div>
                         </div>
                      ))}
                      {(!course.modules || course.modules.length === 0) && (
                          <div className="text-center py-8 text-zinc-600 font-black uppercase text-xs tracking-widest">Sin Módulos</div>
                      )}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          ))}
        </div>
      </div>

      {showCreateModal && (
        <div className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-xl flex items-center justify-center p-6">
            <div className="bg-[#0a0a0a] p-16 rounded-[4rem] w-full max-w-2xl border border-white/10 shadow-2xl relative">
                <button onClick={() => setShowCreateModal(false)} className="absolute top-10 right-10 p-4 bg-white/5 rounded-full hover:bg-red-600 hover:text-white transition-all"><X/></button>
                <h2 className="text-4xl font-black italic uppercase mb-10 tracking-tighter">Crear <span className="text-red-600">Master</span></h2>
                <input autoFocus type="text" onChange={e => setNewCourseData({title: e.target.value})} className="w-full bg-black border border-white/10 p-8 rounded-[2rem] text-white font-black text-xl outline-none focus:border-red-600 transition-all mb-8" placeholder="NOMBRE..."/>
                <button onClick={handleCreateCourse} className="w-full bg-red-600 py-6 rounded-[2.5rem] font-black uppercase tracking-[0.2em] hover:bg-red-700 transition-all">Crear</button>
            </div>
        </div>
      )}
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect } from 'react';
import { 
  Trash2, LogOut, ChevronDown, Layout, PlusCircle, Box, Video, X, MousePointerClick
} from 'lucide-react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';

const AdminPage = ({ onLogout }: { onLogout: () => void }) => {
  const [courses, setCourses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newCourseData, setNewCourseData] = useState({ title: '' });
  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => { fetchData(); }, []);

  async function fetchData() {
    setLoading(true);
    console.log("🔥 INICIANDO ACCIÓN: fetchData (Sincronización)");

    try {
      const { data, error } = await supabase
        .from('courses')
        .select('*, modules(*, lessons(*))') 
        .order('created_at', { ascending: false });

      if (error) throw error;

      // Ordenamiento seguro
      const sortedData = data?.map(course => ({
        ...course,
        modules: course.modules?.sort((a: any, b: any) => (a.created_at || '').localeCompare(b.created_at || ''))
      }));
      setCourses(sortedData || []);
    } catch (error: any) {
      console.error("❌ ERROR FETCH:", error);
      // No usamos alert aquí para no bloquear la carga inicial, pero logueamos fuerte
    } finally {
      setLoading(false);
    }
  }

  // --- HELPER DE NOTIFICACIÓN ---
  const showNotify = (type: 'success'|'error', msg: string) => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  // --- ACCIONES CRUD BLINDADAS (TRIPLE VERIFICACIÓN) ---

  const handleDeleteCourse = async (id: string) => {
    if (!window.confirm("⚠️ ¿ELIMINAR MASTER? Esta acción es irreversible.")) return;

    // 1. Aviso de Inicio
    console.log("🔥 INICIANDO ACCIÓN: handleDeleteCourse");
    setNotification({ type: 'success', msg: "⏳ Procesando eliminación..." });

    try {
      // 2. Bloque Try/Catch con Await explícito
      const { error } = await supabase.from('courses').delete().eq('id', id);

      if (error) throw error;

      // 4. Confirmación de Éxito
      setCourses(prev => prev.filter(c => c.id !== id));
      showNotify('success', '✅ MASTER ELIMINADO');

    } catch (error: any) {
      // 3. Manejo de Error Ruidoso
      console.error("❌ ERROR EN handleDeleteCourse:", error);
      alert("❌ ERROR FATAL: " + error.message);
      showNotify('error', 'Error crítico al eliminar');
    }
  };

  const handleAddModule = async (courseId: string) => {
    const title = window.prompt("Nombre del Nuevo Módulo:");
    if (!title) return;

    // 1. Aviso de Inicio
    console.log("🔥 INICIANDO ACCIÓN: handleAddModule");
    setNotification({ type: 'success', msg: "⏳ Creando módulo..." });

    try {
      // 2. Bloque Try/Catch con Await explícito
      const { error } = await supabase.from('modules').insert([{ title, course_id: courseId }]);

      if (error) throw error;

      // 4. Confirmación de Éxito
      showNotify('success', '✅ MÓDULO CREADO');
      await fetchData(); // Recargamos para ver el orden correcto

    } catch (error: any) {
      // 3. Manejo de Error Ruidoso
      console.error("❌ ERROR EN handleAddModule:", error);
      alert("❌ ERROR FATAL: " + error.message);
      showNotify('error', 'Error crítico al crear módulo');
    }
  };

  const handleDeleteModule = async (moduleId: string) => {
    if (!window.confirm("¿Eliminar este módulo y sus clases?")) return;

    // 1. Aviso de Inicio
    console.log("🔥 INICIANDO ACCIÓN: handleDeleteModule");
    setNotification({ type: 'success', msg: "⏳ Eliminando módulo..." });

    try {
      // 2. Bloque Try/Catch con Await explícito
      const { error } = await supabase.from('modules').delete().eq('id', moduleId);

      if (error) throw error;

      // 4. Confirmación de Éxito
      showNotify('success', '✅ MÓDULO BORRADO');
      await fetchData();

    } catch (error: any) {
      // 3. Manejo de Error Ruidoso
      console.error("❌ ERROR EN handleDeleteModule:", error);
      alert("❌ ERROR FATAL: " + error.message);
      showNotify('error', 'Error crítico al borrar módulo');
    }
  };

  const handleAddLesson = async (moduleId: string) => {
    const title = window.prompt("Título de la Clase:");
    if (!title) return;

    // 1. Aviso de Inicio
    console.log("🔥 INICIANDO ACCIÓN: handleAddLesson");
    setNotification({ type: 'success', msg: "⏳ Añadiendo clase..." });

    try {
      // 2. Bloque Try/Catch con Await explícito
      const { error } = await supabase.from('lessons').insert([{ 
        title, 
        module_id: moduleId,
        description: '# Nueva Clase\nContenido pendiente.',
        video_url: 'https://www.youtube.com/embed/placeholder'
      }]);

      if (error) throw error;

      // 4. Confirmación de Éxito
      showNotify('success', '✅ CLASE AÑADIDA');
      await fetchData();

    } catch (error: any) {
      // 3. Manejo de Error Ruidoso
      console.error("❌ ERROR EN handleAddLesson:", error);
      alert("❌ ERROR FATAL: " + error.message);
      showNotify('error', 'Error crítico al añadir clase');
    }
  };

  const handleCreateCourse = async () => {
    if (!newCourseData.title.trim()) return;

    // 1. Aviso de Inicio
    console.log("🔥 INICIANDO ACCIÓN: handleCreateCourse");
    setNotification({ type: 'success', msg: "⏳ Creando Master..." });

    try {
      // 2. Bloque Try/Catch con Await explícito
      const { error } = await supabase.from('courses').insert([{ title: newCourseData.title }]);

      if (error) throw error;

      // 4. Confirmación de Éxito
      setShowCreateModal(false);
      setNewCourseData({ title: '' });
      showNotify('success', '✅ MASTER CREADO');
      await fetchData();

    } catch (error: any) {
      // 3. Manejo de Error Ruidoso
      console.error("❌ ERROR EN handleCreateCourse:", error);
      alert("❌ ERROR FATAL: " + error.message);
      showNotify('error', 'Error crítico al crear Master');
    }
  };

  const toggleCourse = (id: string) => {
    const next = new Set(expandedCourses);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedCourses(next);
  };

  if (loading) return <div className="min-h-screen bg-black flex items-center justify-center text-red-600 font-bold uppercase tracking-[0.5em]">Sincronizando...</div>;

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans p-8 selection:bg-red-600">
      <AnimatePresence>
        {notification && (
          <motion.div initial={{ y: -100 }} animate={{ y: 0 }} exit={{ y: -100 }} className="fixed top-6 left-1/2 -translate-x-1/2 z-[9999] bg-zinc-800 border border-red-600/50 px-8 py-4 rounded-2xl font-black shadow-[0_0_30px_rgba(220,38,38,0.3)]">
             <span className="text-red-500">●</span> {notification.msg}
          </motion.div>
        )}
      </AnimatePresence>

      <div className="max-w-6xl mx-auto pb-40">
        <nav className="flex justify-between items-center mb-16 border-b border-white/5 pb-8">
            <h1 className="text-4xl font-black italic tracking-tighter">EZEH <span className="text-red-600">ADMIN</span></h1>
            <button onClick={onLogout} className="text-zinc-600 hover:text-white transition-colors"><LogOut size={24}/></button>
        </nav>

        <div className="flex justify-between items-end mb-10">
            <div>
                <h2 className="text-xs font-bold text-zinc-500 uppercase tracking-[0.3em] mb-2">Panel de Control</h2>
                <p className="text-2xl font-bold text-white">Estructura Académica</p>
            </div>
            <button onClick={() => setShowCreateModal(true)} className="px-8 py-4 bg-red-600 hover:bg-red-700 rounded-[1.5rem] font-black uppercase tracking-widest transition-all shadow-lg shadow-red-900/20 active:scale-95 flex items-center gap-3">
                <PlusCircle size={20}/> Nuevo Master
            </button>
        </div>

        <div className="space-y-12">
          {courses.map((course) => (
            <div key={course.id} className="bg-[#0a0a0a] border border-white/10 rounded-[3rem] overflow-hidden shadow-2xl relative">

              {/* --- ZONA SUPERIOR: CONTENEDOR FLEXIBLE --- */}
              <div className="p-10 flex items-center justify-between">

                {/* ZONA 1: CLIC PARA ABRIR (SOLO TÍTULO E ICONO) */}
                <div 
                  className="flex items-center gap-8 cursor-pointer group"
                  onClick={() => toggleCourse(course.id)}
                >
                    <div className="w-16 h-16 bg-red-600/10 rounded-2xl flex items-center justify-center text-red-600 border border-red-600/10 group-hover:bg-red-600 group-hover:text-white transition-all">
                        {expandedCourses.has(course.id) ? <ChevronDown size={32}/> : <Layout size={32}/>}
                    </div>
                    <div>
                        <h3 className="font-black text-2xl uppercase italic tracking-tight group-hover:text-red-500 transition-colors">{course.title}</h3>
                        <div className="flex items-center gap-2 mt-2">
                           <MousePointerClick size={12} className="text-zinc-600"/>
                           <p className="text-zinc-600 text-[10px] font-bold uppercase tracking-[0.2em]">Clic para ver contenido</p>
                        </div>
                    </div>
                </div>

                {/* ZONA 2: BOTONES DE ACCIÓN (TOTALMENTE SEPARADOS DEL CLICK DE APERTURA) */}
                <div className="flex items-center gap-4">
                  <button 
                    type="button"
                    onClick={() => handleAddModule(course.id)}
                    className="bg-white text-black px-6 py-3 rounded-xl font-black text-[10px] uppercase hover:bg-zinc-200 transition-all shadow-lg tracking-widest active:scale-95"
                  >
                    + Módulo
                  </button>
                  <button 
                    type="button"
                    onClick={() => handleDeleteCourse(course.id)}
                    className="p-3 text-zinc-700 hover:text-red-500 bg-black rounded-xl border border-white/5 transition-all hover:border-red-600/30 active:scale-95"
                  >
                    <Trash2 size={20}/>
                  </button>
                </div>
              </div>

              {/* LISTA DE MÓDULOS */}
              <AnimatePresence>
                {expandedCourses.has(course.id) && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden border-t border-white/5 bg-zinc-900/30">
                    <div className="p-10 space-y-6">
                      {course.modules?.map((mod: any) => (
                         <div key={mod.id} className="bg-black border border-white/5 rounded-[2rem] overflow-hidden">
                            {/* CABECERA MÓDULO */}
                            <div className="p-6 flex justify-between items-center border-b border-white/5 bg-white/[0.02]">
                                <div className="flex items-center gap-4">
                                    <Box size={18} className="text-zinc-500"/>
                                    <span className="font-black text-sm text-zinc-200 uppercase tracking-wide">{mod.title}</span>
                                </div>
                                <div className="flex items-center gap-3">
                                    <button 
                                        type="button"
                                        onClick={() => handleAddLesson(mod.id)}
                                        className="text-[9px] bg-red-600/10 text-red-500 border border-red-600/20 px-4 py-2 rounded-lg font-black uppercase hover:bg-red-600 hover:text-white transition-all"
                                    >
                                        + Clase
                                    </button>
                                    <button 
                                        type="button"
                                        onClick={() => handleDeleteModule(mod.id)}
                                        className="text-zinc-600 hover:text-red-500 p-2"
                                    >
                                        <Trash2 size={16}/>
                                    </button>
                                </div>
                            </div>

                            {/* LECCIONES */}
                            <div className="p-4 space-y-2">
                                {mod.lessons?.map((lesson: any) => (
                                    <div key={lesson.id} className="flex items-center gap-4 p-4 rounded-xl hover:bg-white/5 transition-colors group cursor-pointer border border-transparent hover:border-white/5">
                                        <div className="p-2 bg-zinc-900 rounded-lg text-zinc-600 group-hover:text-red-500 transition-colors">
                                            <Video size={16}/>
                                        </div>
                                        <span className="text-xs font-bold text-zinc-400 group-hover:text-white transition-colors uppercase">{lesson.title}</span>
                                    </div>
                                ))}
                                {(!mod.lessons || mod.lessons.length === 0) && (
                                    <div className="py-2 text-center text-[9px] text-zinc-700 font-bold uppercase tracking-widest opacity-50">Vacío</div>
                                )}
                            </div>
                         </div>
                      ))}
                      {(!course.modules || course.modules.length === 0) && (
                          <div className="text-center py-8 text-zinc-600 font-black uppercase text-xs tracking-widest">Sin Módulos</div>
                      )}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          ))}
        </div>
      </div>

      {showCreateModal && (
        <div className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-xl flex items-center justify-center p-6">
            <div className="bg-[#0a0a0a] p-16 rounded-[4rem] w-full max-w-2xl border border-white/10 shadow-2xl relative">
                <button onClick={() => setShowCreateModal(false)} className="absolute top-10 right-10 p-4 bg-white/5 rounded-full hover:bg-red-600 hover:text-white transition-all"><X/></button>
                <h2 className="text-4xl font-black italic uppercase mb-10 tracking-tighter">Crear <span className="text-red-600">Master</span></h2>
                <input autoFocus type="text" onChange={e => setNewCourseData({title: e.target.value})} className="w-full bg-black border border-white/10 p-8 rounded-[2rem] text-white font-black text-xl outline-none focus:border-red-600 transition-all mb-8" placeholder="NOMBRE..."/>
                <button type="button" onClick={handleCreateCourse} className="w-full bg-red-600 py-6 rounded-[2.5rem] font-black uppercase tracking-[0.2em] hover:bg-red-700 transition-all">Crear</button>
            </div>
        </div>
      )}
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Play, CheckCircle, Menu, X, FileText, LogOut, ExternalLink, Bookmark, Star, RefreshCw, AlertCircle, Check
} from 'lucide-react';
import { User, Module, Lesson, Course } from '../types.ts';
import { Link } from 'react-router-dom';
import { marked } from 'marked';
import { supabase } from '../lib/supabase.ts';
import VideoPlayer from '../components/VideoPlayer.tsx';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [course, setCourse] = useState<Course | null>(null);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [progress, setProgress] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [rating, setRating] = useState(0);

  useEffect(() => {
    fetchInitialData();
  }, []);

  async function fetchInitialData() {
    setLoading(true);
    try {
      console.log("Dashboard: Fetching data via manual joins...");

      // 1. Fetch Course
      const { data: courses, error: courseError } = await supabase
        .from('courses')
        .select('*')
        .limit(1);

      if (courseError) throw courseError;

      if (!courses || courses.length === 0) {
        setCourse(null);
        setLoading(false);
        return;
      }

      const mainCourse = courses[0];

      // 2. Fetch Modules manually (bypass relationship check)
      const { data: modules, error: modulesError } = await supabase
        .from('modules')
        .select('*')
        .eq('course_id', mainCourse.id)
        .order('created_at', { ascending: true });

      if (modulesError) throw modulesError;

      // 3. Fetch Lessons manually
      let allLessons: any[] = [];
      if (modules && modules.length > 0) {
        const moduleIds = modules.map((m: any) => m.id);
        const { data: lessons, error: lessonsError } = await supabase
          .from('lessons')
          .select('*')
          .in('module_id', moduleIds)
          .order('created_at', { ascending: true });

        if (lessonsError) throw lessonsError;
        allLessons = lessons || [];
      }

      // 4. Reconstruct Hierarchy
      const modulesWithLessons = modules?.map((mod: any) => ({
        ...mod,
        lessons: allLessons.filter((l: any) => l.module_id === mod.id)
      })) || [];

      const fullCourse: Course = {
        ...mainCourse,
        modules: modulesWithLessons
      };

      setCourse(fullCourse);

      // 5. Set Active Lesson
      if (modulesWithLessons.length > 0 && modulesWithLessons[0].lessons.length > 0) {
        setActiveLesson(modulesWithLessons[0].lessons[0]);
      }

      // 6. Fetch Progress
      const { data: progressData, error: progressError } = await supabase
        .from('user_progress')
        .select('lesson_id')
        .eq('user_id', user.id);

      if (!progressError && progressData) {
        setProgress(progressData.map((p: any) => p.lesson_id));
      }

    } catch (err: any) {
      console.error("DASHBOARD_ERROR:", err.message);
    } finally {
      setLoading(false);
    }
  }

  const onToggleProgress = async (lessonId: string) => {
    try {
      if (progress.includes(lessonId)) {
        // Uncomplete
        const { error } = await supabase.from('user_progress').delete().eq('user_id', user.id).eq('lesson_id', lessonId);
        if (error) throw error;
        setProgress(prev => prev.filter(id => id !== lessonId));
      } else {
        // Complete
        const { error } = await supabase.from('user_progress').insert({ user_id: user.id, lesson_id: lessonId });
        if (error) throw error;
        setProgress(prev => [...prev, lessonId]);
      }
    } catch (e: any) {
      console.error("Progress Error:", e.message);
      // Optional: alert user
    }
  };

  const progressPercent = useMemo(() => {
    if (!course || !course.modules) return 0;
    const allLessons = course.modules.flatMap(m => m.lessons || []);
    if (allLessons.length === 0) return 0;
    return Math.round((progress.length / allLessons.length) * 100);
  }, [course, progress]);

  const htmlDescription = useMemo(() => activeLesson ? marked.parse(activeLesson.description || '') : '', [activeLesson]);

  if (loading) {
    return (
      <div className="min-h-screen bg-[#050505] flex flex-col items-center justify-center gap-6">
        <div className="w-16 h-16 border-4 border-red-600 border-t-transparent rounded-full animate-spin shadow-[0_0_30px_rgba(239,68,68,0.3)]" />
        <div className="text-center">
          <p className="text-[10px] font-black uppercase tracking-[0.5em] text-red-600 animate-pulse italic">Cargando Academia</p>
          <p className="text-gray-600 text-[8px] mt-2 font-bold uppercase tracking-widest">Estableciendo conexión estratégica...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#050505] text-white flex flex-col selection:bg-red-600 font-sans">
      <nav className="fixed top-0 w-full z-50 bg-black/60 backdrop-blur-2xl border-b border-white/5 px-6 py-4 flex justify-between items-center">
        <div className="flex items-center gap-6">
          <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2.5 hover:bg-white/10 rounded-xl transition-all border border-transparent hover:border-white/5">
            {isSidebarOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
          <div className="text-2xl font-black italic tracking-tighter flex items-center gap-2 uppercase select-none">
            <span className="text-red-600">EZEH</span> ACADEMY
          </div>
        </div>

        <div className="flex items-center gap-8">
          <div className="hidden md:flex flex-col items-end gap-1.5">
            <div className="flex items-center gap-3">
              <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-500">Avance del Master</span>
              <span className="text-xs font-bold text-red-500">{progressPercent}%</span>
            </div>
            <div className="w-48 h-1.5 bg-white/5 rounded-full overflow-hidden">
              <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} className="h-full bg-red-600 shadow-[0_0_15px_#ef4444]" />
            </div>
          </div>

          <div className="flex items-center gap-4">
            {user.role === 'admin' && (
              <Link to="/admin" className="p-2.5 text-gray-500 hover:text-white transition-all bg-white/5 rounded-xl border border-white/5 hover:border-red-600/30">
                <Bookmark size={20} />
              </Link>
            )}
            <button onClick={onLogout} className="p-2.5 text-gray-500 hover:text-red-600 transition-colors bg-white/5 rounded-xl border border-white/5 hover:border-red-600/30">
              <LogOut size={18}/>
            </button>
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-red-600 to-red-900 flex items-center justify-center font-black border border-white/20 shadow-2xl shadow-red-600/20">
              {user.fullName?.charAt(0)}
            </div>
          </div>
        </div>
      </nav>

      <div className="flex flex-1 pt-[72px] h-screen overflow-hidden">
        <AnimatePresence>
          {isSidebarOpen && (
            <motion.aside initial={{ x: -350, opacity: 0 }} animate={{ x: 0, opacity: 1 }} exit={{ x: -350, opacity: 0 }} className="w-full lg:w-[360px] bg-[#080808] border-r border-white/5 overflow-y-auto custom-scrollbar flex-shrink-0">
              <div className="p-8 pb-32">
                {course ? (
                  <>
                    <div className="mb-12">
                      <h2 className="text-[9px] font-black text-gray-600 uppercase tracking-[0.4em] mb-4">Currículo del Master</h2>
                      <h1 className="text-sm font-black uppercase italic tracking-tighter text-white leading-tight">{course.title}</h1>
                    </div>

                    {course.modules && course.modules.length > 0 ? (
                      course.modules.map((mod, i) => (
                        <div key={mod.id} className="mb-10">
                          <div className="flex items-center gap-3 mb-4">
                             <span className="text-[8px] font-black text-red-600 uppercase bg-red-600/10 px-2 py-0.5 rounded border border-red-600/20">MOD {i + 1}</span>
                             <h3 className="text-xs font-black uppercase tracking-[0.1em] text-gray-400 truncate">{mod.title}</h3>
                          </div>
                          <div className="space-y-2 ml-1 border-l border-white/5 pl-5 py-1">
                            {mod.lessons && mod.lessons.map(l => (
                              <button 
                                key={l.id} 
                                onClick={() => setActiveLesson(l)} 
                                className={`w-full text-left p-4 rounded-2xl text-[11px] font-bold transition-all flex items-center justify-between group border ${activeLesson?.id === l.id ? 'bg-white/10 text-white border-white/10 shadow-2xl' : 'text-gray-500 hover:bg-white/5 border-transparent'}`}
                              >
                                <span className="uppercase tracking-tighter pr-4 break-words flex-1 leading-normal group-hover:text-white transition-colors">
                                  {l.title}
                                </span>
                                <div 
                                  onClick={(e) => { e.stopPropagation(); onToggleProgress(l.id); }} 
                                  className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${progress.includes(l.id) ? 'bg-green-600 text-white shadow-lg shadow-green-600/20 scale-110' : 'bg-white/5 text-white/20 border border-white/10 group-hover:border-white/30'}`}
                                >
                                  {progress.includes(l.id) ? <Check size={14} strokeWidth={3} /> : <CheckCircle size={14} />}
                                </div>
                              </button>
                            ))}
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="py-20 text-center px-4">
                        <AlertCircle size={32} className="mx-auto text-gray-800 mb-4" />
                        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-700">Contenido en preparación.</p>
                      </div>
                    )}
                  </>
                ) : (
                  <div className="py-24 text-center">
                    <RefreshCw className="animate-spin mx-auto text-red-600 mb-6" size={32} />
                    <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-30">Cargando formación...</p>
                  </div>
                )}
              </div>
            </motion.aside>
          )}
        </AnimatePresence>

        <main className="flex-1 overflow-y-scroll bg-black p-4 lg:p-12 custom-scrollbar relative">
          {activeLesson ? (
            <div className="max-w-6xl mx-auto pb-40">
              <div className="mb-14 group/player relative">
                <div className="absolute -inset-1 bg-gradient-to-r from-red-600 to-red-900 rounded-[1.8rem] blur opacity-10 group-hover/player:opacity-20 transition duration-1000"></div>
                <div className="relative">
                   <VideoPlayer url={activeLesson.video_url} title={activeLesson.title} />
                </div>
              </div>

              <div className="flex flex-col md:flex-row items-start md:items-end justify-between gap-10 mb-12 border-b border-white/5 pb-12">
                <div className="flex-1">
                  <span className="text-[10px] font-black text-red-600 uppercase tracking-[0.4em] mb-3 block">Sesión Activa</span>
                  <h1 className="text-3xl lg:text-4xl font-black italic tracking-tighter uppercase break-words leading-[0.9]">
                    {activeLesson.title}
                  </h1>
                </div>

                <div className="flex flex-col items-start md:items-end gap-3 bg-white/5 p-6 rounded-3xl border border-white/5">
                  <span className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-500">Valoración de Clase</span>
                  <div className="flex gap-1.5">
                    {[1, 2, 3, 4, 5].map((star) => (
                      <button key={star} onClick={() => setRating(star)} className="outline-none transform active:scale-90 transition-transform">
                        <Star size={22} fill={star <= rating ? "#FFD700" : "none"} className={`transition-colors ${star <= rating ? "text-yellow-400 drop-shadow-[0_0_10px_rgba(255,215,0,0.5)]" : "text-gray-800"}`} />
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-20">
                <div className="lg:col-span-8">
                  <h3 className="text-xl font-black uppercase tracking-tighter italic mb-8 flex items-center gap-4">
                    <span className="w-8 h-px bg-red-600"></span> Resumen Estratégico
                  </h3>
                  <div className="prose prose-invert max-w-none prose-p:text-gray-400 prose-p:text-lg prose-headings:text-white leading-relaxed" 
                       dangerouslySetInnerHTML={{ __html: htmlDescription }} />
                </div>

                <div className="lg:col-span-4">
                  <div className="bg-[#080808] border border-white/5 rounded-[2.5rem] p-8 lg:p-10 sticky top-8">
                    <h3 className="text-lg font-black uppercase tracking-tighter italic mb-8 flex items-center gap-3">
                      <FileText size={20} className="text-red-600" /> Materiales
                    </h3>

                    <div className="space-y-4">
                      {activeLesson.resources && activeLesson.resources.length > 0 ? (
                        activeLesson.resources.map((r, i) => (
                          <motion.a key={i} href={r.url} target="_blank" rel="noopener noreferrer" whileHover={{ x: 5 }} className="flex items-center gap-4 p-5 bg-white/5 border border-white/10 rounded-2xl transition-all group hover:border-red-600/50">
                            <div className="w-10 h-10 bg-black rounded-xl flex items-center justify-center group-hover:bg-red-600/10 transition-colors">
                              <FileText size={18} className="text-gray-500 group-hover:text-red-600 transition-colors" />
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="text-[11px] font-black uppercase tracking-tighter truncate text-gray-200">{r.name}</p>
                              <p className="text-[9px] text-gray-600 font-bold uppercase mt-1">Descargar</p>
                            </div>
                            <ExternalLink size={14} className="text-gray-800 group-hover:text-red-600 transition-colors" />
                          </motion.a>
                        ))
                      ) : (
                        <div className="text-center py-12 border border-dashed border-white/5 rounded-3xl opacity-20">
                           <p className="text-[9px] font-black uppercase tracking-[0.2em]">Sin archivos adjuntos</p>
                        </div>
                      )}
                    </div>

                    <button 
                      onClick={() => onToggleProgress(activeLesson.id)} 
                      className={`w-full mt-10 py-5 rounded-2xl font-black uppercase text-[10px] tracking-[0.2em] transition-all flex items-center justify-center gap-3 ${progress.includes(activeLesson.id) ? 'bg-green-600/10 text-green-500 border border-green-600/20' : 'bg-red-600 hover:bg-red-700 text-white shadow-2xl shadow-red-600/20'}`}
                    >
                      {progress.includes(activeLesson.id) ? (
                        <><Check size={16} strokeWidth={3}/> Clase Completada</>
                      ) : (
                        'Marcar Finalizada'
                      )}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-center p-20 select-none">
               <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="relative mb-14">
                  <div className="absolute inset-0 bg-red-600/20 blur-[120px] rounded-full animate-pulse" />
                  <div className="relative w-40 h-40 bg-white/5 rounded-[3rem] flex items-center justify-center border border-white/10 rotate-12">
                    <Play size={64} className="text-white/5 ml-3 -rotate-12" />
                  </div>
               </motion.div>
               <h3 className="text-4xl font-black uppercase tracking-[0.4em] italic leading-tight text-white/50">
                 CENTRAL DE <span className="text-red-600">FORMACIÓN</span>
               </h3>
               <p className="text-[11px] font-bold text-gray-700 mt-8 uppercase tracking-[0.5em] max-w-sm leading-relaxed">
                 Selecciona un módulo del currículo lateral para comenzar tu transformación digital.
               </p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase'; // Asegúrate que esta ruta es correcta

interface AdminProps {
  onLogout: () => void;
}

const AdminPage: React.FC<AdminProps> = ({ onLogout }) => {
  const [courses, setCourses] = useState<any[]>([]);
  const [newTitle, setNewTitle] = useState('');
  const [status, setStatus] = useState('Esperando...');

  // 1. CARGAR CURSOS AL INICIO
  useEffect(() => {
    fetchCourses();
  }, []);

  const fetchCourses = async () => {
    const { data, error } = await supabase.from('courses').select('*').order('created_at', { ascending: false });
    if (error) setStatus('ERROR CARGA: ' + error.message);
    else setCourses(data || []);
  };

  // 2. LA PRUEBA DE FUEGO: CREAR CURSO
  const handleCreateCourse = async () => {
    if (!newTitle) return alert("Escribe un título");

    setStatus('⏳ ENVIANDO A SUPABASE...');
    console.log("INTENTANDO CREAR:", newTitle);

    try {
      const { data, error } = await supabase
        .from('courses')
        .insert([{ title: newTitle, description: 'Creado desde el Bunker' }])
        .select();

      if (error) {
        setStatus('❌ ERROR FATAL: ' + error.message);
        alert('ERROR: ' + error.message);
      } else {
        setStatus('✅ ÉXITO: CURSO CREADO');
        setNewTitle(''); // Limpiar input
        fetchCourses(); // Recargar lista
      }
    } catch (err: any) {
      setStatus('🚨 ERROR DE CÓDIGO: ' + err.message);
    }
  };

  const handleDelete = async (id: string) => {
      if(!confirm("¿Borrar?")) return;
      const { error } = await supabase.from('courses').delete().eq('id', id);
      if(error) alert(error.message);
      else fetchCourses();
  }

  return (
    <div style={{ padding: '50px', background: '#000', minHeight: '100vh', color: 'white', fontFamily: 'monospace' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h1 style={{ color: 'red', fontSize: '30px' }}>PANEL DE PRUEBA DE CONEXIÓN</h1>
          <button onClick={onLogout} style={{ padding: '8px 16px', background: '#222', color: '#fff', border: '1px solid #444', cursor: 'pointer' }}>SALIR</button>
      </div>

      {/* ZONA DE ESTADO */}
      <div style={{ border: '1px solid yellow', padding: '10px', margin: '20px 0', color: 'yellow' }}>
        ESTADO: {status}
      </div>

      {/* ZONA DE CREACIÓN */}
      <div style={{ background: '#111', padding: '20px', border: '1px solid #333' }}>
        <input 
          type="text" 
          value={newTitle}
          onChange={(e) => setNewTitle(e.target.value)}
          placeholder="NOMBRE DEL CURSO..."
          style={{ padding: '10px', width: '300px', marginRight: '10px', color: 'black' }}
        />
        <button 
          onClick={handleCreateCourse}
          style={{ padding: '10px 20px', background: 'red', color: 'white', border: 'none', cursor: 'pointer', fontWeight: 'bold' }}
        >
          CREAR CURSO (TEST)
        </button>
      </div>

      {/* LISTA DE RESULTADOS */}
      <div style={{ marginTop: '30px' }}>
        <h2>CURSOS EN BASE DE DATOS ({courses.length})</h2>
        {courses.map(c => (
          <div key={c.id} style={{ borderBottom: '1px solid #333', padding: '10px', display: 'flex', justifyContent: 'space-between' }}>
            <span>{c.title} (ID: {c.id})</span>
            <button onClick={() => handleDelete(c.id)} style={{color:'red'}}>BORRAR</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect } from 'react';
import { 
  Play, FileText, ChevronDown, CheckCircle, Lock, LogOut, Menu, X, Download, ExternalLink, Zap
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';
import { Link } from 'react-router-dom';
import { User } from '../types';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [courses, setCourses] = useState<any[]>([]);
  const [activeLesson, setActiveLesson] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true); // Para móvil/desktop
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  useEffect(() => {
    fetchData();
  }, []);

  async function fetchData() {
    setLoading(true);
    // 1. Traemos la misma estructura que en el Admin
    const { data, error } = await supabase
      .from('courses')
      .select('*, modules(*, lessons(*))')
      .order('created_at', { ascending: true }); // Ordenamos cronológicamente para el alumno

    if (!error && data) {
      // Ordenar módulos y lecciones
      const sorted = data.map(c => ({
        ...c,
        modules: c.modules?.sort((a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())
          .map((m: any) => ({
             ...m,
             lessons: m.lessons?.sort((x: any, y: any) => new Date(x.created_at).getTime() - new Date(y.created_at).getTime())
          }))
      }));
      setCourses(sorted);

      // Auto-seleccionar la primera lección del primer curso si existe
      if (sorted.length > 0 && sorted[0].modules?.[0]?.lessons?.[0]) {
        setActiveLesson(sorted[0].modules[0].lessons[0]);
        setExpandedModules(new Set([sorted[0].modules[0].id])); // Expandir primer módulo
      }
    }
    setLoading(false);
  }

  const toggleModule = (id: string) => {
    const next = new Set(expandedModules);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedModules(next);
  };

  if (loading) return <div className="min-h-screen bg-black flex items-center justify-center text-white font-bold tracking-widest uppercase">Cargando tu Academia...</div>;

  if (courses.length === 0) return (
