import React, { useState, useEffect } from 'react';
import { 
  Trash2, LogOut, ChevronDown, Layout, Box, Video, X, Plus, FileText, Link as LinkIcon, Save, PlusCircle, Upload, CheckCircle, Loader2, LayoutDashboard, ArrowLeft
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';
import { Link } from 'react-router-dom';

const AdminPage = ({ onLogout }: { onLogout: () => void }) => {
  const [courses, setCourses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());

  // ESTADOS MODALES
  const [modalType, setModalType] = useState<'NONE' | 'COURSE' | 'MODULE' | 'LESSON'>('NONE');
  const [tempId, setTempId] = useState<string>(''); 
  const [inputTitle, setInputTitle] = useState('');

  // DATOS LECCIÓN + ESTADO DE SUBIDA
  const [lessonData, setLessonData] = useState({ 
    title: '', video_url: '', description: '', resources: '' 
  });
  const [uploading, setUploading] = useState(false); // Estado para el spinner de carga

  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => { fetchData(); }, []);

  async function fetchData() {
    setLoading(true);
    const { data, error } = await supabase
      .from('courses')
      .select('*, modules(*, lessons(*))') 
      .order('created_at', { ascending: false });

    if (!error && data) {
      const sorted = data.map(c => ({
        ...c,
        modules: c.modules?.sort((a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())
          .map((m: any) => ({
             ...m,
             lessons: m.lessons?.sort((x: any, y: any) => new Date(x.created_at).getTime() - new Date(y.created_at).getTime())
          }))
      }));
      setCourses(sorted);
    }
    setLoading(false);
  }

  // --- FUNCIÓN DE SUBIDA DE ARCHIVOS (CORE) ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;

    const file = e.target.files[0];
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random()}.${fileExt}`;
    const filePath = `${fileName}`;

    setUploading(true); // Activar spinner

    try {
      // 1. Subir al Bucket 'course_materials'
      const { error: uploadError } = await supabase.storage
        .from('course_materials')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // 2. Obtener URL Pública
      const { data } = supabase.storage.from('course_materials').getPublicUrl(filePath);

      // 3. Guardar URL en el estado (sin borrar lo anterior si quisieras multiples, pero aqui reemplaza)
      setLessonData(prev => ({ ...prev, resources: data.publicUrl }));
      showNotify('success', 'ARCHIVO SUBIDO CORRECTAMENTE');

    } catch (error: any) {
      alert("Error subiendo archivo: " + error.message);
    } finally {
      setUploading(false); // Apagar spinner
    }
  };

  // --- APERTURA MODALES ---
  const openCreateCourse = () => { setModalType('COURSE'); setInputTitle(''); };
  const openCreateModule = (courseId: string) => { setTempId(courseId); setModalType('MODULE'); setInputTitle(''); };
  const openCreateLesson = (moduleId: string) => {
    setTempId(moduleId);
    setModalType('LESSON');
    setLessonData({ title: '', video_url: '', description: '', resources: '' });
  };
  const closeModal = () => { setModalType('NONE'); setTempId(''); setInputTitle(''); };

  // --- SUBMITS ---
  const submitCreateCourse = async () => {
    if (!inputTitle.trim()) return;
    const { error } = await supabase.from('courses').insert([{ title: inputTitle }]);
    if (!error) { closeModal(); fetchData(); showNotify('success', 'MASTER CREADO'); } 
    else alert(error.message);
  };

  const submitCreateModule = async () => {
    if (!inputTitle.trim()) return;
    const { error } = await supabase.from('modules').insert([{ title: inputTitle, course_id: tempId }]);
    if (!error) { closeModal(); fetchData(); showNotify('success', 'MÓDULO CREADO'); }
    else alert(error.message);
  };

  const submitCreateLesson = async () => {
    if (!lessonData.title.trim()) return alert("Título obligatorio");
    const { error } = await supabase.from('lessons').insert([{ 
      title: lessonData.title, 
      module_id: tempId,
      video_url: lessonData.video_url,
      description: lessonData.description,
      resources: lessonData.resources // Aquí va la URL del archivo subido
    }]);

    if (!error) { closeModal(); fetchData(); showNotify('success', 'CLASE GUARDADA'); }
    else alert(error.message);
  };

  const handleDelete = async (table: 'courses'|'modules'|'lessons', id: string) => {
    if (!window.confirm("¿Eliminar elemento?")) return;
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (!error) {
      if (table === 'courses') setCourses(prev => prev.filter(c => c.id !== id));
      else fetchData();
      showNotify('success', 'ELIMINADO');
    } else alert(error.message);
  };

  // --- UTILS ---
  const toggleCourse = (id: string) => {
    const next = new Set(expandedCourses);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedCourses(next);
  };

  const showNotify = (type: 'success'|'error', msg: string) => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  if (loading) return <div className="min-h-screen bg-black flex items-center justify-center text-red-600 font-bold uppercase tracking-widest">Cargando Panel...</div>;

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans p-8 selection:bg-red-600 selection:text-white">
      <AnimatePresence>
        {notification && (
          <motion.div initial={{ y: -100 }} animate={{ y: 0 }} exit={{ y: -100 }} className="fixed top-6 left-1/2 -translate-x-1/2 z-[9999] bg-zinc-800 border border-red-600/50 px-6 py-3 rounded-xl font-bold shadow-2xl flex items-center gap-2">
             <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse"/> {notification.msg}
          </motion.div>
        )}
      </AnimatePresence>

      <div className="max-w-6xl mx-auto pb-40">
        <nav className="flex justify-between items-center mb-10 border-b border-white/5 pb-6">
            <h1 className="text-3xl font-black italic tracking-tighter">EZEH <span className="text-red-600">ADMIN</span></h1>

            <div className="flex items-center gap-4">
                {/* BOTÓN VOLVER A ACADEMIA */}
                <Link to="/dashboard" className="flex items-center gap-2 px-6 py-3 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 hover:border-red-600/50 transition-all text-[10px] font-black uppercase tracking-widest text-zinc-300 hover:text-white group">
                    <LayoutDashboard size={14} className="text-zinc-500 group-hover:text-red-600 transition-colors"/>
                    Volver a Academia
                </Link>

                <div className="w-px h-8 bg-white/10 mx-2 hidden sm:block"></div>

                <button onClick={onLogout} className="flex items-center gap-2 px-4 py-3 rounded-xl bg-zinc-900/50 border border-transparent hover:border-white/10 hover:bg-zinc-800 text-[10px] font-black uppercase tracking-widest text-zinc-500 hover:text-white transition-all">
                    <LogOut size={14}/>
                    <span className="hidden sm:inline">Salir</span>
                </button>
            </div>
        </nav>

        <div className="mb-10 text-right">
            <button onClick={openCreateCourse} className="px-8 py-4 bg-red-600 hover:bg-red-700 rounded-[1.5rem] font-black uppercase tracking-widest shadow-lg shadow-red-900/20 active:scale-95 transition-all flex items-center gap-2 ml-auto">
                <PlusCircle size={20}/> Nuevo Master
            </button>
        </div>

        <div className="space-y-8">
          {courses.map((course) => (
            <div key={course.id} className="bg-[#0a0a0a] border border-white/10 rounded-[2.5rem] overflow-hidden shadow-2xl relative">
              <div className="p-8 flex items-center justify-between hover:bg-white/[0.01] transition-colors">
                <div className="flex items-center gap-6 cursor-pointer group select-none flex-1" onClick={() => toggleCourse(course.id)}>
                    <div className="w-14 h-14 bg-red-600/10 rounded-2xl flex items-center justify-center text-red-600 group-hover:bg-red-600 group-hover:text-white transition-all border border-red-600/10">
                        {expandedCourses.has(course.id) ? <ChevronDown/> : <Layout/>}
                    </div>
                    <div>
                        <h3 className="font-black text-xl uppercase italic group-hover:text-red-500 transition-colors tracking-tight">{course.title}</h3>
                        <p className="text-[10px] text-zinc-500 uppercase tracking-widest mt-1">{course.modules?.length || 0} Módulos</p>
                    </div>
                </div>
                <div className="flex items-center gap-3 pl-6 border-l border-white/5">
                  <button onClick={() => openCreateModule(course.id)} className="bg-white text-black px-5 py-2.5 rounded-xl font-black text-[10px] uppercase hover:bg-zinc-200 transition-all shadow-lg active:scale-95">+ Módulo</button>
                  <button onClick={() => handleDelete('courses', course.id)} className="p-3 text-zinc-600 hover:text-red-500 bg-zinc-900 rounded-xl border border-white/5 hover:border-red-600/50 transition-all active:scale-95"><Trash2 size={18}/></button>
                </div>
              </div>

              <AnimatePresence>
                {expandedCourses.has(course.id) && (
                  <motion.div initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} className="overflow-hidden bg-zinc-900/20 border-t border-white/5">
                    <div className="p-8 space-y-4">
                      {course.modules?.map((mod: any) => (
                         <div key={mod.id} className="bg-black border border-white/5 rounded-3xl overflow-hidden">
                            <div className="p-5 flex justify-between items-center bg-white/[0.02] border-b border-white/5">
                                <div className="flex items-center gap-4">
                                    <Box size={18} className="text-zinc-500"/>
                                    <span className="font-black text-sm text-zinc-300 uppercase tracking-wide">{mod.title}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button onClick={() => openCreateLesson(mod.id)} className="text-[9px] bg-red-600/10 text-red-500 px-4 py-2 rounded-lg border border-red-600/20 hover:bg-red-600 hover:text-white transition-all font-black uppercase flex items-center gap-2"><Plus size={10}/> Clase</button>
                                    <button onClick={() => handleDelete('modules', mod.id)} className="text-zinc-600 hover:text-red-500 p-2 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            </div>
                            <div className="p-2 bg-[#050505]">
                                {mod.lessons?.map((l: any) => (
                                    <div key={l.id} className="flex items-center justify-between p-4 rounded-2xl hover:bg-white/5 transition-all group border border-transparent hover:border-white/5">
                                        <div className="flex items-center gap-4">
                                            <div className="p-2 bg-zinc-900 rounded-lg text-zinc-600 group-hover:text-red-500 transition-colors"><Video size={14}/></div>
                                            <div>
                                                <span className="text-xs font-bold text-zinc-400 group-hover:text-white uppercase block transition-colors">{l.title}</span>
                                                {l.resources && <span className="text-[9px] text-green-500 flex items-center gap-1 mt-1"><FileText size={8}/> Archivo Adjunto</span>}
                                            </div>
                                        </div>
                                        <button onClick={() => handleDelete('lessons', l.id)} className="opacity-0 group-hover:opacity-100 text-zinc-600 hover:text-red-500 p-2 transition-all"><Trash2 size={14}/></button>
                                    </div>
                                ))}
                                {!mod.lessons?.length && <div className="text-[9px] text-zinc-700 text-center py-4 uppercase font-bold tracking-widest opacity-50">Módulo sin contenido</div>}
                            </div>
                         </div>
                      ))}
                      {!course.modules?.length && <div className="text-center text-xs text-zinc-600 uppercase font-black tracking-widest py-4 border-2 border-dashed border-white/5 rounded-2xl">Añade el primer módulo</div>}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          ))}
        </div>
      </div>

      {/* --- MODAL CREAR CURSO --- */}
      {modalType === 'COURSE' && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center p-6">
            <div className="bg-[#0f0f0f] p-10 rounded-[3rem] w-full max-w-lg border border-white/10 relative shadow-2xl">
                <button onClick={closeModal} className="absolute top-8 right-8 text-zinc-500 hover:text-white transition-colors"><X/></button>
                <h2 className="text-3xl font-black italic uppercase mb-8">Nuevo <span className="text-red-600">Master</span></h2>
                <input autoFocus type="text" onChange={e => setInputTitle(e.target.value)} className="w-full bg-black border border-white/10 p-6 rounded-2xl text-white font-bold outline-none focus:border-red-600 mb-6 placeholder:text-zinc-800 transition-colors" placeholder="NOMBRE DEL MASTER..."/>
                <button onClick={submitCreateCourse} className="w-full bg-red-600 py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-red-700 transition-all">Crear Estructura</button>
            </div>
        </div>
      )}

      {/* --- MODAL CREAR MÓDULO --- */}
      {modalType === 'MODULE' && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center p-6">
            <div className="bg-[#0f0f0f] p-10 rounded-[3rem] w-full max-w-lg border border-white/10 relative shadow-2xl">
                <button onClick={closeModal} className="absolute top-8 right-8 text-zinc-500 hover:text-white transition-colors"><X/></button>
                <h2 className="text-2xl font-black italic uppercase mb-8 flex items-center gap-3"><Box className="text-red-600"/> Nuevo Módulo</h2>
                <input autoFocus type="text" onChange={e => setInputTitle(e.target.value)} className="w-full bg-black border border-white/10 p-6 rounded-2xl text-white font-bold outline-none focus:border-red-600 mb-6 placeholder:text-zinc-800 transition-colors" placeholder="NOMBRE DEL MÓDULO..."/>
                <button onClick={submitCreateModule} className="w-full bg-white text-black py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-zinc-200 transition-all">Añadir Módulo</button>
            </div>
        </div>
      )}

      {/* --- MODAL CREAR CLASE (CON UPLOADER) --- */}
      {modalType === 'LESSON' && (
        <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-xl flex items-center justify-center p-4">
            <div className="bg-[#0f0f0f] w-full max-w-2xl rounded-[2.5rem] border border-white/10 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                <div className="p-8 border-b border-white/5 flex justify-between items-center bg-zinc-900/30">
                    <h2 className="text-2xl font-black uppercase italic flex items-center gap-3 text-white">
                        <Video className="text-red-600"/> Nueva <span className="text-red-600">Lección</span>
                    </h2>
                    <button onClick={closeModal} className="p-2 bg-white/5 rounded-full hover:bg-red-600 hover:text-white transition-all"><X size={20}/></button>
                </div>
                <div className="p-8 space-y-6 overflow-y-auto custom-scrollbar">
                    {/* TÍTULO */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-2">Título</label>
                        <input autoFocus type="text" value={lessonData.title} onChange={e => setLessonData({...lessonData, title: e.target.value})} className="w-full bg-black border border-white/10 p-4 rounded-xl text-white font-bold focus:border-red-600 outline-none transition-all placeholder:text-zinc-800" placeholder="Ej: Estrategia de Ventas..."/>
                    </div>
                    {/* VIDEO */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-2">Video URL (Drive/YouTube)</label>
                        <div className="relative">
                            <LinkIcon size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600"/>
                            <input type="text" value={lessonData.video_url} onChange={e => setLessonData({...lessonData, video_url: e.target.value})} className="w-full bg-black border border-white/10 p-4 pl-12 rounded-xl text-zinc-300 focus:border-red-600 outline-none transition-all font-mono text-sm" placeholder="https://..."/>
                        </div>
                    </div>
                    {/* DESCRIPCIÓN */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-2">Descripción</label>
                        <textarea value={lessonData.description} onChange={e => setLessonData({...lessonData, description: e.target.value})} className="w-full bg-black border border-white/10 p-4 rounded-xl text-zinc-400 focus:border-red-600 outline-none transition-all min-h-[100px] resize-none" placeholder="Resumen..."/>
                    </div>

                    {/* --- ZONA DE CARGA DE ARCHIVOS --- */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-2">Materiales / Archivos</label>
                        <div className="w-full bg-black border-2 border-dashed border-white/10 rounded-xl p-8 flex flex-col items-center justify-center gap-3 hover:border-red-600/50 transition-colors relative">
                            {uploading ? (
                                <div className="flex flex-col items-center text-red-600 animate-pulse">
                                    <Loader2 className="animate-spin" size={32}/>
                                    <span className="text-xs font-black uppercase mt-2">Subiendo...</span>
                                </div>
                            ) : lessonData.resources ? (
                                <div className="flex items-center gap-3 text-green-500">
                                    <CheckCircle size={32}/>
                                    <div className="text-left">
                                        <p className="text-xs font-black uppercase">Archivo cargado con éxito</p>
                                        <p className="text-[10px] text-zinc-500 truncate max-w-[200px]">{lessonData.resources}</p>
                                    </div>
                                    <button onClick={() => setLessonData(prev => ({...prev, resources: ''}))} className="p-2 bg-white/5 rounded-full hover:bg-red-600 hover:text-white ml-4"><Trash2 size={14}/></button>
                                </div>
                            ) : (
                                <>
                                    <Upload size={32} className="text-zinc-700"/>
                                    <p className="text-xs font-black uppercase text-zinc-500">Arrastra o selecciona un archivo</p>
                                    <input 
                                        type="file" 
                                        onChange={handleFileUpload}
                                        className="absolute inset-0 opacity-0 cursor-pointer"
                                    />
                                </>
                            )}
                        </div>
                    </div>

                </div>
                <div className="p-8 pt-0 bg-gradient-to-t from-[#0f0f0f] to-transparent">
                    <button onClick={submitCreateLesson} disabled={uploading} className={`w-full bg-red-600 py-5 rounded-2xl font-black uppercase tracking-[0.2em] hover:bg-red-700 transition-all shadow-lg shadow-red-900/20 flex items-center justify-center gap-3 active:scale-95 text-white ${uploading ? 'opacity-50 cursor-not-allowed' : ''}`}>
                        <Save size={20}/> Guardar Lección
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect } from 'react';
import { 
  Trash2, LogOut, ChevronDown, Layout, Box, Video, X, Plus, FileText, Link as LinkIcon, Save, PlusCircle, Upload, CheckCircle, Loader2, LayoutDashboard, ArrowLeft, Pencil
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';
import { Link } from 'react-router-dom';

const AdminPage = ({ onLogout }: { onLogout: () => void }) => {
  const [courses, setCourses] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedCourses, setExpandedCourses] = useState<Set<string>>(new Set());

  // ESTADOS MODALES Y EDICIÓN
  const [modalType, setModalType] = useState<'NONE' | 'COURSE' | 'MODULE' | 'LESSON'>('NONE');
  const [isEditing, setIsEditing] = useState(false); // Nuevo estado para saber si editamos
  const [tempId, setTempId] = useState<string>(''); // Sirve como ParentID (al crear) o TargetID (al editar)
  const [inputTitle, setInputTitle] = useState('');

  // DATOS LECCIÓN + ESTADO DE SUBIDA
  const [lessonData, setLessonData] = useState({ 
    title: '', video_url: '', description: '', resources: '' 
  });
  const [uploading, setUploading] = useState(false);

  const [notification, setNotification] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  useEffect(() => { fetchData(); }, []);

  async function fetchData() {
    setLoading(true);
    const { data, error } = await supabase
      .from('courses')
      .select('*, modules(*, lessons(*))') 
      .order('created_at', { ascending: false });

    if (!error && data) {
      const sorted = data.map(c => ({
        ...c,
        modules: c.modules?.sort((a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())
          .map((m: any) => ({
             ...m,
             lessons: m.lessons?.sort((x: any, y: any) => new Date(x.created_at).getTime() - new Date(y.created_at).getTime())
          }))
      }));
      setCourses(sorted);
    }
    setLoading(false);
  }

  // --- FUNCIÓN DE SUBIDA DE ARCHIVOS (CORE) ---
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;

    const file = e.target.files[0];
    const fileExt = file.name.split('.').pop();
    const fileName = `${Math.random()}.${fileExt}`;
    const filePath = `${fileName}`;

    setUploading(true);

    try {
      const { error: uploadError } = await supabase.storage
        .from('course_materials')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('course_materials').getPublicUrl(filePath);

      setLessonData(prev => ({ ...prev, resources: data.publicUrl }));
      showNotify('success', 'ARCHIVO SUBIDO CORRECTAMENTE');

    } catch (error: any) {
      alert("Error subiendo archivo: " + error.message);
    } finally {
      setUploading(false);
    }
  };

  // --- APERTURA MODALES (CREAR VS EDITAR) ---

  // 1. CURSOS
  const openCreateCourse = () => { 
    setModalType('COURSE'); 
    setIsEditing(false); 
    setInputTitle(''); 
  };
  const openEditCourse = (course: any) => {
    setModalType('COURSE');
    setIsEditing(true);
    setTempId(course.id);
    setInputTitle(course.title);
  };

  // 2. MÓDULOS
  const openCreateModule = (courseId: string) => { 
    setTempId(courseId); // Parent ID
    setModalType('MODULE'); 
    setIsEditing(false); 
    setInputTitle(''); 
  };
  const openEditModule = (module: any) => {
    setTempId(module.id); // Target ID
    setModalType('MODULE');
    setIsEditing(true);
    setInputTitle(module.title);
  };

  // 3. LECCIONES
  const openCreateLesson = (moduleId: string) => {
    setTempId(moduleId); // Parent ID
    setModalType('LESSON');
    setIsEditing(false);
    setLessonData({ title: '', video_url: '', description: '', resources: '' });
  };
  const openEditLesson = (lesson: any) => {
    setTempId(lesson.id); // Target ID
    setModalType('LESSON');
    setIsEditing(true);
    setLessonData({ 
        title: lesson.title, 
        video_url: lesson.video_url || '', 
        description: lesson.description || '', 
        resources: lesson.resources || '' 
    });
  };

  const closeModal = () => { setModalType('NONE'); setTempId(''); setInputTitle(''); };

  // --- SUBMITS (INSERT VS UPDATE) ---

  const submitCourse = async () => {
    if (!inputTitle.trim()) return;

    let error;
    if (isEditing) {
        // UPDATE
        const { error: err } = await supabase.from('courses').update({ title: inputTitle }).eq('id', tempId);
        error = err;
    } else {
        // INSERT
        const { error: err } = await supabase.from('courses').insert([{ title: inputTitle }]);
        error = err;
    }

    if (!error) { closeModal(); fetchData(); showNotify('success', isEditing ? 'MASTER ACTUALIZADO' : 'MASTER CREADO'); } 
    else alert(error.message);
  };

  const submitModule = async () => {
    if (!inputTitle.trim()) return;

    let error;
    if (isEditing) {
        // UPDATE
        const { error: err } = await supabase.from('modules').update({ title: inputTitle }).eq('id', tempId);
        error = err;
    } else {
        // INSERT (tempId es course_id)
        const { error: err } = await supabase.from('modules').insert([{ title: inputTitle, course_id: tempId }]);
        error = err;
    }

    if (!error) { closeModal(); fetchData(); showNotify('success', isEditing ? 'MÓDULO ACTUALIZADO' : 'MÓDULO CREADO'); }
    else alert(error.message);
  };

  const submitLesson = async () => {
    if (!lessonData.title.trim()) return alert("Título obligatorio");

    let error;
    const payload = { 
        title: lessonData.title, 
        video_url: lessonData.video_url,
        description: lessonData.description,
        resources: lessonData.resources 
    };

    if (isEditing) {
        // UPDATE
        const { error: err } = await supabase.from('lessons').update(payload).eq('id', tempId);
        error = err;
    } else {
        // INSERT (tempId es module_id)
        const { error: err } = await supabase.from('lessons').insert([{ ...payload, module_id: tempId }]);
        error = err;
    }

    if (!error) { closeModal(); fetchData(); showNotify('success', isEditing ? 'CLASE ACTUALIZADA' : 'CLASE GUARDADA'); }
    else alert(error.message);
  };

  const handleDelete = async (table: 'courses'|'modules'|'lessons', id: string) => {
    if (!window.confirm("¿Estás seguro de eliminar este elemento permanentemente?")) return;
    const { error } = await supabase.from(table).delete().eq('id', id);
    if (!error) {
      fetchData();
      showNotify('success', 'ELIMINADO CORRECTAMENTE');
    } else alert(error.message);
  };

  // --- UTILS ---
  const toggleCourse = (id: string) => {
    const next = new Set(expandedCourses);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedCourses(next);
  };

  const showNotify = (type: 'success'|'error', msg: string) => {
    setNotification({ type, msg });
    setTimeout(() => setNotification(null), 3000);
  };

  if (loading) return <div className="min-h-screen bg-black flex items-center justify-center text-red-600 font-bold uppercase tracking-widest">Cargando Panel...</div>;

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans p-8 selection:bg-red-600 selection:text-white">
      <AnimatePresence>
        {notification && (
          <motion.div initial={{ y: -100 }} animate={{ y: 0 }} exit={{ y: -100 }} className="fixed top-6 left-1/2 -translate-x-1/2 z-[9999] bg-zinc-800 border border-red-600/50 px-6 py-3 rounded-xl font-bold shadow-2xl flex items-center gap-2">
             <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse"/> {notification.msg}
          </motion.div>
        )}
      </AnimatePresence>

      <div className="max-w-6xl mx-auto pb-40">
        <nav className="flex justify-between items-center mb-10 border-b border-white/5 pb-6">
            <h1 className="text-3xl font-black italic tracking-tighter">EZEH <span className="text-red-600">ADMIN</span></h1>

            <div className="flex items-center gap-4">
                <Link to="/dashboard" className="flex items-center gap-2 px-6 py-3 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 hover:border-red-600/50 transition-all text-[10px] font-black uppercase tracking-widest text-zinc-300 hover:text-white group">
                    <LayoutDashboard size={14} className="text-zinc-500 group-hover:text-red-600 transition-colors"/>
                    Volver a Academia
                </Link>

                <div className="w-px h-8 bg-white/10 mx-2 hidden sm:block"></div>

                <button onClick={onLogout} className="flex items-center gap-2 px-4 py-3 rounded-xl bg-zinc-900/50 border border-transparent hover:border-white/10 hover:bg-zinc-800 text-[10px] font-black uppercase tracking-widest text-zinc-500 hover:text-white transition-all">
                    <LogOut size={14}/>
                    <span className="hidden sm:inline">Salir</span>
                </button>
            </div>
        </nav>

        <div className="mb-10 text-right">
            <button onClick={openCreateCourse} className="px-8 py-4 bg-red-600 hover:bg-red-700 rounded-[1.5rem] font-black uppercase tracking-widest shadow-lg shadow-red-900/20 active:scale-95 transition-all flex items-center gap-2 ml-auto">
                <PlusCircle size={20}/> Nuevo Master
            </button>
        </div>

        <div className="space-y-8">
          {courses.map((course) => (
            <div key={course.id} className="bg-[#0a0a0a] border border-white/10 rounded-[2.5rem] overflow-hidden shadow-2xl relative">
              <div className="p-8 flex items-center justify-between hover:bg-white/[0.01] transition-colors">
                <div className="flex items-center gap-6 cursor-pointer group select-none flex-1" onClick={() => toggleCourse(course.id)}>
                    <div className="w-14 h-14 bg-red-600/10 rounded-2xl flex items-center justify-center text-red-600 group-hover:bg-red-600 group-hover:text-white transition-all border border-red-600/10">
                        {expandedCourses.has(course.id) ? <ChevronDown/> : <Layout/>}
                    </div>
                    <div>
                        <div className="flex items-center gap-3">
                            <h3 className="font-black text-xl uppercase italic group-hover:text-red-500 transition-colors tracking-tight">{course.title}</h3>
                            <button onClick={(e) => { e.stopPropagation(); openEditCourse(course); }} className="text-zinc-600 hover:text-white transition-colors p-1"><Pencil size={14}/></button>
                        </div>
                        <p className="text-[10px] text-zinc-500 uppercase tracking-widest mt-1">{course.modules?.length || 0} Módulos</p>
                    </div>
                </div>
                <div className="flex items-center gap-3 pl-6 border-l border-white/5">
                  <button onClick={() => openCreateModule(course.id)} className="bg-white text-black px-5 py-2.5 rounded-xl font-black text-[10px] uppercase hover:bg-zinc-200 transition-all shadow-lg active:scale-95">+ Módulo</button>
                  <button onClick={() => handleDelete('courses', course.id)} className="p-3 text-zinc-600 hover:text-red-500 bg-zinc-900 rounded-xl border border-white/5 hover:border-red-600/50 transition-all active:scale-95"><Trash2 size={18}/></button>
                </div>
              </div>

              <AnimatePresence>
                {expandedCourses.has(course.id) && (
                  <motion.div initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} className="overflow-hidden bg-zinc-900/20 border-t border-white/5">
                    <div className="p-8 space-y-4">
                      {course.modules?.map((mod: any) => (
                         <div key={mod.id} className="bg-black border border-white/5 rounded-3xl overflow-hidden">
                            <div className="p-5 flex justify-between items-center bg-white/[0.02] border-b border-white/5">
                                <div className="flex items-center gap-4">
                                    <Box size={18} className="text-zinc-500"/>
                                    <span className="font-black text-sm text-zinc-300 uppercase tracking-wide">{mod.title}</span>
                                    <button onClick={() => openEditModule(mod)} className="text-zinc-600 hover:text-white transition-colors"><Pencil size={12}/></button>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button onClick={() => openCreateLesson(mod.id)} className="text-[9px] bg-red-600/10 text-red-500 px-4 py-2 rounded-lg border border-red-600/20 hover:bg-red-600 hover:text-white transition-all font-black uppercase flex items-center gap-2"><Plus size={10}/> Clase</button>
                                    <button onClick={() => handleDelete('modules', mod.id)} className="text-zinc-600 hover:text-red-500 p-2 transition-colors"><Trash2 size={16}/></button>
                                </div>
                            </div>
                            <div className="p-2 bg-[#050505]">
                                {mod.lessons?.map((l: any) => (
                                    <div key={l.id} className="flex items-center justify-between p-4 rounded-2xl hover:bg-white/5 transition-all group border border-transparent hover:border-white/5">
                                        <div className="flex items-center gap-4">
                                            <div className="p-2 bg-zinc-900 rounded-lg text-zinc-600 group-hover:text-red-500 transition-colors"><Video size={14}/></div>
                                            <div>
                                                <div className="flex items-center gap-2">
                                                    <span className="text-xs font-bold text-zinc-400 group-hover:text-white uppercase block transition-colors">{l.title}</span>
                                                    <button onClick={() => openEditLesson(l)} className="opacity-0 group-hover:opacity-100 text-zinc-600 hover:text-white transition-all"><Pencil size={10}/></button>
                                                </div>
                                                {l.resources && <span className="text-[9px] text-green-500 flex items-center gap-1 mt-1"><FileText size={8}/> Archivo Adjunto</span>}
                                            </div>
                                        </div>
                                        <button onClick={() => handleDelete('lessons', l.id)} className="opacity-0 group-hover:opacity-100 text-zinc-600 hover:text-red-500 p-2 transition-all"><Trash2 size={14}/></button>
                                    </div>
                                ))}
                                {!mod.lessons?.length && <div className="text-[9px] text-zinc-700 text-center py-4 uppercase font-bold tracking-widest opacity-50">Módulo sin contenido</div>}
                            </div>
                         </div>
                      ))}
                      {!course.modules?.length && <div className="text-center text-xs text-zinc-600 uppercase font-black tracking-widest py-4 border-2 border-dashed border-white/5 rounded-2xl">Añade el primer módulo</div>}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          ))}
        </div>
      </div>

      {/* --- MODAL CREAR/EDITAR CURSO --- */}
      {modalType === 'COURSE' && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center p-6">
            <div className="bg-[#0f0f0f] p-10 rounded-[3rem] w-full max-w-lg border border-white/10 relative shadow-2xl">
                <button onClick={closeModal} className="absolute top-8 right-8 text-zinc-500 hover:text-white transition-colors"><X/></button>
                <h2 className="text-3xl font-black italic uppercase mb-8">{isEditing ? 'Editar' : 'Nuevo'} <span className="text-red-600">Master</span></h2>
                <input autoFocus type="text" value={inputTitle} onChange={e => setInputTitle(e.target.value)} className="w-full bg-black border border-white/10 p-6 rounded-2xl text-white font-bold outline-none focus:border-red-600 mb-6 placeholder:text-zinc-800 transition-colors" placeholder="NOMBRE DEL MASTER..."/>
                <button onClick={submitCourse} className="w-full bg-red-600 py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-red-700 transition-all">{isEditing ? 'Guardar Cambios' : 'Crear Estructura'}</button>
            </div>
        </div>
      )}

      {/* --- MODAL CREAR/EDITAR MÓDULO --- */}
      {modalType === 'MODULE' && (
        <div className="fixed inset-0 z-[100] bg-black/90 backdrop-blur-sm flex items-center justify-center p-6">
            <div className="bg-[#0f0f0f] p-10 rounded-[3rem] w-full max-w-lg border border-white/10 relative shadow-2xl">
                <button onClick={closeModal} className="absolute top-8 right-8 text-zinc-500 hover:text-white transition-colors"><X/></button>
                <h2 className="text-2xl font-black italic uppercase mb-8 flex items-center gap-3"><Box className="text-red-600"/> {isEditing ? 'Editar' : 'Nuevo'} Módulo</h2>
                <input autoFocus type="text" value={inputTitle} onChange={e => setInputTitle(e.target.value)} className="w-full bg-black border border-white/10 p-6 rounded-2xl text-white font-bold outline-none focus:border-red-600 mb-6 placeholder:text-zinc-800 transition-colors" placeholder="NOMBRE DEL MÓDULO..."/>
                <button onClick={submitModule} className="w-full bg-white text-black py-5 rounded-2xl font-black uppercase tracking-widest hover:bg-zinc-200 transition-all">{isEditing ? 'Guardar Cambios' : 'Añadir Módulo'}</button>
            </div>
        </div>
      )}

      {/* --- MODAL CREAR/EDITAR CLASE --- */}
      {modalType === 'LESSON' && (
        <div className="fixed inset-0 z-[150] bg-black/95 backdrop-blur-xl flex items-center justify-center p-4">
            <div className="bg-[#0f0f0f] w-full max-w-2xl rounded-[2.5rem] border border-white/10 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
                <div className="p-8 border-b border-white/5 flex justify-between items-center bg-zinc-900/30">
                    <h2 className="text-2xl font-black uppercase italic flex items-center gap-3 text-white">
                        <Video className="text-red-600"/> {isEditing ? 'Editar' : 'Nueva'} <span className="text-red-600">Lección</span>
                    </h2>
                    <button onClick={closeModal} className="p-2 bg-white/5 rounded-full hover:bg-red-600 hover:text-white transition-all"><X size={20}/></button>
                </div>
                <div className="p-8 space-y-6 overflow-y-auto custom-scrollbar">
                    {/* TÍTULO */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-2">Título</label>
                        <input autoFocus type="text" value={lessonData.title} onChange={e => setLessonData({...lessonData, title: e.target.value})} className="w-full bg-black border border-white/10 p-4 rounded-xl text-white font-bold focus:border-red-600 outline-none transition-all placeholder:text-zinc-800" placeholder="Ej: Estrategia de Ventas..."/>
                    </div>
                    {/* VIDEO */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-2">Video URL (Drive/YouTube)</label>
                        <div className="relative">
                            <LinkIcon size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600"/>
                            <input type="text" value={lessonData.video_url} onChange={e => setLessonData({...lessonData, video_url: e.target.value})} className="w-full bg-black border border-white/10 p-4 pl-12 rounded-xl text-zinc-300 focus:border-red-600 outline-none transition-all font-mono text-sm" placeholder="https://..."/>
                        </div>
                    </div>
                    {/* DESCRIPCIÓN */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-2">Descripción</label>
                        <textarea value={lessonData.description} onChange={e => setLessonData({...lessonData, description: e.target.value})} className="w-full bg-black border border-white/10 p-4 rounded-xl text-zinc-400 focus:border-red-600 outline-none transition-all min-h-[100px] resize-none" placeholder="Resumen..."/>
                    </div>

                    {/* --- ZONA DE CARGA DE ARCHIVOS --- */}
                    <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase tracking-widest text-zinc-500 ml-2">Materiales / Archivos</label>
                        <div className="w-full bg-black border-2 border-dashed border-white/10 rounded-xl p-8 flex flex-col items-center justify-center gap-3 hover:border-red-600/50 transition-colors relative">
                            {uploading ? (
                                <div className="flex flex-col items-center text-red-600 animate-pulse">
                                    <Loader2 className="animate-spin" size={32}/>
                                    <span className="text-xs font-black uppercase mt-2">Subiendo...</span>
                                </div>
                            ) : lessonData.resources ? (
                                <div className="flex items-center gap-3 text-green-500">
                                    <CheckCircle size={32}/>
                                    <div className="text-left">
                                        <p className="text-xs font-black uppercase">Archivo cargado con éxito</p>
                                        <p className="text-[10px] text-zinc-500 truncate max-w-[200px]">{lessonData.resources}</p>
                                    </div>
                                    <button onClick={() => setLessonData(prev => ({...prev, resources: ''}))} className="p-2 bg-white/5 rounded-full hover:bg-red-600 hover:text-white ml-4"><Trash2 size={14}/></button>
                                </div>
                            ) : (
                                <>
                                    <Upload size={32} className="text-zinc-700"/>
                                    <p className="text-xs font-black uppercase text-zinc-500">Arrastra o selecciona un archivo</p>
                                    <input 
                                        type="file" 
                                        onChange={handleFileUpload}
                                        className="absolute inset-0 opacity-0 cursor-pointer"
                                    />
                                </>
                            )}
                        </div>
                    </div>

                </div>
                <div className="p-8 pt-0 bg-gradient-to-t from-[#0f0f0f] to-transparent">
                    <button onClick={submitLesson} disabled={uploading} className={`w-full bg-red-600 py-5 rounded-2xl font-black uppercase tracking-[0.2em] hover:bg-red-700 transition-all shadow-lg shadow-red-900/20 flex items-center justify-center gap-3 active:scale-95 text-white ${uploading ? 'opacity-50 cursor-not-allowed' : ''}`}>
                        <Save size={20}/> {isEditing ? 'Guardar Cambios' : 'Guardar Lección'}
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Play, FileText, ChevronDown, Lock, LogOut, Menu, X, Zap, ExternalLink, 
  CheckCircle, Trophy, Award, Star, Crown, ChevronRight, LayoutDashboard,
  Shield, Medal, ThumbsUp
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';
import { Link } from 'react-router-dom';
import { User } from '../types';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

type Rank = "Novato" | "Creador" | "Partner" | "Referente" | "Leyenda";
type ViewState = 'HOME' | 'PLAYER';

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [courses, setCourses] = useState<any[]>([]);
  // Use Set for O(1) lookups of completed lessons
  const [completedLessons, setCompletedLessons] = useState<Set<string>>(new Set());
  const [activeLesson, setActiveLesson] = useState<any>(null);
  const [viewState, setViewState] = useState<ViewState>('HOME');
  const [userRating, setUserRating] = useState<number>(0); // Estado local para la valoración

  const [loading, setLoading] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const isAdmin = user.role === 'admin';

  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await Promise.all([fetchCourses(), fetchProgress()]);
      setLoading(false);
    };
    init();
  }, [user.id]);

  async function fetchCourses() {
    const { data, error } = await supabase
      .from('courses')
      .select('*, modules(*, lessons(*))')
      .order('created_at', { ascending: true });

    if (!error && data) {
      const sorted = data.map(c => ({
        ...c,
        modules: c.modules?.sort((a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())
          .map((m: any) => ({
             ...m,
             lessons: m.lessons?.sort((x: any, y: any) => new Date(x.created_at).getTime() - new Date(y.created_at).getTime())
          }))
      }));
      setCourses(sorted);

      // Auto-expand first module if exists
      if (sorted.length > 0 && sorted[0].modules?.[0]) {
        setExpandedModules(new Set([sorted[0].modules[0].id]));
      }
    }
  }

  async function fetchProgress() {
    const { data, error } = await supabase
      .from('user_progress')
      .select('lesson_id')
      .eq('user_id', user.id);

    if (!error && data) {
      const ids = new Set(data.map(item => item.lesson_id));
      setCompletedLessons(ids);
    }
  }

  const toggleLessonCompletion = async (lessonId: string) => {
    const isComplete = completedLessons.has(lessonId);

    // Optimistic UI Update
    const nextSet = new Set(completedLessons);
    if (isComplete) nextSet.delete(lessonId);
    else nextSet.add(lessonId);
    setCompletedLessons(nextSet);

    if (isComplete) {
      // Remove from DB
      await supabase.from('user_progress').delete().match({ user_id: user.id, lesson_id: lessonId });
    } else {
      // Add to DB
      await supabase.from('user_progress').insert({ user_id: user.id, lesson_id: lessonId });
    }
  };

  const handleLessonSelect = (lesson: any) => {
    setActiveLesson(lesson);
    setViewState('PLAYER');
    setUserRating(0); // Reset rating visual al cambiar lección
    // Auto close sidebar on mobile
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const toggleModule = (id: string) => {
    const next = new Set(expandedModules);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedModules(next);
  };

  // --- GAMIFICATION & STATS ENGINE ---

  const stats = useMemo(() => {
    let totalLessons = 0;
    let totalCompleted = 0;

    courses.forEach(course => {
      course.modules?.forEach((mod: any) => {
        mod.lessons?.forEach((lesson: any) => {
          totalLessons++;
          if (completedLessons.has(lesson.id)) totalCompleted++;
        });
      });
    });

    const percentage = totalLessons === 0 ? 0 : Math.round((totalCompleted / totalLessons) * 100);

    let rank: Rank = "Novato";
    if (percentage >= 25) rank = "Creador";
    if (percentage >= 50) rank = "Partner";
    if (percentage >= 75) rank = "Referente";
    if (percentage >= 100) rank = "Leyenda";

    return { totalLessons, totalCompleted, percentage, rank };
  }, [courses, completedLessons]);

  const getRankIcon = (r: Rank, size: number = 20) => {
    switch (r) {
      case "Novato": return <Shield size={size} className="text-zinc-500" />;
      case "Creador": return <Award size={size} className="text-bronze-500" color="#cd7f32" />;
      case "Partner": return <Star size={size} className="text-zinc-300" fill="currentColor" />;
      case "Referente": return <Crown size={size} className="text-yellow-400" fill="currentColor" />;
      case "Leyenda": return <Trophy size={size} className="text-cyan-400" fill="currentColor" />;
    }
  };

  const resumeLearning = () => {
    // Find first uncompleted lesson
    for (const course of courses) {
      for (const mod of course.modules || []) {
        for (const lesson of mod.lessons || []) {
          if (!completedLessons.has(lesson.id)) {
            handleLessonSelect(lesson);
            return;
          }
        }
      }
    }
    // If all completed, go to first lesson of first course
    if (courses[0]?.modules?.[0]?.lessons?.[0]) {
      handleLessonSelect(courses[0].modules[0].lessons[0]);
    }
  };

  // --- SMART VIDEO EMBEDDER LOGIC ---

  const getEmbedUrl = (url: string) => {
    if (!url) return '';
    if (url.includes('drive.google.com')) return url.replace(/\/view.*/, '/preview');
    if (url.includes('youtube.com') || url.includes('youtu.be')) {
      const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
      const match = url.match(regExp);
      return (match && match[2].length === 11) ? `https://www.youtube.com/embed/${match[2]}?modestbranding=1&rel=0` : url;
    }
    if (url.includes('vimeo.com')) {
      const regExp = /vimeo\.com\/(\d+)/;
      const match = url.match(regExp);
      return match ? `https://player.vimeo.com/video/${match[1]}` : url;
    }
    return url;
  };

  const isEmbeddable = (url: string) => {
    if (!url) return false;
    return url.includes('drive.google.com') || url.includes('youtube.com') || url.includes('youtu.be') || url.includes('vimeo.com');
  };

  // ----------------------------------

  if (loading) return <div className="min-h-screen bg-black flex items-center justify-center text-white font-bold tracking-widest uppercase">Cargando tu Academia...</div>;

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans flex overflow-hidden">

      {/* --- SIDEBAR --- */}
      <motion.aside 
        initial={false}
        animate={{ width: sidebarOpen ? '350px' : '0px', opacity: sidebarOpen ? 1 : 0 }}
        className="h-screen bg-[#0a0a0a] border-r border-white/5 flex-shrink-0 flex flex-col overflow-hidden relative z-20"
      >
        <div className="p-6 border-b border-white/5 flex justify-between items-center bg-zinc-900/50 cursor-pointer" onClick={() => setViewState('HOME')}>
            <h2 className="font-black italic text-xl tracking-tighter">EZEH <span className="text-red-600">ACADEMY</span></h2>
            <button onClick={(e) => { e.stopPropagation(); setSidebarOpen(false); }} className="lg:hidden text-white"><X/></button>
        </div>

        {/* --- UNIFIED HOME PANEL & STATS --- */}
        <div 
            onClick={() => setViewState('HOME')}
            className={`p-6 border-b border-white/5 cursor-pointer transition-all group ${viewState === 'HOME' ? 'bg-white/5' : 'hover:bg-white/5'}`}
        >
           {/* HEADER */}
           <div className="flex items-center gap-3 mb-4">
               <div className={`p-2 rounded-lg ${viewState === 'HOME' ? 'bg-red-600 text-white' : 'bg-zinc-800 text-zinc-400 group-hover:text-white'}`}>
                   <LayoutDashboard size={18}/>
               </div>
               <span className={`text-xs font-black uppercase tracking-widest ${viewState === 'HOME' ? 'text-white' : 'text-zinc-500 group-hover:text-white'}`}>
                   Panel Home
               </span>
           </div>

           {/* STATS (SOLO SI NO ES ADMIN) */}
           {!isAdmin && (
               <div className="bg-[#050505] rounded-xl p-4 border border-white/5 relative overflow-hidden">
                   <div className="absolute top-0 right-0 w-20 h-20 bg-red-600/20 blur-xl rounded-full"/>
                   <div className="relative z-10 flex items-center justify-between">
                       <div className="flex flex-col">
                           <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-wider mb-1">Tu Rango</span>
                           <div className="flex items-center gap-2 text-sm font-black italic uppercase text-white">
                                {getRankIcon(stats.rank, 14)} {stats.rank}
                           </div>
                       </div>
                       <div className="w-12 h-12 rounded-full border-2 border-red-600 flex items-center justify-center font-black text-xs text-white bg-red-600/10 shadow-[0_0_15px_rgba(220,38,38,0.3)]">
                          {stats.percentage}%
                       </div>
                   </div>
               </div>
           )}

           {isAdmin && (
               <div className="bg-[#050505] rounded-xl p-4 border border-yellow-500/20 relative overflow-hidden group-hover:border-yellow-500/40 transition-colors">
                   <div className="absolute -top-10 -right-10 w-24 h-24 bg-yellow-500/10 blur-xl rounded-full"/>
                   <div className="relative z-10">
                       <span className="text-[9px] text-yellow-500/80 font-bold uppercase tracking-[0.2em] mb-1 block">Modo Dios</span>
                       <div className="text-xs font-black text-white uppercase flex items-center gap-2">
                           <Crown size={14} className="text-yellow-400"/> Administrador
                       </div>
                   </div>
               </div>
           )}
        </div>

        {/* --- COURSE LIST --- */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-8">
            {courses.map(course => (
                <div key={course.id}>
                    <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 mb-4 ml-2">{course.title}</h3>
                    <div className="space-y-2">
                        {course.modules?.map((mod: any) => (
                            <div key={mod.id} className="bg-black border border-white/5 rounded-2xl overflow-hidden">
                                <button 
                                    onClick={() => toggleModule(mod.id)}
                                    className="w-full p-4 flex justify-between items-center text-left hover:bg-white/5 transition-colors"
                                >
                                    <span className="font-bold text-sm text-zinc-300 uppercase">{mod.title}</span>
                                    <ChevronDown size={16} className={`text-zinc-600 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`}/>
                                </button>

                                <AnimatePresence>
                                    {expandedModules.has(mod.id) && (
                                        <motion.div 
                                            initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} 
                                            className="overflow-hidden bg-zinc-900/30"
                                        >
                                            <div className="p-2 space-y-1">
                                                {mod.lessons?.map((lesson: any) => {
                                                    const isCompleted = completedLessons.has(lesson.id);
                                                    const isActive = activeLesson?.id === lesson.id && viewState === 'PLAYER';
                                                    return (
                                                      <button
                                                          key={lesson.id}
                                                          onClick={() => handleLessonSelect(lesson)}
                                                          className={`w-full p-3 rounded-xl flex items-center gap-3 text-left transition-all group ${isActive ? 'bg-red-600 text-white shadow-lg shadow-red-900/20' : 'hover:bg-white/5 text-zinc-500'}`}
                                                      >
                                                          <div className={`p-1.5 rounded-full relative ${isActive ? 'bg-white/20' : 'bg-black border border-white/10 group-hover:border-white/30'}`}>
                                                              {isActive ? <Play size={10} fill="currentColor"/> : (
                                                                isCompleted ? <CheckCircle size={10} className="text-green-500" /> : <Lock size={10}/>
                                                              )}
                                                          </div>
                                                          <span className={`text-xs font-bold uppercase truncate flex-1 ${isCompleted && !isActive ? 'text-zinc-300 line-through decoration-red-600/50' : ''}`}>{lesson.title}</span>
                                                      </button>
                                                    );
                                                })}
                                            </div>
                                        </motion.div>
                                    )}
                                </AnimatePresence>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>

        <div className="p-4 border-t border-white/5 space-y-3">
            {isAdmin && (
                <Link 
                    to="/admin" 
                    className="w-full py-4 rounded-xl text-xs font-black uppercase text-white bg-gradient-to-r from-red-600 to-red-900 hover:scale-[1.02] transition-transform shadow-lg shadow-red-900/30 flex items-center justify-center gap-2 border border-white/10"
                >
                    <Zap size={16} className="text-yellow-400 fill-yellow-400 animate-pulse"/> EZEH STUDIO
                </Link>
            )}

            <button onClick={onLogout} className="w-full py-3 bg-zinc-900 rounded-xl text-xs font-bold uppercase text-zinc-500 hover:text-white hover:bg-zinc-800 transition-all flex items-center justify-center gap-2">
                <LogOut size={14}/> Cerrar Sesión
            </button>
        </div>
      </motion.aside>

      {/* --- MAIN CONTENT --- */}
      <main className="flex-1 h-screen overflow-y-auto relative bg-[#050505] custom-scrollbar">
        {!sidebarOpen && (
            <button onClick={() => setSidebarOpen(true)} className="absolute top-6 left-6 z-50 p-3 bg-black/50 backdrop-blur-md rounded-full border border-white/10 text-white hover:bg-red-600 transition-all">
                <Menu size={20}/>
            </button>
        )}

        <div className="max-w-6xl mx-auto p-6 lg:p-12">

           {/* === VIEW: HOME (LOBBY) === */}
           {viewState === 'HOME' && (
              <motion.div initial={{opacity: 0, y: 20}} animate={{opacity: 1, y: 0}} className="space-y-12">

                 {/* HERO SECTION (CONDITIONAL STYLE FOR ADMIN) */}
                 <div className={`relative overflow-hidden rounded-[2.5rem] border p-8 lg:p-12 shadow-2xl transition-all ${
                     isAdmin 
                        ? 'bg-gradient-to-br from-amber-200 via-yellow-500 to-amber-700 border-yellow-400/50 shadow-yellow-600/20' 
                        : 'bg-[#0a0a0a] border-white/10'
                 }`}>
                    {/* Background Effects */}
                    {!isAdmin && (
                         <div className="absolute top-0 right-0 w-96 h-96 bg-red-600/10 blur-[100px] rounded-full pointer-events-none"/>
                    )}
                    {isAdmin && (
                        <>
                            <div className="absolute top-0 left-0 w-full h-full bg-[url('https://www.transparenttextures.com/patterns/cubes.png')] opacity-20 mix-blend-overlay pointer-events-none"/>
                            <div className="absolute -bottom-20 -right-20 w-96 h-96 bg-white/30 blur-[80px] rounded-full pointer-events-none"/>
                        </>
                    )}

                    <div className="relative z-10 flex flex-col md:flex-row items-end md:items-center justify-between gap-8">
                       <div className="space-y-4 max-w-xl">
                          <h1 className={`text-4xl lg:text-6xl font-black italic uppercase tracking-tighter ${isAdmin ? 'text-black drop-shadow-sm' : 'text-white'}`}>
                             Hola, <span className={isAdmin ? 'text-white drop-shadow-md' : 'text-transparent bg-clip-text bg-gradient-to-r from-red-500 to-orange-600'}>{user.fullName}</span>
                          </h1>
                          <p className={`text-sm font-medium leading-relaxed ${isAdmin ? 'text-amber-900' : 'text-zinc-400'}`}>
                             {isAdmin 
                                ? "Bienvenido a tu cuartel general. Desde aquí controlas todo el imperio de Ezeh Academy."
                                : <><span className="text-white font-bold">{stats.totalCompleted}</span> de <span className="text-white font-bold">{stats.totalLessons}</span> misiones completadas. Continúa tu camino hacia la leyenda.</>
                             }
                          </p>
                       </div>

                       <div className="text-right">
                          <div className={`text-[10px] font-black uppercase tracking-[0.3em] mb-2 ${isAdmin ? 'text-amber-900' : 'text-zinc-500'}`}>
                              {isAdmin ? 'Status' : 'Nivel Actual'}
                          </div>
                          <div className={`text-4xl font-black uppercase italic flex items-center justify-end gap-3 ${isAdmin ? 'text-white drop-shadow-md' : 'text-white'}`}>
                             {isAdmin 
                                ? <><Crown size={32} fill="white"/> MASTER</>
                                : <>{getRankIcon(stats.rank, 32)} {stats.rank}</>
                             }
                          </div>
                       </div>
                    </div>

                    {/* ANIMATED PROGRESS BAR */}
                    <div className="mt-12">
                       <div className={`flex justify-between text-xs font-bold uppercase tracking-widest mb-3 ${isAdmin ? 'text-amber-900' : 'text-zinc-500'}`}>
                          <span>{isAdmin ? 'Capacidad del Sistema' : 'Progreso General'}</span>
                          <span className={isAdmin ? 'text-black' : 'text-white'}>{isAdmin ? '100%' : `${stats.percentage}%`}</span>
                       </div>
                       <div className={`h-4 rounded-full overflow-hidden relative ${isAdmin ? 'bg-black/10' : 'bg-white/5'}`}>
                          <motion.div 
                             initial={{ width: 0 }}
                             animate={{ width: isAdmin ? '100%' : `${stats.percentage}%` }}
                             transition={{ duration: 1.5, ease: "easeOut" }}
                             className={`absolute top-0 left-0 h-full shadow-[0_0_20px_rgba(220,38,38,0.5)] ${
                                 isAdmin ? 'bg-white' : 'bg-gradient-to-r from-red-600 to-orange-600'
                             }`}
                          />
                       </div>
                    </div>

                    <div className="mt-10">
                       <button onClick={resumeLearning} className={`px-8 py-4 rounded-xl font-black uppercase tracking-widest text-xs hover:scale-105 transition-all flex items-center gap-2 shadow-lg ${
                           isAdmin 
                            ? 'bg-black text-white hover:bg-zinc-800 shadow-black/20'
                            : 'bg-white text-black hover:bg-zinc-200 shadow-white/10'
                       }`}>
                          <Play size={16} fill="currentColor" /> {isAdmin ? 'Revisar Contenido' : 'Continuar Aprendizaje'}
                       </button>
                    </div>
                 </div>

                 {/* TROPHY ROOM (HIDDEN FOR ADMIN) */}
                 {!isAdmin && (
                     <div>
                        <h2 className="text-xl font-black italic uppercase tracking-tighter mb-6 flex items-center gap-3">
                           <Trophy className="text-red-600" /> Sala de Trofeos
                        </h2>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                           {[
                             { limit: 25, label: "Creador", icon: Award, color: "text-amber-700" },
                             { limit: 50, label: "Partner", icon: Star, color: "text-zinc-300" },
                             { limit: 75, label: "Referente", icon: Crown, color: "text-yellow-400" },
                             { limit: 100, label: "Leyenda", icon: Medal, color: "text-cyan-400" },
                           ].map((tier, idx) => {
                              const isUnlocked = stats.percentage >= tier.limit;
                              return (
                                 <div key={idx} className={`relative p-6 rounded-3xl border ${isUnlocked ? 'bg-[#0f0f0f] border-red-600/30 shadow-[0_0_30px_rgba(220,38,38,0.1)]' : 'bg-black border-white/5 opacity-50 grayscale'} flex flex-col items-center justify-center text-center gap-4 transition-all group overflow-hidden`}>
                                    {isUnlocked && <div className="absolute inset-0 bg-gradient-to-t from-red-900/10 to-transparent pointer-events-none" />}
                                    <div className={`p-4 rounded-full ${isUnlocked ? 'bg-white/5 scale-110' : 'bg-white/5'}`}>
                                       <tier.icon size={32} className={isUnlocked ? tier.color : 'text-zinc-600'} fill={isUnlocked ? "currentColor" : "none"} />
                                    </div>
                                    <div>
                                       <h3 className="font-black uppercase text-sm tracking-wide">{tier.label}</h3>
                                       <p className="text-[10px] font-bold text-zinc-600 mt-1">{tier.limit}% COMPLETADO</p>
                                    </div>
                                 </div>
                              );
                           })}
                        </div>
                     </div>
                 )}

              </motion.div>
           )}

           {/* === VIEW: PLAYER (CLASS) === */}
           {viewState === 'PLAYER' && activeLesson && (
              <motion.div initial={{opacity: 0, x: 20}} animate={{opacity: 1, x: 0}} className="space-y-8">

                  {/* BREADCRUMBS */}
                  <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 mb-4">
                     <button onClick={() => setViewState('HOME')} className="hover:text-white transition-colors">Inicio</button>
                     <ChevronRight size={12}/>
                     <span>Lección Actual</span>
                  </div>

                  {/* VIDEO PLAYER UI */}
                  <div className="w-full aspect-video bg-black rounded-[2rem] overflow-hidden border border-white/10 shadow-2xl relative group">
                      {activeLesson.video_url ? (
                          isEmbeddable(activeLesson.video_url) ? (
                              <iframe
                                  src={getEmbedUrl(activeLesson.video_url)}
                                  className="w-full h-full"
                                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen"
                                  allowFullScreen
                                  title={activeLesson.title}
                              />
                          ) : (
                              <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#0a0a0a] p-8 text-center bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]">
                                  <div className="w-24 h-24 bg-white/5 rounded-full flex items-center justify-center mb-6 border border-white/10 shadow-[0_0_30px_rgba(0,0,0,0.5)]">
                                      <Play size={40} className="text-white/30 ml-2" />
                                  </div>
                                  <h3 className="text-2xl font-black uppercase italic text-white mb-3 tracking-tight">Formato Externo</h3>
                                  <a 
                                      href={activeLesson.video_url} 
                                      target="_blank" 
                                      rel="noopener noreferrer"
                                      className="bg-red-600 hover:bg-red-700 text-white px-10 py-5 rounded-2xl font-black uppercase tracking-[0.2em] flex items-center gap-3 transition-all hover:scale-105 shadow-xl shadow-red-900/20"
                                  >
                                      <ExternalLink size={20} /> Abrir Clase Externa
                                  </a>
                              </div>
                          )
                      ) : (
                          <div className="absolute inset-0 flex items-center justify-center">
                               <p className="text-zinc-700 font-black uppercase tracking-[0.5em] text-xs">Sin Video Asignado</p>
                          </div>
                      )}
                  </div>

                  {/* LESSON CONTROLS & INFO */}
                  <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
                      <div className="lg:col-span-2 space-y-8">

                          {/* HEADER & ACTIONS */}
                          <div className="flex flex-col md:flex-row md:items-start justify-between gap-6 border-b border-white/5 pb-8">
                              <h1 className="text-3xl lg:text-4xl font-black uppercase italic tracking-tight text-white flex-1 leading-none">{activeLesson.title}</h1>

                              <div className="flex flex-col items-end gap-4">
                                  {/* MARK AS COMPLETE BUTTON */}
                                  <button 
                                    onClick={() => toggleLessonCompletion(activeLesson.id)}
                                    className={`px-8 py-4 rounded-xl font-black uppercase tracking-wider text-xs flex items-center gap-2 transition-all active:scale-95 shadow-lg ${
                                      completedLessons.has(activeLesson.id) 
                                      ? 'bg-gradient-to-r from-green-500 to-emerald-600 text-black hover:scale-105 shadow-green-500/20' 
                                      : 'bg-zinc-900 border border-white/10 text-zinc-400 hover:text-white hover:border-white/30'
                                    }`}
                                  >
                                    {completedLessons.has(activeLesson.id) ? (
                                      <><CheckCircle size={18} fill="black" className="text-white"/> Lección Completada</>
                                    ) : (
                                      <><div className="w-4 h-4 border-2 border-current rounded-full"/> Marcar como Vista</>
                                    )}
                                  </button>
                              </div>
                          </div>

                          {/* RATING SYSTEM (RESTORED WITH ANIMATION) */}
                          <div className="flex items-center gap-6">
                              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-600">Valorar Clase:</span>
                              <div className="flex items-center gap-2">
                                  {[1, 2, 3, 4, 5].map((star) => (
                                      <motion.button
                                        key={star}
                                        whileHover={{ scale: 1.2 }}
                                        whileTap={{ scale: 0.9 }}
                                        onClick={() => setUserRating(star)}
                                        className="outline-none"
                                      >
                                          <motion.div
                                            animate={{ rotate: userRating >= star ? 360 : 0 }}
                                            transition={{ type: "spring", stiffness: 200, damping: 10 }}
                                          >
                                              <Star 
                                                  size={24} 
                                                  className={userRating >= star ? "text-yellow-400 drop-shadow-[0_0_10px_rgba(250,204,21,0.5)]" : "text-zinc-800"} 
                                                  fill={userRating >= star ? "currentColor" : "none"}
                                              />
                                          </motion.div>
                                      </motion.button>
                                  ))}
                              </div>
                          </div>

                          {/* DESCRIPTION */}
                          <div className="p-8 bg-zinc-900/30 rounded-3xl border border-white/5 text-zinc-400 leading-relaxed text-sm">
                              <h3 className="text-white font-bold uppercase mb-4 text-xs tracking-widest flex items-center gap-2"><FileText size={14} className="text-red-600"/> Resumen</h3>
                              {activeLesson.description || "Sin descripción disponible para esta clase."}
                          </div>
                      </div>

                      {/* SIDEBAR RESOURCES */}
                      <div className="space-y-4">
                          <h3 className="text-xs font-black uppercase tracking-[0.2em] text-zinc-500">Material de Clase</h3>
                          {activeLesson.resources ? (
                              <a 
                                  href={activeLesson.resources} 
                                  target="_blank" 
                                  rel="noopener noreferrer"
                                  className="block p-6 bg-red-600/10 border border-red-600/20 rounded-2xl hover:bg-red-600 hover:text-white transition-all group relative overflow-hidden"
                              >
                                  <div className="absolute inset-0 bg-red-600 opacity-0 group-hover:opacity-100 transition-opacity z-0"/>
                                  <div className="relative z-10">
                                      <div className="flex items-center gap-4 mb-2">
                                          <div className="p-2 bg-red-600 text-white rounded-lg group-hover:bg-white group-hover:text-red-600 transition-colors">
                                              <FileText size={20}/>
                                          </div>
                                          <span className="font-black text-sm uppercase tracking-wide">Descargar Archivo</span>
                                      </div>
                                      <p className="text-[10px] text-zinc-400 group-hover:text-red-100 pl-1">Clic para acceder al recurso</p>
                                  </div>
                              </a>
                          ) : (
                              <div className="p-6 border-2 border-dashed border-white/5 rounded-2xl text-center">
                                  <p className="text-[10px] font-black uppercase text-zinc-700 tracking-widest">Sin materiales</p>
                              </div>
                          )}
                      </div>
                  </div>
              </motion.div>
           )}
        </div>
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Play, FileText, ChevronDown, Lock, LogOut, Menu, X, Zap, ExternalLink, 
  CheckCircle, Trophy, Award, Star, Crown, ChevronRight, LayoutDashboard,
  Shield, Medal, ThumbsUp
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { supabase } from '../lib/supabase';
import { Link } from 'react-router-dom';
import { User } from '../types';

interface DashboardProps {
  user: User;
  onLogout: () => void;
}

type Rank = "Novato" | "Creador" | "Maestro";
type ViewState = 'HOME' | 'PLAYER';

const Dashboard: React.FC<DashboardProps> = ({ user, onLogout }) => {
  const [courses, setCourses] = useState<any[]>([]);
  // Use Set for O(1) lookups of completed lessons
  const [completedLessons, setCompletedLessons] = useState<Set<string>>(new Set());
  const [activeLesson, setActiveLesson] = useState<any>(null);
  const [viewState, setViewState] = useState<ViewState>('HOME');
  const [userRating, setUserRating] = useState<number>(0); // Estado local para la valoración

  const [loading, setLoading] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [expandedModules, setExpandedModules] = useState<Set<string>>(new Set());

  const isAdmin = user.role === 'admin';

  useEffect(() => {
    const init = async () => {
      setLoading(true);
      await Promise.all([fetchCourses(), fetchProgress()]);
      setLoading(false);
    };
    init();
  }, [user.id]);

  async function fetchCourses() {
    const { data, error } = await supabase
      .from('courses')
      .select('*, modules(*, lessons(*))')
      .order('created_at', { ascending: true });

    if (!error && data) {
      const sorted = data.map(c => ({
        ...c,
        modules: c.modules?.sort((a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())
          .map((m: any) => ({
             ...m,
             lessons: m.lessons?.sort((x: any, y: any) => new Date(x.created_at).getTime() - new Date(y.created_at).getTime())
          }))
      }));
      setCourses(sorted);

      // Auto-expand first module if exists
      if (sorted.length > 0 && sorted[0].modules?.[0]) {
        setExpandedModules(new Set([sorted[0].modules[0].id]));
      }
    }
  }

  async function fetchProgress() {
    const { data, error } = await supabase
      .from('user_progress')
      .select('lesson_id')
      .eq('user_id', user.id);

    if (!error && data) {
      const ids = new Set(data.map(item => item.lesson_id));
      setCompletedLessons(ids);
    }
  }

  const toggleLessonCompletion = async (lessonId: string) => {
    const isComplete = completedLessons.has(lessonId);

    // Optimistic UI Update
    const nextSet = new Set(completedLessons);
    if (isComplete) nextSet.delete(lessonId);
    else nextSet.add(lessonId);
    setCompletedLessons(nextSet);

    if (isComplete) {
      // Remove from DB
      await supabase.from('user_progress').delete().match({ user_id: user.id, lesson_id: lessonId });
    } else {
      // Add to DB
      await supabase.from('user_progress').insert({ user_id: user.id, lesson_id: lessonId });
    }
  };

  const handleLessonSelect = (lesson: any) => {
    setActiveLesson(lesson);
    setViewState('PLAYER');
    setUserRating(0); // Reset rating visual al cambiar lección
    // Auto close sidebar on mobile
    if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const toggleModule = (id: string) => {
    const next = new Set(expandedModules);
    if (next.has(id)) next.delete(id); else next.add(id);
    setExpandedModules(next);
  };

  // --- GAMIFICATION & STATS ENGINE ---

  const stats = useMemo(() => {
    let totalLessons = 0;
    let totalCompleted = 0;

    courses.forEach(course => {
      course.modules?.forEach((mod: any) => {
        mod.lessons?.forEach((lesson: any) => {
          totalLessons++;
          if (completedLessons.has(lesson.id)) totalCompleted++;
        });
      });
    });

    const percentage = totalLessons === 0 ? 0 : Math.round((totalCompleted / totalLessons) * 100);

    let rank: Rank = "Novato";
    if (percentage >= 50) rank = "Creador";
    if (percentage >= 100) rank = "Maestro";

    return { totalLessons, totalCompleted, percentage, rank };
  }, [courses, completedLessons]);

  const getRankIcon = (r: Rank, size: number = 20) => {
    switch (r) {
      case "Novato": return <Shield size={size} className="text-zinc-400" />;
      case "Creador": return <Award size={size} className="text-yellow-500" />;
      case "Maestro": return <Crown size={size} className="text-red-500" />;
    }
  };

  const resumeLearning = () => {
    // Find first uncompleted lesson
    for (const course of courses) {
      for (const mod of course.modules || []) {
        for (const lesson of mod.lessons || []) {
          if (!completedLessons.has(lesson.id)) {
            handleLessonSelect(lesson);
            return;
          }
        }
      }
    }
    // If all completed, go to first lesson of first course
    if (courses[0]?.modules?.[0]?.lessons?.[0]) {
      handleLessonSelect(courses[0].modules[0].lessons[0]);
    }
  };

  // --- SMART VIDEO EMBEDDER LOGIC ---

  const getEmbedUrl = (url: string) => {
    if (!url) return '';
    if (url.includes('drive.google.com')) return url.replace(/\/view.*/, '/preview');
    if (url.includes('youtube.com') || url.includes('youtu.be')) {
      const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
      const match = url.match(regExp);
      return (match && match[2].length === 11) ? `https://www.youtube.com/embed/${match[2]}?modestbranding=1&rel=0` : url;
    }
    if (url.includes('vimeo.com')) {
      const regExp = /vimeo\.com\/(\d+)/;
      const match = url.match(regExp);
      return match ? `https://player.vimeo.com/video/${match[1]}` : url;
    }
    return url;
  };

  const isEmbeddable = (url: string) => {
    if (!url) return false;
    return url.includes('drive.google.com') || url.includes('youtube.com') || url.includes('youtu.be') || url.includes('vimeo.com');
  };

  // ----------------------------------

  if (loading) return <div className="min-h-screen bg-black flex items-center justify-center text-white font-bold tracking-widest uppercase">Cargando tu Academia...</div>;

  return (
    <div className="min-h-screen bg-[#050505] text-white font-sans flex overflow-hidden">

      {/* --- SIDEBAR --- */}
      <motion.aside 
        initial={false}
        animate={{ width: sidebarOpen ? '350px' : '0px', opacity: sidebarOpen ? 1 : 0 }}
        className="h-screen bg-[#0a0a0a] border-r border-white/5 flex-shrink-0 flex flex-col overflow-hidden relative z-20"
      >
        <div className="p-6 border-b border-white/5 flex justify-between items-center bg-zinc-900/50 cursor-pointer" onClick={() => setViewState('HOME')}>
            <h2 className="font-black italic text-xl tracking-tighter">EZEH <span className="text-red-600">ACADEMY</span></h2>
            <button onClick={(e) => { e.stopPropagation(); setSidebarOpen(false); }} className="lg:hidden text-white"><X/></button>
        </div>

        {/* --- UNIFIED HOME PANEL & STATS --- */}
        <div 
            onClick={() => setViewState('HOME')}
            className={`p-6 border-b border-white/5 cursor-pointer transition-all group ${viewState === 'HOME' ? 'bg-white/5' : 'hover:bg-white/5'}`}
        >
           {/* HEADER */}
           <div className="flex items-center gap-3 mb-4">
               <div className={`p-2 rounded-lg ${viewState === 'HOME' ? 'bg-red-600 text-white' : 'bg-zinc-800 text-zinc-400 group-hover:text-white'}`}>
                   <LayoutDashboard size={18}/>
               </div>
               <span className={`text-xs font-black uppercase tracking-widest ${viewState === 'HOME' ? 'text-white' : 'text-zinc-500 group-hover:text-white'}`}>
                   Panel Home
               </span>
           </div>

           {/* STATS (SOLO SI NO ES ADMIN) */}
           {!isAdmin && (
               <div className="bg-[#050505] rounded-xl p-4 border border-white/5 relative overflow-hidden">
                   <div className="absolute top-0 right-0 w-20 h-20 bg-red-600/20 blur-xl rounded-full"/>
                   <div className="relative z-10 flex items-center justify-between">
                       <div className="flex flex-col">
                           <span className="text-[10px] text-zinc-500 font-bold uppercase tracking-wider mb-1">Tu Rango</span>
                           <div className="flex items-center gap-2 text-sm font-black italic uppercase text-white">
                                {getRankIcon(stats.rank, 14)} {stats.rank}
                           </div>
                       </div>
                       <div className="w-12 h-12 rounded-full border-2 border-red-600 flex items-center justify-center font-black text-xs text-white bg-red-600/10 shadow-[0_0_15px_rgba(220,38,38,0.3)]">
                          {stats.percentage}%
                       </div>
                   </div>
               </div>
           )}

           {isAdmin && (
               <div className="bg-[#050505] rounded-xl p-4 border border-yellow-500/20 relative overflow-hidden group-hover:border-yellow-500/40 transition-colors">
                   <div className="absolute -top-10 -right-10 w-24 h-24 bg-yellow-500/10 blur-xl rounded-full"/>
                   <div className="relative z-10">
                       <span className="text-[9px] text-yellow-500/80 font-bold uppercase tracking-[0.2em] mb-1 block">Modo Dios</span>
                       <div className="text-xs font-black text-white uppercase flex items-center gap-2">
                           <Crown size={14} className="text-yellow-400"/> Administrador
                       </div>
                   </div>
               </div>
           )}
        </div>

        {/* --- COURSE LIST --- */}
        <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-8">
            {courses.map(course => (
                <div key={course.id}>
                    <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-zinc-500 mb-4 ml-2">{course.title}</h3>
                    <div className="space-y-2">
                        {course.modules?.map((mod: any) => (
                            <div key={mod.id} className="bg-black border border-white/5 rounded-2xl overflow-hidden">
                                <button 
                                    onClick={() => toggleModule(mod.id)}
                                    className="w-full p-4 flex justify-between items-center text-left hover:bg-white/5 transition-colors"
                                >
                                    <span className="font-bold text-sm text-zinc-300 uppercase">{mod.title}</span>
                                    <ChevronDown size={16} className={`text-zinc-600 transition-transform ${expandedModules.has(mod.id) ? 'rotate-180' : ''}`}/>
                                </button>

                                <AnimatePresence>
                                    {expandedModules.has(mod.id) && (
                                        <motion.div 
                                            initial={{ height: 0 }} animate={{ height: 'auto' }} exit={{ height: 0 }} 
                                            className="overflow-hidden bg-zinc-900/30"
                                        >
                                            <div className="p-2 space-y-1">
                                                {mod.lessons?.map((lesson: any) => {
                                                    const isCompleted = completedLessons.has(lesson.id);
                                                    const isActive = activeLesson?.id === lesson.id && viewState === 'PLAYER';
                                                    return (
                                                      <button
                                                          key={lesson.id}
                                                          onClick={() => handleLessonSelect(lesson)}
                                                          className={`w-full p-3 rounded-xl flex items-center gap-3 text-left transition-all group ${isActive ? 'bg-red-600 text-white shadow-lg shadow-red-900/20' : 'hover:bg-white/5 text-zinc-500'}`}
                                                      >
                                                          <div className={`p-1.5 rounded-full relative ${isActive ? 'bg-white/20' : 'bg-black border border-white/10 group-hover:border-white/30'}`}>
                                                              {isActive ? <Play size={10} fill="currentColor"/> : (
                                                                isCompleted ? <CheckCircle size={10} className="text-green-500" /> : <Lock size={10}/>
                                                              )}
                                                          </div>
                                                          <span className={`text-xs font-bold uppercase truncate flex-1 ${isCompleted && !isActive ? 'text-zinc-300 line-through decoration-red-600/50' : ''}`}>{lesson.title}</span>
                                                      </button>
                                                    );
                                                })}
                                            </div>
                                        </motion.div>
                                    )}
                                </AnimatePresence>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
        </div>

        <div className="p-4 border-t border-white/5 space-y-3">
            {isAdmin && (
                <Link 
                    to="/admin" 
                    className="w-full py-4 rounded-xl text-xs font-black uppercase text-white bg-gradient-to-r from-red-600 to-red-900 hover:scale-[1.02] transition-transform shadow-lg shadow-red-900/30 flex items-center justify-center gap-2 border border-white/10"
                >
                    <Zap size={16} className="text-yellow-400 fill-yellow-400 animate-pulse"/> EZEH STUDIO
                </Link>
            )}

            <button onClick={onLogout} className="w-full py-3 bg-zinc-900 rounded-xl text-xs font-bold uppercase text-zinc-500 hover:text-white hover:bg-zinc-800 transition-all flex items-center justify-center gap-2">
