                  </div>

                  {/* LESSON INFO SECTION (NEW LAYOUT) */}
                  <div className="space-y-6">

                      {/* HEADER ROW: TITLE (LEFT) & RATING (RIGHT) */}
                      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-white/5 pb-6">
