                                  <div className="px-6 py-4 border border-dashed border-white/10 rounded-xl">
                                      <p className="text-[10px] font-black uppercase text-zinc-600 tracking-widest">Sin materiales adjuntos</p>
                                  </div>
                              )}
                          </div>
                      </div>
                  </div>

              </motion.div>
           )}
        </div>
      </main>
    </div>
  );
};

