                              <div className="flex items-center gap-2 text-red-500 text-[10px] font-black uppercase tracking-[0.2em] mb-2">
                                  <Signal size={14} className="animate-pulse"/> En Línea Ahora
                              </div>
                              <div className="text-4xl font-black text-white flex items-end gap-2">
                                  {onlineCount} <span className="text-lg text-zinc-600 mb-1">activos</span>
                              </div>
                              <div className="mt-4 text-xs text-red-400/60 font-medium">Usuarios conectados en tiempo real.</div>
