                    </span>
                    <div className={`p-2 rounded-full border ${isAdmin ? 'bg-yellow-500 text-black border-yellow-300' : 'bg-white text-red-600 border-white'} shadow-[0_0_15px_rgba(255,255,255,0.4)]`}>
                        <Play size={14} fill="currentColor" />
                    </div>
                </div>
