                                              fill={userRating >= star ? "currentColor" : "none"}
                                          />
                                      </motion.button>
                                  ))}
                              </div>
                          </div>
                      </div>

                      {/* DESCRIPTION FULL WIDTH */}
                      <div className="p-6 bg-zinc-900/30 rounded-2xl border border-white/5 text-zinc-400 leading-relaxed text-sm">
