                          {activeLesson.description || "Sin descripción disponible para esta clase."}
                      </div>

                      {/* RESOURCES (HORIZONTAL) */}
                      <div>
                          <h3 className="text-xs font-black uppercase tracking-[0.2em] text-zinc-500 mb-4">Materiales Disponibles</h3>
