  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 2. Courses Table
create table if not exists courses (
  id uuid default gen_random_uuid() primary key,
  title text not null,
  description text,
  thumbnail text,
  order_index serial,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 3. Modules Table (Cascade Delete: Deleting a course deletes its modules)
create table if not exists modules (
  id uuid default gen_random_uuid() primary key,
  course_id uuid references courses(id) on delete cascade not null,
  title text not null,
  order_index serial,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 4. Lessons Table (Cascade Delete: Deleting a module deletes its lessons)
create table if not exists lessons (
  id uuid default gen_random_uuid() primary key,
  module_id uuid references modules(id) on delete cascade not null,
  title text not null,
  video_url text,
  description text,
  resources text, -- Stores the public URL of the uploaded file
  order_index serial,
  created_at timestamp with time zone default timezone('utc'::text, now()) not null
);

-- 5. User Progress Table
create table if not exists user_progress (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  lesson_id uuid references lessons(id) on delete cascade not null,
  completed_at timestamp with time zone default timezone('utc'::text, now()) not null,
  unique(user_id, lesson_id)
);

-- 6. Lesson Ratings Table
create table if not exists lesson_ratings (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  lesson_id uuid references lessons(id) on delete cascade not null,
  rating integer check (rating >= 1 and rating <= 5),
  created_at timestamp with time zone default timezone('utc'::text, now()) not null,
  unique(user_id, lesson_id)
);

-- 7. Trigger to automatically create a Profile when a User signs up
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, email, full_name, role)
  values (new.id, new.email, new.raw_user_meta_data->>'full_name', 'student');
  return new;
end;
$$ language plpgsql security definer;

-- Drop trigger if exists to avoid duplication errors on re-runs
