import { HashRouter as Router, Routes, Route, Navigate, useNavigate } from 'react-router-dom';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Admin from './pages/Admin';
import UpdatePassword from './pages/UpdatePassword';
import { User } from './types';
import { supabase, ADMIN_EMAIL } from './lib/supabase';
import { ShieldAlert, Home, Loader2 } from 'lucide-react';

// --- BRIDGE COMPONENT (CRÍTICO) ---
// Este componente actúa como un puente. Si un usuario llega desde un link de correo
// como "misitio.com/update-password", HashRouter no lo verá.
// Este componente detecta esa URL "real" y le dice al Router que navegue internamente.
const URLBridge = () => {
  const navigate = useNavigate();

  useEffect(() => {
    // Leemos la ruta real del navegador
    const currentPath = window.location.pathname;

    // Si contiene 'update-password' (típico link de Supabase)
    if (currentPath.includes('update-password')) {
      console.log("Puente activado: Redirigiendo link de correo a ruta Hash...");
      // Forzamos la navegación interna a la ruta correcta dentro del sistema Hash
      navigate('/update-password', { replace: true });
    }
  }, [navigate]);

  return null;
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // 1. Verificar sesión inicial
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        mapSupabaseUser(session.user);
      } else {
        setLoading(false);
      }
    });

    // 2. Escuchar cambios de estado
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        mapSupabaseUser(session.user);
      } else {
        setUser(null);
        setLoading(false);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // 3. Tracking de actividad (Online Status)
  useEffect(() => {
    if (user) {
      const channel = supabase.channel('online-users', {
        config: { presence: { key: user.id } },
      });

      channel.subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          await channel.track({
            user_id: user.id,
            full_name: user.fullName,
            online_at: new Date().toISOString(),
          });
        }
      });

      return () => { supabase.removeChannel(channel); };
    }
  }, [user?.id, user?.fullName]);

  const mapSupabaseUser = (sbUser: any) => {
    const isAdmin = sbUser.email === ADMIN_EMAIL;
    setUser({
      id: sbUser.id,
      email: sbUser.email || '',
      fullName: sbUser.user_metadata?.full_name || sbUser.email?.split('@')[0],
      role: isAdmin ? 'admin' : 'student',
      progress: [],
    });
    setLoading(false);
